-- Create views AFTER all referenced tables/views exist; inspect DB references and dependency order.
-- Review and execute only when the previous stage succeeded.

CREATE VIEW `zendendb`.`Documentation_v` (`uuid` UUID, `table` String, `engine` String, `metadata_modification_time` DateTime, `total_rows` Nullable(UInt64), `comment` String, `insert_query` Nullable(String), `sourse_uuid` Nullable(UUID), `sourse_table` String, `sourse_metadata_modification_time` Nullable(DateTime), `sourse_total_rows` Nullable(UInt64), `sourse_comment` Nullable(String)) AS WITH tbs AS (SELECT DISTINCT argMax(l.query_kind, l.event_time) AS query_kind, os_user, replaceAll(replaceRegexpAll(multiIf((splitByWhitespace(l.query)[3]) = '`Градусник', splitByChar('`', l.query)[2], l.query_kind = 'Alter', splitByChar('.', splitByWhitespace(l.query)[3])[2], (splitByWhitespace(l.query)[3]) = 'TABLE', splitByWhitespace(l.query)[4], splitByWhitespace(l.query)[3]), '[`"]', ''), 'zendendb.', '') AS insert_table, max(if(l.query_kind = 'Alter', arraySlice(l.tables, 1, 1), l.tables)) AS tables, argMax(l.query, l.event_time) AS query, l.http_user_agent, if(insert_table NOT LIKE '%_temp', insert_table, replaceOne(insert_table, '_temp', '')) AS insert_temp_table_fix FROM system.query_log AS l WHERE (l.event_date > (today() - 7)) AND (current_database = 'zendendb') AND (type = 'QueryStart') AND (l.query_kind IN ('Insert', 'Alter')) GROUP BY insert_table, http_user_agent, os_user HAVING NOT match(insert_table, '^t[a-z0-9]{32}$')), tbs_list AS (SELECT name, uuid, engine, metadata_modification_time, total_rows, total_bytes, parts, active_parts, total_marks, comment FROM system.tables WHERE database = 'zendendb'), tbs_for_join AS (SELECT tl.name AS `table`, uuid, engine, metadata_modification_time, total_rows, comment, query_kind, insert_table, replaceRegexpAll(replaceAll(arrayJoin(if(empty(tables), [''], tables)), 'zendendb.', ''), '[`"]', '') AS sourse_table, query, http_user_agent, os_user FROM tbs_list AS tl LEFT JOIN tbs AS t ON t.insert_temp_table_fix = tl.name) SELECT uuid, `table`, engine, metadata_modification_time, total_rows, comment, tj.query AS insert_query, tl.uuid AS sourse_uuid, tj.sourse_table AS sourse_table, tl.metadata_modification_time AS sourse_metadata_modification_time, tl.total_rows AS sourse_total_rows, tl.comment AS sourse_comment FROM tbs_for_join AS tj LEFT JOIN tbs_list AS tl ON tl.name = tj.sourse_table WHERE (NOT match(sourse_table, '^t[a-z0-9]{32}$')) AND (`table` != 'REPLACE') AND ((insert_table != sourse_table) OR (sourse_table = '')) ORDER BY `table` ASC SETTINGS join_use_nulls = 1;

CREATE VIEW `zendendb`.`ECOM_TM_for_prediction_v` AS WITH price AS (SELECT half AS date, kdo, value_rub FROM `zendendb`.`Себестоимость_по_полугодиям` FINAL WHERE (toStartOfMonth(half) = if(toMonth({start_of_month:date}) <= 6, toStartOfYear({start_of_month:date}), toStartOfYear({start_of_month:date}) + toIntervalMonth(6))) AND (kdo IN (SELECT DISTINCT toInt64OrZero(splitByChar('#', assumeNotNull(PRODUCT_XML_ID))[1]) FROM `zendendb`.`ЗаказКлиента.Товары` FINAL))), orders AS (SELECT toDate(z.DATE_INSERT) AS `Дата`, z.COMPANY_CODE AS `Компания`, ifNull(sum(zt.PRICE), 0) AS `Входящие руб.`, ifNull(countDistinct(z.ID), 0) AS `Кол-во входящих`, ifNull(sum(zt.QUANTITY), 0) AS `Товары во входящих` FROM `zendendb`.`ЗаказКлиента` AS z FINAL LEFT JOIN (SELECT * FROM `zendendb`.`ЗаказКлиента.Товары` AS zt FINAL) AS zt ON zt.ORDER_ID = z.ID WHERE (COMPANY_CODE IN ('THOMAS', 'SALAMANDER')) AND (toStartOfMonth(z.DATE_INSERT) = {start_of_month:date}) GROUP BY `Дата`, `Компания`), sales AS (SELECT toDate(z.DATE_STATUS) AS `Дата`, z.COMPANY_CODE AS `Компания`, ifNull(countIfDistinct(z.ID, (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат'))), 0) AS `Кол-во выполненных`, ifNull(sumIf(zt.QUANTITY, (NOT zt.`Не выкуплен`) AND (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат'))), 0) AS `Товары в выполненных`, ifNull(countIfDistinct(z.ID, (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат')) AND (z.DELIVERY_NAME = 'Самовывоз из салона')), 0) AS `Самовывоз кол-во выполненных`, ifNull(sumIf(zt.QUANTITY, (NOT zt.`Не выкуплен`) AND (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат')) AND (z.DELIVERY_NAME = 'Самовывоз из салона')), 0) AS `Самовывоз товары в выполненных`, ifNull(sumIf(zt.PRICE, (NOT zt.`Не выкуплен`) AND (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат'))), 0) - ifNull(sumIf(zt.PRICE, (zt.`Статус` IN ('Возврат', 'Возврат средств')) AND (STATUS != 'Отказ')), 0) AS `Выручка`, ifNull(sumIf(sb.value_rub, (NOT zt.`Не выкуплен`) AND (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат'))), 0) - ifNull(sumIf(sb.value_rub, (zt.`Статус` IN ('Возврат', 'Возврат средств')) AND (STATUS != 'Отказ')), 0) AS `Себестоимость`, ifNull(sumIf(zt.PRICE, (NOT zt.`Не выкуплен`) AND (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат'))), 0) AS `Выручка с возвратами`, ifNull(sumIf(sb.value_rub, (NOT zt.`Не выкуплен`) AND (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат'))), 0) AS `Себестоимость с возвратами`, ifNull(sumIf(zt.price1C, (NOT zt.`Не выкуплен`) AND (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат'))), 0) AS price1C FROM `zendendb`.`ЗаказКлиента` AS z FINAL LEFT JOIN (SELECT * FROM `zendendb`.`ЗаказКлиента.Товары` AS zt FINAL) AS zt ON zt.ORDER_ID = z.ID LEFT JOIN price AS sb ON (sb.date = toDate(z.DATE_STATUS)) AND (sb.kdo = toUInt64OrZero(splitByChar('#', assumeNotNull(PRODUCT_XML_ID))[1])) WHERE (COMPANY_CODE IN ('THOMAS', 'SALAMANDER')) AND (toStartOfMonth(z.DATE_STATUS) = {start_of_month:date}) GROUP BY `Дата`, `Компания`), plan AS (SELECT *, if(pl.`Подразделение` = 'SR', 'SALAMANDER', 'THOMAS') AS `Компания` FROM `zendendb`.`ПланПродаж_ecom` AS pl FINAL), trafic AS (SELECT *, if(ymv.shop_name = 'Salamander', 'SALAMANDER', 'THOMAS') AS `Компания` FROM `zendendb`.YandexMetrikaVisits AS ymv FINAL), orders_sales AS (SELECT ifNull(o.`Дата`, s.`Дата`) AS `Дата`, ifNull(o.`Компания`, s.`Компания`) AS `Компания`, o.`Входящие руб.`, o.`Кол-во входящих`, o.`Товары во входящих`, s.`Кол-во выполненных` AS `Кол-во выполненных`, s.`Товары в выполненных` AS `Товары в выполненных`, s.`Самовывоз кол-во выполненных` AS `Самовывоз кол-во выполненных`, s.`Самовывоз товары в выполненных` AS `Самовывоз товары в выполненных`, s.`Выручка` AS `Выручка`, s.`Себестоимость` AS `Себестоимость`, s.`Выручка с возвратами` AS `Выручка с возвратами`, s.`Себестоимость с возвратами` AS `Себестоимость с возвратами`, s.price1C AS price1C FROM orders AS o FULL OUTER JOIN sales AS s ON (o.`Дата` = s.`Дата`) AND (o.`Компания` = s.`Компания`) WHERE `Дата` < today()) SELECT ifNull(os.`Дата`, pl.`Дата`) AS `Дата`, ifNull(os.`Компания`, pl.`Компания`) AS `Компания`, tr.visits AS `Трафик`, os.`Входящие руб.` AS `Входящие руб`, os.`Выручка` AS `Выручка`, os.`Выручка` - os.`Себестоимость` AS `Вал`, os.`Выручка с возвратами` AS `Выручка с возвратами`, os.`Выручка с возвратами` - os.`Себестоимость с возвратами` AS `Вал с возвратами`, pl.`Трафик` AS `План Трафик`, pl.`Входящие Заказы` AS `План Входящие`, pl.`Входящие Заказы руб` AS `План Входящие руб`, pl.`Выручка` AS `План Выручка`, pl.`Вал` AS `План Вал` FROM orders_sales AS os FULL OUTER JOIN plan AS pl ON (os.`Дата` = pl.`Дата`) AND (os.`Компания` = pl.`Компания`) LEFT JOIN trafic AS tr ON (os.`Дата` = tr.date) AND (os.`Компания` = tr.`Компания`) WHERE (toStartOfMonth(`Дата`) = {start_of_month:date}) AND (`Компания` = {market:String}) ORDER BY `Дата` ASC SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`ECOM_zenden_v` (`Дата` Date, `ИсточникЗаказа` String, `СпособДоставки` String, `Заказы, шт` UInt64, `Заказы, руб` Nullable(Decimal(38, 3)), `Заказы выкуплено, шт` UInt64, `Заказы выкуплено, руб` Nullable(Decimal(38, 3))) AS SELECT toDate(if((iz.STATUS IN ('Выполнен', 'Частично выполнен')), iz.DATE_UPDATE, iz.DATE_INSERT)) AS `Дата`, assumeNotNull(iz.SHOP_NAME) AS `ИсточникЗаказа`, assumeNotNull(sd.DELIVERY_NAME) AS `СпособДоставки`, count(iz.ID) AS `Заказы, шт`, sum(iz.PRICE) AS `Заказы, руб`, countIf(iz.ID, (iz.STATUS IN ('Выполнен', 'Частично выполнен'))) AS `Заказы выкуплено, шт`, sumIf(iz.PRICE, (iz.STATUS IN ('Выполнен', 'Частично выполнен'))) AS `Заказы выкуплено, руб` FROM `zendendb`.`ЗаказКлиента` AS iz FINAL LEFT JOIN `zendendb`.`СпособыДоставкиИМ` AS sd ON sd.DELIVERY_CODE = iz.DELIVERY_CODE WHERE iz.SHOP_NAME IN ('imshop (Zenden)', 'zenden.ru', 'zenden.ru - ПВЗ', 'zenden.ru - самовывоз', 'zenden.ru - APP') GROUP BY `Дата`, `ИсточникЗаказа`, `СпособДоставки`;

CREATE VIEW `zendendb`.`GoodInWarehousesCR_MP_2024_v` AS SELECT {end_date:date} AS dt, max(w.SkladPodrazdelenie) AS shop, w.PodrazdelenieGuid AS shopGuid, w.Sklad AS warehouse, 'Маркетплейс' AS warehouseType, w.NomenklaturaGuid AS productGuid, w.NomenklaturaKodDlyaObmena AS kdo, w.XarakteristikaNomenklatury AS size, argMax(w.KolichestvoOstatok, w.Period) AS qty FROM `zendendb`.TovaryNaSkladaxCR AS w WHERE (w.Sklad IN ('Маркетплейс Вайлдберриз-ТМ ', 'Маркетплейс Ламода-ТМ', 'Маркетплейс СберМегаМаркет-Мюнц', 'Маркетплейс Озон-ТМ', 'Маркетплейс Яндекс-Маркет-ТМ ')) AND (toDate(Period) <= {end_date:date}) AND (toDate(Period) >= '2024-01-01') GROUP BY w.Sklad, w.NomenklaturaGuid, w.NomenklaturaKodDlyaObmena, w.XarakteristikaNomenklatury, w.PodrazdelenieGuid HAVING qty != 0;

CREATE VIEW `zendendb`.`GoodInWarehousesCR_MP_v` AS SELECT {end_date:date} AS dt, max(w.SkladPodrazdelenie) AS shop, w.PodrazdelenieGuid AS shopGuid, w.Sklad AS warehouse, 'Маркетплейс' AS warehouseType, w.NomenklaturaGuid AS productGuid, w.NomenklaturaKodDlyaObmena AS kdo, w.XarakteristikaNomenklatury AS size, argMax(w.KolichestvoOstatok, w.Period) AS qty FROM `zendendb`.TovaryNaSkladaxCR AS w WHERE (w.Sklad IN ('Маркетплейс Вайлдберриз-ТМ ', 'Маркетплейс Ламода-ТМ', 'Маркетплейс СберМегаМаркет-Мюнц', 'Маркетплейс Озон-ТМ', 'Маркетплейс Яндекс-Маркет-ТМ ', 'ИНТЕРНЕТ-магазин Thomas Munz')) AND (toDate(Period) <= {end_date:date}) AND (toDate(Period) >= '2025-01-01') GROUP BY w.Sklad, w.NomenklaturaGuid, w.NomenklaturaKodDlyaObmena, w.XarakteristikaNomenklatury, w.PodrazdelenieGuid HAVING qty != 0;

CREATE VIEW `zendendb`.`GoodInWarehousesCR_RT_2024_v` AS WITH tm_shops AS (SELECT s.`Магазин` FROM `zendendb`.`Магазины_fix` AS s WHERE s.`Магазин Родитель` IN ('Thomas Munz', 'Salamander', 'Закрытые SALAMANDER', 'Неиспользуемые ТМ')), good_in_sales AS (SELECT t.`КодДляОбмена` FROM `zendendb`.`ТоварыУПП` AS t WHERE (`ТипНоменклатуры` IN ('Реклама')) AND (`Товар` ILIKE '%пакет%') UNION ALL SELECT t.`КодДляОбмена` FROM `zendendb`.`ТоварыУПП` AS t WHERE `ТипНоменклатуры` NOT IN ('ИТ-оборудование', 'Реклама', 'Хоз. товары', 'Бытовая техника', 'Рекламное оборудование', 'Светильники', 'Торговое оборудование', 'Электроматериалы', 'Оборудование', '*не исп. Канц./хоз. товары', 'Канцтовары', 'производственный и хозяйственный инвентарь', 'Хоз. инвентарь', 'Материалы и оборудование', 'Офисная мебель', 'Реклама и оборудование ТМ', 'НЕ_ИСП_Оргтехника', 'Маски не медицинские', 'Пожарная безопасность', 'Строительные материалы', 'Периодические издания')) SELECT {end_date:date} AS dt, max(w.SkladPodrazdelenie) AS shop, s.`МагазинГуид` AS shopGuid, w.Sklad AS warehouse, max(splitByWhitespace(w.Sklad)[1]) AS warehouseType, w.NomenklaturaGuid AS productGuid, w.NomenklaturaKodDlyaObmena AS kdo, w.XarakteristikaNomenklatury AS size, argMax(w.KolichestvoOstatok, w.Period) AS qty FROM `zendendb`.TovaryNaSkladaxCR AS w ANY LEFT JOIN `zendendb`.`Магазины_fix` AS s ON s.`Магазин` = w.SkladPodrazdelenie WHERE (w.SkladPodrazdelenie IN (SELECT `Магазин` FROM tm_shops)) AND (w.NomenklaturaKodDlyaObmena IN (SELECT * FROM good_in_sales)) AND (toDate(Period) <= {end_date:date}) AND (toDate(Period) >= '2024-01-01') GROUP BY w.Sklad, w.NomenklaturaGuid, w.NomenklaturaKodDlyaObmena, w.XarakteristikaNomenklatury, s.`МагазинГуид` HAVING qty != 0;

CREATE VIEW `zendendb`.`GoodInWarehousesCR_RT_v` AS WITH tm_shops AS (SELECT s.`Магазин` FROM `zendendb`.`Магазины_fix` AS s WHERE s.`Магазин Родитель` IN ('Thomas Munz', 'Salamander', 'Закрытые SALAMANDER', 'Неиспользуемые ТМ')), good_in_sales AS (SELECT t.`КодДляОбмена` FROM `zendendb`.`ТоварыУПП` AS t WHERE (`ТипНоменклатуры` IN ('Реклама')) AND (`Товар` ILIKE '%пакет%') UNION ALL SELECT t.`КодДляОбмена` FROM `zendendb`.`ТоварыУПП` AS t WHERE `ТипНоменклатуры` NOT IN ('ИТ-оборудование', 'Реклама', 'Хоз. товары', 'Бытовая техника', 'Рекламное оборудование', 'Светильники', 'Торговое оборудование', 'Электроматериалы', 'Оборудование', '*не исп. Канц./хоз. товары', 'Канцтовары', 'производственный и хозяйственный инвентарь', 'Хоз. инвентарь', 'Материалы и оборудование', 'Офисная мебель', 'Реклама и оборудование ТМ', 'НЕ_ИСП_Оргтехника', 'Маски не медицинские', 'Пожарная безопасность', 'Строительные материалы', 'Периодические издания')) SELECT {end_date:date} AS dt, max(w.SkladPodrazdelenie) AS shop, s.`МагазинГуид` AS shopGuid, w.Sklad AS warehouse, max(splitByWhitespace(w.Sklad)[1]) AS warehouseType, w.NomenklaturaGuid AS productGuid, w.NomenklaturaKodDlyaObmena AS kdo, w.XarakteristikaNomenklatury AS size, argMax(w.KolichestvoOstatok, w.Period) AS qty FROM `zendendb`.TovaryNaSkladaxCR AS w ANY LEFT JOIN `zendendb`.`Магазины_fix` AS s ON s.`Магазин` = w.SkladPodrazdelenie WHERE (w.SkladPodrazdelenie IN (SELECT `Магазин` FROM tm_shops)) AND (w.NomenklaturaKodDlyaObmena IN (SELECT * FROM good_in_sales)) AND (toDate(Period) <= {end_date:date}) AND (toDate(Period) >= '2025-01-01') GROUP BY w.Sklad, w.NomenklaturaGuid, w.NomenklaturaKodDlyaObmena, w.XarakteristikaNomenklatury, s.`МагазинГуид` HAVING qty != 0;

CREATE VIEW `zendendb`.`GoodInWarehouses_API_TM_v` AS WITH wb AS (SELECT {end_date:date} AS dt, 'Вайлдберриз-ТМ' AS shop, '7efc26fe-4635-11e9-80d7-0050569c7f45' AS shopGuid, w.warehouseName AS warehouse, 'Оптовый' AS warehouseType, t.`ТоварГуид` AS productGuid, m.kdo AS kdo, w.techSize AS size, toUInt64(sum(w.quantity)) AS qty FROM `zendendb`.WB_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.vendorCode) AND (m.mp = 'Вайлдберриз') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = m.kdo WHERE (w.date = {end_date:date}) AND (w.warehouseName NOT IN ('Всего находится на складах')) GROUP BY warehouseName, kdo, size, productGuid), oz AS (SELECT {end_date:date} AS dt, 'Озон-ТМ' AS shop, '843d07ad-cd74-11ea-80dd-0050569c7f45' AS shopGuid, w.warehouse_name AS warehouse, 'Оптовый' AS warehouseType, t.`ТоварГуид` AS productGuid, m.kdo AS kdo, splitByChar('_', w.offer_id)[2] AS size, toUInt64(sum((available_stock_count + return_to_seller_stock_count) + outbound_pending_delivery)) AS qty FROM `zendendb`.OZON_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.offer_id) AND (m.mp = 'Озон') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = m.kdo WHERE toDate(w.timestamp) = {end_date:date} GROUP BY warehouse_name, kdo, size, productGuid), lm AS (SELECT {end_date:date} AS dt, 'Ламода-ТМ' AS shop, 'e4f2d2fa-d326-11ea-80dd-0050569c7f45' AS shopGuid, 'Маркетплейс Ламода-ТМ' AS warehouse, 'Оптовый' AS warehouseType, t.`ТоварГуид` AS productGuid, m.kdo AS kdo, if(match(if(countMatches(splitByChar('-', w.sku)[-1], '_') > 0, splitByChar('_', w.sku)[-1], splitByChar('-', w.sku)[-1]), '^\\d{4,}$'), '', if(countMatches(splitByChar('-', w.sku)[-1], '_') > 0, splitByChar('_', w.sku)[-1], splitByChar('-', w.sku)[-1])) AS size, sum(w.quantity) AS qty FROM `zendendb`.LAMODA_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.sku) AND (m.mp = 'Ламода') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = m.kdo WHERE toDate(w.date) = {end_date:date} GROUP BY kdo, size, productGuid), ya AS (WITH o AS (SELECT {end_date:date} AS dt, multiIf((o.OFFER_STATUS IN ('Отгружен')), 'В пути до получателей', (o.OFFER_STATUS IN ('Невыкуп отправлен', 'Возврат отправлен', 'Возврат принят', 'Невыкуп принят', 'Возврат оформлен')), 'В пути возвраты на склад YA', '') AS warehouse, o.ORDER_ID, o.SHOP_SKU, m.kdo AS kdo, if((splitByChar('_', o.SHOP_SKU)[-1]) = o.SHOP_SKU, '', splitByChar('_', o.SHOP_SKU)[-1]) AS size, argMax(o.DELIVERED_OR_RETURNED, o.STATUS_CHANGED) AS DELIVERED_OR_RETURNED, argMax(o.OFFER_STATUS, o.STATUS_CHANGED) AS OFFER_STATUS FROM `zendendb`.YANDEX_Orders_TM AS o FINAL ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = o.SHOP_SKU) AND (m.mp = 'Яндекс') WHERE toDate(o.STATUS_CHANGED) = {end_date:date} GROUP BY toDate(o.STATUS_CHANGED), o.ORDER_ID, m.kdo, SHOP_SKU, o.OFFER_STATUS) SELECT dt, 'Яндекс-Маркет-ТМ' AS shop, 'd85c2349-d7ba-11ee-80e5-0050569c7f45' AS shopGuid, warehouse AS warehouse, 'Оптовый' AS warehouseType, t.`ТоварГуид` AS productGuid, kdo, size, toUInt64(sum(DELIVERED_OR_RETURNED)) AS qty FROM o ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = o.kdo WHERE warehouse != '' GROUP BY dt, kdo, size, productGuid, warehouse UNION ALL WITH o AS (SELECT {end_date:date} AS dt, multiIf((o.OFFER_STATUS IN ('Отгружен')), 'В пути до получателей', (o.OFFER_STATUS IN ('Невыкуп отправлен', 'Возврат отправлен', 'Возврат принят', 'Невыкуп принят', 'Возврат оформлен')), 'В пути возвраты на склад YA', '') AS warehouse, o.ORDER_ID, o.SHOP_SKU, m.kdo AS kdo, if((splitByChar('_', o.SHOP_SKU)[-1]) = o.SHOP_SKU, '', splitByChar('_', o.SHOP_SKU)[-1]) AS size, argMax(o.DELIVERED_OR_RETURNED, o.STATUS_CHANGED) AS DELIVERED_OR_RETURNED, argMax(o.OFFER_STATUS, o.STATUS_CHANGED) AS OFFER_STATUS FROM `zendendb`.YANDEX_Orders_TM AS o FINAL ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = o.SHOP_SKU) AND (m.mp = 'Яндекс') WHERE toDate(o.STATUS_CHANGED) = {end_date:date} GROUP BY toDate(o.STATUS_CHANGED), o.ORDER_ID, m.kdo, SHOP_SKU, o.OFFER_STATUS) SELECT {end_date:date} AS dt, 'Яндекс-Маркет-ТМ' AS shop, 'd85c2349-d7ba-11ee-80e5-0050569c7f45' AS shopGuid, warehouseName AS warehouse, 'Оптовый' AS warehouseType, t.`ТоварГуид` AS productGuid, m.kdo AS kdo, if((splitByChar('_', offerId)[-1]) = offerId, '', splitByChar('_', offerId)[-1]) AS size, sum(w.count) AS qty FROM `zendendb`.YANDEX_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.offerId) AND (m.mp = 'Яндекс') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = m.kdo WHERE (toDate(w.date) = {end_date:date}) AND (w.type = 'AVAILABLE') GROUP BY warehouseName, kdo, size, productGuid) SELECT * FROM ya UNION ALL WITH wb AS (SELECT {end_date:date} AS dt, 'Вайлдберриз-ТМ' AS shop, '7efc26fe-4635-11e9-80d7-0050569c7f45' AS shopGuid, w.warehouseName AS warehouse, 'Оптовый' AS warehouseType, t.`ТоварГуид` AS productGuid, m.kdo AS kdo, w.techSize AS size, toUInt64(sum(w.quantity)) AS qty FROM `zendendb`.WB_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.vendorCode) AND (m.mp = 'Вайлдберриз') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = m.kdo WHERE (w.date = {end_date:date}) AND (w.warehouseName NOT IN ('Всего находится на складах')) GROUP BY warehouseName, kdo, size, productGuid), oz AS (SELECT {end_date:date} AS dt, 'Озон-ТМ' AS shop, '843d07ad-cd74-11ea-80dd-0050569c7f45' AS shopGuid, w.warehouse_name AS warehouse, 'Оптовый' AS warehouseType, t.`ТоварГуид` AS productGuid, m.kdo AS kdo, splitByChar('_', w.offer_id)[2] AS size, toUInt64(sum((available_stock_count + return_to_seller_stock_count) + outbound_pending_delivery)) AS qty FROM `zendendb`.OZON_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.offer_id) AND (m.mp = 'Озон') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = m.