CREATE VIEW `zendendb`.`GoodInWarehouses_RETAIL_v` AS WITH tm_shops AS (SELECT s.`МагазинГуид` FROM `zendendb`.`Магазины_fix` AS s WHERE s.`Магазин Родитель` IN ('Thomas Munz', 'Salamander', 'Закрытые SALAMANDER', 'Неиспользуемые ТМ')), good_in_sales AS (SELECT t.`КодДляОбмена` FROM `zendendb`.`ТоварыУПП` AS t WHERE (`ТипНоменклатуры` IN ('Реклама')) AND (`Товар` ILIKE '%пакет%') UNION ALL SELECT t.`КодДляОбмена` FROM `zendendb`.`ТоварыУПП` AS t WHERE `ТипНоменклатуры` NOT IN ('ИТ-оборудование', 'Реклама', 'Хоз. товары', 'Бытовая техника', 'Рекламное оборудование', 'Светильники', 'Торговое оборудование', 'Электроматериалы', 'Оборудование', '*не исп. Канц./хоз. товары', 'Канцтовары', 'производственный и хозяйственный инвентарь', 'Хоз. инвентарь', 'Материалы и оборудование', 'Офисная мебель', 'Реклама и оборудование ТМ', 'НЕ_ИСП_Оргтехника', 'Маски не медицинские', 'Пожарная безопасность', 'Строительные материалы', 'Периодические издания')) SELECT {end_date:date} AS dt, max(w.`Подразделение`) AS shop, w.`ПодразделениеГуид` AS shopGuid, w.`Склад` AS warehouse, max(w.`ВидСклада`) AS warehouseType, w.`НоменклатураГуид` AS productGuid, w.`НоменклатураКодДляОбмена` AS kdo, w.`ХарактеристикаНоменклатуры` AS size, argMax(w.`КоличествоОстаток`, w.`Период`) AS qty FROM `zendendb`.`ТоварыНаСкладахЦР` AS w WHERE (w.`ПодразделениеГуид` IN (SELECT `МагазинГуид` FROM tm_shops)) AND (w.`НоменклатураКодДляОбмена` IN (SELECT * FROM good_in_sales)) AND (toDate(`Период`) <= {end_date:date}) AND (toDate(`Период`) >= '2024-01-01') GROUP BY w.`Склад`, w.`НоменклатураГуид`, w.`НоменклатураКодДляОбмена`, w.`ХарактеристикаНоменклатуры`, w.`ПодразделениеГуид` HAVING qty != 0 SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`GoodInWarehouses_TM_MP_RETAIL_v` AS WITH tm_shops AS (SELECT s.`МагазинГуид` FROM `zendendb`.`Магазины_fix` AS s WHERE s.`Магазин Родитель` IN ('Thomas Munz', 'Salamander', 'Закрытые SALAMANDER', 'Неиспользуемые ТМ')), good_in_sales AS (SELECT t.`КодДляОбмена` FROM `zendendb`.`ТоварыУПП` AS t WHERE (`ТипНоменклатуры` IN ('Реклама')) AND (`Товар` ILIKE '%пакет%') UNION ALL SELECT t.`КодДляОбмена` FROM `zendendb`.`ТоварыУПП` AS t WHERE `ТипНоменклатуры` NOT IN ('ИТ-оборудование', 'Реклама', 'Хоз. товары', 'Бытовая техника', 'Рекламное оборудование', 'Светильники', 'Торговое оборудование', 'Электроматериалы', 'Оборудование', '*не исп. Канц./хоз. товары', 'Канцтовары', 'производственный и хозяйственный инвентарь', 'Хоз. инвентарь', 'Материалы и оборудование', 'Офисная мебель', 'Реклама и оборудование ТМ', 'НЕ_ИСП_Оргтехника', 'Маски не медицинские', 'Пожарная безопасность', 'Строительные материалы', 'Периодические издания')) SELECT {end_date:date} AS dt, max(w.`Подразделение`) AS shop, w.`ПодразделениеГуид` AS shopGuid, w.`Склад` AS warehouse, max(w.`ВидСклада`) AS warehouseType, w.`НоменклатураГуид` AS productGuid, w.`НоменклатураКодДляОбмена` AS kdo, w.`ХарактеристикаНоменклатуры` AS size, argMax(w.`КоличествоОстаток`, w.`Период`) AS qty FROM `zendendb`.`ТоварыНаСкладахЦР` AS w WHERE ((`Склад` IN ('Маркетплейс Вайлдберриз-ТМ ', 'Маркетплейс Ламода-ТМ', 'Маркетплейс СберМегаМаркет-Мюнц', 'Маркетплейс Озон-ТМ', 'Маркетплейс Яндекс-Маркет-ТМ ')) OR (w.`ПодразделениеГуид` IN (SELECT `МагазинГуид` FROM tm_shops))) AND (w.`НоменклатураКодДляОбмена` IN (SELECT * FROM good_in_sales)) AND (toDate(`Период`) <= {end_date:date}) AND (toDate(`Период`) >= '2024-01-01') GROUP BY w.`Склад`, w.`НоменклатураГуид`, w.`НоменклатураКодДляОбмена`, w.`ХарактеристикаНоменклатуры`, w.`ПодразделениеГуид` HAVING qty != 0 SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`GoodInWarehouses_TM_v` AS SELECT {end_date:date} AS dt, `Склад` AS mp, `НоменклатураКодДляОбмена` AS kdo, argMax(w.`КоличествоОстаток`, w.`Период`) AS qty FROM `zendendb`.`ТоварыНаСкладахЦР` AS w WHERE (`Склад` IN ('Маркетплейс Вайлдберриз-ТМ ', 'Маркетплейс Ламода-ТМ', 'Маркетплейс СберМегаМаркет-Мюнц', 'Маркетплейс Озон-ТМ', 'Маркетплейс Яндекс-Маркет-ТМ ')) AND (toDate(`Период`) <= {end_date:date}) AND (toDate(`Период`) >= '2024-01-01') GROUP BY w.`Склад`, w.`НоменклатураКодДляОбмена`;

CREATE VIEW `zendendb`.`GoodsInMarketplaces_TM_v` AS SELECT {end_date:date} AS dt, w.`Контрагент` AS mp, w.`НоменклатураКодДляОбмена` AS kdo, argMax(w.`КоличествоОстаток`, w.`Период`) AS qty FROM `zendendb`.`ТоварыПереданныеTM` AS w WHERE (w.`Контрагент` IN ('Вайлдберриз ООО', 'Интернет Решения ООО Thomas Munz (Озон)', 'Купишуз ООО', 'МАРКЕТПЛЕЙС ООО', 'РВБ ООО', 'Вайлдберриз-Thomas Muenz', 'Яндекс ООО', 'Яндекс Маркет ООО')) AND (toDate(`Период`) <= {end_date:date}) GROUP BY w.`Контрагент`, w.`НоменклатураКодДляОбмена`;

CREATE VIEW `zendendb`.`GoodsMovements_TM_v` AS SELECT {end_date:date} AS dt, w.`Контрагент` AS mp, `НоменклатураКодДляОбмена` AS kdo, sum(w.`Количество`) AS qty FROM `zendendb`.`ТоварыПереданныеTM` AS w WHERE (`Контрагент` IN ('Вайлдберриз ООО', 'Интернет Решения ООО Thomas Munz (Озон)', 'Купишуз ООО', 'МАРКЕТПЛЕЙС ООО', 'РВБ ООО', 'Вайлдберриз-Thomas Muenz', 'Яндекс ООО', 'Яндекс Маркет ООО')) AND (toDate(`Период`) = {end_date:date}) GROUP BY dt, w.`Контрагент`, w.`НоменклатураКодДляОбмена`;

CREATE VIEW `zendendb`.`GoodsReserveShipmentSurplus_TM_v` AS WITH warehouses_list AS (SELECT * FROM `VALUES`('НОГИНСК Ламода MG', 'НОГИНСК Озон MG', 'НОГИНСК Яндекс Маркет MG', 'НОГИНСК Вайлдберриз MG', 'НОГИНСК СберМегаМаркет MG', 'яяя РЦ ДОМОДЕДОВО Вайлдберриз ТМ', 'РЦ ДОМОДЕДОВО Вайлдберриз ТМ', 'РЦ ДОМОДЕДОВО Ламода ТМ', 'РЦ ДОМОДЕДОВО Озон ТМ', '*РЦ ДОМОДЕДОВО Вайлдберриз ТМ')), `ВТ_Данные` AS (SELECT w.`Склад`, w.`НоменклатураГуид`, argMax(w.`КоличествоОстаток`, w.`Период`) AS `КоличествоОстаток`, 0 AS `КоличествоЗаказ`, 0 AS `КоличествоВРезерве`, 0 AS `КоличествоКПередаче` FROM `zendendb`.`ТоварыНаСкладахУПП` AS w WHERE (toDate(`Период`) < {end_date:date}) AND (w.`Склад` IN (SELECT * FROM warehouses_list)) GROUP BY w.`Склад`, w.`НоменклатураГуид` HAVING `КоличествоОстаток` != 0 UNION ALL SELECT w.`Склад`, w.`НоменклатураГуид`, 0 AS `КоличествоОстаток`, 0 AS `КоличествоЗаказ`, argMax(w.`КоличествоОстаток`, w.`Период`) AS `КоличествоВРезерве`, 0 AS `КоличествоКПередаче` FROM `zendendb`.`ТоварыВРезервеНаСкладах` AS w WHERE (toDate(`Период`) < {end_date:date}) AND (w.`Склад` IN (SELECT * FROM warehouses_list)) GROUP BY w.`Склад`, w.`НоменклатураГуид` HAVING `КоличествоВРезерве` != 0 UNION ALL SELECT w.`Склад`, w.`НоменклатураГуид`, 0 AS `КоличествоОстаток`, argMax(w.`КоличествоОстаток`, w.`Период`) AS `КоличествоЗаказ`, 0 AS `КоличествоВРезерве`, 0 AS `КоличествоКПередаче` FROM `zendendb`.`ЗаказыПокупателей` AS w WHERE (toDate(`Период`) < {end_date:date}) AND (w.`Склад` IN (SELECT * FROM warehouses_list)) GROUP BY w.`Склад`, w.`НоменклатураГуид` HAVING `КоличествоЗаказ` != 0 UNION ALL SELECT w.`Склад`, w.`НоменклатураГуид`, 0 AS `КоличествоОстаток`, 0 AS `КоличествоЗаказ`, 0 AS `КоличествоВРезерве`, argMax(w.`КоличествоОстаток`, w.`Период`) AS `КоличествоКПередаче` FROM `zendendb`.`ТоварыКПередачеСоСкладов` AS w WHERE (toDate(`Период`) < {end_date:date}) AND (w.`Склад` IN (SELECT * FROM warehouses_list)) GROUP BY w.`Склад`, w.`НоменклатураГуид` HAVING `КоличествоКПередаче` != 0) SELECT {end_date:date} AS dt, w.`Склад` AS warehouse, t.`КодДляОбмена` AS kdo, sum(ifNull(w.`КоличествоВРезерве`, 0)) AS qty_reserved, sum(ifNull(w.`КоличествоКПередаче`, 0)) AS qty_claimed_for_shipment, (sum(ifNull(w.`КоличествоОстаток`, 0)) - sum(ifNull(w.`КоличествоВРезерве`, 0))) - sum(ifNull(w.`КоличествоКПередаче`, 0)) AS qty_free_stock FROM `ВТ_Данные` AS w ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`ТоварГуид` = w.`НоменклатураГуид` GROUP BY w.`Склад`, w.`НоменклатураГуид`, t.`КодДляОбмена` SETTINGS join_use_nulls = 1;

CREATE VIEW `zendendb`.`LAMODA_orders_v` AS WITH lm_dubles AS (SELECT item_id, min(s.createdAt) AS min_date, max(s.createdAt) AS max_date FROM `zendendb`.LAMODA_Sales_TM AS s FINAL GROUP BY item_id HAVING min_date != max_date), lm_sale AS (SELECT orderNr, createdAt, o.item_id AS item_id, argMax(m.art, o.updatedAt) AS art, argMax(m.art_mp, o.updatedAt) AS art_mp, argMax(m.kdo, o.updatedAt) AS kdo, argMax(o.status, o.updatedAt) AS status, argMax(o.sku, o.updatedAt) AS sku, argMax(o.item_size, o.updatedAt) AS size, argMax(if(lower(o.currency) = 'kzt', toInt32(o.partnerAgreedPrice) * (toInt32(c.Value) / c.Nominal), toInt32(o.partnerAgreedPrice)), o.updatedAt) AS partnerAgreedPrice, argMax(if(lower(o.currency) = 'kzt', toInt32(o.paidPrice) * (toInt32(c.Value) / c.Nominal), toInt32(o.paidPrice)), o.updatedAt) AS paidPrice, argMax(o.currency, o.updatedAt) AS currency FROM `zendendb`.LAMODA_Sales_TM AS o LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = toString(o.sku)) AND (m.mp = 'Ламода') LEFT JOIN `zendendb`.currency_rate AS c ON (c.Date = o.createdAt) AND (c.CharCode = 'KZT') LEFT JOIN lm_dubles AS db ON db.item_id = o.item_id WHERE ((source IS NULL) OR (source = '')) AND ((toDate(o.createdAt) >= {start_date:date}) AND (toDate(o.createdAt) <= {end_date:date})) AND ((db.min_date = toDate(o.createdAt)) OR (db.min_date IS NULL)) GROUP BY orderNr, createdAt, o.item_id) SELECT toDate(o.createdAt) AS dt, 'Ламода' AS mp, 'не указано' AS warehouseName, 'не указано' AS warehouseRegionName, 'не указано' AS warehouseOblastOkrugName, 'не указано' AS regionName, 'не указано' AS oblastOkrugName, m.art AS art, m.kdo AS kdo, o.size, toInt32(countDistinct(o.item_id)) AS order_qty, toInt32(countIfDistinct(o.item_id, (o.status IN ('Returned', 'Canceled', 'Not bought')))) AS order_qty_cancelled, toDecimal64(sum(o.partnerAgreedPrice), 3) AS order_rub, toDecimal64(sumIf(o.partnerAgreedPrice, (o.status IN ('Returned', 'Canceled', 'Not bought'))), 3) AS order_rub_cancelled, toDecimal64(sum(o.paidPrice), 3) AS order_rub_spp, toDecimal64(sumIf(o.paidPrice, (o.status IN ('Returned', 'Canceled', 'Not bought'))), 3) AS order_rub_spp_cancelled FROM lm_sale AS o ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = toString(o.sku)) AND (m.mp = 'Ламода') WHERE (toDate(o.createdAt) >= {start_date:date}) AND (toDate(o.createdAt) <= {end_date:date}) GROUP BY dt, mp, art, kdo, size ORDER BY dt DESC, kdo DESC SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`LM_by_day_v` (`Дата` Date, `Магазин` String, `Заказы руб` Nullable(Decimal(10, 3)), `Заказы НДС` Nullable(Decimal(10, 3)), `Заказы шт` Nullable(Int64), `Продажи руб` Nullable(Decimal(10, 3)), `Продажи НДС` Nullable(Decimal(10, 3)), `Продажи шт` Nullable(Int64), `Возвраты руб` Nullable(Decimal(10, 3)), `Возвраты НДС` Nullable(Decimal(10, 3)), `Возвраты шт` Nullable(Int64), `Себестоимость руб` Nullable(Decimal(10, 3)), `Одежда Заказы руб` Nullable(Decimal(10, 3)), `Одежда Заказы НДС` Nullable(Decimal(10, 3)), `Одежда Заказы шт` Nullable(Int64), `Одежда Продажи руб` Nullable(Decimal(10, 3)), `Одежда Продажи НДС` Nullable(Decimal(10, 3)), `Одежда Продажи шт` Nullable(Int64), `Одежда Возвраты руб` Nullable(Decimal(10, 3)), `Одежда Возвраты НДС` Nullable(Decimal(10, 3)), `Одежда Возвраты шт` Nullable(Int64), `Одежда Себестоимость руб` Nullable(Decimal(10, 3)), `Товарный остаток шт` Nullable(Int64), `Одежда Товарный остаток шт` Nullable(Int64), `Поступления ДС руб` Nullable(Decimal(10, 3)), `Комиссия` Nullable(Decimal(10, 3)), `Хранение` Nullable(Decimal(10, 3)), `Логистика` Nullable(Decimal(10, 3)), `Складская логистика` Nullable(Decimal(10, 3)), `Эквайринг` Nullable(Decimal(10, 3)), `Компенсации` Nullable(Decimal(10, 3)), `Штрафы` Nullable(Decimal(10, 3)), `Услуги поверенного` Nullable(Decimal(10, 3)), `Обработка брака` Nullable(Decimal(10, 3)), `Размещение возврата FBS` Nullable(Decimal(10, 3)), `Обработка опознанных излишков` Nullable(Decimal(10, 3)), `Обработка товара на FBO` Nullable(Decimal(10, 3)), `Кроссдокинг` Nullable(Decimal(10, 3)), `Обработка ошибок продавца` Nullable(Decimal(10, 3)), `Бронирование места` Nullable(Decimal(10, 3)), `Утилизация остатков` Nullable(Decimal(10, 3)), `Восстановление товара` Nullable(Decimal(10, 3)), `Приемка на складе` Nullable(Decimal(10, 3)), `Отказ возврат товара` Nullable(Decimal(10, 3)), `НДС Казахстан` Nullable(Decimal(10, 3)), `Переупаковка товара` Nullable(Decimal(10, 3)), `Подготовка товара к возвра