Canceled') AND (createdAt >= '2024-06-01') GROUP BY createdAt), sales AS (SELECT toDate(ls.delivered) AS delivered, sum(if((currency = 'kzt') AND (cr.Value > 0), divideDecimal(toDecimal32(salePrice, 0), cr.Value, 0), salePrice)) AS `Продажи руб`, sum(if((currency = 'kzt') AND (cr.Value > 0), divideDecimal(toDecimal32(salePrice, 0), cr.Value, 0) * a.nds, salePrice * a.nds)) AS `Продажи НДС`, count(id) AS `Продажи шт`, sum(if((currency = 'kzt') AND (cr.Value > 0), divideDecimal(toDecimal32(paidPrice, 0), cr.Value, 0), paidPrice)) AS `Продажи Оплата руб`, sum(sb.value_rub) AS `Себестоимость руб`, sumIf(if((currency = 'kzt') AND (cr.Value > 0), divideDecimal(toDecimal32(salePrice, 0), cr.Value, 0), salePrice), a.`Одежда`) AS `Одежда Продажи руб`, sumIf(if((currency = 'kzt') AND (cr.Value > 0), divideDecimal(toDecimal32(salePrice, 0), cr.Value, 0) * a.nds, salePrice * a.nds), a.`Одежда`) AS `Одежда Продажи НДС`, countIf(id, a.`Одежда`) AS `Одежда Продажи шт`, sumIf(sb.value_rub, a.`Одежда`) AS `Одежда Себестоимость руб` FROM `zendendb`.LAMODA_Sales AS ls FINAL LEFT JOIN art_dict AS a ON a.sku = (splitByChar('_', ls.sku)[1]) LEFT JOIN `zendendb`.currency_rate AS cr ON (cr.Date = ls.createdAt) AND (cr.CharCode = 'KZT') ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS sb ON (sb.half = if(toMonth(ls.delivered) <= 6, toStartOfYear(ls.delivered), toStartOfYear(ls.delivered) + toIntervalMonth(6))) AND (sb.kdo = a.kdo) AND (sb.price_type = 'Себестоимость') WHERE delivered >= '2024-06-01' GROUP BY delivered), refunded AS (SELECT toDate(ls.delivered) AS delivered, sum(if((currency = 'kzt') AND (cr.Value > 0), divideDecimal(toDecimal32(salePrice, 0), cr.Value, 0), salePrice)) AS `Возвраты руб`, sum(if((currency = 'kzt') AND (cr.Value > 0), divideDecimal(toDecimal32(salePrice, 0), cr.Value, 0) * a.nds, salePrice * a.nds)) AS `Возвраты НДС`, count(id) AS `Возвраты шт`, sum(if((currency = 'kzt') AND (cr.Value > 0), divideDecimal(toDecimal32(paidPrice, 0), cr.Value, 0), paidPrice)) AS `Возвраты Оплата руб`, sum(sb.value_rub) AS `Себестоимость руб`, sumIf(if((currency = 'kzt') AND (cr.Value > 0), divideDecimal(toDecimal32(salePrice, 0), cr.Value, 0), salePrice), a.`Одежда`) AS `Одежда Возвраты руб`, sumIf(if((currency = 'kzt') AND (cr.Value > 0), divideDecimal(toDecimal32(salePrice, 0), cr.Value, 0) * a.nds, salePrice * a.nds), a.`Одежда`) AS `Одежда Возвраты НДС`, countIf(id, a.`Одежда`) AS `Одежда Возвраты шт`, sumIf(sb.value_rub, a.`Одежда`) AS `Одежда Себестоимость руб` FROM `zendendb`.LAMODA_Sales AS ls FINAL LEFT JOIN art_dict AS a ON a.sku = (splitByChar('_', ls.sku)[1]) LEFT JOIN `zendendb`.currency_rate AS cr ON (cr.Date = ls.createdAt) AND (cr.CharCode = 'KZT') ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS sb ON (sb.half = if(toMonth(ls.delivered) <= 6, toStartOfYear(ls.delivered), toStartOfYear(ls.delivered) + toIntervalMonth(6))) AND (sb.kdo = a.kdo) AND (sb.price_type = 'Себестоимость') WHERE (delivered >= '2024-06-01') AND (item_status IN ('Refunded')) GROUP BY delivered), marketing AS (SELECT date, sum(cost) AS `Товарная реклама` FROM `zendendb`.LAMODA_Adv AS la GROUP BY date) SELECT o.createdAt AS `Дата`, '3.Lamoda' AS `Магазин`, o.`Заказы руб` AS `Заказы руб`, o.`Заказы НДС` AS `Заказы НДС`, o.`Заказы шт` AS `Заказы шт`, s.`Продажи руб` AS `Продажи руб`, s.`Продажи НДС` AS `Продажи НДС`, s.`Продажи шт` AS `Продажи шт`, r.`Возвраты руб` AS `Возвраты руб`, r.`Возвраты НДС` AS `Возвраты НДС`, r.`Возвраты шт` AS `Возвраты шт`, s.`Себестоимость руб` - r.`Себестоимость руб` AS `Себестоимость руб`, o.`Одежда Заказы руб` AS `Одежда Заказы руб`, o.`Одежда Заказы НДС` AS `Одежда Заказы НДС`, o.`Одежда Заказы шт` AS `Одежда Заказы шт`, s.`Одежда Продажи руб` AS `Одежда Продажи руб`, s.`Одежда Продажи НДС` AS `Одежда Продажи НДС`, s.`Одежда Продажи шт` AS `Одежда Продажи шт`, r.`Одежда Возвраты руб` AS `Одежда Возвраты руб`, r.`Одежда Возвраты НДС` AS `Одежда Возвраты НДС`, r.`Одежда Возвраты шт` AS `Одежда Возвраты шт`, s.`Одежда Себестоимость руб` - r.`Одежда Себестоимость руб` AS `Одежда Себестоимость руб`, 0 AS `Товарный остаток шт`, 0 AS `Одежда Товарный остаток шт`, 0 AS `Поступления ДС руб`, (s.`Продажи руб` - r.`Возвраты руб`) * 0.3 AS `Комиссия`, 0 AS `Хранение`, 0 AS `Логистика`, 0 AS `Складская логистика`, (s.`Продажи Оплата руб` + r.`Возвраты Оплата руб`) * 0.14 AS `Эквайринг`, 0 AS `Компенсации`, 0 AS `Штрафы`, 0 AS `Услуги поверенного`, 0 AS `Обработка брака`, 0 AS `Размещение возврата FBS`, 0 AS `Обработка опознанных излишков`, 0 AS `Обработка товара на FBO`, 0 AS `Кроссдокинг`, 0 AS `Обработка ошибок продавца`, 0 AS `Бронирование места`, 0 AS `Утилизация остатков`, 0 AS `Восстановление товара`, 0 AS `Приемка на складе`, 0 AS `Отказ возврат товара`, 0 AS `НДС Казахстан`, 0 AS `Переупаковка товара`, 0 AS `Подготовка товара к возврату`, 0 AS `Прочие удержания`, m.`Товарная реклама` AS `Товарная реклама`, 0 AS `Баннерная реклама`, 0 AS `Внешняя реклама`, 0 AS `Прочие услуги маркетинга`, 0 AS `Маркетинговое агентство` FROM orders AS o LEFT JOIN sales AS s ON o.createdAt = s.delivered LEFT JOIN refunded AS r ON o.createdAt = r.delivered LEFT JOIN marketing AS m ON o.createdAt = m.date LEFT JOIN income AS i ON o.createdAt = i.`Дата` WHERE (o.createdAt >= '2024-06-01') AND (o.createdAt < today()) SETTINGS final = 1;

CREATE VIEW `zendendb`.`LM_orders_by_size_v` AS WITH lm_dubles AS (SELECT item_id, min(s.createdAt) AS min_date, max(s.createdAt) AS max_date FROM `zendendb`.LAMODA_Sales_TM AS s FINAL GROUP BY item_id HAVING min_date != max_date), lm_sale AS (SELECT orderNr, createdAt, o.item_id AS item_id, argMax(m.art, o.updatedAt) AS art, argMax(m.art_mp, o.updatedAt) AS art_mp, argMax(m.kdo, o.updatedAt) AS kdo, argMax(o.status, o.updatedAt) AS status, argMax(o.sku, o.updatedAt) AS sku, argMax(o.item_size, o.updatedAt) AS size, argMax(if(o.currency = 'kzt', o.partnerAgreedPrice * (c.Value / c.Nominal), o.partnerAgreedPrice), o.updatedAt) AS partnerAgreedPrice, argMax(if(o.currency = 'kzt', o.paidPrice * (c.Value / c.Nominal), o.paidPrice), o.updatedAt) AS paidPrice, argMax(o.currency, o.updatedAt) AS currency FROM `zendendb`.LAMODA_Sales_TM AS o LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = toString(o.sku)) AND (m.mp = 'Ламода') LEFT JOIN `zendendb`.currency_rate AS c ON (c.Date = o.createdAt) AND (c.CharCode = 'KZT') LEFT JOIN lm_dubles AS db ON db.item_id = o.item_id WHERE (source IS NULL) AND ((toDate(o.createdAt) >= {start_date:date}) AND (toDate(o.createdAt) <= {end_date:date})) AND ((db.min_date = toDate(o.createdAt)) OR (db.min_date IS NULL)) GROUP BY orderNr, createdAt, o.item_id) SELECT toDate(o.createdAt) AS dt, 'Ламода' AS mp, m.art AS art, m.kdo AS kdo, o.size, toInt32(countDistinct(o.item_id)) AS order_qty, toInt32(countIfDistinct(o.item_id, (o.status IN ('Returned', 'Canceled', 'Not bought')))) AS order_qty_cancelled, toDecimal64(sum(o.partnerAgreedPrice), 3) AS order_rub, toDecimal64(sumIf(o.partnerAgreedPrice, (o.status IN ('Returned', 'Canceled', 'Not bought'))), 3) AS order_rub_cancelled, toDecimal64(sum(o.paidPrice), 3) AS order_rub_spp, toDecimal64(sumIf(o.paidPrice, (o.status IN ('Returned', 'Canceled', 'Not bought'))), 3) AS order_rub_spp_cancelled FROM lm_sale AS o ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = toString(o.sku)) AND (m.mp = 'Ламода') WHERE (toDate(o.createdAt) >= {start_date:date}) AND (toDate(o.createdAt) <= {end_date:date}) GROUP BY dt, mp, art, kdo, size ORDER BY dt DESC, kdo DESC SETTINGS final = 1, join_use_nulls = 1;

