e = i.`Дата` WHERE (c.date >= '2024-06-01') AND (c.date < today()) SETTINGS final = 1;

CREATE VIEW `zendendb`.`MPWarehouses_report_TM_v` AS WITH wb AS (SELECT {end_date:date} AS dt, 'Вайлдберриз' AS shop, if(w.warehouseName = 'Склад WB', 'Склад WB РФ', w.warehouseName) AS warehouse, wm.regionName AS regionName, wm.oblastOkrugName AS oblastOkrugName, m.kdo AS kdo, w.techSize AS size, toUInt64(sum(w.quantity)) AS qty FROM `zendendb`.WB_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.vendorCode) AND (m.mp = 'Вайлдберриз') ANY LEFT JOIN `zendendb`.WB_warehouses_catalog AS wm ON wm.warehouseName = w.warehouseName WHERE (w.date = {end_date:date}) AND (w.warehouseName IN ('Склад WB РФ', 'Склад WB', 'В пути возвраты на склад WB', 'В пути до получателей')) AND (w.vendorCode NOT LIKE 'wh-service%') GROUP BY warehouse, regionName, oblastOkrugName, kdo, size), oz AS (SELECT {end_date:date} AS dt, 'Озон' AS shop, replaceRegexpAll(w.warehouse_name, '_\\d+$', '') AS warehouse, trimBoth(c.region) AS regionName, trimBoth(c.district) AS oblastOkrugName, m.kdo AS kdo, splitByChar('_', w.offer_id)[2] AS size, toUInt64(sum(available_stock_count)) AS qty FROM `zendendb`.OZON_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.offer_id) AND (m.mp = 'Озон') ANY LEFT JOIN `zendendb`.OZON_clasters_TM AS c ON c.cluster_id = w.cluster_id WHERE (toDate(w.timestamp) = {end_date:date}) AND (available_stock_count != 0) AND (warehouse != '') GROUP BY warehouse, regionName, oblastOkrugName, kdo, size UNION ALL SELECT {end_date:date} AS dt, 'Озон' AS shop, 'В пути возвраты на склад OZ' AS warehouse, NULL AS regionName, NULL AS oblastOkrugName, m.kdo AS kdo, splitByChar('_', w.offer_id)[2] AS size, toUInt64(sum(return_from_customer_stock_count)) AS qty FROM `zendendb`.OZON_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.offer_id) AND (m.mp = 'Озон') ANY LEFT JOIN `zendendb`.OZON_clasters_TM AS c ON c.cluster_id = w.cluster_id WHERE toDate(w.timestamp) = {end_date:date} GROUP BY warehouse_name, regionName, oblastOkrugName, kdo, size UNION ALL SELECT {end_date:date} AS dt, 'Озон' AS shop, 'В пути до получателей' AS warehouse, NULL AS regionName, NULL AS oblastOkrugName, m.kdo AS kdo, splitByChar('_', w.offer_id)[2] AS size, toUInt64(sum(outbound_pending_delivery)) AS qty FROM `zendendb`.OZON_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.offer_id) AND (m.mp = 'Озон') ANY LEFT JOIN `zendendb`.OZON_clasters_TM AS c ON c.cluster_id = w.cluster_id WHERE toDate(w.timestamp) = {end_date:date} GROUP BY warehouse_name, regionName, oblastOkrugName, kdo, size), lm AS (SELECT {end_date:date} AS dt, 'Ламода' AS shop, 'Центральный склад Ламода' AS warehouse, NULL AS regionName, 'Центральный федеральный округ' AS oblastOkrugName, m.kdo AS kdo, if(match(if(countMatches(splitByChar('-', w.sku)[-1], '_') > 0, splitByChar('_', w.sku)[-1], splitByChar('-', w.sku)[-1]), '^\\d{4,}$'), '', if(countMatches(splitByChar('-', w.sku)[-1], '_') > 0, splitByChar('_', w.sku)[-1], splitByChar('-', w.sku)[-1])) AS size, sum(w.quantity) AS qty FROM `zendendb`.LAMODA_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.sku) AND (m.mp = 'Ламода') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = m.kdo WHERE toDate(w.date) = {end_date:date} GROUP BY kdo, size), ya AS (SELECT {end_date:date} AS dt, 'Яндекс' AS shop, warehouseName AS warehouse, wm.region AS regionName, wm.okrug AS oblastOkrugName, m.kdo AS kdo, if((splitByChar('_', offerId)[-1]) = offerId, '', splitByChar('_', offerId)[-1]) AS size, sum(w.count) AS qty FROM `zendendb`.YANDEX_Warehouse_TM AS w ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = w.offerId) AND (m.mp = 'Яндекс') ANY LEFT JOIN `zendendb`.YANDEX_warehouses AS wm ON wm.id = w.warehouseId WHERE (toDate(w.date) = {end_date:date}) AND (w.type = 'AVAILABLE') GROUP BY warehouseName, regionName, oblastOkrugName, kdo, size UNION ALL WITH o AS (SELECT {end_date:date} AS dt, o.ORDER_ID, o.SHOP_SKU, m.kdo AS kdo, if((splitByChar('_', o.SHOP_SKU)[-1]) = o.SHOP_SKU, '', splitByChar('_', o.SHOP_SKU)[-1]) AS size, argMin(o.DELIVERED_OR_RETURNED, o.STATUS_CHANGED) AS DELIVERED_OR_RETURNED, argMin(o.OFFER_STATUS, o.STATUS_CHANGED) AS OFFER_STATUS FROM `zendendb`.YANDEX_Orders_TM AS o FINAL ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = o.SHOP_SKU) AND (m.mp = 'Яндекс') WHERE toDate(o.STATUS_CHANGED) = {end_date:date} GROUP BY toDate(o.STATUS_CHANGED), o.ORDER_ID, m.kdo, SHOP_SKU) SELECT dt, 'Яндекс' AS shop, multiIf((OFFER_STATUS IN ('Отгружен')), 'В пути до получателей', (OFFER_STATUS IN ('Невыкуп отправлен', 'Возврат отправлен', 'Возврат принят', 'Невыкуп принят', 'Возврат оформлен')), 'В пути возвраты на склад YA', '') AS warehouse, NULL AS regionName, NULL AS oblastOkrugName, kdo, size, toUInt64(sum(DELIVERED_OR_RETURNED)) AS qty FROM o GROUP BY dt, shop, warehouse, regionName, oblastOkrugName, kdo, size HAVING warehouse != ''), all_mp AS (SELECT * FROM wb UNION ALL SELECT * FROM oz UNION ALL SELECT * FROM ya UNION ALL SELECT * FROM lm) SELECT r.dt AS dt, r.shop AS shop, r.warehouse AS warehouse, r.regionName AS regionName, r.oblastOkrugName AS oblastOkrugName, r.kdo AS kdo, r.size AS size, r.qty AS qty, c.value_rub AS cost_val, multiIf((t.`СвойствоТорговаяМарка` IN ('ARA', 'Bugatti', 'KINETIX', 'LUMBERJACK', 'POLARIS', 'Reebok', 'REMONTE', 'Rieker', 'U.S. POLO ASSN.')), 'ПТМ', (t.`СвойствоТорговаяМарка` IN ('Bridget', 'BRIGGS', 'LOLLI|POLLI', 'MUNZ Shoes', 'MUNZ YOUNG', 'O2')), 'СТМ', (t.`СвойствоТорговаяМарка` IN ('LURCHI', 'M-Shoes', 'SALAMANDER')), 'Salamander', (t.`СвойствоТорговаяМарка` IN ('Thomas Munz', 'Thomas Munz black')), 'Thomas Munz', '') AS `Группа`, t.`Артикул` AS `Артикул`, t.`СвойствоВидОбуви` AS `СвойствоВидОбуви`, t.`СвойствоГод` AS `СвойствоГод`, t.`СвойствоМатериалВерха` AS `СвойствоМатериалВерха`, t.`СвойствоРод` AS `СвойствоРод`, t.`СвойствоСезон` AS `СвойствоСезон`, t.`СвойствоТорговаяМарка` AS `СвойствоТорговаяМарка`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, t.`СтавкаНДС` AS `СтавкаНДС`, t.OrderTM AS OrderTM, t.`СвойствоКоллекцияПроизводства` AS `СвойствоКоллекцияПроизводства`, t.`СвойствоКоллекцияПроизводстваКомментарий` AS `СвойствоКоллекцияПроизводстваКомментарий`, t.`ПовторАналогНовинка` AS `ПовторАналогНовинка` FROM all_mp AS r ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = r.kdo LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS c ON (c.half = if(toMonth(r.dt) <= 6, toStartOfYear(r.dt), toStartOfYear(r.dt) + toIntervalMonth(6))) AND (c.kdo = r.kdo) SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`OMS_pickup_orders_v` AS WITH oms_orders AS (SELECT ID, XML_ID, max(z.DATE_INSERT) AS DATE_INSERT, argMax(COMPANY_NAME, z.DATE_UPDATE) AS COMPANY_NAME, argMax(SHOP_NAME, z.DATE_UPDATE) AS SHOP_NAME, argMax(PRICE, z.DATE_UPDATE) AS PRICE, argMax(STATUS, z.DATE_UPDATE) AS STATUS, argMax(`Склад самовывоза`, z.DATE_UPDATE) AS `Склад самовывоза` FROM `zendendb`.`ЗаказКлиента` AS z FINAL WHERE ((CANCELED = 0) AND (DATE_CANCELED IS NULL)) AND ((REASON_CANCELED IS NULL) OR (REASON_CANCELED = '')) AND (z.STATUS NOT IN ('Отказ', 'Аннулирован', 'Возврат')) AND (DELIVERY_NAME = 'Самовывоз из салона') AND (COMPANY_CODE != 'ZENDEN') AND (z.DATE_UPDATE >= {start_date:date}) GROUP BY ID, XML_ID ORDER BY ID ASC), accountable AS (SELECT toUInt32(`ЗаказПокупателя`) AS ORDER_ID, max(o.`Период`) AS `Период`, `НомерЗаказаИнтернетМагазина`, `Ответственный`, `Источник`, `Статус`, `Подразделение`, `ПодразделениеГуид` FROM `zendendb`.`ДанныеЗаказовОМС` AS o WHERE (o.`Источник` NOT ILIKE '%zenden%') AND (o.`Период` >= {start_date:date}) AND (o.`Статус` != 'Отказ') GROUP BY ORDER_ID, `НомерЗаказаИнтернетМагазина`, `Ответственный`, `Источник`, `Статус`, `Подразделение`, `ПодразделениеГуид` ORDER BY ORDER_ID ASC), oms_order_info AS (SELECT o.ID AS ID, o.XML_ID AS `Номер заказа`, o.DATE_INSERT AS `Дата заказа`, o.PRICE AS `Сумма заказа`, ifNull(vid.`ПодразделениеГуид`, sbor.`ПодразделениеГуид`) AS `ПодразделениеГуид`, o.`Склад самовывоза` AS `Склад самовывоза`, o.STATUS AS `Статус`, o.COMPANY_NAME AS `Компания`, ifNull(sbor.`Период`, vid.`Период`) AS `Дата сборки`, ifNull(sbor.`Ответственный`, vid.`Ответственный`) AS `Ответственный сборки`, if((vid.`Период` IS NULL) AND (o.STATUS IN ('Выполнен', 'Частично выполнен')), sbor.`Период`, vid.`Период`) AS `Дата выдачи`, if((vid.`Ответственный` IS NULL) AND (o.STATUS IN ('Выполнен', 'Частично выполнен')), sbor.`Ответственный`, vid.`Ответственный`) AS `Ответственный выдачи` FROM oms_orders AS o LEFT JOIN accountable AS sbor ON (o.ID = sbor.ORDER_ID) AND (sbor.`Статус` = 'Товар поступил в пункт самовывоза') LEFT JOIN accountable AS vid ON (o.ID = vid.ORDER_ID) AND (vid.`Статус` = 'Выкуплен')) SELECT ID, `Номер заказа`, `Дата заказа`, `Сумма заказа`, `Статус`, `Компания`, `Дата сборки`, `Ответственный сборки`, `Дата выдачи`, `Ответственный выдачи`, o.`Склад самовывоза` AS `Склад самовывоза`, ifNull(m.`Магазин`, m2.`Магазин`) AS `Магазин`, ifNull(m.`Магазин Родитель`, m2.`Магазин Родитель`) AS `Магазин Родитель`, if(empty(m.`Иерархия`), m2.`Иерархия`, m.`Иерархия`) AS `Иерархия`, ifNull(m.`Дивизиональный Директор`, m2.`Дивизиональный Директор`) AS `Дивизиональный Директор`, ifNull(m.`Территорияальный Менеджер`, m2.`Территорияальный Менеджер`) AS `Территориальный Менеджер`, ifNull(m.`Региональный Директор`, m2.`Региональный Директор`) AS `Региональный Директор`, ifNull(m.`Город`, m2.`Город`) AS `Город`, ifNull(m.`Регион`, m2.`Регион`) AS `Регион`, ifNull(m.`ТипМагазинаДляПланированияУПП`, m2.`ТипМагазинаДляПланированияУПП`) AS `ТипМагазинаДляПланированияУПП` FROM oms_order_info AS o ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = o.`ПодразделениеГуид` ANY LEFT JOIN `zendendb`.OMS_shop_mapping_v AS om ON om.`Склад самовывоза` = o.`Склад самовывоза` ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m2 ON m2.`МагазинГуид` = om.`МагазинГуид` WHERE `Дата заказа` >= {start_date:date} SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`OMS_shop_mapping_v` (`Склад самовывоза` Nullable(String), `Склад самовывоза Гуид` String, `МагазинГуид` Nullable(String), `Магазин` Nullable(String)) AS WITH onec_shop AS (SELECT `Магазин`, `МагазинГуид`, lowerUTF8(trimBoth(splitByChar('-', assumeNotNull(`Магазин`))[-2])) AS shop_for_join FROM `zendendb`.`Магазины_fix` AS m WHERE `Магазин Родитель` IN ('Розница Mascotte', 'Закрытые Mascotte')), oms_shop AS (SELECT DISTINCT z.`Склад самовывоза` AS `Склад самовывоза`, z.`Склад самовывоза Гуид` AS `Склад самовывоза Гуид`, ifNull(ifNull(m1.`МагазинГуид`, m2.`МагазинГуид`), m3.`МагазинГуид`) AS `МагазинГуид`, ifNull(ifNull(m1.`Магазин`, m2.`Магазин`), m3.`МагазинГуид`) AS `Магазин` FROM `zendendb`.`ЗаказКлиента` AS z LEFT JOIN `zendendb`.`Магазины_fix` AS m1 ON m1.`МагазинГуид` = z.`Склад самовывоза Гуид` LEFT JOIN `zendendb`.`Магазины_fix` AS m2 ON m2.`Магазин` = z.`Склад самовывоза` LEFT JOIN `zendendb`.b_catalog_store_mysql AS cs ON cs.TITLE = z.`Склад самовывоза` LEFT JOIN `zendendb`.`Магазины_fix` AS m3 ON m3.`МагазинГуид` = cs.XML_ID WHERE (z.DELIVERY_NAME = 'Самовывоз из салона') AND (z.COMPANY_CODE != 'ZENDEN') AND (z.DATE_UPDATE >= '2025-07-01') AND (z.`Склад самовывоза` IS NOT NULL)), not_found AS (SELECT o.`Склад самовывоза`, o.`Склад самовывоза Гуид`, m.`МагазинГуид` AS `МагазинГуид`, m.`Магазин` AS `Магазин` FROM oms_shop AS o LEFT JOIN onec_shop AS m ON m.shop_for_join = trimBoth(lowerUTF8(splitByString('ТЦ', assumeNotNull(o.`Склад самовывоза`))[2])) WHERE o.`МагазинГуид` IS NULL) SELECT * FROM not_found UNION ALL WITH onec_shop AS (SELECT `Магазин`, `МагазинГуид`, lowerUTF8(trimBoth(splitByChar('-', assumeNotNull(`Магазин`))[-2])) AS shop_for_join FROM `zendendb`.`Магазины_fix` AS m WHERE `Магазин Родитель` IN ('Розница Mascotte', 'Закрытые Mascotte')), oms_shop AS (SELECT DISTINCT z.`Склад самовывоза` AS `Склад самовывоза`, z.`Склад самовывоза Гуид` AS `Склад самовывоза Гуид`, ifNull(ifNull(m1.`МагазинГуид`, m2.`МагазинГуид`), m3.`МагазинГуид`) AS `МагазинГуид`, ifNull(ifNull(m1.`Магазин`, m2.`Магазин`), m3.`МагазинГуид`) AS `Магазин` FROM `zendendb`.`ЗаказКлиента` AS z LEFT JOIN `zendendb`.`Магазины_fix` AS m1 ON m1.`МагазинГуид` = z.`Склад самовывоза Гуид` LEFT JOIN `zendendb`.`Магазины_fix` AS m2 ON m2.`Магазин` = z.`Склад самовывоза` LEFT JOIN `zendendb`.b_catalog_store_mysql AS cs ON cs.TITLE = z.`Склад самовывоза` LEFT JOIN `zendendb`.`Магазины_fix` AS m3 ON m3.`МагазинГуид` = cs.XML_ID WHERE (z.DELIVERY_NAME = 'Самовывоз из салона') AND (z.COMPANY_CODE != 'ZENDEN') AND (z.DATE_UPDATE >= '2025-07-01') AND (z.`Склад самовывоза` IS NOT NULL)), not_found AS (SELECT o.`Склад самовывоза`, o.`Склад самовывоза Гуид`, m.`МагазинГуид` AS `МагазинГуид`, m.`Магазин` AS `Магазин` FROM oms_shop AS o LEFT JOIN onec_shop AS m ON m.shop_for_join = trimBoth(lowerUTF8(splitByString('ТЦ', assumeNotNull(o.`Склад самовывоза`))[2])) WHERE o.`МагазинГуид` IS NULL) SELECT * FROM oms_shop WHERE `МагазинГуид` IS NOT NULL SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`OZON_WH_ARCHIVE_v` (`dt` Date, `shop` String, `warehouse` String, `regionName` String, `oblastOkrugName` String, `kdo` UInt32, `size` LowCardinality(String), `qty` Int32, `cost_val` Nullable(Decimal(10, 5)), `Группа` String, `Артикул` Nullable(String), `СвойствоВидОбуви` Nullable(String), `СвойствоГод` Nullable(String), `СвойствоМатериалВерха` Nullable(String), `СвойствоРод` Nullable(String), `СвойствоСезон` Nullable(String), `СвойствоТорговаяМарка` Nullable(String), `ТипНоменклатуры` Nullable(String), `СтавкаНДС` Nullable(String), `OrderTM` Nullable(String), `СвойствоКоллекцияПроизводства` Nullable(String), `СвойствоКоллекцияПроизводстваКомментарий` Nullable(String), `ПовторАналогНовинка` Nullable(String)) AS WITH oz AS (SELECT dt, 'Озон' AS shop, 'Центральный склад' AS warehouse, '' AS regionName, 'Центральный федеральный округ' AS oblastOkrugName, w.kdo AS kdo, w.size, w.qty FROM `zendendb`.`ТоварыНаСкладахAPI_TM` AS w WHERE (w.shop = 'Озон-ТМ') AND (w.dt < '2026-05-07') AND (w.dt >= '2026-01-01')) SELECT r.dt AS dt, r.shop AS shop, r.warehouse AS warehouse, r.regionName AS regionName, r.oblastOkrugName AS oblastOkrugName, r.kdo AS kdo, r.size AS size, r.qty AS qty, c.value_rub AS cost_val, multiIf((t.`СвойствоТорговаяМарка` IN ('ARA', 'Bugatti', 'KINETIX', 'LUMBERJACK', 'POLARIS', 'Reebok', 'REMONTE', 'Rieker', 'U.S. POLO ASSN.')), 'ПТМ', (t.`СвойствоТорговаяМарка` IN ('Bridget', 'BRIGGS', 'LOLLI|POLLI', 'MUNZ Shoes', 'MUNZ YOUNG', 'O2')), 'СТМ', (t.`СвойствоТорговаяМарка` IN ('LURCHI', 'M-Shoes', 'SALAMANDER')), 'Salamander', (t.`СвойствоТорговаяМарка` IN ('Thomas Munz', 'Thomas Munz black')), 'Thomas Munz', '') AS `Группа`, t.`Артикул` AS `Артикул`, t.`СвойствоВидОбуви` AS `СвойствоВидОбуви`, t.`СвойствоГод` AS `СвойствоГод`, t.`СвойствоМатериалВерха` AS `СвойствоМатериалВерха`, t.`СвойствоРод` AS `СвойствоРод`, t.`СвойствоСезон` AS `СвойствоСезон`, t.`СвойствоТорговаяМарка` AS `СвойствоТорговаяМарка`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, t.`СтавкаНДС` AS `СтавкаНДС`, t.OrderTM AS OrderTM, t.`СвойствоКоллекцияПроизводства` AS `СвойствоКоллекцияПроизводства`, t.`СвойствоКоллекцияПроизводстваКомментарий` AS `СвойствоКоллекцияПроизводстваКомментарий`, t.`ПовторАналогНовинка` AS `ПовторАналогНовинка` FROM oz AS r ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = r.kdo LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS c ON (c.half = if(toMonth(r.dt) <= 6, toStartOfYear(r.dt), toStartOfYear(r.dt) + toIntervalMonth(6))) AND (c.kdo = r.kdo) SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`OZON_orders_v` AS SELECT toDate(o.`Принят в обработку`) AS dt, 'Озон' AS mp, 'не указано' AS warehouseName, 'не указано' AS warehouseRegionName, 'не указано' AS warehouseOblastOkrugName, 'не указано' AS regionName, 'не указано' AS oblastOkrugName, m.art AS art, m.kdo AS kdo, replaceAll(splitByChar('_', o.`Артикул`)[2], ',', '.') AS size, toInt32(sum(o.`Количество`)) AS order_qty, toInt32(sumIf(o.`Количество`, o.`Статус` = 'Отменён')) AS order_qty_cancelled, toDecimal64(sum(o.`Ваша цена`), 3) AS order_rub, toDecimal64(sumIf(o.`Ваша цена`, o.`Статус` = 'Отменён'), 3) AS order_rub_cancelled, toDecimal64(sum(o.`Оплачено покупателем`), 3) AS order_rub_spp, toDecimal64(sumIf(o.`Оплачено покупателем`, o.`Статус` = 'Отменён'), 3) AS order_rub_spp_cancelled FROM `zendendb`.OZON_Orders_TM AS o ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = o.`Артикул`) AND (m.mp = 'Озон') WHERE (toDate(o.`Принят в обработку`) >= {start_date:date}) AND (toDate(o.`Принят в обработку`) <= {end_date:date}) GROUP BY dt, mp, art, kdo, size SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`OZ_by_day_v` (`Дата` Date, `Магазин` String, `Заказы руб` Nullable(Decimal(10, 3)), `Заказы НДС` Nullable(Decimal(10, 3)), `Заказы шт` Nullable(Int64), `Продажи руб` Nullable(Decimal(10, 3)), `Продажи НДС` Nullable(Decimal(10, 3)), `Продажи шт` Nullable(Int64), `Возвраты руб` Nullable(Decimal(10, 3)), `Возвраты НДС` Nullable(Decimal(10, 3)), `Возвраты шт` Nullable(Int64), `Себестоимость руб` Nullable(Decimal(10, 3)), `Одежда Заказы руб` Nullable(Decimal(10, 3)), `Одежда Заказы НДС` Nullable(Decimal(10, 3)), `Одежда Заказы шт` Nullable(Int64), `Одежда Продажи руб` Nullable(Decimal(10, 3)), `Одежда Продажи НДС` Nullable(Decimal(10, 3)), `Одежда Продажи шт` Nullable(Int64), `Одежда Возвраты руб` Nullable(Decimal(10, 3)), `Одежда Возвраты НДС` Nullable(Decimal(10, 3)), `Одежда Возвраты шт` Nullable(Int64), `Одежда Себестоимость руб` Nullable(Decimal(10, 3)), `Товарный остаток шт` Nullable(Int64), `Одежда Товарный остаток шт` Nullable(Int64), `Поступления ДС руб` Nullable(Decimal(10, 3)), `Комиссия` Nullable(Decimal(10, 3)), `Хранение` Nullable(Decimal(10, 3)), `Логистика` Nullable(Decimal(10, 3)), `Складская логистика` Nullable(Decimal(10, 3)), `Эквайринг` Nullable(Decimal(10, 3)), `Компенсации` Nullable(Decimal(10, 3)), `Штрафы` Nullable(Decimal(10, 3)), `Услуги поверенного` Nullable(Decimal(10, 3)), `Обработка брака` Nullable(Decimal(10, 3)), `Размещение возврата FBS` Nullable(Decimal(10, 3)), `Обработка опознанных излишков` Nullable(Decimal(10, 3)), `Обработка товара на FBO` Nullable(Decimal(10, 3)), `Кроссдокинг` Nullable(Decimal(10, 3)), `Обработка ошибок продавца` Nullable(Decimal(10, 3)), `Бронирование места` Nullable(Decimal(10, 3)), `Утилизация остатков` Nullable(Decimal(10, 3)), `Восстановление товара` Nullable(Decimal(10, 3)), `Приемка на складе` Nullable(Decimal(10, 3)), `Отказ возврат товара` Nullable(Decimal(10, 3)), `НДС Казахстан` Nullable(Decimal(10, 3)), `Переупаковка товара` Nullable(Decimal(10, 3)), `Подготовка товара к возврату` Nullable(Decimal(10, 3)), `Прочие удержания` Nullable(Decimal(10, 3)), `Товарная реклама` Nullable(Int64), `Баннерная реклама` Nullable(Decimal(10, 3)), `Внешняя реклама` Nullable(Decimal(10, 3)), `Прочие услуги маркетинга` Nullable(Decimal(10, 3)), `Маркетинговое агентство` Nullable(Decimal(10, 3))) AS WITH income AS (SELECT toDate(pp.`Дата`) AS `Дата`, sum(`СуммаДокумента`) AS `Поступления ДС руб` FROM `zendendb`.`ПлатежноеПоручениеВходящее` AS pp WHERE (`Подразделение` IN ('Отдел по работе с Market Places Zenden')) AND (`Контрагент` = 'Интернет Решения ООО') GROUP BY `Дата`), ozon_orders AS (SELECT toDate(in_process_at) AS in_process_at, offer_id, quantity, fin_price, sku FROM `zendendb`.OZON_FBO_Orders AS fbo FINAL UNION ALL SELECT toDate(in_process_at) AS in_process_at, offer_id, quantity, fin_price, sku FROM `zendendb`.OZON_FBS_Orders AS fbs FINAL), arts AS (SELECT DISTINCT splitByChar('_', offer_id)[1] AS art, sku FROM ozon_orders WHERE art != ''), art_dict AS (SELECT DISTINCT art, t.`КодДляОбмена` AS kdo, sku, t.`ТипНоменклатуры` IN ('Изделия бельевые', 'Изделия верхние', 'Одежда') AS `Одежда`, round(toInt32OrZero(splitByChar('%', assumeNotNull(t.`СтавкаНДС`))[1]) / (100 + toInt32OrZero(splitByChar('%', assumeNotNull(t.`СтавкаНДС`))[1])), 4) AS nds FROM arts AS a ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`Артикул` = a.art), ozon_orders_by_day AS (SELECT in_process_at, sum(quantity) AS `Заказы шт`, sum(fin_price) AS `Заказы руб`, sum(fin_price * a.nds) AS `Заказы НДС`, sumIf(quantity, a.`Одежда`) AS `Одежда Заказы шт`, sumIf(fin_price, a.`Одежда`) AS `Одежда Заказы руб`, sumIf(fin_price * a.nds, a.`Одежда`) AS `Одежда Заказы НДС` FROM ozon_orders AS o LEFT JOIN art_dict AS a ON a.sku = o.sku GROUP BY in_process_at), ozon_sales AS (SELECT toDate(operation_date) AS operation_date, countIf(operation_type IN ('OperationAgentDeliveredToCustomer')) AS `Продажи шт`, sumIf(accruals_for_sale, (operation_type IN ('OperationAgentDeliveredToCustomer'))) AS `Продажи руб`, sumIf(accruals_for_sale * a.nds, (operation_type IN ('OperationAgentDeliveredToCustomer'))) AS `Продажи НДС`, countIf(operation_type IN ('ClientReturnAgentOperation', 'OperationAgentStornoDeliveredToCustomer')) AS `Возвраты шт`, abs(sumIf(accruals_for_sale, (operation_type IN ('ClientReturnAgentOperation', 'OperationAgentStornoDeliveredToCustomer')))) AS `Возвраты руб`, abs(sumIf(accruals_for_sale * a.nds, (operation_type IN ('ClientReturnAgentOperation', 'OperationAgentStornoDeliveredToCustomer')))) AS `Возвраты НДС`, sumIf(sb.value_rub, (operation_type IN ('OperationAgentDeliveredToCustomer'))) - sumIf(sb.value_rub, (operation_type IN ('ClientReturnAgentOperation', 'OperationAgentStornoDeliveredToCustomer'))) AS `Себестоимость руб`, countIf((operation_type IN ('OperationAgentDeliveredToCustomer')) AND a.`Одежда`) AS `Одежда Продажи шт`, sumIf(accruals_for_sale, (operation_type IN ('OperationAgentDeliveredToCustomer')) AND a.`Одежда`) AS `Одежда Продажи руб`, sumIf(accruals_for_sale * a.nds, (operation_type IN ('OperationAgentDeliveredToCustomer')) AND a.`Одежда`) AS `Одежда Продажи НДС`, countIf((operation_type IN ('ClientReturnAgentOperation', 'OperationAgentStornoDeliveredToCustomer')) AND a.`Одежда`) AS `Одежда Возвраты шт`, abs(sumIf(accruals_for_sale, (operation_type IN ('ClientReturnAgentOperation', 'OperationAgentStornoDeliveredToCustomer')) AND a.`Одежда`)) AS `Одежда Возвраты руб`, abs(sumIf(accruals_for_sale * a.nds, (operation_type IN ('ClientReturnAgentOperation', 'OperationAgentStornoDeliveredToCustomer')) AND a.`Одежда`)) AS `Одежда Возвраты НДС`, sumIf(sb.value_rub, (operation_type IN ('OperationAgentDeliveredToCustomer')) AND a.`Одежда`) - sumIf(sb.value_rub, (operation_type IN ('ClientReturnAgentOperation', 'OperationAgentStornoDeliveredToCustomer')) AND a.`Одежда`) AS `Одежда Себестоимость руб` FROM `zendendb`.OZON_TRANSACTION_Orders AS o FINAL LEFT JOIN art_dict AS a ON a.sku = o.sku ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS sb ON (sb.half = if(toMonth(o.operation_date) <= 6, toStartOfYear(o.operation_date), toStartOfYear(o.operation_date) + toIntervalMonth(6))) AND (sb.kdo = a.kdo) AND (sb.price_type = 'Себестоимость') GROUP BY operation_date), ozon_spends AS (SELECT toDate(operation_date) AS operation_date, -(sumIf(o.sale_commission, (operation_type IN ('OperationAgentDeliveredToCustomer', 'OperationAgentStornoDeliveredToCustomer'))) + sumIf(o.sale_commission, operation_type = 'ClientReturnAgentOperation')) AS `Комиссия`, abs(sumIf(o.amount, (operation_type IN ('MarketplaceRedistributionOfAcquiringOperation')))) AS `Эквайринг`, abs(sumIf(o.amount, (operation_type IN ('MarketplaceSellerCompensationOperation', 'AccrualWithoutDocs', 'AccrualConsigWriteOff', 'AccrualInternalClaim', 'OperationCorrectionSeller', 'OperationClaim', 'OperationDefectiveWriteOff', 'OperationLackWriteOff', 'MarketplaceSellerShippingCompensationReturnOperation')))) AS `Компенсации`, abs(sumIf(o.amount, (operation_type IN ('OperationMarketplaceServiceProcessingSpoilageSurplus', 'AccrualConsigDefectiveWriteOff')))) AS `Обработка брака`, abs(sumIf(o.amount, (operation_type IN ('OperationMarketplaceServiceSupplyInboundSupplySurplus', 'OperationMarketplaceServiceProcessingNotIdentifiedSurplus', 'OperationMarketplaceServiceSupplyInboundCargoSurplus')))) AS `Обработка опознанных излишков`, abs(sumIf(o.amount, (operation_type IN ('OperationMarketplaceSupplyAdditional')))) AS `Обработка товара на FBO`, abs(sumIf(o.amount, (operation_type IN ('OperationMarketplaceCrossDockServiceWriteOff', 'MarketplaceServiceItemCrossdocking')))) AS `Кроссдокинг`, abs(sumIf(o.amount, (operation_type IN ('DefectRateCancellation', 'DefectRateShipmentDelay', 'DefectRateDetailed', 'DefectRateCancellation')))) AS `Обработка ошибок продавца`, abs(sumIf(o.amount, (operation_type IN ('OperationMarketplaceServiceSupplyInboundSupplyShortage', 'OperationMarketplaceServiceSupplyInboundCargoShortage')))) AS `Бронирование места`, abs(sumIf(o.amount, (operation_type IN ('OperationMarketplaceServiceStockDisposal', 'OperationMarketplaceReturnStorageServiceAtThePickupPointFbs', 'DisposalReasonDamagedPackaging', 'DisposalReasonDamagedReturn', 'DisposalReasonFailedToPickupOnTime', 'DisposalReasonSellerOrderedUtilization', 'DisposalReasonRezon', 'DisposalReasonScattered')))) AS `Утилизация остатков`, abs(sumIf(o.amount, (operation_type IN ('OperationMarketplaceServicePreparingToReturn')))) AS `Подготовка товара к возврату` FROM `zendendb`.OZON_TRANSACTION_Orders AS o FINAL GROUP BY operation_date), ozon_marketing AS (SELECT date, sum(moneySpent) + sum(prepaymentSpent) AS `Товарная реклама` FROM `zendendb`.OZON_Expense AS oe FINAL WHERE (oe.title NOT ILIKE '%баннер%') OR (oe.title NOT ILIKE '%пакет%') OR (oe.title NOT ILIKE '%шторк%') GROUP BY date), ozon_banner AS (SELECT date, sum(moneySpent) + sum(prepaymentSpent) AS `Баннерная реклама` FROM `zendendb`.OZON_Expense AS oe WHERE (oe.title ILIKE '%баннер%') OR (oe.title ILIKE '%пакет%') OR (oe.title ILIKE '%шторк%') GROUP BY date), ozon_other_marketing AS (SELECT toDate(o.operation_date) AS operation_date, abs(sumIf(o.amount, (operation_type IN ('OperationPointsForReviews', 'OperationMarketplaceServicePremiumCashbackIndividualPoints', 'OperationSubscriptionPremiumPlus', 'OperationMarketplaceServicePremiumCashbackBonusAccrual')))) AS `Прочие услуги маркетинга` FROM `zendendb`.OZON_TRANSACTION_Orders AS o GROUP BY operation_date), warehouse AS (SELECT date, sum(quantityFBO + quantityFBS) AS `Товарный остаток шт`, sumIf(quantityFBO + quantityFBS, a.`Одежда`) AS `Одежда Товарный остаток шт` FROM `zendendb`.OZON_Warehouse AS w ANY LEFT JOIN art_dict AS a ON lower(replaceAll(a.art, ' ', '')) = lower(replaceAll(splitByChar('_', w.offer_id)[1], ' ', '')) GROUP BY date) SELECT o.in_process_at AS `Дата`, '2.Ozon' AS `Магазин`, o.`Заказы руб` AS `Заказы руб`, o.`Заказы НДС` AS `Заказы НДС`, o.`Заказы шт` AS `Заказы шт`, sl.`Продажи руб` AS `Продажи руб`, sl.`Продажи НДС` AS `Продажи НДС`, sl.`Продажи шт` AS `Продажи шт`, sl.`Возвраты руб` AS `Возвраты руб`, sl.`Возвраты НДС` AS `Возвраты НДС`, sl.`Возвраты шт` AS `Возвраты шт`, sl.`Себестоимость руб` AS `Себестоимость руб`, o.`Одежда Заказы шт` AS `Одежда Заказы шт`, o.`Одежда Заказы руб` AS `Одежда Заказы руб`, o.`Одежда Заказы НДС` AS `Одежда Заказы НДС`, sl.`Одежда Продажи руб` AS `Одежда Продажи руб`, sl.`Одежда Продажи НДС` AS `Одежда Продажи НДС`, sl.`Одежда Продажи шт` AS `Одежда Продажи шт`, sl.`Одежда Возвраты руб` AS `Одежда Возвраты руб`, sl.`Одежда Возвраты НДС` AS `Одежда Возвраты НДС`, sl.`Одежда Возвраты шт` AS `Одежда Возвраты шт`, sl.`Одежда Себестоимость руб` AS `Одежда Себестоимость руб`, w.`Товарный остаток шт` AS `Товарный остаток шт`, w.`Одежда Товарный остаток шт` AS `Одежда Товарный остаток шт`, ifNull(i.`Поступления ДС руб`, 0) AS `Поступления ДС руб`, s.`Комиссия` AS `Комиссия`, 0 AS `Хранение`, 0 AS `Логистика`, 0 AS `Складская логистика`, s.`Эквайринг` AS `Эквайринг`, s.`Компенсации` AS `Компенсации`, 0 AS `Штрафы`, 0 AS `Услуги поверенного`, s.`Обработка брака` AS `Обработка брака`, 0 AS `Размещение возврата FBS`, s.`Обработка опознанных излишков` AS `Обработка опознанных излишков`, s.`Обработка товара на FBO` AS `Обработка товара на FBO`, s.`Кроссдокинг` AS `Кроссдокинг`, s.`Обработка ошибок продавца` AS `Обработка ошибок продавца`, s.`Бронирование места` AS `Бронирование места`, s.`Утилизация остатков` AS `Утилизация остатков`, 0 AS `Восстановление товара`, 0 AS `Приемка на складе`, 0 AS `Отказ возврат товара`, 0 AS `НДС Казахстан`, 0 AS `Переупаковка товара`, s.`Подготовка товара к возврату` AS `Подготовка товара к возврату`, 0 AS `Прочие удержания`, m.`Товарная реклама` AS `Товарная реклама`, b.`Баннерная реклама` AS `Баннерная реклама`, 0 AS `Внешняя реклама`, om.`Прочие услуги маркетинга` AS `Прочие услуги маркетинга`, 0 AS `Маркетинговое агентство` FROM ozon_orders_by_day AS o LEFT JOIN ozon_sales AS sl ON o.in_process_at = sl.operation_date LEFT JOIN ozon_spends AS s ON o.in_process_at = s.operation_date LEFT JOIN ozon_marketing AS m ON o.in_process_at = m.date LEFT JOIN ozon_banner AS b ON o.in_process_at = b.date LEFT JOIN ozon_other_marketing AS om ON o.in_process_at = om.operation_date LEFT JOIN income AS i ON o.in_process_at = i.`Дата` LEFT JOIN warehouse AS w ON o.in_process_at = w.date WHERE (o.in_process_at >= '2024-06-01') AND (o.in_process_at < today()) SETTINGS final = 1;

CREATE VIEW `zendendb`.`OZ_orders_by_size_v` AS SELECT toDate(o.`Принят в обработку`) AS dt, 'Озон' AS mp, m.art AS art, m.kdo AS kdo, replaceAll(splitByChar('_', o.`Артикул`)[2], ',', '.') AS size, toInt32(sum(o.`Количество`)) AS order_qty, toInt32(sumIf(o.`Количество`, o.`Статус` = 'Отменён')) AS order_qty_cancelled, toDecimal64(sum(o.`Ваша цена`), 3) AS order_rub, toDecimal64(sumIf(o.`Ваша цена`, o.`Статус` = 'Отменён'), 3) AS order_rub_cancelled, toDecimal64(sum(o.`Оплачено покупателем`), 3) AS order_rub_spp, toDecimal64(sumIf(o.`Оплачено покупателем`, o.`Статус` = 'Отменён'), 3) AS order_rub_spp_cancelled FROM `zendendb`.OZON_Orders_TM AS o ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = o.`Артикул`) AND (m.mp = 'Озон') WHERE (toDate(o.`Принят в обработку`) >= {start_date:date}) AND (toDate(o.`Принят в обработку`) <= {end_date:date}) GROUP BY dt, mp, art, kdo, size SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`SailPlay_cards_by_day_v` (`Дата` Date, `Магазин Родитель` Nullable(String), `Магазин` Nullable(String), `ПокупкиКарта` UInt64, `Покупки` UInt64, `Новые КЛ` Nullable(UInt64), `ПокупателиКарта` UInt64, `p.store_department_id` UInt32, `Начислено` Nullable(Int64), `Списано` Nullable(UInt64), `Регион` String) AS WITH shops AS (SELECT * FROM `zendendb`.`Магазины_fix` AS m WHERE (NOT ((`ДатаОткрытия` = '1970-01-01') AND (m.`ДатаЗакрытия` = '1970-01-01'))) AND (m.`КодМагазина` != 0)), mapping AS (SELECT store_department_id, m.shop_name AS shop_name, m.`Магазин` AS `Магазин`, m.`Магазин Родитель` AS `Магазин Родитель`, sh.`Регион` AS `Регион`, multiIf(m.`Магазин` = 'Челябинск-Фокус-SR', toDate('2023-03-02'), m.`Магазин` = 'Ростов-на-Дону-Золотой Вавилон-ТМ', toDate('2023-11-15'), m.`ДатаОткрытия` = '1970-01-01', toDate('2149-01-01'), m.`ДатаОткрытия`) AS `ДатаОткрытия`, multiIf(m.`Магазин` = 'Челябинск-Фокус-SR', toDate('2024-08-21'), m.`Магазин` = 'Ростов-на-Дону-Золотой Вавилон-ТМ', toDate('2024-06-14'), m.`ДатаЗакрытия` = '1970-01-01', toDate('2149-01-01'), m.`ДатаЗакрытия`) AS `ДатаЗакрытия` FROM `zendendb`.SailPlay_shop_mapping AS m LEFT JOIN shops AS sh ON sh.`Магазин` = m.`Магазин`), user_reg_shops_by_shop AS (SELECT create_date, store_department_id, countDistinct(user_id) AS `Новые КЛ` FROM `zendendb`.SailPlay_tags_reg AS sptr GROUP BY create_date, store_department_id), user_internet_reg AS (SELECT user_id, toDate(max(user_register_date)) AS user_register_date, argMin(store_department_id, p.purchase_date) AS store_department_id, argMin(if(p.shop_name IS NULL, 'ИНТЕРНЕТ-магазин Thomas Munz', m.`Магазин`), p.purchase_date) AS `Магазин`, argMin(if(p.shop_name IS NULL, 'ThomasMuenz', m.`Магазин Родитель`), p.purchase_date) AS `Магазин Родитель`, min(p.purchase_date) AS first_date FROM `zendendb`.SailPlay_purchase AS p ANY LEFT JOIN mapping AS m ON m.store_department_id = p.store_department_id WHERE user_id NOT IN (SELECT user_id FROM `zendendb`.SailPlay_tags_reg) GROUP BY user_id HAVING `Магазин Родитель` IN ('Интернет SALAMANDER', 'ThomasMuenz')), user_internet_reg_shops_by_shop AS (SELECT user_register_date, store_department_id, countIfDistinct(user_id, user_register_date <= first_date) AS `Новые КЛ` FROM user_internet_reg GROUP BY user_register_date, store_department_id), extrapoints AS (SELECT purchase_id, sum(sp.points) AS points FROM `zendendb`.SailPlay_stores_extrapoints AS sp WHERE type NOT IN (17, 16) GROUP BY purchase_id), purchase_by_shop AS (SELECT toDate(p.purchase_date) AS `Дата`, p.store_department_id AS store_department_id, multiIf(p.shop_name IS NULL, 'ThomasMuenz', m.`Магазин Родитель`) AS `Магазин Родитель`, ifNull(m.`Регион`, '-') AS `Регион`, if(p.shop_name IS NULL, 'ИНТЕРНЕТ-магазин Thomas Munz', m.`Магазин`) AS `Магазин`, countIfDistinct(p.purchase_id, p.user_id IS NOT NULL) AS `ПокупкиКарта`, countDistinct(p.purchase_id) AS `Покупки`, countDistinct(p.user_id) AS `ПокупателиКарта`, sumIf(p.price, p.user_id IS NOT NULL) AS `ТОКарта`, sum(p.price) AS `ТО`, sum(if(sp.points >= 0, points, 0) + if(points_delta >= 0, points_delta, 0)) AS `Начислено`, abs(sum(if(sp.points < 0, points, 0) + if(points_delta < 0, points_delta, 0))) AS `Списано` FROM `zendendb`.SailPlay_purchase AS p LEFT JOIN mapping AS m ON m.store_department_id = p.store_department_id LEFT JOIN extrapoints AS sp ON sp.purchase_id = p.purchase_id WHERE (`Магазин` NOT IN ('default_dep', 'Rieker')) AND (((store_department_id = 78994) AND (toDate(p.purchase_date) >= m.`ДатаОткрытия`) AND ((toDate(p.purchase_date) < m.`ДатаЗакрытия`) OR (m.`ДатаЗакрытия` IS NULL))) OR ((store_department_id = 81293) AND (toDate(p.purchase_date) >= m.`ДатаОткрытия`) AND ((toDate(p.purchase_date) < m.`ДатаЗакрытия`) OR (m.`ДатаЗакрытия` IS NULL))) OR (store_department_id NOT IN (81293, 78994))) AND (NOT p.is_deleted) GROUP BY `Дата`, `Магазин Родитель`, `Магазин`, p.store_department_id, p.shop_name, m.`Регион`) SELECT p.`Дата` AS `Дата`, p.`Магазин Родитель` AS `Магазин Родитель`, p.`Магазин` AS `Магазин`, p.`ПокупкиКарта` AS `ПокупкиКарта`, p.`Покупки` AS `Покупки`, if((p.`Магазин Родитель` IN ('Интернет SALAMANDER', 'ThomasMuenz')), iu.`Новые КЛ`, u.`Новые КЛ`) AS `Новые КЛ`, p.`ПокупателиКарта` AS `ПокупателиКарта`, p.store_department_id, p.`Начислено` AS `Начислено`, p.`Списано` AS `Списано`, p.`Регион` AS `Регион` FROM purchase_by_shop AS p LEFT JOIN user_reg_shops_by_shop AS u ON (u.store_department_id = p.store_department_id) AND (u.create_date = p.`Дата`) LEFT JOIN user_internet_reg_shops_by_shop AS iu ON (iu.store_department_id = p.store_department_id) AND (iu.user_register_date = p.`Дата`) SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`SailPlay_errors_v` (`Тип ошибки` String, `Магазин` String, `Дата` Nullable(Date)) AS SELECT DISTINCT 'Нет магазинов в SailPlay_cards_by_day' AS `Тип ошибки`, m.`Магазин` AS `Магазин`, NULL AS `Дата` FROM `zendendb`.`ПродажиПроведенные` AS s LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = s.MagazinGuid WHERE (m.`Магазин Родитель` NOT LIKE '%Zenden%') AND (m.`Магазин Родитель` NOT LIKE '%Mascotte%') AND (m.`Магазин Родитель` != '') AND (toDate(Period) > '2024-01-01') AND (m.`Магазин` NOT IN (SELECT DISTINCT `Магазин` FROM `zendendb`.SailPlay_cards_by_day AS spcbd)) UNION ALL SELECT DISTINCT 'Лишние магазины в SailPlay_cards_by_day' AS `Тип ошибки`, `Магазин`, NULL AS `Дата` FROM `zendendb`.SailPlay_cards_by_day AS s WHERE (s.`Дата` > '2024-01-01') AND (`Магазин` NOT IN (SELECT DISTINCT m.`Магазин` FROM `zendendb`.`ПродажиПроведенные` AS s LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = s.MagazinGuid WHERE (m.`Магазин Родитель` NOT LIKE '%Zenden%') AND (m.`Магазин Родитель` NOT LIKE '%Mascotte%') AND (m.`Магазин Родитель` != '') AND (toDate(Period) > '2024-01-01'))) AND (`Магазин` NOT IN ('ИМ Thomas Munz (моб.приложение)', 'ИНТЕРНЕТ-магазин Thomas Munz', 'ИНТЕРНЕТ-магазин Salamander', 'ИМ Salamander (моб.приложение)')) UNION ALL SELECT 'Пустые значения в SailPlay_shop_mapping' AS `Тип ошибки`, toString(store_department_id) AS `Магазин`, NULL AS `Дата` FROM `zendendb`.SailPlay_shop_mapping AS s WHERE (s.`КодМагазина` IS NULL) AND (`Последняя продажа` > '2023-01-01') AND (shop_name NOT IN ('Rieker', 'default_dep')) UNION ALL SELECT 'Дубли в SailPlay_shop_mapping' AS `Тип ошибки`, toString(s.store_department_id) AS `Магазин`, NULL AS `Дата` FROM `zendendb`.SailPlay_shop_mapping AS s WHERE store_department_id NOT IN (81293, 78994, 85639, 5431) GROUP BY s.store_department_id HAVING count(*) > 1 UNION ALL SELECT 'Дубли в SailPlay_cards_by_day' AS `Тип ошибки`, toString(store_department_id) AS `Магазин`, `Дата` FROM `zendendb`.SailPlay_cards_by_day AS s FINAL GROUP BY `Дата`, store_department_id HAVING count(*) > 1 UNION ALL SELECT 'Дубли в SailPlay_sms_light' AS `Тип ошибки`, toString(store_department_id) AS `Магазин`, `Дата` FROM `zendendb`.SailPlay_cards_by_day AS s GROUP BY `Дата`, store_department_id HAVING count(*) > 1;

CREATE VIEW `zendendb`.`SailPlay_purchase_v` (`tm` LowCardinality(String), `p.shop_name` Nullable(String), `purchase_id` UInt64, `purchase_date` DateTime, `is_deleted` Bool, `is_completed` Bool, `points_delta` Nullable(Int64), `points` Nullable(Int64), `price` Nullable(Int64), `user_id` Nullable(UInt64), `last_name` Nullable(String), `user_register_date` Nullable(DateTime), `user_created_date` Nullable(DateTime), `last_date` Nullable(Date), `first_name` Nullable(String), `is_email_notifications` Nullable(Bool), `phone` Nullable(String), `email` Nullable(String), `sex` Nullable(UInt16), `birth_date` Nullable(String), `store_department_id` UInt32, `Магазин` Nullable(String), `Магазин Родитель` Nullable(String), `Регион` String, `store_registration` Nullable(String), `store_registration_parent` Nullable(String), `card_create_date` Nullable(Date)) AS WITH shops AS (SELECT * FROM `zendendb`.`Магазины_fix` AS m WHERE (NOT ((`ДатаОткрытия` = '1970-01-01') AND (m.`ДатаЗакрытия` = '1970-01-01'))) AND (m.`КодМагазина` != 0)), mapping AS (SELECT store_department_id, shop_name, `Магазин`, `Магазин Родитель`, sh.`Регион` AS `Регион`, multiIf(`Магазин` = 'Челябинск-Фокус-SR', toDate('2023-03-02'), `Магазин` = 'Ростов-на-Дону-Золотой Вавилон-ТМ', toDate('2023-11-15'), `ДатаОткрытия` = '1970-01-01', NULL, `ДатаОткрытия`) AS `ДатаОткрытия`, multiIf(`Магазин` = 'Челябинск-Фокус-SR', toDate('2024-08-21'), `Магазин` = 'Ростов-на-Дону-Золотой Вавилон-ТМ', toDate('2024-06-14'), `ДатаЗакрытия` = '1970-01-01', NULL, `ДатаЗакрытия`) AS `ДатаЗакрытия` FROM `zendendb`.SailPlay_shop_mapping AS m LEFT JOIN shops AS sh ON sh.`Магазин` = m.`Магазин`), last_purchase AS (SELECT p.user_id, p.tm, max(toDate(p.purchase_date)) AS last_date FROM `zendendb`.SailPlay_purchase AS p WHERE NOT p.is_deleted GROUP BY p.user_id, p.tm), extrapoints AS (SELECT purchase_id, sum(sp.points) AS points FROM `zendendb`.SailPlay_stores_extrapoints AS sp WHERE type NOT IN (17, 16) GROUP BY purchase_id) SELECT p.tm AS tm, p.shop_name, p.purchase_id AS purchase_id, p.purchase_date AS purchase_date, p.is_deleted AS is_deleted, p.is_completed AS is_completed, p.points_delta AS points_delta, sp.points AS points, p.price AS price, p.user_id AS user_id, p.last_name AS last_name, p.user_register_date AS user_register_date, p.user_created_date AS user_created_date, lp.last_date AS last_date, p.first_name AS first_name, p.is_email_notifications AS is_email_notifications, p.phone AS phone, p.email AS email, p.sex AS sex, p.birth_date AS birth_date, p.store_department_id AS store_department_id, m.`Магазин` AS `Магазин`, m.`Магазин Родитель` AS `Магазин Родитель`, ifNull(m.`Регион`, '-') AS `Регион`, m2.`Магазин` AS store_registration, m2.`Магазин Родитель` AS store_registration_parent, us.create_date AS card_create_date FROM `zendendb`.SailPlay_purchase AS p FINAL LEFT JOIN mapping AS m ON m.store_department_id = p.store_department_id LEFT JOIN `zendendb`.SailPlay_tags_reg AS us ON p.user_id = us.user_id ANY LEFT JOIN mapping AS m2 ON m2.store_department_id = us.store_department_id LEFT JOIN last_purchase AS lp ON (lp.user_id = p.user_id) AND (lp.tm = p.tm) LEFT JOIN extrapoints AS sp ON sp.purchase_id = p.purchase_id WHERE (toYear(p.purchase_date) >= (toYear(today()) - 2)) AND (NOT p.is_deleted) AND (((p.store_department_id = 78994) AND (toDate(p.purchase_date) >= m.`ДатаОткрытия`) AND ((toDate(p.purchase_date) < m.`ДатаЗакрытия`) OR (m.`ДатаЗакрытия` IS NULL))) OR ((p.store_department_id = 81293) AND (toDate(p.purchase_date) >= m.`ДатаОткрытия`) AND ((toDate(p.purchase_date) < m.`ДатаЗакрытия`) OR (m.`ДатаЗакрытия` IS NULL))) OR (p.store_department_id NOT IN (81293, 78994))) SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`SailPlay_shop_mapping_v` (`tm` LowCardinality(String), `store_department_id` UInt32, `shop_name` Nullable(String), `Последняя продажа` Nullable(DateTime), `Магазин` Nullable(String), `КодМагазина` Nullable(UInt32), `Магазин Родитель` Nullable(String), `ДатаЗакрытия` Nullable(Date), `ДатаОткрытия` Nullable(Date), `tag_names` Array(String), `Закрыт` UInt8) AS WITH user_reg AS (SELECT DISTINCT tm, tag_name, trimBoth(splitByChar('_', assumeNotNull(tag_name))[2]) AS `МагазинРегистрации` FROM `zendendb`.SailPlay_users_tags AS sput WHERE tag_name LIKE 'МагазинРегистрации_%'), user_reg_fix AS (SELECT DISTINCT tm, tag_name, multiIf((splitByChar('-', `МагазинРегистрации`)[-1]) = 'ТМS', replaceOne(`МагазинРегистрации`, 'ТМS', 'ТМ'), (tm = 'SR') AND ((splitByChar('-', `МагазинРегистрации`)[-1]) = 'STORE'), replaceOne(`МагазинРегистрации`, 'STORE', 'SR'), (tm = 'TM') AND ((splitByChar('-', `МагазинРегистрации`)[-1]) = 'STORE'), replaceOne(`МагазинРегистрации`, 'STORE', 'ТМ'), `МагазинРегистрации`) AS `МагазинРегистрации` FROM user_reg), shop_1c AS (SELECT `Магазин`, replaceOne(`Магазин`, '-TM', '-ТМ') AS `Магазин_fix`, `Магазин Родитель`, `МагазинГуид`, `МагазинРодительГуид`, `Региональный Директор`, `Статус Работы`, `Территорияальный Менеджер`, `Город`, `Относительно Москвы`, `ТипМагазинаУПП`, `Регион`, `ТипМагазинаДляПланированияУПП`, `КодМагазина`, `ДатаЗакрытия`, `ДатаОткрытия` FROM `zendendb`.`Магазины_fix` AS m WHERE (m.`Магазин`, m.`Магазин Родитель`) != ('Москва-Хорошо-ТМ', 'Неиспользуемые ТМ')), shops AS (SELECT tm, p.store_department_id AS store_department_id, p.shop_name AS shop_name, multiIf((p.shop_name = 'Челябинск-Фокус-SR') AND (toDate(p.purchase_date) > m.`ДатаЗакрытия`), 'Челябинск-Фокус2-SR', (p.shop_name = 'Ростов-на-Дону-Золотой Вавилон-ТМ') AND (toDate(p.purchase_date) > m.`ДатаЗакрытия`), 'Ростов-на-Дону-Золотой Вавилон2-ТМ', p.store_department_id = 6255, 'ИНТЕРНЕТ-магазин Thomas Munz', p.shop_name = 'Site SR', 'ИНТЕРНЕТ-магазин Salamander', p.shop_name = 'imshop tm', 'ИМ Thomas Munz (моб.приложение)', m.`Магазин` IS NOT NULL, m.`Магазин`, m1.`Магазин` IS NOT NULL, m1.`Магазин`, m2.`Магазин` IS NOT NULL, m2.`Магазин`, ((splitByChar('-', assumeNotNull(p.shop_name))[-1]) = 'ТМ') AND (toYear(max_date) <= 2022), p.shop_name, ((splitByChar('-', assumeNotNull(p.shop_name))[-1]) = 'ТМ') AND (toYear(max_date) > 2022), replaceOne(p.shop_name, 'ТМ', 'STORE'), concat(p.shop_name)) AS `Магазин`, lowerUTF8(if(((splitByChar('-', assumeNotNull(p.shop_name))[1]) IN ('Зеленоград', 'Одинцово', 'Люберцы', 'Мытищи')), concat('МО-', p.shop_name), p.shop_name)) AS t, pr.max_date AS max_date FROM `zendendb`.SailPlay_purchase AS p LEFT JOIN shop_1c AS m ON lowerUTF8(m.`Магазин_fix`) = lowerUTF8(multiIf(p.shop_name = 'Одинцово-О\'Парк-ТМ', 'МО-Одинцово-О\\\'Парк-ТМ', p.shop_name = 'Новосибирск Ройял Парк', 'Новосибирск-Ройял Парк-ТМ', p.shop_name)) LEFT JOIN shop_1c AS m1 ON lowerUTF8(m1.`Магазин_fix`) = lowerUTF8(if(((splitByChar('-', assumeNotNull(p.shop_name))[1]) IN ('Зеленоград', 'Одинцово', 'Люберцы', 'Мытищи')), concat('МО-', p.shop_name), p.shop_name)) LEFT JOIN shop_1c AS m2 ON m2.`КодМагазина` = toInt32OrNull(p.shop_origin_id) LEFT JOIN (SELECT DISTINCT store_department_id, shop_name, max(purchase_date) AS max_date FROM `zendendb`.SailPlay_purchase GROUP BY store_department_id, shop_name) AS pr ON pr.store_department_id = p.store_department_id GROUP BY tm, `Магазин`, p.shop_name, p.store_department_id, pr.max_date, t), all_shops AS (SELECT s.tm, store_department_id, shop_name, max_date AS `Последняя продажа`, s.`Магазин`, m.`КодМагазина` AS `КодМагазина`, if((m.`Магазин Родитель` IS NULL) AND (s.`Магазин` NOT IN ('Rieker', 'default_dep')), 'Неиспользуемые ТМ', m.`Магазин Родитель`) AS `Магазин Родитель`, toDate(m.`ДатаЗакрытия`) AS `ДатаЗакрытия`, toDate(m.`ДатаОткрытия`) AS `ДатаОткрытия` FROM shops AS s LEFT JOIN shop_1c AS m ON m.`Магазин` = s.`Магазин`), tag_array AS (SELECT groupArrayDistinct(tag_name) AS tag_names, s.store_department_id AS store_department_id FROM user_reg_fix AS u LEFT JOIN all_shops AS s ON lowerUTF8(u.`МагазинРегистрации`) = lowerUTF8(s.`Магазин`) GROUP BY store_department_id) SELECT s.*, tag_names, if((`Магазин Родитель` IN ('Закрытые Mascotte', 'Закрытые SALAMANDER', 'Неиспользуемые Zenden', 'Неиспользуемые ТМ')), 1, 0) AS `Закрыт` FROM all_shops AS s LEFT JOIN tag_array AS t ON t.store_department_id = s.store_department_id SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`SailPlay_sms_light_last_purchase_v` (`tag_name` Nullable(String), `user_id` UInt64, `purchase_id` Nullable(UInt64), `purchase_date` Nullable(Date), `price` Nullable(Int64), `store_department_id` Nullable(UInt32), `Магазин` Nullable(String), `Магазин Родитель` Nullable(String), `last_purchase` Nullable(UInt64), `last_purchase_date` Nullable(Date), `last_purchase_price` Nullable(Int64), `users_by_month` Array(UInt64)) AS WITH shops AS (SELECT * FROM `zendendb`.`Магазины_fix` AS m WHERE (NOT ((`ДатаОткрытия` = '1970-01-01') AND (m.`ДатаЗакрытия` = '1970-01-01'))) AND (m.`КодМагазина` != 0)), mapping AS (SELECT store_department_id, argMin(shop_name, `Закрыт`) AS shop_name, argMin(`Магазин`, `Закрыт`) AS `Магазин`, argMin(`Магазин Родитель`, `Закрыт`) AS `Магазин Родитель`, argMin(sh.`Регион`, `Закрыт`) AS `Регион`, argMin(multiIf(`ДатаОткрытия` = '1970-01-01', NULL, `ДатаОткрытия`), `Закрыт`) AS `ДатаОткрытия`, argMin(multiIf(`ДатаЗакрытия` = '1970-01-01', NULL, `ДатаЗакрытия`), `Закрыт`) AS `ДатаЗакрытия` FROM `zendendb`.SailPlay_shop_mapping AS m LEFT JOIN shops AS sh ON sh.`КодМагазина` = m.`КодМагазина` WHERE store_department_id NOT IN (81293, 78994) GROUP BY store_department_id UNION ALL SELECT store_department_id, shop_name, `Магазин`, `Магазин Родитель`, sh.`Регион` AS `Регион`, multiIf(`КодМагазина` = 1372, toDate('2023-03-02'), `КодМагазина` = 68993, toDate('2023-11-15'), `ДатаОткрытия` = '1970-01-01', NULL, `ДатаОткрытия`) AS `ДатаОткрытия`, multiIf(`КодМагазина` = 1372, toDate('2024-08-21'), `КодМагазина` = 68993, toDate('2024-06-14'), `ДатаЗакрытия` = '1970-01-01', NULL, `ДатаЗакрытия`) AS `ДатаЗакрытия` FROM `zendendb`.SailPlay_shop_mapping AS m LEFT JOIN shops AS sh ON sh.`КодМагазина` = m.`КодМагазина` WHERE store_department_id IN (81293, 78994)), tags AS (SELECT DISTINCT tg.tag_name, toDate(create_date) AS create_date, user_id FROM `zendendb`.SailPlay_users_tags AS tg WHERE (toDate(create_date) >= toStartOfMonth(today() - toIntervalMonth(2))) AND ((tag_name ILIKE 'Пользователю было отправлено SMS%') OR (tag_name ILIKE 'Участник контрольной группы рассылки%'))), purchase_prices AS (SELECT purchase_id, sum(product_new_price) AS price FROM `zendendb`.SailPlay_carts_positions AS spcp GROUP BY purchase_id), purchases AS (SELECT p.purchase_id AS purchase_id, p.user_id AS user_id, toDate(p.purchase_date) AS purchase_date, pp.price AS price, p.store_department_id AS store_department_id, m.`Магазин` AS `Магазин`, m.`Магазин Родитель` AS `Магазин Родитель`, m.`Регион` AS `Регион`, anyLast(purchase_id) OVER (PARTITION BY user_id ORDER BY toYYYYMM(p.purchase_date) ASC RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS last_purchase, toStartOfMonth(anyLast(purchase_date) OVER (PARTITION BY user_id ORDER BY toYYYYMM(p.purchase_date) ASC RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING)) AS last_purchase_date, anyLast(price) OVER (PARTITION BY user_id ORDER BY toYYYYMM(p.purchase_date) ASC RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS last_purchase_price FROM `zendendb`.SailPlay_purchase AS p LEFT JOIN purchase_prices AS pp ON p.purchase_id = pp.purchase_id ANY LEFT JOIN mapping AS m ON m.store_department_id = p.store_department_id WHERE user_id IS NOT NULL), tag_users_by_month AS (SELECT t.tag_name, 999 AS user_id, toStartOfMonth(p.purchase_date) AS purchase_month, p.`Магазин Родитель` AS `Магазин Родитель`, groupArrayDistinct(t.user_id) AS users_by_month FROM tags AS t LEFT JOIN purchases AS p ON p.user_id = t.user_id GROUP BY t.tag_name, toStartOfMonth(p.purchase_date), p.`Магазин Родитель`), report AS (SELECT t.tag_name AS tag_name, t.user_id AS user_id, p.purchase_id AS purchase_id, p.purchase_date AS purchase_date, p.price AS price, p.store_department_id AS store_department_id, p.`Магазин` AS `Магазин`, p.`Магазин Родитель` AS `Магазин Родитель`, p.last_purchase AS last_purchase, p.last_purchase_date AS last_purchase_date, p.last_purchase_price AS last_purchase_price FROM tags AS t LEFT JOIN purchases AS p ON p.user_id = t.user_id UNION ALL SELECT DISTINCT tag_name, 999 AS user_id, NULL AS purchase_id, NULL AS purchase_date, NULL AS price, NULL AS store_department_id, NULL AS `Магазин`, p.`Магазин Родитель` AS `Магазин Родитель`, NULL AS last_purchase, toStartOfMonth(p.last_purchase_date) AS last_purchase_date, NULL AS last_purchase_price FROM tags AS t LEFT JOIN purchases AS p ON p.user_id = t.user_id WHERE last_purchase_date != '1970-01-01') SELECT ifNull(r.tag_name, t.tag_name) AS tag_name, ifNull(r.user_id, 999) AS user_id, purchase_id, purchase_date, price, store_department_id, `Магазин`, ifNull(r.`Магазин Родитель`, t.`Магазин Родитель`) AS `Магазин Родитель`, last_purchase, ifNull(r.last_purchase_date, t.purchase_month) AS last_purchase_date, last_purchase_price, users_by_month FROM report AS r FULL OUTER JOIN tag_users_by_month AS t ON (t.purchase_month = r.last_purchase_date) AND (r.tag_name = t.tag_name) AND (r.user_id = t.user_id) AND (r.`Магазин Родитель` = t.`Магазин Родитель`) SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`SailPlay_sms_light_v` (`Магазин` Nullable(String), `Магазин Родитель` Nullable(String), `purchase_id` UInt64, `purchase_date` Date, `user_id` Nullable(UInt64), `price` Nullable(Int64), `cost` Nullable(Decimal(38, 5)), `gross` Nullable(Decimal(38, 5)), `points_received` Nullable(Int64), `points_write_off` Nullable(UInt64), `tag_names` Array(String), `tag_sbp` UInt8, `last_purchase_date` Date) AS WITH shops AS (SELECT * FROM `zendendb`.`Магазины_fix` AS m WHERE (NOT ((`ДатаОткрытия` = '1970-01-01') AND (m.`ДатаЗакрытия` = '1970-01-01'))) AND (m.`КодМагазина` != 0)), mapping AS (SELECT store_department_id, argMin(shop_name, `Закрыт`) AS shop_name, argMin(`Магазин`, `Закрыт`) AS `Магазин`, argMin(`Магазин Родитель`, `Закрыт`) AS `Магазин Родитель`, argMin(sh.`Регион`, `Закрыт`) AS `Регион`, argMin(multiIf(`ДатаОткрытия` = '1970-01-01', NULL, `ДатаОткрытия`), `Закрыт`) AS `ДатаОткрытия`, argMin(multiIf(`ДатаЗакрытия` = '1970-01-01', NULL, `ДатаЗакрытия`), `Закрыт`) AS `ДатаЗакрытия` FROM `zendendb`.SailPlay_shop_mapping AS m LEFT JOIN shops AS sh ON sh.`КодМагазина` = m.`КодМагазина` WHERE store_department_id NOT IN (81293, 78994) GROUP BY store_department_id UNION ALL SELECT store_department_id, shop_name, `Магазин`, `Магазин Родитель`, sh.`Регион` AS `Регион`, multiIf(`КодМагазина` = 1372, toDate('2023-03-02'), `КодМагазина` = 68993, toDate('2023-11-15'), `ДатаОткрытия` = '1970-01-01', NULL, `ДатаОткрытия`) AS `ДатаОткрытия`, multiIf(`КодМагазина` = 1372, toDate('2024-08-21'), `КодМагазина` = 68993, toDate('2024-06-14'), `ДатаЗакрытия` = '1970-01-01', NULL, `ДатаЗакрытия`) AS `ДатаЗакрытия` FROM `zendendb`.SailPlay_shop_mapping AS m LEFT JOIN shops AS sh ON sh.`КодМагазина` = m.`КодМагазина` WHERE store_department_id IN (81293, 78994)), tags AS (SELECT DISTINCT user_id, tg.tag_name, toDate(create_date) AS create_date FROM `zendendb`.SailPlay_users_tags AS tg WHERE (toDate(create_date) >= toStartOfMonth(today() - toIntervalMonth(2))) AND ((tag_name ILIKE 'Пользователю было отправлено SMS%') OR (tag_name ILIKE 'Участник контрольной группы рассылки%'))), tags_agr AS (SELECT DISTINCT user_id, groupArray(tag_name) AS tag_names FROM tags GROUP BY user_id), extrapoints AS (SELECT purchase_id, sum(sp.points) AS points FROM `zendendb`.SailPlay_stores_extrapoints AS sp WHERE (type NOT IN (17, 16)) AND (purchase_id != 0) GROUP BY purchase_id), tags_sbp AS (SELECT DISTINCT user_id, 1 AS tag_sbp FROM `zendendb`.SailPlay_users_tags AS tg WHERE (toDate(create_date) >= toStartOfMonth(today() - toIntervalMonth(2))) AND (tag_name IN ('Бонусы СБП', 'Бонусы за СПБ'))), purchase AS (SELECT m.`Магазин` AS `Магазин`, m.`Магазин Родитель` AS `Магазин Родитель`, pc.purchase_id AS purchase_id, toDate(pc.purchase_date) AS purchase_date, pc.user_id AS user_id, sum(p.product_new_price) AS price, sumIf(ifNull(s.value_rub, s2.value_rub), t.`ТипНоменклатуры` != 'Реклама') AS cost, sumIf(p.product_new_price - ifNull(s.value_rub, s2.value_rub), t.`ТипНоменклатуры` != 'Реклама') AS gross, max(p.points_delta) AS points_delta FROM `zendendb`.SailPlay_purchase AS pc LEFT JOIN `zendendb`.SailPlay_carts_positions AS p ON p.purchase_id = pc.purchase_id LEFT JOIN mapping AS m ON m.store_department_id = pc.store_department_id LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = p.sku ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS s ON (p.sku = s.kdo) AND (s.half = if(toMonth(p.purchase_date) <= 6, toStartOfYear(p.purchase_date), toStartOfYear(p.purchase_date) + toIntervalMonth(6))) AND (s.price_type = 'Себестоимость') ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS s2 ON (p.sku = s2.kdo) AND (s2.half = if(toMonth(p.purchase_date) <= 6, toStartOfYear(p.purchase_date), toStartOfYear(p.purchase_date) + toIntervalMonth(6))) AND (s2.price_type != 'Себестоимость') WHERE (((pc.store_department_id = 78994) AND (toDate(pc.purchase_date) >= m.`ДатаОткрытия`) AND ((toDate(pc.purchase_date) < m.`ДатаЗакрытия`) OR (m.`ДатаЗакрытия` IS NULL))) OR ((pc.store_department_id = 81293) AND (toDate(pc.purchase_date) >= m.`ДатаОткрытия`) AND ((toDate(pc.purchase_date) < m.`ДатаЗакрытия`) OR (m.`ДатаЗакрытия` IS NULL))) OR (pc.store_department_id NOT IN (81293, 78994))) AND (NOT pc.is_deleted) AND (`Магазин` NOT IN ('default_dep', 'Rieker')) GROUP BY m.`Магазин Родитель`, m.`Магазин`, pc.store_department_id, pc.purchase_id, toDate(pc.purchase_date), pc.user_id) SELECT p.`Магазин` AS `Магазин`, p.`Магазин Родитель` AS `Магазин Родитель`, p.purchase_id AS purchase_id, p.purchase_date AS purchase_date, p.user_id AS user_id, p.price AS price, p.cost AS cost, p.gross AS gross, if(pt.points >= 0, pt.points, 0) + if(p.points_delta >= 0, p.points_delta, 0) AS points_received, abs(if(pt.points < 0, pt.points, 0) + if(p.points_delta < 0, p.points_delta, 0)) AS points_write_off, t.tag_names AS tag_names, if(tg.tag_sbp IS NULL, 0, 1) AS tag_sbp, toStartOfMonth(anyLast(purchase_date) OVER (PARTITION BY user_id ORDER BY toYYYYMM(p.purchase_date) ASC RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING)) AS last_purchase_date FROM purchase AS p LEFT JOIN tags_agr AS t ON t.user_id = p.user_id LEFT JOIN tags_sbp AS tg ON tg.user_id = p.user_id LEFT JOIN extrapoints AS pt ON pt.purchase_id = p.purchase_id SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`SailPlay_sms_light_with_users_by_tag_v` (`Магазин` String, `Магазин Родитель` String, `purchase_id` UInt64, `purchase_date` Date, `user_id` UInt64, `price` Int64, `tag` String, `last_purchase_date` Date, `user_ids` Array(UInt64), `tag_in_purch` UInt64, `user_ids_in_tag` Nullable(UInt64)) AS WITH purchase AS (SELECT `Магазин`, `Магазин Родитель`, purchase_id, purchase_date, user_id, price, cost, gross, points_received, points_write_off, tag_sbp, last_purchase_date, arrayJoin(tag_names) AS tag, length(tag_names) AS tag_in_purch FROM `zendendb`.SailPlay_sms_light AS p), tag_users AS (SELECT toStartOfMonth(purchase_date) AS purchase_date_month, s.`Магазин Родитель`, groupArrayDistinct(user_id) AS user_ids, arrayJoin(s.tag_names) AS tag, length(groupArrayDistinct(user_id)) AS user_ids_in_tag FROM `zendendb`.SailPlay_sms_light AS s WHERE user_id != 0 GROUP BY tag, toStartOfMonth(purchase_date), s.`Магазин Родитель`), report AS (SELECT `Магазин`, `Магазин Родитель`, purchase_id, purchase_date, user_id, price, tag, last_purchase_date, if(empty(u.user_ids), [0], u.user_ids) AS user_ids, tag_in_purch, user_ids_in_tag FROM purchase AS p LEFT JOIN tag_users AS u ON (u.purchase_date_month = p.last_purchase_date) AND (u.tag = p.tag) AND (u.`Магазин Родитель` = p.`Магазин Родитель`)) SELECT * FROM report SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`SailPlay_tags_reg_v` (`tm` Nullable(String), `user_id` UInt64, `create_date` Nullable(Date), `tag_name` Nullable(String), `store_registration` Nullable(String), `store_department_id` Nullable(UInt32)) AS WITH shops AS (SELECT * FROM `zendendb`.`Магазины_fix` AS m WHERE (NOT ((`ДатаОткрытия` = '1970-01-01') AND (m.`ДатаЗакрытия` = '1970-01-01'))) AND (m.`КодМагазина` != 0)), last_purchase AS (SELECT tm, shop_name, store_department_id, toDate(max(purchase_date)) AS last_purchase FROM `zendendb`.SailPlay_purchase GROUP BY tm, shop_name, store_department_id), mapping AS (SELECT m.`Магазин` AS `Магазин`, m.tm AS tm, m.store_department_id AS store_department_id, lp.last_purchase AS last_purchase, argMax(m.tag_names, m.store_department_id) AS tag_names FROM `zendendb`.SailPlay_shop_mapping AS m LEFT JOIN shops AS sh ON sh.`Магазин` = m.`Магазин` LEFT JOIN last_purchase AS lp ON (m.store_department_id = lp.store_department_id) AND (m.tm = lp.tm) GROUP BY m.`Магазин`, m.tm, m.store_department_id, lp.last_purchase), tags_mapping AS (SELECT tm, `Магазин`, store_department_id, arrayJoin(tag_names) AS tag_name, last_purchase FROM mapping), user_reg AS (SELECT argMax(t.tm, t.create_date) AS tm, user_id, argMax(t.tag_name, t.create_date) AS tag_name, toDate(max(t.create_date)) AS create_date FROM `zendendb`.SailPlay_users_tags AS t WHERE t.tag_name LIKE 'МагазинРегистрации_%' GROUP BY user_id) SELECT argMin(r.tm, m.last_purchase) AS tm, user_id, argMin(r.create_date, last_purchase) AS create_date, argMin(r.tag_name, m.last_purchase) AS tag_name, argMin(m.`Магазин`, m.last_purchase) AS store_registration, argMin(store_department_id, m.last_purchase) AS store_department_id FROM user_reg AS r LEFT JOIN tags_mapping AS m ON (m.tag_name = r.tag_name) AND (r.tm = m.tm) WHERE (m.`Магазин` NOT IN ('default_dep', 'Rieker')) AND (r.create_date <= m.last_purchase) GROUP BY user_id SETTINGS join_use_nulls = 1, final = 1;

