 toIntervalMonth(1))) OVER (PARTITION BY `Подразделение`) AS `СредняяЧисленностьЗаПериод`, `ПринятоСписочногоСостава`, `УволеноСписочногоСостава`, `ПринятоВсего`, `УволеноВсего`, `ПричинаУвольнения` FROM `ВТИтоговыеДанные`), shops AS (SELECT DISTINCT h.`Подразделение` AS `Подразделение`, r.`КодМагазина` AS `КодМагазина`, m.`МагазинГуид` AS `МагазинГуид`, m.`Магазин` AS `Магазин`, m.`Магазин Родитель` AS `Магазин Родитель`, multiIf(((p.`Округ` = 'Московская область') AND (m.`Город` != 'Москва')) OR (m.`Город` = 'Москвовская область'), 'Московская область', m.`Город` = 'Ростов', 'Ростов-на-Дону', m.`Город`) AS `Город`, m.`Регион` AS `Регион`, m.`Дивизиональный Директор` AS `Дивизиональный Директор`, m.`Региональный Директор` AS `Региональный Директор`, m.`Территорияальный Менеджер` AS `Территорияальный Менеджер`, m.`ТипМагазинаДляПланированияУПП` AS `ТипМагазинаДляПланированияУПП` FROM `zendendb`.`КадроваяИсторияСотрудников` AS h LEFT JOIN `zendendb`.`МестоПозицииШтатногоРасписания` AS r ON h.`ДолжностьПоШтатномуРасписаниюГуид` = r.`ПозицияГуид` LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`КодМагазина` = abs(r.`КодМагазина`) ANY LEFT JOIN `zendendb`.`ЧасовыеПояса` AS p ON m.`Город` = p.`Город` WHERE r.`КодМагазина` != 0) SELECT {start_date:date} AS `Месяц`, r.`Подразделение`, m.`КодМагазина` AS `КодМагазина`, r.`ДолжностьПоШтатномуРасписанию`, r.`СотрудникГуид`, r.`ВидЗанятости`, r.`СредняяЧисленность`, r.`ЧисленностьДляРасчетаСредней`, r.`Численность`, r.`ПринятоСписочногоСостава`, r.`УволеноСписочногоСостава`, r.`ПринятоВсего`, r.`УволеноВсего`, r.`ПричинаУвольнения`, m.`Магазин` AS `Магазин`, m.`Магазин Родитель` AS `Магазин Родитель`, m.`Город` AS `Город`, m.`Регион` AS `Регион`, m.`Дивизиональный Директор` AS `Дивизиональный Директор`, m.`Региональный Директор` AS `Региональный Директор`, m.`Территорияальный Менеджер` AS `Территорияальный Менеджер`, m.`ТипМагазинаДляПланированияУПП` AS `ТипМагазинаДляПланированияУПП` FROM final_report AS r LEFT JOIN shops AS m ON m.`Подразделение` = r.`Подразделение` WHERE m.`Магазин Родитель` IN (SELECT * FROM `zendendb`.`Магазины_Родители_v`) SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`Staffing_v` AS WITH employees AS (SELECT DISTINCT {start_date:date} AS `Период`, s.* FROM `zendendb`.`Сотрудники` AS s), state AS (SELECT s.*, ss.`ПериодЗаписи` AS `ПериодЗаписи`, ss.`Состояние` AS `Состояние`, ss.`ВидВремени` AS `ВидВремени`, ss.`ДействуетДо` AS `ДействуетДо`, ss.`ОкончаниеПредположительно` AS `ОкончаниеПредположительно` FROM employees AS s LEFT JOIN `zendendb`.`СостоянияСотрудников` AS ss ON s.`СотрудникГуид` = ss.`СотрудникГуид` WHERE (toDate32(ss.`ПериодЗаписи`) <= s.`Период`) AND (((toDate32(ss.`ДействуетДо`) + 1) >= s.`Период`) OR (toDate32(ss.`ДействуетДо`) <= '1970-01-02'))), work_chedule AS (SELECT s.*, reg.`ДатаОкончания` AS `ДатаОкончания`, reg.`ДатаНачала` AS `ДатаНачала`, reg.`ПериодПредыдущейЗаписи` AS `ПериодПредыдущейЗаписи`, reg.`ГрафикРаботы` AS `ГрафикРаботы`, reg.`ДлительностьРабочейНедели` AS `ДлительностьРабочейНедели`, reg.`РабочихДнейВНеделе` AS `РабочихДнейВНеделе` FROM employees AS s LEFT JOIN `zendendb`.`ГрафикРаботыСотрудников` AS reg ON reg.`СотрудникГуид` = s.`СотрудникГуид` WHERE (toDate32(reg.`ДатаНачала`) <= s.`Период`) AND (((toDate32(reg.`ДатаОкончания`) + 1) >= s.`Период`) OR (toDate32(reg.`ДатаОкончания`) <= '1970-01-02'))), history AS (SELECT s.*, reg.`ДатаОкончания` AS `ДатаОкончания`, reg.`ДатаНачала` AS `ДатаНачала`, reg.`ПериодПредыдущейЗаписи` AS `ПериодПредыдущейЗаписи`, reg.`ПериодЗаписи` AS `ПериодЗаписи`, reg.`Подразделение` AS `Подразделение`, reg.`КодМагазина` AS `КодМагазина`, reg.`Должность` AS `Должность`, reg.`ДолжностьПоШтатномуРасписаниюГуид` AS `ДолжностьПоШтатномуРасписаниюГуид`, reg.`ДолжностьПоШтатномуРасписанию` AS `ДолжностьПоШтатномуРасписанию`, reg.`ВидСобытия` AS `ВидСобытия`, reg.`КоличествоСтавок` AS `КоличествоСтавок` FROM employees AS s LEFT JOIN `zendendb`.`КадроваяИсторияСотрудников` AS reg ON reg.`СотрудникГуид` = s.`СотрудникГуид` WHERE (toDate32(reg.`ДатаНачала`) <= s.`Период`) AND (((toDate32(reg.`ДатаОкончания`) + 1) >= s.`Период`) OR (toDate32(reg.`ДатаОкончания`) <= '1970-01-02'))), employees_types AS (SELECT s.*, reg.`ДатаОкончанияИнтервала` AS `ДатаОкончанияИнтервала`, reg.`ДатаНачала` AS `ДатаНачала`, reg.`ПериодПредыдущейЗаписи` AS `ПериодПредыдущейЗаписи`, reg.`ПериодЗаписи` AS `ПериодЗаписи`, reg.`ВидЗанятости` AS `ВидЗанятости` FROM employees AS s INNER JOIN `zendendb`.`ВидыЗанятостиСотрудников` AS reg ON reg.`СотрудникГуид` = s.`СотрудникГуид` WHERE (toDate32(reg.`ДатаНачала`) <= s.`Период`) AND (((toDate32(reg.`ДатаОкончанияИнтервала`) + 1) >= s.`Период`) OR (toDate32(reg.`ДатаОкончанияИнтервала`) <= '1970-01-02'))), plan AS (SELECT toDate32(r.`ДатаВыгрузки`) AS `Дата`, r.`ДолжностьУправленческая` AS `ДолжностьУправленческая`, r.`ШтатноеРасписаниеГуид` AS `ШтатноеРасписаниеГуид`, argMax(r.`КоличествоСтавок`, r.`ДатаВыгрузки`) AS `План`, r.`Подразделение` AS `Подразделение`, r.`КодМагазина`, argMax(if(r.`ДатаЗакрытия` <= '1970-01-02', NULL, r.`ДатаЗакрытия`), r.`ДатаВыгрузки`) AS `ДатаЗакрытия` FROM `zendendb`.`ШтатноеРасписание` AS r WHERE (r.`Должность` IS NOT NULL) AND (toDate32(r.`ДатаВыгрузки`) = {start_date:date}) AND ((r.`ДатаЗакрытия` IS NULL) OR (toDate32(r.`ДатаЗакрытия`) > {start_date:date}) OR (toDate32(r.`ДатаЗакрытия`) <= '1970-01-02')) AND (r.`КодМагазина` != 0) GROUP BY `Дата`, `ДолжностьУправленческая`, `ШтатноеРасписаниеГуид`, `Подразделение`, `КодМагазина`), fact_by_employee AS (SELECT s.`Период` AS `Период`, s.`СотрудникГуид` AS `СотрудникГуид`, s.`Код` AS `Код`, s.`Сотрудник` AS `Сотрудник`, s.`ФизическоеЛицоГуид` AS `ФизическоеЛицоГуид`, s.`ФизическоеЛицо` AS `ФизическоеЛицо`, s.`ОрганизацияГуид` AS `ОрганизацияГуид`, s.`Организация` AS `Организация`, s.`ГоловнойСотрудникГуид` AS `ГоловнойСотрудникГуид`, ki.`ПериодЗаписи` AS `РабочееМестоПериодРегистрации`, ki.`Подразделение` AS `Подразделение`, ki.`Должность` AS `Должность`, ki.`ДолжностьПоШтатномуРасписаниюГуид` AS `ДолжностьПоШтатномуРасписаниюГуид`, ki.`ДолжностьПоШтатномуРасписанию` AS `ДолжностьПоШтатномуРасписанию`, ki.`КоличествоСтавок` AS `КоличествоСтавок`, vz.`ВидЗанятости` AS `ВидЗанятости`, ki.`ВидСобытия` AS `ВидСобытия`, tkd.`ДатаПриема` AS `ДатаПриема`, tkdg.`ДатаУвольнения` AS `ДатаУвольнения`, gr.`ГрафикРаботы` AS `ГрафикРаботы`, gr.`ДлительностьРабочейНедели` AS `ДлительностьРабочейНедели`, gr.`РабочихДнейВНеделе` AS `РабочихДнейВНеделе`, ss.`Состояние` AS `Состояние`, p.`Подразделение` AS `ПодразделениеШтат`, p.`КодМагазина` AS `КодМагазина` FROM employees AS s LEFT JOIN `zendendb`.`ТекущиеКадровыеДанныеСотрудников` AS tkd ON s.`СотрудникГуид` = tkd.`СотрудникГуид` LEFT JOIN `zendendb`.`ТекущиеКадровыеДанныеСотрудников` AS tkdg ON s.`ГоловнойСотрудникГуид` = tkdg.`СотрудникГуид` LEFT JOIN history AS ki ON (s.`СотрудникГуид` = ki.`СотрудникГуид`) AND (s.`Период` = ki.`Период`) LEFT JOIN employees_types AS vz ON (s.`СотрудникГуид` = vz.`СотрудникГуид`) AND (s.`Период` = vz.`Период`) LEFT JOIN work_chedule AS gr ON (s.`СотрудникГуид` = gr.`СотрудникГуид`) AND (s.`Период` = gr.`Период`) LEFT JOIN state AS ss ON (s.`СотрудникГуид` = ss.`СотрудникГуид`) AND (s.`Период` = ss.`Период`) LEFT JOIN `zendendb`.`МестоПозицииШтатногоРасписания` AS p ON p.`ПозицияГуид` = ki.`ДолжностьПоШтатномуРасписаниюГуид` WHERE (ki.`Должность` IS NOT NULL) AND (ki.`ВидСобытия` != 'Увольнение') AND (ki.`ВидСобытия` != 'НеподтвержденныеДанные') AND (p.`КодМагазина` != 0) AND (vz.`ВидЗанятости` IN ('Внутреннее cовместительство', 'Основное место работы', 'Совместительство')) AND (ss.`Состояние` IN ('Работа', 'Болезнь', 'Командировка', 'Отпуск основной', 'Отпуск учебный оплачиваемый', 'Дополнительный отпуск', 'Дополнительные выходные дни (оплачиваемые)'))), fact AS (SELECT `Период`, `ДолжностьПоШтатномуРасписаниюГуид`, `Должность`, `ПодразделениеШтат`, `КодМагазина`, sum(`КоличествоСтавок`) AS `КоличествоСтавок` FROM fact_by_employee GROUP BY `Период`, `ДолжностьПоШтатномуРасписаниюГуид`, `Должность`, `ПодразделениеШтат`, `КодМагазина`), plan_fact AS (SELECT ifNull(f.`Период`, p.`Дата`) AS `Дата`, ifNull(f.`ДолжностьПоШтатномуРасписаниюГуид`, p.`ШтатноеРасписаниеГуид`) AS `ДолжностьГуид`, ifNull(f.`Должность`, p.`ДолжностьУправленческая`) AS `Должность`, ifNull(f.`КодМагазина`, p.`КодМагазина`) AS `КодМагазина`, ifNull(f.`ПодразделениеШтат`, p.`Подразделение`) AS `Подразделение`, p.`План` AS `План`, ifNull(f.`КоличествоСтавок`, 0) AS `Факт` FROM plan AS p FULL OUTER JOIN fact AS f ON f.`ДолжностьПоШтатномуРасписаниюГуид` = p.`ШтатноеРасписаниеГуид`) SELECT `Дата`, m.`Магазин Родитель` AS `Магазин Родитель`, m.`Магазин` AS `Подразделение`, multiIf(((p.`Округ` = 'Московская область') AND (m.`Город` != 'Москва')) OR (m.`Город` = 'Москвовская область'), 'Московская область', m.`Город` = 'Ростов', 'Ростов-на-Дону', m.`Город`) AS `Город`, m.`ТипМагазинаДляПланированияУПП` AS `ТипМагазина`, `Должность`, `ДолжностьГуид`, m.`Территорияальный Менеджер` AS `Территориальный Менеджер`, `План`, `Факт`, pf.`КодМагазина` FROM plan_fact AS pf ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`КодМагазина` = pf.`КодМагазина` ANY LEFT JOIN `zendendb`.`ЧасовыеПояса` AS p ON m.`Город` = p.`Город` WHERE ((`План` IS NOT NULL) OR (`Факт` IS NOT NULL)) AND (m.`Магазин Родитель` IN (SELECT * FROM `zendendb`.`Магазины_Родители_v`)) SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`Stock_TM_MP_v` AS SELECT {end_date:date} AS dt, w.`Контрагент` AS mp, w.`НоменклатураКодДляОбмена` AS kdo, sum(w.`Количество`) AS qty FROM `zendendb`.`ТоварыПереданныеTM` AS w WHERE (w.`Контрагент` IN ('Вайлдберриз ООО', 'Интернет Решения ООО Thomas Munz (Озон)', 'Купишуз ООО', 'МАРКЕТПЛЕЙС ООО', 'РВБ ООО', 'Вайлдберриз-Thomas Muenz', 'Яндекс ООО', 'Яндекс Маркет ООО')) AND (toDate(`Период`) <= {end_date:date}) GROUP BY w.`Контрагент`, w.`НоменклатураКодДляОбмена`;

