CREATE VIEW `zendendb`.`TM_MP_Retail_sales_report_SALES_MP_v` (`Дата` Date, `ТипДанных` String, `Магазин` LowCardinality(Nullable(String)), `ТипСклада` String, `Склад` String, `ТипКоммерции` String, `Чек` UUID, `Возврат` UInt8, `КДО` Nullable(UInt32), `Размер` Nullable(String), `Количество` Decimal(38, 3), `Сумма` Decimal(38, 2), `СуммаСоСкидкой` Decimal(38, 2), `Себестоимость` Nullable(Decimal(10, 5)), `Трафик` Nullable(Nothing), `Артикул` Nullable(String), `Товар` Nullable(String), `СвойствоВидОбуви` Nullable(String), `СвойствоГод` Nullable(String), `СвойствоРод` Nullable(String), `СвойствоСезон` Nullable(String), `СвойствоТорговаяМарка` Nullable(String), `СвойствоТорговаяМаркаГруппа` LowCardinality(Nullable(String)), `ТипНоменклатуры` Nullable(String), `OrderTM` Nullable(String), `СвойствоКоллекцияПроизводства` Nullable(String), `СвойствоКоллекцияПроизводстваКомментарий` Nullable(String), `ПовторАналогНовинка` Nullable(String), `СвойствоПодвидОбуви` Nullable(String), `СвойствоВысотаКаблука` Nullable(Float32), `СвойствоМатериалВерха` Nullable(String), `СвойствоМатериалВерхаКомментарий` Nullable(String), `СвойствоРазмерТовара` Nullable(String), `СвойствоПроект` LowCardinality(Nullable(String)), `m.Дивизиональный Директор` Nullable(String), `Магазин Родитель` Nullable(String), `Региональный Директор` Nullable(String), `Территориальный Менеджер` Nullable(String), `Город` Nullable(String), `ТипМагазинаУПП` Nullable(String), `Регион` Nullable(String), `ТипМагазинаДляПланированияУПП` Nullable(String), `КодМагазина` Nullable(UInt32)) AS WITH sales AS (SELECT toDate(s.`Период`) AS `Дата`, mpm.group_str AS `Магазин`, t.`ТоварГуид` AS `ТоварГуид`, t.`КодДляОбмена` AS `КДО`, s.`ХарактеристикаНоменклатуры` AS `Размер`, sumIf(s.`Количество`, s.`СтоимостьРегл` != 0) AS `Количество`, sum(s.`СтоимостьРегл`) AS `Сумма`, if(s.`Количество` < 0, 1, 0) AS `Возврат` FROM `zendendb`.`ПродажиУПП` AS s ANY LEFT JOIN `zendendb`.TM_MP_mapping AS mpm ON (mpm.value_str = s.`Контрагент`) AND (mpm.mapping_type = 'Контрагент') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`ТоварГуид` = s.`ТоварГуид` WHERE (s.`Организация` = 'Мюнц Групп ООО') AND (s.`Контрагент` IN ('Вайлдберриз-Thomas Muenz', 'Вайлдберриз ООО', 'Интернет Решения ООО Thomas Munz (Озон)', 'Купишуз ООО', 'МАРКЕТПЛЕЙС ООО', 'РВБ ООО', 'Яндекс Маркет ООО', 'Яндекс ООО')) AND (t.`ТипНоменклатуры` NOT IN ('Услуги', 'Услуги (оказанные)', 'Услуги (полученные)')) GROUP BY `Дата`, `Магазин`, `ТоварГуид`, `КДО`, `Размер`, `Возврат`) SELECT s.`Дата` AS `Дата`, 'ПродажаМП' AS `ТипДанных`, s.`Магазин` AS `Магазин`, '' AS `ТипСклада`, '' AS `Склад`, 'Маркетплейс' AS `ТипКоммерции`, toUUID('00000000-0000-0000-0000-000000000000') AS `Чек`, s.`Возврат` AS `Возврат`, s.`КДО` AS `КДО`, s.`Размер` AS `Размер`, s.`Количество` AS `Количество`, s.`Сумма` AS `Сумма`, s.`Сумма` AS `СуммаСоСкидкой`, sb.value_rub AS `Себестоимость`, NULL AS `Трафик`, t.`Артикул` AS `Артикул`, t.`Товар` AS `Товар`, t.`СвойствоВидОбуви` AS `СвойствоВидОбуви`, t.`СвойствоГод` AS `СвойствоГод`, t.`СвойствоРод` AS `СвойствоРод`, t.`СвойствоСезон` AS `СвойствоСезон`, t.`СвойствоТорговаяМарка` AS `СвойствоТорговаяМарка`, tm.group_str AS `СвойствоТорговаяМаркаГруппа`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, t.OrderTM AS OrderTM, t.`СвойствоКоллекцияПроизводства` AS `СвойствоКоллекцияПроизводства`, t.`СвойствоКоллекцияПроизводстваКомментарий` AS `СвойствоКоллекцияПроизводстваКомментарий`, t.`ПовторАналогНовинка` AS `ПовторАналогНовинка`, t.`СвойствоПодвидОбуви` AS `СвойствоПодвидОбуви`, toFloat32OrZero(replaceAll(t.`СвойствоВысотаКаблука`, ',', '.')) AS `СвойствоВысотаКаблука`, `СвойствоМатериалВерха`, `СвойствоМатериалВерхаКомментарий`, `СвойствоРазмерТовара`, p.`Проект` AS `СвойствоПроект`, m.`Дивизиональный Директор`, `Магазин Родитель` AS `Магазин Родитель`, m.`Региональный Директор` AS `Региональный Директор`, m.`Территорияальный Менеджер` AS `Территориальный Менеджер`, m.`Город` AS `Город`, m.`ТипМагазинаУПП` AS `ТипМагазинаУПП`, m.`Регион` AS `Регион`, m.`ТипМагазинаДляПланированияУПП` AS `ТипМагазинаДляПланированияУПП`, m.`КодМагазина` AS `КодМагазина` FROM sales AS s ANY LEFT JOIN (SELECT t.*, c.`Комментарий` AS `СвойствоМатериалВерхаКомментарий` FROM `zendendb`.`ТоварыУПП` AS t LEFT JOIN (SELECT t.`Наименование`, max(t.`Комментарий`) AS `Комментарий` FROM `zendendb`.`ТоварыУППКомментарии` AS t WHERE (`Код` ILIKE '%материал верха%') AND (`Код` NOT ILIKE '%Материал верха доп%') GROUP BY t.`Наименование`) AS c ON t.`СвойствоМатериалВерха` = c.`Наименование`) AS t ON t.`КодДляОбмена` = s.`КДО` LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS sb ON (sb.half = if(toMonth(s.`Дата`) <= 6, toStartOfYear(s.`Дата`), toStartOfYear(s.`Дата`) + toIntervalMonth(6))) AND (sb.kdo = t.`КодДляОбмена`) LEFT JOIN `zendendb`.TM_MP_mapping AS tm ON (tm.value_str = t.`СвойствоТорговаяМарка`) AND (tm.mapping_type = 'ТМ') LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`Магазин` = s.`Магазин` ANY LEFT JOIN `zendendb`.`ТорговаяМаркаПроект` AS p ON t.`СвойствоТорговаяМарка` = p.`СвойствоТорговаяМарка` SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`TM_MP_Retail_sales_report_SALES_RT_v` (`Дата` Date, `ТипДанных` String, `Магазин` Nullable(String), `ТипСклада` String, `Склад` String, `ТипКоммерции` String, `Чек` UUID, `Возврат` UInt8, `КДО` Nullable(UInt32), `Размер` String, `Количество` Decimal(38, 3), `Сумма` Decimal(38, 2), `СуммаСоСкидкой` Decimal(38, 2), `Себестоимость` Nullable(Decimal(10, 5)), `Трафик` Nullable(Nothing), `Артикул` Nullable(String), `Товар` Nullable(String), `СвойствоВидОбуви` Nullable(String), `СвойствоГод` Nullable(String), `СвойствоРод` Nullable(String), `СвойствоСезон` Nullable(String), `СвойствоТорговаяМарка` Nullable(String), `СвойствоТорговаяМаркаГруппа` LowCardinality(Nullable(String)), `ТипНоменклатуры` Nullable(String), `OrderTM` Nullable(String), `СвойствоКоллекцияПроизводства` Nullable(String), `СвойствоКоллекцияПроизводстваКомментарий` Nullable(String), `ПовторАналогНовинка` Nullable(String), `СвойствоПодвидОбуви` Nullable(String), `СвойствоВысотаКаблука` Nullable(Float32), `t.СвойствоМатериалВерха` Nullable(String), `t.СвойствоМатериалВерхаКомментарий` Nullable(String), `t.СвойствоРазмерТовара` Nullable(String), `СвойствоПроект` LowCardinality(Nullable(String)), `m.Дивизиональный Директор` Nullable(String), `Магазин Родитель` Nullable(String), `Региональный Директор` Nullable(String), `Территориальный Менеджер` Nullable(String), `Город` Nullable(String), `ТипМагазинаУПП` Nullable(String), `Регион` Nullable(String), `ТипМагазинаДляПланированияУПП` Nullable(String), `КодМагазина` Nullable(UInt32)) AS WITH tm_shops AS (SELECT s.`МагазинГуид` FROM `zendendb`.`Магазины_fix` AS s WHERE s.`Магазин Родитель` IN ('Thomas Munz', 'Salamander', 'Закрытые SALAMANDER', 'Неиспользуемые ТМ')), sales AS (SELECT toDate(s.Period) AS `Дата`, s.MagazinGuid AS `МагазинГуид`, s.NomenklaturaGuid, s.KHarakteristikaNomenklatury, toUUIDOrDefault(s.UnikalnyyIdentifikatorCHeka, toUUID(hex(sipHash128(s.Period, s.MagazinGuid, s.NomerCHekaKKM)))) AS ChekGuid, if(s.VidOperatsii = 'про