эффициент`)), 3) AS `Трафик`, 0 AS `КДО` FROM `zendendb`.`ПосещаемостьМагазинов` AS t LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = t.`МагагазинГуид` WHERE (toDate(t.`Период`) < today()) AND (t.`МагагазинГуид` IN (SELECT `МагазинГуид` FROM tm_shops)) GROUP BY `Дата`, `МагазинГуид`) SELECT s.`Дата` AS `Дата`, 'Трафик' AS `ТипДанных`, m.`Магазин` AS `Магазин`, '' AS `ТипСклада`, '' AS `Склад`, 'Розница' AS `ТипКоммерции`, toUUID('00000000-0000-0000-0000-000000000000') AS `Чек`, NULL AS `Возврат`, s.`КДО` AS `КДО`, '' AS `Размер`, NULL AS `Количество`, NULL AS `Сумма`, NULL AS `СуммаСоСкидкой`, NULL AS `Себестоимость`, s.`Трафик` AS `Трафик`, t.`Артикул` AS `Артикул`, t.`Товар` AS `Товар`, t.`СвойствоВидОбуви` AS `СвойствоВидОбуви`, t.`СвойствоГод` AS `СвойствоГод`, t.`СвойствоРод` AS `СвойствоРод`, t.`СвойствоСезон` AS `СвойствоСезон`, t.`СвойствоТорговаяМарка` AS `СвойствоТорговаяМарка`, NULL AS `СвойствоТорговаяМаркаГруппа`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, t.OrderTM AS OrderTM, t.`СвойствоКоллекцияПроизводства` AS `СвойствоКоллекцияПроизводства`, t.`СвойствоКоллекцияПроизводстваКомментарий` AS `СвойствоКоллекцияПроизводстваКомментарий`, t.`ПовторАналогНовинка` AS `ПовторАналогНовинка`, t.`СвойствоПодвидОбуви` AS `СвойствоПодвидОбуви`, toFloat32OrZero(replaceAll(t.`СвойствоВысотаКаблука`, ',', '.')) AS `СвойствоВысотаКаблука`, `СвойствоМатериалВерха`, `СвойствоМатериалВерхаКомментарий`, `СвойствоРазмерТовара`, p.`Проект` AS `СвойствоПроект`, m.`Дивизиональный Директор`, m.`Магазин Родитель` AS `Магазин Родитель`, m.`Региональный Директор` AS `Региональный Директор`, m.`Территорияальный Менеджер` AS `Территориальный Менеджер`, m.`Город` AS `Город`, m.`ТипМагазинаУПП` AS `ТипМагазинаУПП`, m.`Регион` AS `Регион`, m.`ТипМагазинаДляПланированияУПП` AS `ТипМагазинаДляПланированияУПП`, m.`КодМагазина` AS `КодМагазина` FROM shop_traffic AS s ANY LEFT JOIN (SELECT t.*, c.`Комментарий` AS `СвойствоМатериалВерхаКомментарий` FROM `zendendb`.`ТоварыУПП` AS t LEFT JOIN (SELECT t.`Наименование`, max(t.`Комментарий`) AS `Комментарий` FROM `zendendb`.`ТоварыУППКомментарии` AS t WHERE (`Код` ILIKE '%материал верха%') AND (`Код` NOT ILIKE '%Материал верха доп%') GROUP BY t.`Наименование`) AS c ON t.`СвойствоМатериалВерха` = c.`Наименование`) AS t ON (t.`КодДляОбмена` = s.`КДО`) AND (t.`КодДляОбмена` != 0) LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = s.`МагазинГуид` ANY LEFT JOIN `zendendb`.`ТорговаяМаркаПроект` AS p ON t.`СвойствоТорговаяМарка` = p.`СвойствоТорговаяМарка` SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`TM_MP_art_zoning_v` AS WITH today_season AS (SELECT multiIf((toMonth({cur_date:date}) IN (1, 2)), toStartOfYear({cur_date:date}) - toIntervalMonth(6), (toMonth({cur_date:date}) IN (9, 10, 11, 12)), toStartOfYear({cur_date:date}) + toIntervalMonth(6), (toMonth({cur_date:date}) IN (3, 4, 5, 6, 7, 8)), toStartOfYear({cur_date:date}), NULL) AS period_start_date, multiIf((toMonth({cur_date:date}) IN (1, 2)), toStartOfYear({cur_date:date}) - toIntervalMonth(4), (toMonth({cur_date:date}) IN (9, 10, 11, 12)), toStartOfYear({cur_date:date}) + toIntervalMonth(8), (toMonth({cur_date:date}) IN (3, 4, 5, 6, 7, 8)), toStartOfYear({cur_date:date}) + toIntervalMonth(2), NULL) AS season_start_date, multiIf(toMonth(season_start_date) = 3, concat('SS', toYear(season_start_date)), toMonth({cur_date:date}) >= 9, concat('FW', toYear({cur_date:date}), '-', toYear({cur_date:date}) + 1), concat('FW', toYear({cur_date:date}) - 1, '-', toYear({cur_date:date}))) AS type_season_year, if(toMonth(season_start_date) = 3, 'SS', 'FW') AS type_season), total_sales AS (SELECT mp, kdo, sum(qty) AS qty_total, sum(s.turnover) AS turnover_total, (SELECT type_season FROM today_season) AS type_season, (SELECT type_season_year FROM today_season) AS type_season_year FROM `zendendb`.`ПродажиУПП_MP_TM_v` AS s WHERE (dt <= {cur_date:date}) AND (dt >= (SELECT period_start_date FROM today_season)) GROUP BY mp, kdo), total_orders AS (SELECT mp, kdo, sum(order_qty) AS order_qty_total, sum(order_rub) AS order_rub_total, SumIf(order_qty, dt >= ({cur_date:date} - 6)) AS order_qty_week, (SELECT type_season FROM today_season) AS type_season, (SELECT type_season_year FROM today_season) AS type_season_year FROM `zendendb`.orders_TM_MP WHERE (dt <= {cur_date:date}) AND (dt >= (SELECT period_start_date FROM today_season)) GROUP BY mp, kdo), stock AS (SELECT group_str AS mp, kdo, sum(qty) AS total_stock FROM `zendendb`.`ТоварыПереданныеКонтрагентам_TM` AS t LEFT JOIN `zendendb`.TM_MP_mapping AS m ON (m.value_str = t.mp) AND (m.mapping_type = 'Склад') WHERE dt = ({cur_date:date} - 1) GROUP BY kdo, group_str HAVING total_stock != 0), for_join AS (SELECT mp, kdo FROM total_sales UNION DISTINCT SELECT mp, kdo FROM total_orders UNION DISTINCT SELECT mp, kdo FROM stock), for_plan_join AS (SELECT {cur_date:date} AS dt, t.mp AS mp, t.kdo AS kdo, (SELECT type_season FROM today_season) AS type_season, (SELECT type_season_year FROM today_season) AS type_season_year, g.`СвойствоКоллекцияПроизводстваКомментарий` AS collection, collection = '0. New (0)' AS is_new, g.`ТипНоменклатуры` AS goods_type, g.`СвойствоРод` AS gender, g.`СвойствоСезон` AS season, qty_total, turnover_total, order_qty_total, order_qty_week, order_rub_total, total_stock, if((order_qty_total IS NULL) OR (qty_total IS NULL), 0, qty_total / order_qty_total) AS buyout, if(((qty_total IS NULL) AND ((qty_total + total_stock) IS NULL)) OR ((qty_total + total_stock) = 0), 0, qty_total / (qty_total + total_stock)) AS selling_share, if((order_qty_week * buyout) != 0, (((order_qty_week * buyout) + (total_stock * 2)) / 2) / (order_qty_week * buyout), 999) AS turnaround FROM for_join AS t LEFT JOIN total_sales AS s ON (s.mp = t.mp) AND (s.kdo = t.kdo) LEFT JOIN total_orders AS o ON (o.mp = t.mp) AND (o.kdo = t.kdo) LEFT JOIN stock AS st ON (st.mp = t.mp) AND (st.kdo = t.kdo) LEFT JOIN `zendendb`.`ТоварыУПП` AS g ON g.`КодДляОбмена` = t.kdo) SELECT dt, mp, kdo, type_season_year AS type_season, is_new, qty_total, turnover_total, order_qty_total, order_qty_week, order_rub_total, total_stock, buyout, selling_share, turnaround, p.selling_share AS plan_selling_share, p.turnaround AS plan_turnaround, multiIf(plan_selling_share IS NULL, NULL, total_stock IS NULL, NULL, (selling_share >= plan_selling_share) AND (turnaround <= plan_turnaround), 'Белая зона', (selling_share < plan_selling_share) AND (turnaround < plan_turnaround), 'Серая зона', (selling_share >= plan_selling_share) AND (turnaround > plan_turnaround), 'Жёлтая зона', 'Красная зона') AS sale_zone, toUUID(hex(sipHash128(s.type_season_year, s.mp, s.kdo))) AS season_mp_kdo FROM for_plan_join AS s LEFT JOIN `zendendb`.`ПланОборачиваемостиМП_TM` AS p ON (p.is_new = (s.collection = '0. New (0)')) AND (p.year_num = toYear(s.dt)) AND (p.week_num = toWeek(s.dt)) AND (multiIf(p.mp = 'LM', 'Ламода', p.mp = 'OZ', 'Озон', p.mp = 'WB', 'Вайлдберриз', '') = s.mp) AND (p.gender = s.gender) AND (p.season = s.season) AND (p.type_season = s.type_season) AND (s.goods_type = 'Обувь') SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`TM_MP_conversion_v` (`mp` String, `dt` Date, `kdo` UInt32, `Показы` Nullable(Int64), `Переходы` Int64, `Корзина` Int64, `Заказы` Int64, `Возвраты` Int64, `Отмены` Int64, `Заказы, руб` Decimal(38, 3), `pr_group` String, `Артикул` String, `СвойствоВидОбуви` String, `СвойствоГод` String, `СвойствоМатериалВерха` String, `СвойствоРод` String, `СвойствоСезон` String, `СвойствоТорговаяМарка` String, `ТипНоменклатуры` String, `СтавкаНДС` String, `OrderTM` String, `СвойствоКоллекцияПроизводства` String, `СвойствоКоллекцияПроизводстваКомментарий` String, `ПовторАналогНовинка` String) AS WITH conversion AS (SELECT 'Вайлдберриз' AS mp, r.dt, m.kdo, NULL AS `Показы`, sum(r.openCardCount) AS `Переходы`, sum(r.addToCartCount) AS `Корзина`, sum(r.ordersCount) AS `Заказы`, (sum(r.ordersCount) - sum(r.buyoutsCount)) - sum(r.cancelCount) AS `Возвраты`, sum(r.cancelCount) AS `Отмены`, sum(r.ordersSumRub) AS `Заказы, руб` FROM `zendendb`.WB_Order_nm_report AS r ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_in_mp = toString(r.nmID)) AND (m.mp = 'Вайлдберриз') GROUP BY r.dt, m.kdo UNION ALL SELECT 'Озон' AS mp, r.date, m.kdo, sum(r.hits_view) AS `Показы`, sum(r.hits_view_pdp) AS `Переходы`, sum(r.hits_tocart) AS `Корзина`, sum(r.ordered_units) AS `Заказы`, sum(r.returns) AS `Возвраты`, sum(r.cancellations) AS `Отмены`, sum(r.revenue) AS `Заказы, руб` FROM `zendendb`.OZON_analytic_TM AS r ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_in_mp = r.sku) AND (m.mp = 'Озон') GROUP BY r.date, m.kdo) SELECT c.*, multiIf((t.`СвойствоТорговаяМарка` IN ('ARA', 'Bugatti', 'KINETIX', 'LUMBERJACK', 'POLARIS', 'Reebok', 'REMONTE', 'Rieker', 'U.S. POLO ASSN.')), 'ПТМ', (t.`СвойствоТорговаяМарка` IN ('Bridget', 'BRIGGS', 'LOLLI|POLLI', 'MUNZ Shoes', 'MUNZ YOUNG', 'O2')), 'СТМ', (t.`СвойствоТорговаяМарка` IN ('LURCHI', 'M-Shoes', 'SALAMANDER')), 'Salamander', (t.`СвойствоТорговаяМарка` IN ('Thomas Munz', 'Thomas Munz black')), 'Thomas Munz', '') AS pr_group, t.`Артикул` AS `Артикул`, t.`СвойствоВидОбуви` AS `СвойствоВидОбуви`, t.`СвойствоГод` AS `СвойствоГод`, t.`СвойствоМатериалВерха` AS `СвойствоМатериалВерха`, t.`СвойствоРод` AS `СвойствоРод`, t.`СвойствоСезон` AS `СвойствоСезон`, t.`СвойствоТорговаяМарка` AS `СвойствоТорговаяМарка`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, t.`СтавкаНДС` AS `СтавкаНДС`, t.OrderTM AS OrderTM, t.`СвойствоКоллекцияПроизводства` AS `СвойствоКоллекцияПроизводства`, t.`СвойствоКоллекцияПроизводстваКомментарий` AS `СвойствоКоллекцияПроизводстваКомментарий`, t.`ПовторАналогНовинка` AS `ПовторАналогНовинка` FROM conversion AS c LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = c.kdo SETTINGS final = 1;

CREATE VIEW `zendendb`.`TM_MP_sales_report_by_region_v` AS WITH kdo_mp_dt_prep AS (SELECT DISTINCT o.dt, toUInt32(o.kdo) AS kdo, mp FROM `zendendb`.orders_TM_MP AS o WHERE (dt >= {start_day:date}) AND (dt <= {end_day:date}) UNION DISTINCT SELECT DISTINCT p.dt AS dt, toUInt32(p.kdo), mp FROM `zendendb`.prices_TM_MP AS p WHERE (dt >= {start_day:date}) AND (dt <= {end_day:date}) UNION DISTINCT SELECT DISTINCT dt, toUInt32(s.kdo), mp FROM `zendendb`.`ПродажиУПП_MP_TM_v` AS s WHERE (dt >= {start_day:date}) AND (dt <= {end_day:date}) UNION DISTINCT SELECT DISTINCT dt, toUInt32(s.kdo), warehouse FROM `zendendb`.`ТоварыНаСкладахAPI_TM` AS s WHERE (dt >= {start_day:date}) AND (dt <= {end_day:date})), kdo_mp_dt AS (SELECT DISTINCT dt, kdo, ifNull(group_str, t.mp) AS mp, 'не указано' AS stockWarehouseName, 'не указано' AS stockWarehouseRegionName, 'не указано' AS stockWarehouseOblastOkrugName, 'не указано' AS warehouseName, 'не указано' AS warehouseRegionName, 'не указано' AS warehouseOblastOkrugName, 'не указано' AS deliveryOdoblastOkrugName, 'не указано' AS deliveryRegionName FROM kdo_mp_dt_prep AS t LEFT JOIN `zendendb`.TM_MP_mapping AS m ON (m.value_str = t.mp) AND (m.mapping_type = 'Склад') WHERE (kdo != 0) AND (kdo IS NOT NULL)), stock_ship AS (SELECT dt, kdo, group_str AS mp, sum(qty_reserved) AS qty_reserved, sum(qty_claimed_for_shipment) AS qty_claimed_for_shipment, sum(qty_free_stock) AS qty_free_stock FROM `zendendb`.`ТоварыВРезервеКПередачеОстаток_TM` AS t LEFT JOIN `zendendb`.TM_MP_mapping AS m ON (m.value_str = t.warehouse) AND (m.mapping_type = 'Склад') WHERE ((dt >= {start_day:date}) AND (dt <= {end_day:date})) AND (kdo != 0) GROUP BY dt, kdo, group_str), stock_mp AS (SELECT dt, kdo, sum(qty) AS qty, group_str AS mp FROM `zendendb`.`ТоварыНаСкладах_TM` AS t LEFT JOIN `zendendb`.TM_MP_mapping AS m ON (m.value_str = t.warehouse) AND (m.mapping_type = 'Склад') WHERE ((dt >= {start_day:date}) AND (dt <= {end_day:date})) AND (warehouse IN ('Маркетплейс Ламода-ТМ', 'Маркетплейс СберМегаМаркет-Мюнц', 'Маркетплейс Озон-ТМ', 'Маркетплейс Яндекс-Маркет-ТМ ')) GROUP BY dt, kdo, group_str), stock_mp_wb AS (SELECT dt, kdo, warehouse AS stockWarehouseName, max(wct.regionName) AS stockRegionName, max(wct.oblastOkrugName) AS stockOkrugName, sum(qty) AS qty, 'Вайлдберриз' AS mp FROM `zendendb`.`ТоварыНаСкладахAPI_TM` AS t LEFT JOIN `zendendb`.TM_MP_mapping AS m ON (m.value_str = t.warehouse) AND (m.mapping_type = 'Склад') ANY LEFT JOIN `zendendb`.WB_warehouses_catalog AS wct ON wct.warehouseName = t.warehouse WHERE ((dt >= {start_day:date}) AND (dt <= {end_day:date})) AND (shop IN ('Вайлдберриз-ТМ')) GROUP BY dt, kdo, mp, stockWarehouseName), stock_1c AS (SELECT dt, kdo, sum(qty) AS qty, group_str AS mp FROM `zendendb`.`ТоварыПереданныеКонтрагентам_TM` AS t LEFT JOIN `zendendb`.TM_MP_mapping AS m ON (m.value_str = t.mp) AND (m.mapping_type = 'Склад') WHERE ((dt >= {start_day:date}) AND (dt <= {end_day:date})) GROUP BY dt, kdo, group_str), shipments AS (SELECT dt, kdo, sum(qty) AS qty, group_str AS mp FROM `zendendb`.`ТоварыПереданныеДвижения_TM` AS t LEFT JOIN `zendendb`.TM_MP_mapping AS m ON (m.value_str = t.mp) AND (m.mapping_type = 'Склад') WHERE ((dt >= {start_day:date}) AND (dt <= {end_day:date})) GROUP BY dt, kdo, group_str), sales AS (SELECT dt, kdo, qty, turnover, mp FROM `zendendb`.`ПродажиУПП_MP_TM_v` AS t WHERE ((dt >= {start_day:date}) AND (dt <= {end_day:date}))), orders AS (SELECT o.dt, o.mp, o.kdo, o.warehouseName, o.warehouseRegionName, o.warehouseOblastOkrugName, if(o.oblastOkrugName = '', 'ЕАЭС', o.oblastOkrugName) AS oblastOkrugName, o.regionName, sum(o.order_qty) AS order_qty, sum(o.order_rub) AS order_rub, sum(o.order_rub_spp) AS order_rub_spp, sum(o.order_qty_cancelled) AS order_qty_cancelled, sum(o.order_rub_cancelled) AS order_rub_cancelled, sum(o.order_rub_spp_cancelled) AS order_rub_spp_cancelled FROM `zendendb`.orders_TM_MP_by_region AS o WHERE ((dt >= {start_day:date}) AND (dt <= {end_day:date})) GROUP BY o.dt, o.mp, o.kdo, o.warehouseName, o.warehouseRegionName, o.warehouseOblastOkrugName, o.oblastOkrugName, o.regionName), final_dataset AS (SELECT kmd.dt AS dt, kmd.mp AS mp, 'не указано' AS stockWarehouseName, 'не указано' AS stockRegionName, 'не указано' AS stockOkrugName, o.warehouseName AS warehouseName, o.warehouseRegionName AS warehouseRegionName, o.warehouseOblastOkrugName AS warehouseOkrugName, o.oblastOkrugName AS deliveryOkrugName, o.regionName AS deliveryRegionName, kmd.kdo AS kdo, 0 AS sales_qty, 0 AS turnover, 0 AS stock_qty, 0 AS shipment_qty, 0 AS qty_reserved, 0 AS qty_claimed_for_shipment, 0 AS qty_free_stock, 0 AS qty_stock_mp, 0 AS cur_pr, 0 AS init_pr, o.order_qty AS orders_qty, o.order_rub AS order_rub, o.order_rub_spp AS order_rub_spp, o.order_qty_cancelled AS orders_qty_cancelled, o.order_rub_cancelled AS order_rub_cancelled, o.order_rub_spp_cancelled AS order_rub_spp_cancelled FROM kdo_mp_dt AS kmd LEFT JOIN orders AS o ON (o.dt = kmd.dt) AND (o.kdo = kmd.kdo) AND (o.mp = kmd.mp) WHERE (warehouseName != 'не указано') AND ((dt >= {start_day:date}) AND (dt <= {end_day:date})) UNION ALL SELECT kmd.dt AS dt, kmd.mp AS mp, s.stockWarehouseName AS stockWarehouseName, s.stockRegionName AS stockRegionName, s.stockOkrugName AS stockOkrugName, 'не указано' AS warehouseName, 'не указано' AS warehouseRegionName, 'не указано' AS warehouseOkrugName, 'не указано' AS deliveryOkrugName, 'не указано' AS deliveryRegionName, kmd.kdo AS kdo, 0 AS sales_qty, 0 AS turnover, 0 AS stock_qty, 0 AS shipment_qty, 0 AS qty_reserved, 0 AS qty_claimed_for_shipment, 0 AS qty_free_stock, s.qty AS qty_stock_mp, 0 AS cur_pr, 0 AS init_pr, 0 AS orders_qty, 0 AS order_rub, 0 AS order_rub_spp, 0 AS orders_qty_cancelled, 0 AS order_rub_cancelled, 0 AS order_rub_spp_cancelled FROM kdo_mp_dt AS kmd LEFT JOIN stock_mp_wb AS s ON (s.dt = kmd.dt) AND (s.kdo = kmd.kdo) AND (s.mp = kmd.mp) WHERE (stockWarehouseName != 'не указано') AND ((dt >= {start_day:date}) AND (dt <= {end_day:date})) UNION ALL SELECT kmd.dt AS dt, kmd.mp AS mp, 'не указано' AS stockWarehouseName, 'не указано' AS stockRegionName, 'не указано' AS stockOkrugName, 'не указано' AS warehouseName, 'не указано' AS warehouseRegionName, 'не указано' AS warehouseOkrugName, 'не указано' AS deliveryOkrugName, 'не указано' AS deliveryRegionName, kmd.kdo AS kdo, s.qty AS sales_qty, s.turnover AS turnover, soc.qty AS stock_qty, sh.qty AS shipment_qty, snd.qty_reserved AS qty_reserved, snd.qty_claimed_for_shipment AS qty_claimed_for_shipment, snd.qty_free_stock AS qty_free_stock, sm.qty AS qty_stock_mp, p.cur_pr AS cur_pr, p.init_pr AS init_pr, o.order_qty AS orders_qty, o.order_rub AS order_rub, o.order_rub_spp AS order_rub_spp, o.order_qty_cancelled AS orders_qty_cancelled, o.order_rub_cancelled AS order_rub_cancelled, o.order_rub_spp_cancelled AS order_rub_spp_cancelled FROM kdo_mp_dt AS kmd LEFT JOIN sales AS s ON (s.kdo = kmd.kdo) AND (s.mp = kmd.mp) AND (s.dt = kmd.dt) LEFT JOIN stock_1c AS soc ON (soc.kdo = kmd.kdo) AND (soc.mp = kmd.mp) AND (soc.dt = kmd.dt) LEFT JOIN shipments AS sh ON (sh.kdo = kmd.kdo) AND (sh.mp = kmd.mp) AND (sh.dt = kmd.dt) LEFT JOIN stock_ship AS snd ON (snd.kdo = kmd.kdo) AND (snd.mp = kmd.mp) AND (snd.dt = kmd.dt) LEFT JOIN orders AS o ON (o.dt = kmd.dt) AND (o.kdo = kmd.kdo) AND (o.mp = kmd.mp) AND (o.warehouseName = 'не указано') LEFT JOIN stock_mp AS sm ON (sm.dt = kmd.dt) AND (sm.kdo = kmd.kdo) AND (sm.mp = kmd.mp) LEFT JOIN stock_mp_wb AS smw ON (smw.dt = kmd.dt) AND (smw.kdo = kmd.kdo) AND (smw.mp = kmd.mp) AND (smw.stockWarehouseName = 'не указано') LEFT JOIN `zendendb`.prices_TM_MP AS p ON (p.dt = kmd.dt) AND (p.kdo = kmd.kdo) AND (p.mp = kmd.mp) WHERE ((dt >= {start_day:date}) AND (dt <= {end_day:date}))) SELECT f.dt AS dt, f.mp AS mp, f.stockWarehouseName AS stockWarehouseName, f.stockRegionName AS stockRegionName, f.stockOkrugName AS stockOkrugName, f.warehouseName AS warehouseName, f.warehouseRegionName AS warehouseRegionName, f.warehouseOkrugName AS warehouseOkrugName, f.deliveryRegionName AS deliveryRegionName, f.deliveryOkrugName AS deliveryOkrugName, f.kdo AS kdo, am.art_mp AS art_mp, am.art AS art, am.art_link AS art_link, sales_qty, turnover, stock_qty, shipment_qty, qty_reserved, qty_claimed_for_shipment, qty_free_stock, c.value_rub AS cost_val, qty_stock_mp, cur_pr, init_pr, orders_qty, order_rub, order_rub_spp, orders_qty_cancelled, order_rub_cancelled, order_rub_spp_cancelled, multiIf((t.`СвойствоТорговаяМарка` IN ('ARA', 'Bugatti', 'KINETIX', 'LUMBERJACK', 'POLARIS', 'Reebok', 'REMONTE', 'Rieker', 'U.S. POLO ASSN.')), 'ПТМ', (t.`СвойствоТорговаяМарка` IN ('Bridget', 'BRIGGS', 'LOLLI|POLLI', 'MUNZ Shoes', 'MUNZ YOUNG', 'O2')), 'СТМ', (t.`СвойствоТорговаяМарка` IN ('LURCHI', 'M-Shoes', 'SALAMANDER')), 'Salamander', (t.`СвойствоТорговаяМарка` IN ('Thomas Munz', 'Thomas Munz black')), 'Thomas Munz', '') AS pr_group, toYYYYMM(f.dt) AS month_year, (toYear(f.dt) * 100) + toWeek(f.dt) AS week_year, t.`Артикул` AS `Артикул`, t.`СвойствоВидОбуви` AS `СвойствоВидОбуви`, t.`СвойствоГод` AS `СвойствоГод`, t.`СвойствоМатериалВерха` AS `СвойствоМатериалВерха`, t.`СвойствоРод` AS `СвойствоРод`, t.`СвойствоСезон` AS `СвойствоСезон`, t.`СвойствоТорговаяМарка` AS `СвойствоТорговаяМарка`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, t.`СтавкаНДС` AS `СтавкаНДС`, t.OrderTM AS OrderTM, t.`СвойствоКоллекцияПроизводства` AS `СвойствоКоллекцияПроизводства`, t.`СвойствоКоллекцияПроизводстваКомментарий` AS `СвойствоКоллекцияПроизводстваКомментарий`, t.`ПовторАналогНовинка` AS `ПовторАналогНовинка` FROM final_dataset AS f LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS c ON (c.half = if(toMonth(f.dt) <= 6, toStartOfYear(f.dt), toStartOfYear(f.dt) + toIntervalMonth(6))) AND (c.kdo = f.kdo) ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS am ON (am.kdo = f.kdo) AND (am.mp = f.mp) ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = f.kdo WHERE ((sales_qty IS NOT NULL) OR (turnover IS NOT NULL) OR (stock_qty IS NOT NULL) OR (shipment_qty IS NOT NULL) OR (qty_reserved IS NOT NULL) OR (qty_claimed_for_shipment IS NOT NULL) OR (qty_free_stock IS NOT NULL) OR (qty_stock_mp IS NOT NULL) OR (orders_qty IS NOT NULL) OR (cur_pr IS NOT NULL)) AND ((f.dt >= {start_day:date}) AND (f.dt <= {end_day:date})) SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`TM_MP_sales_report_plan_v` AS WITH sales AS (SELECT toDate(s.`Период`) AS dt, s.`Контрагент` AS mp, multiIf(s.`Организация` = 'Дом Одежды ООО', 'ДО', s.`Организация` = 'РАДОСТЬ ООО', 'R', s.`Организация`) AS org, t.`КодДляОбмена` AS kdo, sumIf(s.`Количество`, s.`СтоимостьРегл` != 0) AS qty, sum(s.`СтоимостьРегл`) AS turnover FROM `zendendb`.`ПродажиУПП` AS s ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`ТоварГуид` = s.`ТоварГуид` WHERE (s.`Контрагент` IN ('Вайлдберриз-Thomas Muenz', 'Вайлдберриз ООО', 'Интернет Решения ООО Thomas Munz (Озон)', 'Интернет Решения ООО', 'Купишуз ООО', 'МАРКЕТПЛЕЙС ООО', 'РВБ ООО', 'Яндекс Маркет ООО', 'Яндекс ООО')) AND (t.`ТипНоменклатуры` NOT IN ('Услуги', 'Услуги (оказанные)', 'Услуги (полученные)')) AND (toDate(s.`Период`) >= {start_date:date}) AND (s.`Организация` IN ('Мюнц Групп ООО', 'Дом Одежды ООО', 'РАДОСТЬ ООО')) GROUP BY dt, org, mp, kdo), sales_with_groups AS (SELECT s.dt AS dt, s.mp AS kontragent, mp.group_str AS mp, s.org AS org, sum(s.qty) AS sales_qty, sum(s.turnover) AS turnover, sum(ifNull(c.value_rub, c2.value_rub)) AS cost_val, sum(s.turnover - (c.value_rub * s.qty)) AS gross, v.group_str AS type_group, tm.group_str AS tm_group, multiIf((t.`СвойствоРод` IN ('муж', 'Муж', 'Муж.', 'муж.', 'мальч.')), 'Муж', (t.`СвойствоРод` IN ('жен', 'Жен', 'Жен.', 'жен.', 'девич.')), 'Жен', 'без разделения') AS gender FROM sales AS s ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS c ON (c.half = if(toMonth(s.dt) <= 6, toStartOfYear(s.dt), toStartOfYear(s.dt) + toIntervalMonth(6))) AND (c.kdo = s.kdo) AND (c.price_type = 'Себестоимость') ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS c2 ON (c2.half = if(toMonth(s.dt) <= 6, toStartOfYear(s.dt), toStartOfYear(s.dt) + toIntervalMonth(6))) AND (c2.kdo = s.kdo) AND (c2.price_type = 'Плановая себестоимость') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = s.kdo ANY LEFT JOIN `zendendb`.TM_MP_mapping AS tm ON (tm.value_str = t.`СвойствоТорговаяМарка`) AND (tm.mapping_type = 'ТМ') ANY LEFT JOIN `zendendb`.TM_MP_mapping AS v ON (v.value_str = t.`ТипНоменклатуры`) AND (v.mapping_type = 'ВидНоменклатуры') ANY LEFT JOIN `zendendb`.TM_MP_mapping AS mp ON (mp.value_str = s.mp) AND (mp.mapping_type = 'Контрагент') GROUP BY dt, tm_group, mp, org, kontragent, gender, type_group), kontragent_mapping AS (SELECT DISTINCT s.dt, s.mp, s.kontragent FROM sales_with_groups AS s ORDER BY mp ASC, s.dt ASC WITH FILL FROM {start_date:date} TO {end_date:date} + toIntervalDay(1) STEP toIntervalDay(1) INTERPOLATE (`kontragent` AS kontragent)), plan AS (SELECT *, multiIf((`Пол` IN ('муж', 'Муж', 'Муж.', 'муж.', 'мальч.')), 'Муж', (`Пол` IN ('жен', 'Жен', 'Жен.', 'жен.', 'девич.')), 'Жен', 'без разделения') AS gender_fix FROM `zendendb`.`ПланПродаж_TM_MP`), predictions AS (SELECT p.`Дата` AS dt, p.`Проект` AS tm_group, p.`Маркетплейс` AS mp, p.gender_fix AS gender, m.kontragent AS kontragent, p.`Продуктовая группа` AS type_group, p.`Выручка` AS turnover_plan, p.`Вал` AS gross_plan, pr.sales_qty AS sales_qty_predict, pr.turnover AS turnover_predict, pr.gross AS gross_predict FROM plan AS p ANY LEFT JOIN `zendendb`.TM_MP_sales_report_prediction AS pr ON (p.`Дата` = pr.dt) AND (p.`Продуктовая группа` = pr.type_group) AND (lowerUTF8(p.`Маркетплейс`) = lowerUTF8(pr.mp)) AND (p.gender_fix = pr.gender) AND (p.`Проект` = pr.tm_group) ANY LEFT JOIN kontragent_mapping AS m ON (p.`Дата` = m.dt) AND (lowerUTF8(p.`Маркетплейс`) = lowerUTF8(m.mp)) WHERE p.`Дата` >= {start_date:date}), fact_prediction_plan AS (SELECT ifNull(s.dt, p.dt) AS dt, ifNull(s.tm_group, p.tm_group) AS tm_group, ifNull(s.mp, p.mp) AS mp, ifNull(s.gender, p.gender) AS gender, ifNull(s.type_group, p.type_group) AS type_group, ifNull(s.org, 'Мюнц Групп ООО') AS org, ifNull(s.kontragent, p.kontragent) AS kontragent, s.sales_qty, s.turnover, s.gross, s.cost_val, ifNull(p.sales_qty_predict, toDecimal64(s.sales_qty, 3)) AS sales_qty_predict, ifNull(p.turnover_predict, toDecimal64(s.turnover, 3)) AS turnover_predict, ifNull(p.gross_predict, toDecimal64(s.gross, 3)) AS gross_predict, p.turnover_plan AS turnover_plan, p.gross_plan AS gross_plan FROM sales_with_groups AS s FULL OUTER JOIN predictions AS p ON (p.dt = s.dt) AND (p.kontragent = s.kontragent) AND (p.tm_group = s.tm_group) AND (lowerUTF8(p.mp) = lowerUTF8(s.mp)) AND (p.gender = s.gender) AND (p.type_group = s.type_group) AND (s.org = 'Мюнц Групп ООО')) SELECT dt, kontragent, mp, org, type_group, tm_group, gender, sales_qty, sales_qty_predict, turnover, turnover_plan, turnover_predict, cost_val, gross, gross_plan, gross_predict FROM fact_prediction_plan SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`TM_MP_sales_report_prediction_first_day_v` (`dt` Nullable(Date), `tm_group` Nullable(String), `mp` Nullable(String), `gender` Nullable(String), `type_group` Nullable(String), `sales_qty` Nullable(Decimal(38, 3)), `turnover` Nullable(Decimal(18, 3)), `turnover_plan` Nullable(Decimal(18, 3)), `gross` Nullable(Decimal(18, 3)), `gross_plan` Nullable(Decimal(18, 3))) AS WITH sales AS (SELECT toDate(s.`Период`) AS dt, s.`Контрагент` AS mp, s.`Организация` AS org, t.`КодДляОбмена` AS kdo, sum(s.`Количество`) AS qty, sum(s.`СтоимостьРегл`) AS turnover FROM `zendendb`.`ПродажиУПП` AS s ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`ТоварГуид` = s.`ТоварГуид` WHERE (s.`Контрагент` IN ('Вайлдберриз-Thomas Muenz', 'Вайлдберриз ООО', 'Интернет Решения ООО Thomas Munz (Озон)', 'Интернет Решения ООО', 'Купишуз ООО', 'МАРКЕТПЛЕЙС ООО', 'РВБ ООО', 'Яндекс Маркет ООО', 'Яндекс ООО')) AND (t.`ТипНоменклатуры` NOT IN ('Услуги', 'Услуги (оказанные)', 'Услуги (полученные)')) AND (s.`Организация` IN ('Мюнц Групп ООО')) AND (dt >= if(((today() - 1) - toStartOfMonth(today() - 1)) < 7, today() - 7, toStartOfMonth(today() - 1))) GROUP BY dt, org, mp, kdo), sales_with_groups AS (SELECT s.dt AS dt, tm.group_str AS tm_group, mp.group_str AS mp, multiIf((t.`СвойствоРод` IN ('муж', 'Муж', 'Муж.', 'муж.', 'мальч.')), 'Муж', (t.`СвойствоРод` IN ('жен', 'Жен', 'Жен.', 'жен.', 'девич.')), 'Жен', 'без разделения') AS gender, v.group_str AS type_group, sum(s.qty) AS sales_qty, sum(s.turnover) AS turnover, sum(s.turnover - (c.value_rub * s.qty)) AS gross FROM sales AS s LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS c ON (c.half = if(toMonth(s.dt) <= 6, toStartOfYear(s.dt), toStartOfYear(s.dt) + toIntervalMonth(6))) AND (c.kdo = s.kdo) AND (c.price_type = 'Себестоимость') LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS c2 ON (c2.half = if(toMonth(s.dt) <= 6, toStartOfYear(s.dt), toStartOfYear(s.dt) + toIntervalMonth(6))) AND (c2.kdo = s.kdo) AND (c2.price_type = 'Плановая себестоимость') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = s.kdo LEFT JOIN `zendendb`.TM_MP_mapping AS tm ON (tm.value_str = t.`СвойствоТорговаяМарка`) AND (tm.mapping_type = 'ТМ') LEFT JOIN `zendendb`.TM_MP_mapping AS v ON (v.value_str = t.`ТипНоменклатуры`) AND (v.mapping_type = 'ВидНоменклатуры') LEFT JOIN `zendendb`.TM_MP_mapping AS mp ON (mp.value_str = s.mp) AND (mp.mapping_type = 'Контрагент') GROUP BY dt, tm_group, mp, gender, type_group), plan_fact AS (SELECT ifNull(s.dt, p.`Дата`) AS dt, ifNull(s.tm_group, p.`Проект`) AS tm_group, if(ifNull(s.mp, p.`Маркетплейс`) = 'ОЗОН', 'Озон', ifNull(s.mp, p.`Маркетплейс`)) AS mp, ifNull(s.gender, p.gender_fix) AS gender, ifNull(s.type_group, p.`Продуктовая группа`) AS type_group, if((s.turnover IS NULL) AND (ifNull(s.dt, p.`Дата`) < (SELECT max(dt) + 1 FROM sales_with_groups)), 0, s.turnover) AS turnover, if((p.`Выручка` IS NULL) AND (ifNull(s.dt, p.`Дата`) < (SELECT max(dt) + 1 FROM sales_with_groups)), 0, p.`Выручка`) AS turnover_plan, if((s.gross IS NULL) AND (ifNull(s.dt, p.`Дата`) < (SELECT max(dt) + 1 FROM sales_with_groups)), 0, s.gross) AS gross, if((p.`Вал` IS NULL) AND (ifNull(s.dt, p.`Дата`) < (SELECT max(dt) + 1 FROM sales_with_groups)), 0, p.`Вал`) AS gross_plan, if((s.sales_qty IS NULL) AND (ifNull(s.dt, p.`Дата`) < (SELECT max(dt) + 1 FROM sales_with_groups)), 0, s.sales_qty) AS sales_qty FROM sales_with_groups AS s FULL OUTER JOIN (SELECT *, multiIf((`Пол` IN ('муж', 'Муж', 'Муж.', 'муж.', 'мальч.')), 'Муж', (`Пол` IN ('жен', 'Жен', 'Жен.', 'жен.', 'девич.')), 'Жен', 'без разделения') AS gender_fix FROM `zendendb`.`ПланПродаж_TM_MP` WHERE `Дата` >= if(((today() - 1) - toStartOfMonth(today() - 1)) < 7, today() - 7, toStartOfMonth(today() - 1))) AS p ON (p.`Дата` = s.dt) AND (p.`Проект` = s.tm_group) AND (lowerUTF8(p.`Маркетплейс`) = lowerUTF8(s.mp)) AND (p.gender_fix = s.gender) AND (p.`Продуктовая группа` = s.type_group)), plan_fact_for_prediction AS (SELECT dt, tm_group, mp, gender, type_group, turnover, turnover_plan, gross, gross_plan, sales_qty, sum(turnover) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS turnover_7, sum(turnover_plan) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS turnover_plan_7, sum(gross) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS gross_7, sum(gross_plan) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS gross_plan_7 FROM plan_fact), predictions AS (SELECT dt, tm_group, mp, gender, type_group, sales_qty, ifNull(toDecimal64(p.turnover, 3), toDecimal64(multiIf((toDecimal64(turnover_plan_7, 2) IS NULL) OR (turnover_plan_7 = 0), 0, divideDecimal(toDecimal64(turnover_7, 2), toDecimal64(turnover_plan_7, 2), 3)) * p.turnover_plan, 3)) AS turnover, turnover_plan, ifNull(toDecimal64(p.gross, 3), toDecimal64(multiIf((toDecimal64(gross_plan_7, 2) IS NULL) OR (gross_plan_7 = 0), 0, divideDecimal(toDecimal64(gross_7, 2), toDecimal64(gross_plan_7, 2), 3)) * p.gross_plan, 3)) AS gross, gross_plan, sum(turnover) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING) AS pred_turnover, sum(sales_qty) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING) AS pred_sales_qty FROM plan_fact_for_prediction AS p WHERE dt <= (SELECT max(dt) + 1 FROM sales_with_groups)) SELECT dt, tm_group, mp, gender, type_group, round(ifNull(toDecimal64(sales_qty, 3), pred_sales_qty + toDecimal64(multiIf((pred_turnover IS NULL) OR (pred_turnover = 0), 0, divideDecimal(toDecimal64(turnover - pred_turnover, 3), toDecimal64(pred_turnover, 3))) * pred_sales_qty, 3))) AS sales_qty, turnover, turnover_plan, gross, gross_plan FROM predictions SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`TM_MP_sales_report_prediction_v` (`dt` Nullable(Date), `tm_group` Nullable(String), `mp` Nullable(String), `gender` Nullable(String), `type_group` Nullable(String), `sales_qty` Nullable(Decimal(38, 3)), `turnover` Nullable(Decimal(18, 3)), `turnover_plan` Nullable(Decimal(18, 3)), `gross` Nullable(Decimal(18, 3)), `gross_plan` Nullable(Decimal(18, 3))) AS WITH sales_with_groups AS (SELECT * FROM `zendendb`.TM_MP_sales_report_prediction), plan_fact AS (SELECT ifNull(s.dt, p.`Дата`) AS dt, ifNull(s.tm_group, p.`Проект`) AS tm_group, if(ifNull(s.mp, p.`Маркетплейс`) = 'ОЗОН', 'Озон', ifNull(s.mp, p.`Маркетплейс`)) AS mp, ifNull(s.gender, p.gender_fix) AS gender, ifNull(s.type_group, p.`Продуктовая группа`) AS type_group, if((s.turnover IS NULL) AND (ifNull(s.dt, p.`Дата`) < (SELECT max(dt) + 1 FROM sales_with_groups)), 0, s.turnover) AS turnover, if((p.`Выручка` IS NULL) AND (ifNull(s.dt, p.`Дата`) < (SELECT max(dt) + 1 FROM sales_with_groups)), 0, p.`Выручка`) AS turnover_plan, if((s.gross IS NULL) AND (ifNull(s.dt, p.`Дата`) < (SELECT max(dt) + 1 FROM sales_with_groups)), 0, s.gross) AS gross, if((p.`Вал` IS NULL) AND (ifNull(s.dt, p.`Дата`) < (SELECT max(dt) + 1 FROM sales_with_groups)), 0, p.`Вал`) AS gross_plan, if((s.sales_qty IS NULL) AND (ifNull(s.dt, p.`Дата`) < (SELECT max(dt) + 1 FROM sales_with_groups)), 0, s.sales_qty) AS sales_qty FROM sales_with_groups AS s FULL OUTER JOIN (SELECT *, multiIf((`Пол` IN ('муж', 'Муж', 'Муж.', 'муж.', 'мальч.')), 'Муж', (`Пол` IN ('жен', 'Жен', 'Жен.', 'жен.', 'девич.')), 'Жен', 'без разделения') AS gender_fix FROM `zendendb`.`ПланПродаж_TM_MP` WHERE `Дата` >= if(((today() - 1) - toStartOfMonth(today() - 1)) < 7, today() - 7, toStartOfMonth(today() - 1))) AS p ON (p.`Дата` = s.dt) AND (p.`Проект` = s.tm_group) AND (lowerUTF8(p.`Маркетплейс`) = lowerUTF8(s.mp)) AND (p.gender_fix = s.gender) AND (p.`Продуктовая группа` = s.type_group)), plan_fact_for_prediction AS (SELECT dt, tm_group, mp, gender, type_group, turnover, turnover_plan, gross, gross_plan, sales_qty, sum(turnover) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS turnover_7, sum(turnover_plan) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS turnover_plan_7, sum(gross) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS gross_7, sum(gross_plan) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS gross_plan_7 FROM plan_fact), predictions AS (SELECT dt, tm_group, mp, gender, type_group, sales_qty, ifNull(toDecimal64(p.turnover, 3), toDecimal64(multiIf((toDecimal64(turnover_plan_7, 2) IS NULL) OR (turnover_plan_7 = 0), 0, divideDecimal(toDecimal64(turnover_7, 2), toDecimal64(turnover_plan_7, 2), 3)) * p.turnover_plan, 3)) AS turnover, turnover_plan, ifNull(toDecimal64(p.gross, 3), toDecimal64(multiIf((toDecimal64(gross_plan_7, 2) IS NULL) OR (gross_plan_7 = 0), 0, divideDecimal(toDecimal64(gross_7, 2), toDecimal64(gross_plan_7, 2), 3)) * p.gross_plan, 3)) AS gross, gross_plan, sum(turnover) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING) AS pred_turnover, sum(sales_qty) OVER (PARTITION BY tm_group, mp, gender, type_group ORDER BY dt ASC ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING) AS pred_sales_qty FROM plan_fact_for_prediction AS p WHERE dt <= (SELECT max(dt) + 1 FROM sales_with_groups)) SELECT dt, tm_group, mp, gender, type_group, round(ifNull(toDecimal64(sales_qty, 3), pred_sales_qty + toDecimal64(multiIf((pred_turnover IS NULL) OR (pred_turnover = 0), 0, divideDecimal(toDecimal64(turnover - pred_turnover, 3), toDecimal64(pred_turnover, 3))) * pred_sales_qty, 3))) AS sales_qty, turnover, turnover_plan, gross, gross_plan FROM predictions WHERE dt = (SELECT max(dt) + 1 FROM sales_with_groups) SETTINGS final = 1, join_use_nulls = 1;

