CREATE VIEW `zendendb`.`TM_MP_zeros_in_kdo_v` (`mp` String, `supplierArticle` Nullable(String)) AS SELECT 'WB' AS mp, o.supplierArticle FROM `zendendb`.WB_FBO_Orders_TM AS o LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON m.art_mp = toString(o.supplierArticle) WHERE (toDate(o.date) > (today() - toIntervalMonth(6))) AND ((m.kdo IS NULL) OR (m.kdo = 0)) UNION ALL SELECT 'OZ', o.`Артикул` FROM `zendendb`.OZON_Orders_TM AS o LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON m.art_mp = toString(o.`Артикул`) WHERE (toDate(o.`Принят в обработку`) > (today() - toIntervalMonth(6))) AND ((m.kdo IS NULL) OR (m.kdo = 0)) UNION ALL SELECT 'LM', o.sku FROM `zendendb`.LAMODA_Sales_TM AS o LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON m.art_mp = toString(o.sku) WHERE (toDate(o.createdAt) > (today() - toIntervalMonth(6))) AND ((m.kdo IS NULL) OR (m.kdo = 0)) UNION ALL SELECT 'YA', o.SHOP_SKU FROM `zendendb`.YANDEX_Orders_TM AS o LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON m.art_mp = toString(o.SHOP_SKU) WHERE (toDate(o.CREATION_DATE) > (today() - toIntervalMonth(6))) AND ((m.kdo IS NULL) OR (m.kdo = 0));

