 `Себестоимость входящих`, ifNull(countDistinct(z.ID), 0) AS `Кол-во входящих`, ifNull(sum(zt.QUANTITY), 0) AS `Товары во входящих` FROM `zendendb`.`ЗаказКлиента` AS z FINAL LEFT JOIN (SELECT * FROM `zendendb`.`ЗаказКлиента.Товары` AS zt FINAL) AS zt ON zt.ORDER_ID = z.ID ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS sb ON (sb.half = if(toMonth(z.DATE_STATUS) <= 6, toStartOfYear(z.DATE_STATUS), toStartOfYear(z.DATE_STATUS) + toIntervalMonth(6))) AND (sb.kdo = toUInt64OrZero(splitByChar('#', assumeNotNull(PRODUCT_XML_ID))[1])) WHERE COMPANY_CODE IN ('THOMAS', 'SALAMANDER') GROUP BY `Дата`, z.SHOP_NAME, `Компания`, `Доставка`, `Тип оплаты`, `КДО`), sales AS (SELECT toDate(z.DATE_STATUS) AS `Дата`, if((z.SHOP_NAME IN ('thomas-muenz.ru', 'thomas-muenz.ru - самовывоз', 'thomas-muenz.ru - ПВЗ', 'salamander.ru', 'salamander.ru - самовывоз', 'rieker-online.ru')), 'Сайт', 'APP') AS `Тип источника`, multiIf(z.SHOP_NAME = 'salamander.ru - Приложение продавца', 'salamander.ru - APP', z.SHOP_NAME = 'thomas-muenz.ru - Приложение продавца', 'thomas-muenz.ru - APP', (z.SHOP_NAME IN ('Ozon (Thomas-munz)', 'Wildberries (Thomas-munz)', 'rieker-online.ru')) OR (z.SHOP_NAME IS NULL), 'Другое', z.SHOP_NAME) AS `Источник`, z.COMPANY_CODE AS `Компания`, z.DELIVERY_NAME AS `Доставка`, z.PAY_SYSTEM_NAME AS `Тип оплаты`, toInt64OrZero(splitByChar('#', assumeNotNull(zt.PRODUCT_XML_ID))[1]) AS `КДО`, ifNull(countIfDistinct(z.ID, (NOT zt.`Не выкуплен`) AND (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат'))), 0) AS `Кол-во выполненных`, ifNull(sumIf(zt.QUANTITY, (NOT zt.`Не выкуплен`) AND (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат'))), 0) AS `Товары в выполненных`, ifNull(countIfDistinct(z.ID, (NOT zt.`Не выкуплен`) AND (STATUS IN ('Выполнен', 'Частично выполнен', 'Частичный возврат')) AND (z.DELIVERY_NAME = 'Самовывоз из салона')), 0) AS `Самовывоз кол-во выполненных`, ifNull(sumIf(zt.QUANTITY, (NOT zt.`Не выкуплен`) AND (STATUS IN ('Выполнен', 'Ч