точника` = s.`Тип источника`) AND (o.`Источник` = s.`Источник`) AND (o.`Компания` = s.`Компания`) AND (o.`Доставка` = s.`Доставка`) AND (o.`Тип оплаты` = s.`Тип оплаты`) AND (o.`Склад` = s.`Склад`) WHERE `Дата` < today()), orders_sales_for_plan AS (SELECT * FROM orders_sales UNION ALL SELECT DISTINCT `Дата`, 'План' AS `Тип источника`, 'План' AS `Источник`, `Компания`, 'План' AS `Доставка`, 'План' AS `Тип оплаты`, 'План' AS `Склад`, NULL AS `Входящие руб.`, NULL AS `Кол-во входящих`, NULL AS `Товары во входящих`, NULL AS `Кол-во выполненных`, NULL AS `Товары в выполненных`, NULL AS `Самовывоз кол-во выполненных`, NULL AS `Самовывоз товары в выполненных`, NULL AS `Выручка`, NULL AS `Себестоимость`, NULL AS `Выручка с возвратами`, NULL AS `Себестоимость с возвратами`, NULL AS price1C FROM orders_sales UNION ALL SELECT DISTINCT `Дата`, 'Трафик' AS `Тип источника`, 'Трафик' AS `Источник`, `Компания`, 'Трафик' AS `Доставка`, 'Трафик' AS `Тип оплаты`, 'Трафик' AS `Склад`, NULL AS `Входящие руб.`, NULL AS `Кол-во входящих`, NULL AS `Товары во входящих`, NULL AS `Кол-во выполненных`, NULL AS `Товары в выполненных`, NULL AS `Самовывоз кол-во выполненных`, NULL AS `Самовывоз товары в выполненных`, NULL AS `Выручка`, NULL AS `Себестоимость`, NULL AS `Выручка с возвратами`, NULL AS `Себестоимость с возвратами`, NULL AS price1C FROM orders_sales) SELECT ifNull(os.`Дата`, pl.`Дата`) AS `Дата`, ifNull(os.`Тип источника`, pl.`Тип источника`) AS `Тип источника`, ifNull(os.`Источник`, pl.`Источник`) AS `Источник`, ifNull(os.`Компания`, pl.`Компания`) AS `Компания`, ifNull(os.`Доставка`, pl.`Доставка`) AS `Доставка`, ifNull(os.`Тип оплаты`, pl.`Тип оплаты`) AS `Тип оплаты`, ifNull(os.`Склад`, pl.`Склад`) AS `Склад`, tr.visits AS `Трафик`, os.`Входящие руб.` AS `Входящие руб.`, os.`Кол-во входящих` AS `Кол-во входящих`, os.`Товары во входящих` AS `Товары во входящих`, os.`Кол-во выполненных` AS `Кол-во выполненных`, os.`Товары в выполненных` AS `Товары в выполненных`, os.`Самовывоз кол-во выполненных` AS `Самовывоз кол-во выполненных`, os.`Самовывоз товары в выполненных` AS `Самовывоз товары в выполненных`, os.`Выручка` AS `Выручка`, os.`Себестоимость` AS `Себестоимость`, os.`Выручка с возвратами` AS `Выручка с возвратами`, os.`Себестоимость с возвратами` AS `Себестоимость с возвратами`, os.price1C AS price1C, pl.`Трафик` AS `План Трафик`, pl.`Входящие Заказы` AS `План Входящие`, pl.`Входящие Заказы руб` AS `План Входящие руб.`, pl.`Выручка` AS `План Выручка`, pl.`Вал` AS `План Вал`, pl.`Ср. цена` AS `План Ср. цена`, pl.`Ср. себестоимость` AS `План Ср. Себестоимость`, pl.`Входящие UPT` AS `План Входящие UPT`, pl.`Вес` AS `План Вес дня`, pl.`Трафик_прогноз` AS `Трафик_прогноз`, pl.`Входящие_руб_прогноз` AS `Входящие_руб_прогноз`, pl.`Выручка_прогноз` AS `Выручка_прогноз`, pl.`Вал_прогноз` AS `Вал_прогноз`, pl.`Выручка_с_возвратами_прогноз` AS `Выручка_с_возвратами_прогноз`, pl.`Вал_с_возвратами_прогноз` AS `Вал_с_возвратами_прогноз` FROM orders_sales_for_plan AS os FULL OUTER JOIN plan AS pl ON (os.`Дата` = pl.`Дата`) AND (os.`Тип источника` = pl.`Тип источника`) AND (os.`Источник` = pl.`Источник`) AND (os.`Компания` = pl.`Компания`) AND (os.`Доставка` = pl.`Доставка`) AND (os.`Тип оплаты` = pl.`Тип оплаты`) AND (os.`Склад` = pl.`Склад`) LEFT JOIN trafic AS tr ON (os.`Дата` = tr.date) AND (os.`Тип источника` = tr.`Тип источника`) AND (os.`Источник` = tr.`Источник`) AND (os.`Компания` = tr.`Компания`) AND (os.`Доставка` = tr.`Доставка`) AND (os.`Тип оплаты` = tr.`Тип оплаты`) AND (os.`Склад` = tr.`Склад`) SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`ThomasMunzEcom_stock_by_day_insert_v` AS WITH werehouse AS (SELECT w.productGuid AS `НоменклатураГуид`, sum(w.qty) AS `Количество` FROM `zendendb`.`ТоварыНаСкладах_TM` AS w WHERE (w.warehouse IN ('ИНТЕРНЕТ-магазин Thomas Munz')) AND (w.dt = {start_date:date}) GROUP BY w.productGuid), stock_on_date AS (SELECT {start_date:date} AS `Дата`, w.`НоменклатураГуид` AS `НоменклатураГуид`, w.`Количество` AS `Количество`, t.`КодДляОбмена` AS `КодДляОбмена`, t.`Артикул` AS `Артикул`, t.`Товар` AS `Товар`, t.`СвойствоСезон`, t.`СвойствоРод`, t.`СвойствоТорговаяМарка`, toInt8OrZero(splitByChar('%', ifNull(tupp.`СтавкаНДС`, '0%'))[1]) AS `СтавкаНДС`, t.`ТипНоменклатуры`, tupp.OrderTM FROM werehouse AS w ANY LEFT JOIN `zendendb`.`Товары` AS t ON t.`ТоварГуид` = w.`НоменклатураГуид` ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS tupp ON tupp.`КодДляОбмена` = t.`КодДляОбмена` WHERE `Количество` > 0), price_on_date AS (SELECT {start_date:date} AS `Дата`, toInt32OrZero(splitByChar('#', XML_ID)[1]) AS `КодДляОбмена`, argMax(pr.PRICE, pr.TIMESTAMP_X) AS PRICE, max(pr.TIMESTAMP_X) AS TIMESTAMP_X FROM `zendendb`.`ЦеныНоменклатурыOMS` AS pr FINAL WHERE pr.TIMESTAMP_X < {start_date:date} GROUP BY `КодДляОбмена`), price_on_date_from_sales AS (SELECT {start_date:date} AS `Дата`, toInt32OrZero(splitByChar('#', PRODUCT_XML_ID)[1]) AS `КодДляОбмена`, argMax(PRICE, DATE_INSERT) AS PRICE FROM `zendendb`.`ЗаказКлиента.Товары` AS t FINAL WHERE DATE_INSERT < {start_date:date} GROUP BY `КодДляОбмена`), cost_price AS (SELECT * FROM `zendendb`.`Себестоимость_по_полугодиям` AS c FINAL WHERE (half = if(toMonth({start_date:date}) <= 6, toStartOfYear({start_date:date}), toStartOfYear({start_date:date}) + toIntervalMonth(6))) AND (price_type = 'Себестоимость')) SELECT s.*, ifNull(pr.PRICE, pr2.PRICE) AS PRICE, c.value_rub FROM stock_on_date AS s LEFT JOIN price_on_date AS pr ON pr.`КодДляОбмена` = s.`КодДляОбмена` LEFT JOIN price_on_date_from_sales AS pr2 ON pr2.`КодДляОбмена` = s.`КодДляОбмена` LEFT JOIN cost_price AS c ON c.kdo = s.`КодДляОбмена` SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`ThomasMunzEcom_stock_by_day_v` (`Дата` Date, `НоменклатураГуид` String, `Количество` UInt32, `КодДляОбмена` UInt32, `Артикул` Nullable(String), `Товар` Nullable(String), `СвойствоСезон` Nullable(String), `СвойствоРод` Nullable(String), `СвойствоТорговаяМарка` Nullable(String), `СтавкаНДС` Nullable(UInt8), `ТипНоменклатуры` Nullable(String), `OrderTM` Nullable(String), `Цена` Nullable(Decimal(10, 3)), `Себестоимость` Nullable(Decimal(10, 3))) AS SELECT * FROM `zendendb`.ThomasMunzEcom_stock_by_day FINAL WHERE `КодДляОбмена` != 0;

