а`, `Родитель1`, `Родитель2`, `Родитель3`, `Родитель4`, `Родитель5`), `ВентраПоМагазину` AS (SELECT `Реестр`, sum(`Часов день`) AS `Сумма по полю Часов день`, sum(`Всего без НДС`) AS `Сумма по полю Всего без НДС` FROM `zendendb`.`Вентра` WHERE toStartOfMonth(`Дата начала работы`) = {month:date} GROUP BY `Реестр`), `ПродажиПоМагазину` AS (SELECT m.`КодМагазина` AS `КодМагазина`, s.`МагазинГуид`, sum(s.`КоличествоОборот`) AS `Количество`, sum(s.`СтоимостьОборот`) AS `ТО`, sum(s.`Вал`) AS `Вал`, sum(s.`Трафик`) AS `Трафик`, sumIf(s.`КоличествоОборот`, s.`ТипНоменклатуры` = 'Обувь') AS `Пары`, countIfDistinct(s.`ЧекГуид`, NOT s.`Возврат`) AS `Чеки покупок`, countIfDistinct(s.`ЧекГуид`, s.`Возврат`) AS `Чеки возвратов`, sum(s.`План Оборот`) AS `План Оборот`, sum(s.`План Трафик`) AS `План Трафик`, sum(s.`План Вал`) AS `План Вал`, sum(s.`План Чеки`) AS `План Чеки`, sum(s.`План Пары`) AS `План Пары` FROM `zendendb`.sales_report_MAIN_all AS s LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = s.`МагазинГуид` WHERE toStartOfMonth(`Период`) = {month:date} GROUP BY m.`КодМагазина`, s.`МагазинГуид`), `УкомплектованностьПоДатеПоМагазину` AS (SELECT `Дата`, `КодМагазина`, `Подразделение`, sum(`Факт`) AS `Факт`, sum(`План`) AS `План` FROM `zendendb`.`Укомплектованность` AS t WHERE (toStartOfMonth(`Дата`) = {month:date}) AND (t.`План` != 0) GROUP BY `Дата`, `КодМагазина`, `Подразделение`), `УкомплектованностьПоМагазину` AS (SELECT `КодМагазина`, `Подразделение`, argMax(t.`Факт`, t.`Дата`) AS `Факт`, argMax(t.`План`, t.`Дата`) AS `План`, argMax(t.`Факт`, t.`Дата`) / argMax(t.`План`, t.`Дата`) AS `Укомплектованность` FROM `УкомплектованностьПоДатеПоМагазину` AS t GROUP BY `КодМагазина`, `Подразделение`), `ЗатратыПоСотрудникуДляСоединения` AS (SELECT * FROM `ЗатратыПоСотрудникуВидуНачисления` UNION ALL SELECT DISTINCT `Месяц`, '---Подразделение---' AS `СотрудникГуид`, '---Подразделение---' AS `Сотрудник`, '---Подразделение---' AS `Должность`, '---Подразделение---' AS `ДолжностьУправленческая`, `Организация`, `СтатьяФинансирования`, `Подразделение`, `ПодразделениеУправленческое`, `КодМагазина`, `Родитель1`, `Родитель2`, `Родитель3`, `Родитель4`, `Родитель5`, 0 AS `ОтработаноДней`, 0 AS `ОтработаноЧасов`, 0 AS `ПФР по суммарному тарифу`, 0 AS `ФСС НС`, 0 AS `НДФЛ`, 0 AS `Районный коэффициент`, 0 AS `Праздничные и вых. дни`, 0 AS `Оклад`, 0 AS `Премия`, 0 AS `Отпуск`, 0 AS `Командировка`, 0 AS `Больничный`, 0 AS `Комп отпуска при увольнении`, 0 AS `Северная надбавка`, 0 AS `Удержание по исполнительному документу`, 0 AS `Мат помощь`, 0 AS `Компенсация по соглашению сторон` FROM `ЗатратыПоСотрудникуВидуНачисления`), `Итоги` AS (SELECT z.`Месяц` AS `Месяц`, z.`СотрудникГуид` AS `СотрудникГуид`, z.`Сотрудник` AS `Сотрудник`, z.`Должность` AS `Должность`, z.`ДолжностьУправленческая` AS `ДолжностьУправленческая`, z.`Организация` AS `Организация`, z.`СтатьяФинансирования` AS `СтатьяФинансирования`, z.`Подразделение` AS `Подразделение`, z.`ПодразделениеУправленческое` AS `ПодразделениеУправленческое`, z.`КодМагазина` AS `КодМагазина`, z.`Родитель1` AS `ТМ`, z.`Родитель2` AS `РМ`, m.`Магазин Родитель` AS `Магазин Родитель`, multiIf(((p.`Округ` = 'Московская область') AND (m.`Город` != 'Москва')) OR (m.`Город` = 'Москвовская область'), 'Московская область', m.`Город` = 'Ростов', 'Ростов-на-Дону', m.`Город`) AS `Город`, m.`Регион` AS `Регион`, z.`ОтработаноДней` AS `ОтработаноДней`, z.`ОтработаноЧасов` AS `ОтработаноЧасов`, z.`ПФР по суммарному тарифу` AS `ПФР по суммарному тарифу`, z.`ФСС НС` AS `ФСС НС`, z.`НДФЛ` AS `НДФЛ`, z.`Районный коэффициент` AS `Районный коэффициент`, z.`Праздничные и вых. дни` AS `Праздничные и вых. дни`, z.`Оклад` AS `Оклад`, z.`Премия` AS `Премия`, z.`Отпуск` AS `Отпуск`, z.`Командировка` AS `Командировка`, z.`Больничный` AS `Больничный`, z.`Комп отпуска при увольнении` AS `Комп отпуска при увольнении`, z.`Северная надбавка` AS `Северная надбавка`, z.`Удержание по исполнительному документу` AS `Удержание по исполнительному документу`, z.`Мат помощь` AS `Мат помощь`, z.`Компенсация по соглашению сторон` AS `Компенсация по соглашению сторон`, u.`Факт` AS `ШтатФакт`, u.`План` AS `ШтатПлан`, u.`Укомплектованность` AS `Укомплектованность`, s.`Количество` AS `Количество`, s.`ТО` AS `ТО`, s.`Вал` AS `Вал`, s.`Трафик` AS `Трафик`, s.`Пары` AS `Пары`, s.`Чеки покупок` AS `Чеки покупок`, s.`Чеки возвратов` AS `Чеки возвратов`, s.`План Оборот` AS `План Оборот`, s.`План Трафик` AS `План Трафик`, s.`План Вал` AS `План Вал`, s.`План Чеки` AS `План Чеки`, s.`План Пары` AS `План Пары`, v.`Сумма по полю Часов день` AS `Сумма по полю Часов день`, v.`Сумма по полю Всего без НДС` AS `Сумма по полю Всего без НДС` FROM `ЗатратыПоСотрудникуДляСоединения` AS z LEFT JOIN `УкомплектованностьПоМагазину` AS u ON (z.`КодМагазина` = u.`КодМагазина`) AND (z.`Сотрудник` = '---Подразделение---') LEFT JOIN `ПродажиПоМагазину` AS s ON (z.`КодМагазина` = s.`КодМагазина`) AND (z.`Сотрудник` = '---Подразделение---') LEFT JOIN `ВентраПоМагазину` AS v ON (z.`СтатьяФинансирования` = v.`Реестр`) AND (z.`Сотрудник` = '---Подразделение---') ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`КодМагазина` = z.`КодМагазина` ANY LEFT JOIN `zendendb`.`ЧасовыеПояса` AS p ON m.`Город` = p.`Город`) SELECT * FROM `Итоги` SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`WB_by_day_v` (`Дата` Date, `Магазин` String, `Заказы руб` Nullable(Decimal(10, 3)), `Заказы НДС` Nullable(Decimal(10, 3)), `Заказы шт` Nullable(Int64), `Продажи руб` Nullable(Decimal(10, 3)), `Продажи НДС` Nullable(Decimal(10, 3)), `Продажи шт` Nullable(Int64), `Возвраты руб` Nullable(Decimal(10, 3)), `Возвраты НДС` Nullable(Decimal(10, 3)), `Возвраты шт` Nullable(Int64), `Себестоимость руб` Nullable(Decimal(10, 3)), `Одежда Заказы руб` Nullable(Decimal(10, 3)), `Одежда Заказы НДС` Nullable(Decimal(10, 3)), `Одежда Заказы шт` Nullable(Int64), `Одежда Продажи руб` Nullable(Decimal(10, 3)), `Одежда Продажи НДС` Nullable(Decimal(10, 3)), `Одежда Продажи шт` Nullable(Int64), `Одежда Возвраты руб` Nullable(Decimal(10, 3)), `Одежда Возвраты НДС` Nullable(Decimal(10, 3)), `Одежда Возвраты шт` Nullable(Int64), `Одежда Себестоимость руб` Nullable(Decimal(10, 3)), `Товарный остаток шт` Nullable(Int64), `Одежда Товарный остаток шт` Nullable(Int64), `Поступления ДС руб` Nullable(Decimal(10, 3)), `Комиссия` Nullable(Decimal(10, 3)), `Хранение` Nullable(Decimal(10, 3)), `Логистика` Nullable(Decimal(10, 3)), `Складская логистика` Nullable(Decimal(10, 3)), `Эквайринг` Nullable(Decimal(10, 3)), `Компенсации` Nullable(Decimal(10, 3)), `Штрафы` Nullable(Decimal(10, 3)), `Услуги поверенного` Nullable(Decimal(10, 3)), `Обработка брака` Nullable(Decimal(10, 3)), `Размещение возврата FBS` Nullable(Decimal(10, 3)), `Обработка опознанных излишков` Nullable(Decimal(10, 3)), `Обработка товара на FBO` Nullable(Decimal(10, 3)), `Кроссдокинг` Nullable(Decimal(10, 3)), `Обработка ошибок продавца` Nullable(Decimal(10, 3)), `Бронирование места` Nullable(Decimal(10, 3)), `Утилизация остатков` Nullable(Decimal(10, 3)), `Восстановление товара` Nullable(Decimal(10, 3)), `Приемка на складе` Nullable(Decimal(10, 3)), `Отказ возврат товара` Nullable(Decimal(10, 3)), `НДС Казахстан` Nullable(Decimal(10, 3)), `Переупаковка товара` Nullable(Decimal(10, 3)), `Подготовка товара к возврату` Nullable(Decimal(10, 3)), `Прочие удержания` Nullable(Decimal(10, 3)), `Товарная реклама` Nullable(Int64), `Баннерная реклама` Nullable(Decimal(10, 3)), `Внешняя реклама` Nullable(Decimal(10, 3)), `Прочие услуги маркетинга` Nullable(Decimal(10, 3)), `Маркетинговое агентство` Nullable(Decimal(10, 3))) AS WITH income AS (SELECT toDate(pp.`Дата`) AS `Дата`, sum(`СуммаДокумента`) AS `Поступления ДС руб` FROM `zendendb`.`ПлатежноеПоручениеВходящее` AS pp WHERE (`Подразделение` IN ('Отдел по работе с Market Places Zenden')) AND (`Контрагент` IN ('РВБ ООО', 'Вайлдберриз ООО')) GROUP BY `Дата`), arts AS (SELECT DISTINCT supplierArticle AS art FROM `zendendb`.WB_FBO_Orders FINAL WHERE art != ''), art_dict AS (SELECT DISTINCT art, t.`КодДляОбмена` AS kdo, t.`ТипНоменклатуры` IN ('Изделия бельевые', 'Изделия верхние', 'Одежда') AS `Одежда`, round(toInt32OrZero(splitByChar('%', assumeNotNull(t.`СтавкаНДС`))[1]) / (100 + toInt32OrZero(splitByChar('%', assumeNotNull(t.`СтавкаНДС`))[1])), 4) AS nds FROM arts AS a ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`Артикул` = a.art), orders AS (SELECT toDate(wfo.date) AS date, count(*) AS `Заказы шт`, sum(priceWithDisc) AS `Заказы руб`, sum(priceWithDisc * a.nds) AS `Заказы НДС`, countIf(nmId, a.`Одежда`) AS `Одежда Заказы шт`, sumIf(priceWithDisc, a.`Одежда`) AS `Одежда Заказы руб`, sumIf(priceWithDisc * a.nds, a.`Одежда`) AS `Одежда Заказы НДС` FROM `zendendb`.WB_FBO_Orders AS wfo FINAL LEFT JOIN art_dict AS a ON lower(a.art) = lower(wfo.supplierArticle) WHERE orderType = 'Клиентский' GROUP BY date), sales AS (SELECT toDate(ws.sale_dt) AS sale_dt, sumIf(quantity, supplier_oper_name = 'Продажа') AS `Продажи шт`, sumIf(retail_price_withdisc_rub, supplier_oper_name = 'Продажа') AS `Продажи руб`, sumIf(retail_price_withdisc_rub * a.nds, supplier_oper_name = 'Продажа') AS `Продажи НДС`, sumIf(quantity, supplier_oper_name = 'Возврат') AS `Возвраты шт`, sumIf(retail_price_withdisc_rub, supplier_oper_name = 'Возврат') AS `Возвраты руб`, sumIf(retail_price_withdisc_rub * a.nds, supplier_oper_name = 'Возврат') AS `Возвраты НДС`, sumIf(sb.value_rub, supplier_oper_name = 'Продажа') AS `Себестоимость руб`, sumIf(quantity, (supplier_oper_name = 'Продажа') AND a.`Одежда`) AS `Одежда Продажи шт`, sumIf(retail_price_withdisc_rub, (supplier_oper_name = 'Продажа') AND a.`Одежда`) AS `Одежда Продажи руб`, sumIf(retail_price_withdisc_rub * a.nds, (supplier_oper_name = 'Продажа') AND a.`Одежда`) AS `Одежда Продажи НДС`, sumIf(quantity, (supplier_oper_name = 'Возврат') AND a.`Одежда`) AS `Одежда Возвраты шт`, sumIf(retail_price_withdisc_rub, (supplier_oper_name = 'Возврат') AND a.`Одежда`) AS `Одежда Возвраты руб`, sumIf(retail_price_withdisc_rub * a.nds, (supplier_oper_name = 'Возврат') AND a.`Одежда`) AS `Одежда Возвраты НДС`, sumIf(sb.value_rub, (supplier_oper_name = 'Продажа') AND a.`Одежда`) AS `Одежда Себестоимость руб`, sumIf(retail_price_withdisc_rub * if(commission_percent > 1, commission_percent / 100, commission_percent), supplier_oper_name = 'Продажа') - sumIf(retail_price_withdisc_rub * if(commission_percent > 1, commission_percent / 100, commission_percent), supplier_oper_name = 'Возврат') AS `Комиссия` FROM `zendendb`.WB_Sales_DetailByPeriod AS ws FINAL LEFT JOIN art_dict AS a ON lower(a.art) = lower(ws.sa_name) ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS sb ON (sb.half = if(toMonth(ws.sale_dt) <= 6, toStartOfYear(ws.sale_dt), toStartOfYear(ws.sale_dt) + toIntervalMonth(6))) AND (sb.price_type = 'Себестоимость') AND (sb.kdo = a.kdo) GROUP BY sale_dt), sales_temp AS (SELECT toDate(ws.date) AS sale_dt, toInt64(countIf(nmId, saleID LIKE 'S%')) AS `Продажи шт`, sumIf(priceWithDisc, saleID LIKE 'S%') AS `Продажи руб`, sumIf(priceWithDisc * a.nds, saleID LIKE 'S%') AS `Продажи НДС`, toInt64(countIf(nmId, saleID LIKE 'R%')) AS `Возвраты шт`, abs(sumIf(priceWithDisc, saleID LIKE 'R%')) AS `Возвраты руб`, abs(sumIf(priceWithDisc * a.nds, saleID LIKE 'R%')) AS `Возвраты НДС`, sumIf(sb.value_rub, saleID LIKE 'S%') AS `Себестоимость руб`, toInt64(countIf(nmId, (saleID LIKE 'S%') AND a.`Одежда`)) AS `Одежда Продажи шт`, sumIf(priceWithDisc, (saleID LIKE 'S%') AND a.`Одежда`) AS `Одежда Продажи руб`, sumIf(priceWithDisc * a.nds, (saleID LIKE 'S%') AND a.`Одежда`) AS `Одежда Продажи НДС`, toInt64(countIf(nmId, (saleID LIKE 'S%') AND a.`Одежда`)) AS `Одежда Возвраты шт`, sumIf(priceWithDisc, (saleID LIKE 'R%') AND a.`Одежда`) AS `Одежда Возвраты руб`, sumIf(priceWithDisc * a.nds, (saleID LIKE 'R%') AND a.`Одежда`) AS `Одежда Возвраты НДС`, sumIf(sb.value_rub, (saleID LIKE 'S%') AND a.`Одежда`) AS `Одежда Себестоимость руб`, 0 AS `Комиссия` FROM `zendendb`.WB_Sales AS ws LEFT JOIN art_dict AS a ON lower(a.art) = lower(ws.supplierArticle) ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS sb ON (sb.half = if(toMonth(ws.date) <= 6, toStartOfYear(ws.date), toStartOfYear(ws.date) + toIntervalMonth(6))) AND (sb.kdo = a.kdo) AND (sb.price_type = 'Себестоимость') WHERE (toDate(ws.date) > (SELECT max(date_to) FROM `zendendb`.WB_Sales_DetailByPeriod)) AND (toDate(ws.date) < today()) GROUP BY sale_dt), all_sales AS (SELECT * FROM sales UNION ALL SELECT * FROM sales_temp), spends AS (SELECT toDate(ws.rr_dt) AS sale_dt, sum(storage_fee) AS `Хранение`, sum(delivery_rub) + sum(ppvz_reward) AS `Логистика`, sum(rebill_logistic_cost) AS `Складская логистика`, sum(acquiring_fee) AS `Эквайринг`, sum(penalty) AS `Штрафы`, sum(acceptance) AS `Приемка на складе`, sum(deduction) AS `Прочие удержания` FROM `zendendb`.WB_Sales_DetailByPeriod AS ws FINAL GROUP BY rr_dt), marketing AS (SELECT toDate(updTime) AS sale_dt, sum(updSum) AS `Товарная реклама` FROM `zendendb`.WB_Advert GROUP BY sale_dt), banner AS (SELECT `Дата списания` AS sale_dt, sum(`Сумма`) AS `Баннерная реклама` FROM `zendendb`.WB_Media_spends AS wms GROUP BY sale_dt), warehouse AS (SELECT Date, sum(quantity) AS `Товарный остаток шт`, sumIf(quantity, a.`Одежда`) AS `Одежда Товарный остаток шт` FROM `zendendb`.WB_Warehouse AS wbw LEFT JOIN art_dict AS a ON lower(replaceAll(a.art, ' ', '')) = lower(replaceAll(wbw.vendorCode, ' ', '')) WHERE warehouseName = 'Всего находится на складах' GROUP BY Date) SELECT o.date AS `Дата`, '1.Wildberries' AS `Магазин`, o.`Заказы руб` AS `Заказы руб`, o.`Заказы НДС` AS `Заказы НДС`, o.`Заказы шт` AS `Заказы шт`, sl.`Продажи руб` AS `Продажи руб`, sl.`Продажи НДС` AS `Продажи НДС`, sl.`Продажи шт` AS `Продажи шт`, sl.`Возвраты руб` AS `Возвраты руб`, sl.`Возвраты НДС` AS `Возвраты НДС`, sl.`Возвраты шт` AS `Возвраты шт`, sl.`Себестоимость руб` AS `Себестоимость руб`, o.`Одежда Заказы руб` AS `Одежда Заказы руб`, o.`Одежда Заказы НДС` AS `Одежда Заказы НДС`, o.`Одежда Заказы шт` AS `Одежда Заказы шт`, sl.`Одежда Продажи руб` AS `Одежда Продажи руб`, sl.`Одежда Продажи НДС` AS `Одежда Продажи НДС`, sl.`Одежда Продажи шт` AS `Одежда Продажи шт`, sl.`Одежда Возвраты руб` AS `Одежда Возвраты руб`, sl.`Одежда Возвраты НДС` AS `Одежда Возвраты НДС`, sl.`Одежда Возвраты шт` AS `Одежда Возвраты шт`, sl.`Одежда Себестоимость руб` AS `Одежда Себестоимость руб`, w.`Товарный остаток шт` AS `Товарный остаток шт`, w.`Одежда Товарный остаток шт` AS `Одежда Товарный остаток шт`, i.`Поступления ДС руб` AS `Поступления ДС руб`, sl.`Комиссия` AS `Комиссия`, s.`Хранение` AS `Хранение`, s.`Логистика` AS `Логистика`, s.`Складская логистика` AS `Складская логистика`, s.`Эквайринг` AS `Эквайринг`, 0 AS `Компенсации`, s.`Штрафы` AS `Штрафы`, 0 AS `Услуги поверенного`, 0 AS `Обработка брака`, 0 AS `Размещение возврата FBS`, 0 AS `Обработка опознанных излишков`, 0 AS `Обработка товара на FBO`, 0 AS `Кроссдокинг`, 0 AS `Обработка ошибок продавца`, 0 AS `Бронирование места`, 0 AS `Утилизация остатков`, 0 AS `Восстановление товара`, s.`Приемка на складе` AS `Приемка на складе`, 0 AS `Отказ возврат товара`, 0 AS `НДС Казахстан`, 0 AS `Переупаковка товара`, 0 AS `Подготовка товара к возврату`, s.`Прочие удержания` AS `Прочие удержания`, m.`Товарная реклама` AS `Товарная реклама`, b.`Баннерная реклама` AS `Баннерная реклама`, 0 AS `Внешняя реклама`, 0 AS `Прочие услуги маркетинга`, 0 AS `Маркетинговое агентство` FROM orders AS o LEFT JOIN all_sales AS sl ON o.date = sl.sale_dt LEFT JOIN spends AS s ON o.date = s.sale_dt LEFT JOIN marketing AS m ON o.date = m.sale_dt LEFT JOIN banner AS b ON o.date = b.sale_dt LEFT JOIN income AS i ON o.date = i.`Дата` LEFT JOIN warehouse AS w ON o.date = w.Date WHERE (o.date >= '2024-06-01') AND (o.date < today()) SETTINGS final = 1;

CREATE VIEW `zendendb`.`WB_orders_by_size_v` AS WITH wb_orders AS (SELECT toDate(o.date) AS dt, o.nmId AS nmId, toInt32(countDistinct(o.srid)) AS order_qty, toInt32(countIfDistinct(o.srid, o.isCancel)) AS order_qty_cancelled, sum(if((o.totalPrice = 0) AND (o.priceWithDisc != 0), toDecimal64(o.priceWithDisc, 2), toDecimal64(o.totalPrice * (1 - (o.discountPercent * 0.01)), 2))) AS order_rub, toDecimal64(sum(o.finishedPrice), 2) AS order_rub_spp FROM `zendendb`.WB_FBO_Orders_TM AS o FINAL WHERE (toDate(o.date) >= {start_date:date}) AND (toDate(o.date) <= {end_date:date}) GROUP BY dt, nmId), wb_last_spp AS (SELECT toDate(o.date) AS dt, o.nmId AS nmId, toDecimal64(avg(o.finishedPrice), 2) AS order_rub_spp FROM `zendendb`.WB_FBO_Orders_TM AS o FINAL WHERE (o.date < today()) AND (o.date >= '2025-01-01') GROUP BY dt, nmId ORDER BY nmId ASC, dt ASC WITH FILL TO today() STEP toIntervalDay(1) INTERPOLATE (`order_rub_spp` AS order_rub_spp)), orders AS (SELECT toDate(o.date) AS dt, 'Вайлдберриз' AS mp, m.art AS art, m.kdo AS kdo, o.techSize AS size, toInt32(countDistinct(o.srid)) AS order_qty, toInt32(countDistinctIf(o.srid, isCancel)) AS order_qty_cancelled, sum(if((o.totalPrice = 0) AND (o.priceWithDisc != 0), toDecimal64(o.priceWithDisc, 2), toDecimal64(o.totalPrice * (1 - (o.discountPercent * 0.01)), 2))) AS order_rub, sumIf(if((o.totalPrice = 0) AND (o.priceWithDisc != 0), toDecimal64(o.priceWithDisc, 2), toDecimal64(o.totalPrice * (1 - (o.discountPercent * 0.01)), 2)), isCancel) AS order_rub_cancelled, toDecimal64(sum(o.finishedPrice), 2) AS order_rub_spp, toDecimal64(sumIf(o.finishedPrice, isCancel), 2) AS order_rub_spp_cancelled FROM `zendendb`.WB_FBO_Orders_TM AS o ANY LEFT JOIN (SELECT art, toInt32(art_in_mp) AS nmID, kdo FROM `zendendb`.TM_MP_art_mapping WHERE mp = 'Вайлдберриз') AS m ON o.nmId = m.nmID WHERE (toDate(o.date) >= {start_date:date}) AND (toDate(o.date) <= {end_date:date}) GROUP BY toDate(o.date), mp, m.art, m.kdo, o.techSize), nm_report AS (SELECT r.dt AS dt, 'Вайлдберриз' AS mp, m.art AS art, m.kdo AS kdo, '' AS size, r.ordersCount AS order_qty, r.cancelCount AS order_qty_cancelled, r.ordersSumRub AS order_rub, r.cancelSumRub AS order_rub_cancelled, multiIf(r.ordersCount = o.order_qty, o.order_rub_spp, o.order_rub_spp IS NULL, l.order_rub_spp * r.ordersCount, o.order_qty = 0, l.order_rub_spp * r.ordersCount, toDecimal64(r.ordersCount / o.order_qty, 2) * o.order_rub_spp) AS order_rub_spp, multiIf(r.cancelCount = o.order_qty_cancelled, o.order_rub_spp, o.order_rub_spp IS NULL, l.order_rub_spp * r.cancelCount, o.order_qty_cancelled = 0, l.order_rub_spp * r.cancelCount, toDecimal64(r.cancelCount / o.order_qty_cancelled, 2) * o.order_rub_spp) AS order_rub_spp_cancelled FROM `zendendb`.WB_Order_nm_report AS r FULL OUTER JOIN wb_orders AS o ON (o.nmId = r.nmID) AND (o.dt = r.dt) LEFT JOIN wb_last_spp AS l ON (l.nmId = r.nmID) AND (l.dt = r.dt) ANY LEFT JOIN (SELECT art, toInt32(art_in_mp) AS nmID, kdo FROM `zendendb`.TM_MP_art_mapping WHERE mp = 'Вайлдберриз') AS m ON r.nmID = m.nmID WHERE ((r.dt >= {start_date:date}) AND (r.dt <= {end_date:date})) AND ((r.ordersCount > 0) OR (r.cancelCount > 0))), orders_group_by_art AS (SELECT dt, mp, art, kdo, sum(order_qty) AS order_qty, sum(order_qty_cancelled) AS order_qty_cancelled, sum(order_rub) AS order_rub, sum(order_rub_cancelled) AS order_rub_cancelled, sum(order_rub_spp) AS order_rub_spp, sum(order_rub_spp_cancelled) AS order_rub_spp_cancelled FROM orders AS o GROUP BY dt, mp, art, kdo) SELECT dt, mp, art, kdo, size AS size, order_qty, order_qty_cancelled, order_rub, toDecimal64(order_rub_cancelled, 3) AS order_rub_cancelled, toDecimal64(order_rub_spp, 3) AS order_rub_spp, toDecimal64(order_rub_spp_cancelled, 3) AS order_rub_spp_cancelled FROM orders UNION ALL WITH wb_orders AS (SELECT toDate(o.date) AS dt, o.nmId AS nmId, toInt32(countDistinct(o.srid)) AS order_qty, toInt32(countIfDistinct(o.srid, o.isCancel)) AS order_qty_cancelled, sum(if((o.totalPrice = 0) AND (o.priceWithDisc != 0), toDecimal64(o.priceWithDisc, 2), toDecimal64(o.totalPrice * (1 - (o.discountPercent * 0.01)), 2))) AS order_rub, toDecimal64(sum(o.finishedPrice), 2) AS order_rub_spp FROM `zendendb`.WB_FBO_Orders_TM AS o FINAL WHERE (toDate(o.date) >= {start_date:date}) AND (toDate(o.date) <= {end_date:date}) GROUP BY dt, nmId), wb_last_spp AS (SELECT toDate(o.date) AS dt, o.nmId AS nmId, toDecimal64(avg(o.finishedPrice), 2) AS order_rub_spp FROM `zendendb`.WB_FBO_Orders_TM AS o FINAL WHERE (o.date < today()) AND (o.date >= '2025-01-01') GROUP BY dt, nmId ORDER BY nmId ASC, dt ASC WITH FILL TO today() STEP toIntervalDay(1) INTERPOLATE (`order_rub_spp` AS order_rub_spp)), orders AS (SELECT toDate(o.date) AS dt, 'Вайлдберриз' AS mp, m.art AS art, m.kdo AS kdo, o.techSize AS size, toInt32(countDistinct(o.srid)) AS order_qty, toInt32(countDistinctIf(o.srid, isCancel)) AS order_qty_cancelled, sum(if((o.totalPrice = 0) AND (o.priceWithDisc != 0), toDecimal64(o.priceWithDisc, 2), toDecimal64(o.totalPrice * (1 - (o.discountPercent * 0.01)), 2))) AS order_rub, sumIf(if((o.totalPrice = 0) AND (o.priceWithDisc != 0), toDecimal64(o.priceWithDisc, 2), toDecimal64(o.totalPrice * (1 - (o.discountPercent * 0.01)), 2)), isCancel) AS order_rub_cancelled, toDecimal64(sum(o.finishedPrice), 2) AS order_rub_spp, toDecimal64(sumIf(o.finishedPrice, isCancel), 2) AS order_rub_spp_cancelled FROM `zendendb`.WB_FBO_Orders_TM AS o ANY LEFT JOIN (SELECT art, toInt32(art_in_mp) AS nmID, kdo FROM `zendendb`.TM_MP_art_mapping WHERE mp = 'Вайлдберриз') AS m ON o.nmId = m.nmID WHERE (toDate(o.date) >= {start_date:date}) AND (toDate(o.date) <= {end_date:date}) GROUP BY toDate(o.date), mp, m.art, m.kdo, o.techSize), nm_report AS (SELECT r.dt AS dt, 'Вайлдберриз' AS mp, m.art AS art, m.kdo AS kdo, '' AS size, r.ordersCount AS order_qty, r.cancelCount AS order_qty_cancelled, r.ordersSumRub AS order_rub, r.cancelSumRub AS order_rub_cancelled, multiIf(r.ordersCount = o.order_qty, o.order_rub_spp, o.order_ru