, toDecimal64(o.totalPrice * (1 - (o.discountPercent * 0.01)), 2)), isCancel) AS order_rub_cancelled, toDecimal64(sum(o.finishedPrice), 2) AS order_rub_spp, toDecimal64(sumIf(o.finishedPrice, isCancel), 2) AS order_rub_spp_cancelled FROM `zendendb`.WB_FBO_Orders_TM AS o ANY LEFT JOIN (SELECT art, toInt32(art_in_mp) AS nmID, kdo FROM `zendendb`.TM_MP_art_mapping WHERE mp = 'Вайлдберриз') AS m ON o.nmId = m.nmID ANY LEFT JOIN `zendendb`.WB_warehouses_catalog AS w ON w.warehouseName = o.warehouseName WHERE (toDate(o.date) >= {start_date:date}) AND (toDate(o.date) <= {end_date:date}) GROUP BY toDate(o.date), mp, o.warehouseName, w.regionName, w.oblastOkrugName, o.regionName, o.oblastOkrugName, m.art, m.kdo), nm_report AS (SELECT r.dt AS dt, 'Вайлдберриз' AS mp, m.art AS art, m.kdo AS kdo, '-' AS size, r.ordersCount AS order_qty, r.cancelCount AS order_qty_cancelled, r.ordersSumRub AS order_rub, r.cancelSumRub AS order_rub_cancelled, multiIf(r.ordersCount = o.order_qty, o.order_rub_spp, o.order_rub_spp IS NULL, l.order_rub_spp * r.ordersCount, o.order_qty = 0, l.order_rub_spp * r.ordersCount, toDecimal64(r.ordersCount / o.order_qty, 2) * o.order_rub_spp) AS order_rub_spp, multiIf(r.cancelCount = o.order_qty_cancelled, o.order_rub_spp, o.order_rub_spp IS NULL, l.order_rub_spp * r.cancelCount, o.order_qty_cancelled = 0, l.order_rub_spp * r.cancelCount, toDecimal64(r.cancelCount / o.order_qty_cancelled, 2) * o.order_rub_spp) AS order_rub_spp_cancelled FROM `zendendb`.WB_Order_nm_report AS r LEFT JOIN wb_orders AS o ON (o.nmId = r.nmID) AND (o.dt = r.dt) LEFT JOIN wb_last_spp AS l ON (l.nmId = r.nmID) AND (l.dt = r.dt) ANY LEFT JOIN (SELECT art, toInt32(art_in_mp) AS nmID, kdo FROM `zendendb`.TM_MP_art_mapping WHERE mp = 'Вайлдберриз') AS m ON r.nmID = m.nmID WHERE ((r.dt >= {start_date:date}) AND (r.dt <= {end_date:date})) AND ((r.ordersCount > 0) OR (r.cancelCount > 0))), orders_group_by_art AS (SELECT dt, mp, art, kdo, sum(order_qty) AS order_qty, sum(order_qty_cancelled) AS order_qty_cancelled, sum(order_rub) AS order_rub, sum(order_rub_cancelled) AS order_rub_cancelled, sum(order_rub_spp) AS order_rub_spp, sum(order_rub_spp_cancelled) AS order_rub_spp_cancelled FROM orders AS o GROUP BY dt, mp, art, kdo) SELECT n.dt, n.mp, 'не указано' AS warehouseName, 'не указано' AS warehouseRegionName, 'не указано' AS warehouseOblastOkrugName, 'не указано' AS regionName, 'не указано' AS oblastOkrugName, n.art, n.kdo, '-' AS size, if((n.order_qty - ifNull(o.order_qty, 0)) < 0, 0, n.order_qty - ifNull(o.order_qty, 0)) AS order_qty, if((n.order_qty_cancelled - ifNull(o.order_qty_cancelled, 0)) < 0, 0, n.order_qty_cancelled - ifNull(o.order_qty_cancelled, 0)) AS order_qty_cancelled, if((n.order_rub - ifNull(o.order_rub, 0)) < 0, 0, n.order_rub - ifNull(o.order_rub, 0)) AS order_rub, if((n.order_rub_cancelled - ifNull(o.order_rub_cancelled, 0)) < 0, 0, n.order_rub_cancelled - ifNull(o.order_rub_cancelled, 0)) AS order_rub_cancelled, if((n.order_rub_spp - ifNull(o.order_rub_spp, 0)) < 0, 0, n.order_rub_spp - ifNull(o.order_rub_spp, 0)) AS order_rub_spp, if((n.order_rub_spp_cancelled - ifNull(o.order_rub_spp_cancelled, 0)) < 0, 0, n.order_rub_spp_cancelled - ifNull(o.order_rub_spp_cancelled, 0)) AS order_rub_spp_cancelled FROM nm_report AS n LEFT JOIN orders_group_by_art AS o ON (n.dt = o.dt) AND (n.kdo = o.kdo) SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`WarehousesOnDate_v` AS SELECT {end_date:date} AS `Период`, `СкладГуид`, `Склад`, splitByWhitespace(`Склад`)[1] AS `СкладТип`, `ПодразделениеГуид`, `Подразделение`, `НоменклатураГуид`, argMax(w.`КоличествоОстаток`, w.`Период`) AS `КоличествоОстаток` FROM `zendendb`.`ТоварыНаСкладахЦР` AS w WHERE (toDate(w.`Период`) <= {end_date:date}) AND ((splitByWhitespace(`Склад`)[1]) IN ('Основной', 'Маркетплейс', 'ИНТЕРНЕТ-магазин')) GROUP BY `СкладГуид`, `Склад`, `СкладТип`, `ПодразделениеГуид`, `Подразделение`, `НоменклатураГуид` HAVING `КоличествоОстаток` != 0 SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`YANDEX_orders_v` AS WITH yandex_orders_rows AS (SELECT x.*, rank() OVER (PARTITION BY ORDER_ID, SHOP_SKU, toDate(timestamp) ORDER BY OFFER_STATUS ASC) AS row_num FROM `zendendb`.YANDEX_Orders_TM AS x FINAL), agg_orders AS (SELECT ORDER_ID, SHOP_SKU, argMax(s.CREATION_DATE, timestamp) AS CREATION_DATE, argMax(s.DELIVERED_OR_RETURNED, timestamp) AS DELIVERED_OR_RETURNED, argMax(s.PARTNER_PRICE_FOR_DELIVERY, timestamp) AS PARTNER_PRICE_FOR_DELIVERY, argMax(s.BILLING_PRICE, timestamp) AS BILLING_PRICE, argMax(s.MARKETPLACE_SUBSIDY, timestamp) AS MARKETPLACE_SUBSIDY, argMax(s.OFFER_STATUS, timestamp) AS OFFER_STATUS, argMax(s.STATUS_CHANGED, timestamp) AS STATUS_CHANGED FROM yandex_orders_rows AS s WHERE (toDate(s.CREATION_DATE) >= {start_date:date}) AND (toDate(s.CREATION_DATE) <= {end_date:date}) GROUP BY ORDER_ID, SHOP_SKU, row_num) SELECT y.CREATION_DATE AS dt, 'Яндекс' AS mp, 'не указано' AS warehouseName, 'не указано' AS warehouseRegionName, 'не указано' AS warehouseOblastOkrugName, 'не указано' AS regionName, 'не указано' AS oblastOkrugName, m.art AS art, m.kdo AS kdo, replaceAll(splitByChar('_', y.SHOP_SKU)[2], ',', '.') AS size, toInt32(sum(DELIVERED_OR_RETURNED)) AS order_qty, toInt32(sumIf(DELIVERED_OR_RETURNED, y.OFFER_STATUS = 'Отменён')) AS order_qty_cancelled, toDecimal64(sum(y.BILLING_PRICE), 3) AS order_rub, toDecimal64(sumIf(y.BILLING_PRICE, y.OFFER_STATUS = 'Отменён'), 3) AS order_rub_cancelled, toDecimal64(sum(y.BILLING_PRICE) - sum(y.MARKETPLACE_SUBSIDY), 3) AS order_rub_spp, toDecimal64(sumIf(y.BILLING_PRICE, y.OFFER_STATUS = 'Отменён') - sumIf(y.MARKETPLACE_SUBSIDY, y.OFFER_STATUS = 'Отменён'), 3) AS order_rub_spp_cancelled FROM agg_orders AS y ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = y.SHOP_SKU) AND (m.mp = 'Яндекс') WHERE (y.CREATION_DATE >= {start_date:date}) AND (y.CREATION_DATE <= {end_date:date}) GROUP BY dt, mp, art, kdo, size SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`YA_by_day_v` (`Дата` Date, `Магазин` String, `Заказы руб` Nullable(Decimal(10, 3)), `Заказы НДС` Nullable(Decimal(10, 3)), `Заказы шт` Nullable(Int64), `Продажи руб` Nullable(Decimal(10, 3)), `Продажи НДС` Nullable(Decimal(10, 3)), `Продажи шт` Nullable(Int64), `Возвраты руб` Nullable(Decimal(10, 3)), `Возвраты НДС` Nullable(Decimal(10, 3)), `Возвраты шт` Nullable(Int64), `Себестоимость руб` Nullable(Decimal(10, 3)), `Одежда Заказы руб` Nullable(Decimal(10, 3)), `Одежда Заказы НДС` Nullable(Decimal(10, 3)), `Одежда Заказы шт` Nullable(Int64), `Одежда Продажи руб` Nullable(Decimal(10, 3)), `Одежда Продажи НДС` Nullable(Decimal(10, 3)), `Одежда Продажи шт` Nullable(Int64), `Одежда Возвраты руб` Nullable(Decimal(10, 3)), `Одежда Возвраты НДС` Nullable(Decimal(10, 3)), `Одежда Возвраты шт` Nullable(Int64), `Одежда Себестоимость руб` Nullable(Decimal(10, 3)), `Товарный остаток шт` Nullable(Int64), `Одежда Товарный остаток шт` Nullable(Int64), `Поступления ДС руб` Nullable(Decimal(10, 3)), `Комиссия` Nullable(Decimal(10, 3)), `Хранение` Nullable(Decimal(10, 3)), `Логистика` Nullable(Decimal(10, 3)), `Складская логистика` Nullable(Decimal(10, 3)), `Эквайринг` Nullable(Decimal(10, 3)), `Компенсации` Nullable(Decimal(10, 3)), `Штрафы` Nullable(Decimal(10, 3)), `Услуги поверенного` Nullable(Decimal(10, 3)), `Обработка брака` Nullable(Decimal(10, 3)), `Размещение возврата FBS` Nullable(Decimal(10, 3)), `Обработка опознанных излишков` Nullable(Decimal(10, 3)), `Обработка товара на FBO` Nullable(Decimal(10, 3)), `Кроссдокинг` Nullable(Decimal(10, 3)), `Обработка ошибок продавца` Nullable(Decimal(10, 3)), `Бронирование места` Nullable(Decimal(10, 3)), `Утилизация остатков` Nullable(Decimal(10, 3)), `Восстановление товара` Nullable(Decimal(10, 3)), `Приемка на складе` Nullable(Decimal(10, 3)), `Отказ возврат товара` Nullable(Decimal(10, 3)), `НДС Казахстан` Nullable(Decimal(10, 3)), `Переупаковка товара` Nullable(Decimal(10, 3)), `Подготовка товара к возврату` Nullable(Decimal(10, 3)), `Прочие удержания` Nullable(Decimal(10, 3)), `Товарная реклама` Nullable(Int64), `Баннерная реклама` Nullable(Decimal(10, 3)), `Внешняя реклама` Nullable(Decimal(10, 3)), `Прочие услуги маркетинга` Nullable(Decimal(10, 3)), `Маркетинговое агентство` Nullable(Decimal(10, 3))) AS WITH income AS (SELECT toDate(pp.`Дата`) AS `Дата`, sum(`СуммаДокумента`) AS `Поступления ДС руб` FROM `zendendb`.`ПлатежноеПоручениеВходящее` AS pp WHERE (`Подразделение` IN ('Отдел по работе с Market Places Zenden')) AND (`Контрагент` IN ('Яндекс ООО', 'Яндекс Маркет ООО')) GROUP BY `Дата`), arts AS (SELECT DISTINCT splitByChar('_', SHOP_SKU)[1] AS art FROM `zendendb`.YANDEX_Orders AS yo WHERE art != ''), art_dict AS (SELECT DISTINCT art, t.`КодДляОбмена` AS kdo, t.`ТипНоменклатуры` IN ('Изделия бельевые', 'Изделия верхние', 'Одежда') AS `Одежда`, round(toInt32OrZero(splitByChar('%', assumeNotNull(t.`СтавкаНДС`))[1]) / (100 + toInt32OrZero(splitByChar('%', assumeNotNull(t.`СтавкаНДС`))[1])), 4) AS nds FROM arts AS a ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`Артикул` = a.art), orders AS (SELECT CREATION_DATE, sum(BILLING_PRICE) AS `Заказы руб`, sum(BILLING_PRICE * a.nds) AS `Заказы НДС`, count(SHOP_SKU) AS `Заказы шт`, sumIf(BILLING_PRICE, a.`Одежда`) AS `Одежда Заказы руб`, sumIf(BILLING_PRICE * a.nds, a.`Одежда`) AS `Одежда Заказы НДС`, countIf(SHOP_SKU, a.`Одежда`) AS `Одежда Заказы шт` FROM `zendendb`.YANDEX_Orders AS yo FINAL LEFT JOIN art_dict AS a ON a.art = (splitByChar('_', SHOP_SKU)[1]) GROUP BY CREATION_DATE), sales AS (SELECT toDate(STATUS_CHANGED) AS STATUS_CHANGED, sumIf(BILLING_PRICE, OFFER_STATUS = 'Доставлен покупателю') AS `Продажи руб`, sumIf(BILLING_PRICE * a.nds, OFFER_STATUS = 'Доставлен покупателю') AS `Продажи НДС`, countIf(SHOP_SKU, OFFER_STATUS = 'Доставлен покупателю') AS `Продажи шт`, sumIf(BILLING_PRICE, (OFFER_STATUS IN ('Возврат принят на складе'))) AS `Возвраты руб`, sumIf(BILLING_PRICE * a.nds, (OFFER_STATUS IN ('Возврат принят на складе'))) AS `Возвраты НДС`, countIf(SHOP_SKU, (OFFER_STATUS IN ('Возврат принят на складе'))) AS `Возвраты шт`, sumIf(sb.value_rub, OFFER_STATUS = 'Доставлен покупателю') AS `Себестоимость руб`, sumIf(BILLING_PRICE, (OFFER_STATUS = 'Доставлен покупателю') AND a.`Одежда`) AS `Одежда Продажи руб`, sumIf(BILLING_PRICE * a.nds, (OFFER_STATUS = 'Доставлен покупателю') AND a.`Одежда`) AS `Одежда Продажи НДС`, countIf(SHOP_SKU, (OFFER_STATUS = 'Доставлен покупателю') AND a.`Одежда`) AS `Одежда Продажи шт`, sumIf(BILLING_PRICE, (OFFER_STATUS IN ('Возврат принят на складе')) AND a.`Одежда`) AS `Одежда Возвраты руб`, sumIf(BILLING_PRICE * a.nds, (OFFER_STATUS IN ('Возврат принят на складе')) AND a.`Одежда`) AS `Одежда Возвраты НДС`, countIf(SHOP_SKU, (OFFER_STATUS IN ('Возврат принят на складе')) AND a.`Одежда`) AS `Одежда Возвраты шт`, sumIf(sb.value_rub, (OFFER_STATUS = 'Доставлен покупателю') AND a.`Одежда`) AS `Одежда Себестоимость руб` FROM `zendendb`.YANDEX_Orders AS yo FINAL LEFT JOIN art_dict AS a ON a.art = (splitByChar('_', SHOP_SKU)[1]) ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS sb ON (sb.half = if(toMonth(yo.STATUS_CHANGED) <= 6, toStartOfYear(yo.STATUS_CHANGED), toStartOfYear(yo.STATUS_CHANGED) + toIntervalMonth(6))) AND (sb.kdo = a.kdo) AND (sb.price_type = 'Себестоимость') GROUP BY STATUS_CHANGED), spends AS (SELECT SERVICE_DATE, sumIf(SERVICE_PRICE, (SERVICE_NAME IN ('Размещение товара'))) AS `Комиссия`, sumIf(SERVICE_PRICE, (SERVICE_NAME IN ('Платное хранение'))) AS `Хранение`, sumIf(SERVICE_PRICE, (SERVICE_NAME IN ('Приём платежа', 'Перевод платежа'))) AS `Эквайринг`, sumIf(SERVICE_PRICE, (SERVICE_NAME IN ('Организация утилизации товаров, принятых с нарушением условий поставки'))) AS `Утилизация остатков`, sumIf(SERVICE_PRICE, (SERVICE_NAME IN ('Возврат товара заказчику'))) AS `Отказ возврат товара`, sumIf(SERVICE_PRICE, (SERVICE_NAME IN ('Буст продаж с оплатой за показы', 'Буст продаж', 'Полка'))) AS `Товарная реклама`, sumIf(SERVICE_PRICE, (SERVICE_NAME IN ('Баллы за фото к отзыву', 'Баллы за отзыв', 'Участие в программе лояльности'))) AS `Прочие услуги маркетинга` FROM `zendendb`.YANDEX_Spends AS ys FINAL GROUP BY SERVICE_DATE) SELECT o.CREATION_DATE AS `Дата`, '4.Yandex' AS `Магазин`, o.`Заказы руб` AS `Заказы руб`, o.`Заказы НДС` AS `Заказы НДС`, o.`Заказы шт` AS `Заказы шт`, s.`Продажи руб` AS `Продажи руб`, s.`Продажи НДС` AS `Продажи НДС`, s.`Продажи шт` AS `Продажи шт`, s.`Возвраты руб` AS `Возвраты руб`, s.`Возвраты НДС` AS `Возвраты НДС`, s.`Возвраты шт` AS `Возвраты шт`, s.`Себестоимость руб` AS `Себестоимость руб`, o.`Одежда Заказы руб` AS `Одежда Заказы руб`, o.`Одежда Заказы НДС` AS `Одежда Заказы НДС`, o.`Одежда Заказы шт` AS `Одежда Заказы шт`, s.`Одежда Продажи руб` AS `Одежда Продажи руб`, s.`Одежда Продажи шт` AS `Одежда Продажи шт`, s.`Одежда Продажи НДС` AS `Одежда Продажи НДС`, s.`Одежда Возвраты руб` AS `Одежда Возвраты руб`, s.`Одежда Возвраты НДС` AS `Одежда Возвраты НДС`, s.`Одежда Возвраты шт` AS `Одежда Возвраты шт`, s.`Одежда Себестоимость руб` AS `Одежда Себестоимость руб`, 0 AS `Товарный остаток шт`, 0 AS `Одежда Товарный остаток шт`, i.`Поступления ДС руб` AS `Поступления ДС руб`, sp.`Комиссия` AS `Комиссия`, sp.`Хранение` AS `Хранение`, 0 AS `Логистика`, 0 AS `Складская логистика`, sp.`Эквайринг` AS `Эквайринг`, 0 AS `Компенсации`, 0 AS `Штрафы`, 0 AS `Услуги поверенного`, 0 AS `Обработка брака`, 0 AS `Размещение возврата FBS`, 0 AS `Обработка опознанных излишков`, 0 AS `Обработка товара на FBO`, 0 AS `Кроссдокинг`, 0 AS `Обработка ошибок продавца`, 0 AS `Бронирование места`, sp.`Утилизация остатков` AS `Утилизация остатков`, 0 AS `Восстановление товара`, 0 AS `Приемка на складе`, sp.`Отказ возврат товара` AS `Отказ возврат товара`, 0 AS `НДС Казахстан`, 0 AS `Переупаковка товара`, 0 AS `Подготовка товара к возврату`, 0 AS `Прочие удержания`, sp.`Товарная реклама` AS `Товарная реклама`, 0 AS `Баннерная реклама`, 0 AS `Внешняя реклама`, sp.`Прочие услуги маркетинга` AS `Прочие услуги маркетинга`, 0 AS `Маркетинговое агентство` FROM orders AS o LEFT JOIN sales AS s ON o.CREATION_DATE = s.STATUS_CHANGED LEFT JOIN spends AS sp ON o.CREATION_DATE = sp.SERVICE_DATE LEFT JOIN income AS i ON o.CREATION_DATE = i.`Дата` WHERE (o.CREATION_DATE >= '2024-06-01') AND (o.CREATION_DATE < today()) SETTINGS final = 1;

CREATE VIEW `zendendb`.`YA_orders_by_size_v` AS WITH yandex_orders_rows AS (SELECT x.*, rank() OVER (PARTITION BY ORDER_ID, SHOP_SKU, toDate(timestamp) ORDER BY OFFER_STATUS ASC) AS row_num FROM `zendendb`.YANDEX_Orders_TM AS x FINAL), agg_orders AS (SELECT ORDER_ID, SHOP_SKU, argMax(s.CREATION_DATE, timestamp) AS CREATION_DATE, argMax(s.DELIVERED_OR_RETURNED, timestamp) AS DELIVERED_OR_RETURNED, argMax(s.PARTNER_PRICE_FOR_DELIVERY, timestamp) AS PARTNER_PRICE_FOR_DELIVERY, argMax(s.BILLING_PRICE, timestamp) AS BILLING_PRICE, argMax(s.MARKETPLACE_SUBSIDY, timestamp) AS MARKETPLACE_SUBSIDY, argMax(s.OFFER_STATUS, timestamp) AS OFFER_STATUS, argMax(s.STATUS_CHANGED, timestamp) AS STATUS_CHANGED FROM yandex_orders_rows AS s WHERE (toDate(s.CREATION_DATE) >= {start_date:date}) AND (toDate(s.CREATION_DATE) <= {end_date:date}) GROUP BY ORDER_ID, SHOP_SKU, row_num) SELECT y.CREATION_DATE AS dt, 'Яндекс' AS mp, m.art AS art, m.kdo AS kdo, replaceAll(splitByChar('_', y.SHOP_SKU)[2], ',', '.') AS size, toInt32(sum(DELIVERED_OR_RETURNED)) AS order_qty, toInt32(sumIf(DELIVERED_OR_RETURNED, y.OFFER_STATUS = 'Отменён')) AS order_qty_cancelled, toDecimal64(sum(y.BILLING_PRICE), 3) AS order_rub, toDecimal64(sumIf(y.BILLING_PRICE, y.OFFER_STATUS = 'Отменён'), 3) AS order_rub_cancelled, toDecimal64(sum(y.BILLING_PRICE) - sum(y.MARKETPLACE_SUBSIDY), 3) AS order_rub_spp, toDecimal64(sumIf(y.BILLING_PRICE, y.OFFER_STATUS = 'Отменён') - sumIf(y.MARKETPLACE_SUBSIDY, y.OFFER_STATUS = 'Отменён'), 3) AS order_rub_spp_cancelled FROM agg_orders AS y ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = y.SHOP_SKU) AND (m.mp = 'Яндекс') WHERE (y.CREATION_DATE >= {start_date:date}) AND (y.CREATION_DATE <= {end_date:date}) GROUP BY dt, mp, art, kdo, size SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`art_mapping_oms_upp_v` (`NAME` Nullable(String), `PRODUCT_ID` UInt32, `PRODUCT_XML_ID` String, `kdo` String) AS WITH goods AS (SELECT `Товар`, if(`Артикул` = '', NULL, `Артикул`) AS `Артикул`, if(`КодДляОбмена` = 0, NULL, `КодДляОбмена`) AS `КодДляОбмена`, if(if(endsWith(assumeNotNull(`Артикул`), '\'') = 1, splitByString('\\\'', trimBoth(assumeNotNull(`Артикул`)))[1], trimBoth(assumeNotNull(`Артикул`))) = '', NULL, if(endsWith(assumeNotNull(`Артикул`), '\'') = 1, splitByString('\\\'', trimBoth(assumeNotNull(`Артикул`)))[1], trimBoth(assumeNotNull(`Артикул`)))) AS `Артикул_fix`, if((splitByString(' ', trimBoth(assumeNotNull(`Артикул`)))[1]) = '', NULL, (splitByString(' ', trimBoth(assumeNotNull(`Артикул`)))[1]) = '') AS `Артикул_trim`, if(toString(`КодДляОбмена`) = '', NULL, toString(`КодДляОбмена`)) AS `КодДляОбмена_string`, if(trimBoth(`Товар`) = '', NULL, trimBoth(`Товар`)) AS `Товар_trim` FROM `zendendb`.`ТоварыУПП`), art AS (SELECT trimBoth(NAME) AS NAME, PRODUCT_ID, PRODUCT_XML_ID, t.`Артикул`, multiIf(t.`Артикул` IS NOT NULL, trimBoth(t.`Артикул`), splitByWhitespace(assumeNotNull(NAME))[1]) AS art, splitByChar('#', t.PRODUCT_XML_ID)[1] AS kdo, trimBoth(concat(splitByWhitespace(assumeNotNull(NAME))[1], ' ', splitByWhitespace(assumeNotNull(NAME))[2])) AS art2 FROM `zendendb`.`ЗаказКлиента.Товары` AS t), kdo AS (SELECT DISTINCT NAME, PRODUCT_ID, PRODUCT_XML_ID, kdo FROM art AS a ANY LEFT JOIN goods AS t ON (t.`Артикул_fix` = a.art) OR (t.`КодДляОбмена_string` = a.kdo) OR (t.`Артикул_fix` = a.art2) OR (t.`Товар_trim` = a.NAME) OR (toString(t.`Артикул_trim`) = a.art) WHERE t.`КодДляОбмена` IS NULL SETTINGS final = 1, join_use_nulls = 1, join_algorithm = 'hash') SELECT * FROM kdo AS k SETTINGS final = 1, join_use_nulls = 1, join_algorithm = 'hash';

CREATE VIEW `zendendb`.`check_table_update` (`table` String, `query_id` String, `event_type` Nullable(Enum8('NewPart' = 1, 'MergeParts' = 2, 'DownloadPart' = 3, 'RemovePart' = 4, 'MutatePart' = 5, 'MovePart' = 6, 'MergePartsStart' = 7, 'MutatePartStart' = 8)), `last_event` DateTime('Europe/Moscow'), `part_name` String, `partition_id` String, `rows` UInt64) AS SELECT `table`, argMax(query_id, event_time) AS query_id, argMax(if(event_type = 'NewPart', event_type, NULL), event_time) AS event_type, toDateTime(max(event_time), 'Europe/Moscow') AS last_event, argMax(part_name, event_time) AS part_name, argMax(partition_id, event_time) AS partition_id, argMax(rows, event_time) AS rows FROM system.part_log AS p WHERE (database = 'zendendb') AND (`table` IN ('ИнтернетЗаказПокупателя', 'ИнтернетЗаказПокупателя_Товары', 'ТоварыУПП', 'ТоварыУчаствующиеВАкции', 'ЦеныНоменклатурыЦР', 'ПродажиУПП', 'ТоварыНаСкладахЦР', 'ТоварыНаСкладахУПП', 'Продажи', 'ПродажиПроведенные', 'Товары', 'ПосещаемостьМагазинов', 'Магазины', 'ЦеныНоменклатуры', 'ПлатежноеПоручениеВходящее', 'ДокументыНаОснованииИнтернет', 'КадроваяИсторияСотрудников', 'ГрафикРаботыСотрудников', 'ВидыЗанятостиСотрудников', 'МестоПозицииШтатногоРасписания', 'Сотрудники', 'СостоянияСотрудников', 'ТекущиеКадровыеДанныеСотрудников', 'ФизическиеЛица', 'ШтатноеРасписание', 'ТоварыПереданныеTM', 'ТоварыВРезервеНаСкладах', 'ТоварыКПередачеСоСкладов', 'ЗаказыПокупателей', 'НоменклатураМаркетплейсов', 'NomenklaturaMP', 'ДанныеЗаказовОМС', 'TovaryNaSkladaxCR')) GROUP BY `table` ORDER BY last_event DESC;

CREATE VIEW `zendendb`.`cost_by_half_v` (`half` Date, `last_date` Date, `guid` String, `guidSales` Nullable(String), `kdo` Nullable(UInt32), `price_type` String, `value_rub` Decimal(15, 2)) AS WITH cost AS (SELECT `ТоварГуид` AS guid, `ТипЦен` AS price_type, toDate(max(`Период`), 'UTC') AS last_date, argMax(`Цена`, `Период`) AS value_rub, if(toMonth(`Период`) <= 6, toStartOfYear(`Период`, 'UTC'), toStartOfYear(`Период`, 'UTC') + toIntervalMonth(6)) AS half FROM `zendendb`.`ЦеныНоменклатуры_2005-2022` AS sp WHERE `Период` < '2023-01-01' GROUP BY guid, price_type, half UNION ALL SELECT `ТоварГуид` AS guid, `ТипЦен` AS price_type, toDate(max(`Период`), 'UTC') AS last_date, argMax(`Цена`, `Период`) AS value_rub, if(toMonth(`Период`) <= 6, toStartOfYear(`Период`, 'UTC'), toStartOfYear(`Период`, 'UTC') + toIntervalMonth(6)) AS half FROM `zendendb`.`ЦеныНоменклатуры` AS sp GROUP BY guid, price_type, half), all_cost AS (SELECT * FROM cost ORDER BY guid ASC, price_type ASC, half ASC WITH FILL TO if(toMonth(today()) <= 6, toStartOfYear(today()), toStartOfYear(today() + toIntervalMonth(6))) + 1 STEP toIntervalMonth(6) INTERPOLATE (`value_rub` AS value_rub, `last_date` AS last_date)) SELECT half, last_date, guid, t3.`ТоварГуид` AS guidSales, t3.`КодДляОбмена` AS kdo, price_type, value_rub FROM all_cost AS c LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`ТоварГуид` = c.guid LEFT JOIN `zendendb`.`Товары` AS t2 ON t2.`ТоварГуид` = c.guid LEFT JOIN `zendendb`.`Товары` AS t3 ON ifNull(t.`КодДляОбмена`, t2.`КодДляОбмена`) = t3.`КодДляОбмена` SETTINGS join_use_nulls = 1;

CREATE VIEW `zendendb`.`goods_v` AS SELECT {end_date:date} AS dt, w.`Контрагент` AS mp, w.`НоменклатураКодДляОбмена` AS kdo, sum(w.`Количество`) AS qty FROM `zendendb`.`ТоварыПереданныеTM` AS w WHERE (w.`Контрагент` IN ('Вайлдберриз ООО', 'Интернет Решения ООО Thomas Munz (Озон)', 'Купишуз ООО', 'МАРКЕТПЛЕЙС ООО', 'РВБ ООО', 'Вайлдберриз-Thomas Muenz', 'Яндекс ООО', 'Яндекс Маркет ООО')) AND (toDate(`Период`) <= {end_date:date}) GROUP BY w.`Контрагент`, w.`НоменклатураКодДляОбмена`;

CREATE VIEW `zendendb`.`lm_art_mapping_v` (`mp` String, `art_mp` String, `art` Nullable(String), `kdo` Nullable(UInt32), `art_in_mp` String, `art_link` String) AS WITH arts AS (SELECT DISTINCT sku, lamodaparentsku FROM `zendendb`.LAMODA_Prices_TM AS p WHERE p.timestamp > (today() - toIntervalYear(1))), goods AS (SELECT * FROM `zendendb`.`Товары` AS t WHERE `Артикул` != ''), art_corr AS (SELECT a.sku, a.lamodaparentsku, arrayStringConcat(arraySlice(splitByChar('-', sku), 1, -1), '-') AS art, arrayStringConcat(arraySlice(splitByChar('_', sku), 1, -1), '_') AS art1, arrayStringConcat(arraySlice(splitByChar('-', sku), 1, -2), '-') AS art2, arrayStringConcat(arraySlice(splitByChar('-', sku), 1, -3), '-') AS art3, arrayStringConcat(arraySlice(splitByChar('-', sku), 1, -4), '-') AS art4 FROM arts AS a ANY LEFT JOIN goods AS t ON t.`Артикул` = arrayStringConcat(arraySlice(splitByChar('-', sku), 1, -1), '-') WHERE t.`Артикул` IS NULL), art_fix AS (SELECT sku, lamodaparentsku, multiIf(sku = 'SL_111_черн-00', 'SL 111 черн', sku LIKE '073-002E-2121%', '073-002E-2102', sku LIKE '689-92l-1302%', '689-92L-1302', t.`Артикул` IS NOT NULL, t.`Артикул`, t1.`Артикул` IS NOT NULL, t1.`Артикул`, t2.`Артикул` IS NOT NULL, t2.`Артикул`, t3.`Артикул` IS NOT NULL, t3.`Артикул`, t4.`Артикул` IS NOT NULL, t4.`Артикул`, NULL) AS `Артикул` FROM art_corr AS a ANY LEFT JOIN goods AS t ON t.`Артикул` = a.sku ANY LEFT JOIN goods AS t1 ON t1.`Артикул` = a.art1 ANY LEFT JOIN goods AS t2 ON t2.`Артикул` = a.art2 ANY LEFT JOIN goods AS t3 ON t3.`Артикул` = a.art3 ANY LEFT JOIN goods AS t4 ON t4.`Артикул` = a.art4) SELECT 'Ламода' AS mp, sku AS art_mp, t.`Артикул` AS art, t.`КодДляОбмена` AS kdo, a.lamodaparentsku AS art_in_mp, concat('https://www.lamoda.ru/p/', lower(a.lamodaparentsku)) AS art_link FROM arts AS a ANY LEFT JOIN goods AS t ON t.`Артикул` = arrayStringConcat(arraySlice(splitByChar('-', sku), 1, -1), '-') WHERE t.`Артикул` IS NOT NULL UNION ALL WITH arts AS (SELECT DISTINCT sku, lamodaparentsku FROM `zendendb`.LAMODA_Prices_TM AS p WHERE p.timestamp > (today() - toIntervalYear(1))), goods AS (SELECT * FROM `zendendb`.`Товары` AS t WHERE `Артикул` != ''), art_corr AS (SELECT a.sku, a.lamodaparentsku, arrayStringConcat(arraySlice(splitByChar('-', sku), 1, -1), '-') AS art, arrayStringConcat(arraySlice(splitByChar('_', sku), 1, -1), '_') AS art1, arrayStringConcat(arraySlice(splitByChar('-', sku), 1, -2), '-') AS art2, arrayStringConcat(arraySlice(splitByChar('-', sku), 1, -3), '-') AS art3, arrayStringConcat(arraySlice(splitByChar('-', sku), 1, -4), '-') AS art4 FROM arts AS a ANY LEFT JOIN goods AS t ON t.`Артикул` = arrayStringConcat(arraySlice(splitByChar('-', sku), 1, -1), '-') WHERE t.`Артикул` IS NULL), art_fix AS (SELECT sku, lamodaparentsku, multiIf(sku = 'SL_111_черн-00', 'SL 111 черн', sku LIKE '073-002E-2121%', '073-002E-2102', sku LIKE '689-92l-1302%', '689-92L-1302', t.`Артикул` IS NOT NULL, t.`Артикул`, t1.`Артикул` IS NOT NULL, t1.`Артикул`, t2.`Артикул` IS NOT NULL, t2.`Артикул`, t3.`Артикул` IS NOT NULL, t3.`Артикул`, t4.`Артикул` IS NOT NULL, t4.`Артикул`, NULL) AS `Артикул` FROM art_corr AS a ANY LEFT JOIN goods AS t ON t.`Артикул` = a.sku ANY LEFT JOIN goods AS t1 ON t1.`Артикул` = a.art1 ANY LEFT JOIN goods AS t2 ON t2.`Артикул` = a.art2 ANY LEFT JOIN goods AS t3 ON t3.`Артикул` = a.art3 ANY LEFT JOIN goods AS t4 ON t4.`Артикул` = a.art4) SELECT 'Ламода' AS mp, sku AS art_mp, `Артикул` AS art, t.`КодДляОбмена` AS kdo, a.lamodaparentsku AS art_in_mp, concat('https://www.lamoda.ru/p/', lower(a.lamodaparentsku)) AS art_link FROM art_fix AS a ANY LEFT JOIN goods AS t ON t.`Артикул` = a.`Артикул` SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`orders_TM_MP_v` (`dt` Date, `mp` String, `art` Nullable(String), `kdo` Nullable(UInt32), `iscancel` UInt8, `order_qty` Nullable(Int32), `order_rub` Nullable(Decimal(38, 3)), `order_rub_spp` Nullable(Decimal(18, 3))) AS WITH yandex_orders_rows AS (SELECT x.*, rank() OVER (PARTITION BY ORDER_ID, SHOP_SKU, toDate(timestamp) ORDER BY OFFER_STATUS ASC) AS row_num FROM `zendendb`.YANDEX_Orders_TM AS x FINAL), agg_orders AS (SELECT ORDER_ID, SHOP_SKU, argMax(s.CREATION_DATE, timestamp) AS CREATION_DATE, argMax(s.DELIVERED_OR_RETURNED, timestamp) AS DELIVERED_OR_RETURNED, argMax(s.PARTNER_PRICE_FOR_DELIVERY, timestamp) AS PARTNER_PRICE_FOR_DELIVERY, argMax(s.BILLING_PRICE, timestamp) AS BILLING_PRICE, argMax(s.MARKETPLACE_SUBSIDY, timestamp) AS MARKETPLACE_SUBSIDY, argMax(s.OFFER_STATUS, timestamp) AS OFFER_STATUS, argMax(s.STATUS_CHANGED, timestamp) AS STATUS_CHANGED FROM yandex_orders_rows AS s WHERE toDate(s.CREATION_DATE) < today() GROUP BY ORDER_ID, SHOP_SKU, row_num), lm_dubles AS (SELECT item_id, toYear(today()), s.createdAt FROM `zendendb`.LAMODA_Sales_TM AS s WHERE (toYear(s.createdAt) = toYear(today())) AND (item_id IN (SELECT item_id FROM `zendendb`.LAMODA_Sales_TM WHERE toYear(createdAt) < toYear(today())))), lm_sale AS (SELECT orderNr, createdAt, item_id, argMax(m.art, o.updatedAt) AS art, argMax(m.art_mp, o.updatedAt) AS art_mp, argMax(m.kdo, o.updatedAt) AS kdo, argMax(o.status, o.updatedAt) AS status, argMax(o.sku, o.updatedAt) AS sku, argMax(if(o.currency = 'kzt', o.partnerAgreedPrice * (c.Value / c.Nominal), o.partnerAgreedPrice), o.updatedAt) AS partnerAgreedPrice, argMax(if(o.currency = 'kzt', o.paidPrice * (c.Value / c.Nominal), o.paidPrice), o.updatedAt) AS paidPrice, argMax(o.currency, o.updatedAt) AS currency FROM `zendendb`.LAMODA_Sales_TM AS o FINAL LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = toString(o.sku)) AND (m.mp = 'Ламода') LEFT JOIN `zendendb`.currency_rate AS c ON (c.Date = o.createdAt) AND (c.CharCode = 'KZT') WHERE (source IS NULL) AND (toDate(o.createdAt) < today()) AND (((item_id NOT IN (SELECT item_id FROM lm_dubles)) AND (toYear(o.createdAt) = toYear(today()))) OR (toYear(o.createdAt) != toYear(today()))) GROUP BY orderNr, createdAt, item_id) SELECT y.CREATION_DATE AS dt, 'Яндекс' AS mp, m.art AS art, m.kdo AS kdo, y.OFFER_STATUS = 'Отменён' AS iscancel, toInt32(sum(DELIVERED_OR_RETURNED)) AS order_qty, toDecimal64(sum(y.BILLING_PRICE), 3) AS order_rub, toDecimal64(sum(y.BILLING_PRICE) - sum(y.MARKETPLACE_SUBSIDY), 3) AS order_rub_spp FROM agg_orders AS y ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = y.SHOP_SKU) AND (m.mp = 'Яндекс') WHERE y.CREATION_DATE < today() GROUP BY dt, mp, art, kdo, iscancel UNION ALL WITH yandex_orders_rows AS (SELECT x.*, rank() OVER (PARTITION BY ORDER_ID, SHOP_SKU, toDate(timestamp) ORDER BY OFFER_STATUS ASC) AS row_num FROM `zendendb`.YANDEX_Orders_TM AS x FINAL), agg_orders AS (SELECT ORDER_ID, SHOP_SKU, argMax(s.CREATION_DATE, timestamp) AS CREATION_DATE, argMax(s.DELIVERED_OR_RETURNED, timestamp) AS DELIVERED_OR_RETURNED, argMax(s.PARTNER_PRICE_FOR_DELIVERY, timestamp) AS PARTNER_PRICE_FOR_DELIVERY, argMax(s.BILLING_PRICE, timestamp) AS BILLING_PRICE, argMax(s.MARKETPLACE_SUBSIDY, timestamp) AS MARKETPLACE_SUBSIDY, argMax(s.OFFER_STATUS, timestamp) AS OFFER_STATUS, argMax(s.STATUS_CHANGED, timestamp) AS STATUS_CHANGED FROM yandex_orders_rows AS s WHERE toDate(s.CREATION_DATE) < today() GROUP BY ORDER_ID, SHOP_SKU, row_num), lm_dubles AS (SELECT item_id, toYear(today()), s.createdAt FROM `zendendb`.LAMODA_Sales_TM AS s WHERE (toYear(s.createdAt) = toYear(today())) AND (item_id IN (SELECT item_id FROM `zendendb`.LAMODA_Sales_TM WHERE toYear(createdAt) < toYear(today())))), lm_sale AS (SELECT orderNr, createdAt, item_id, argMax(m.art, o.updatedAt) AS art, argMax(m.art_mp, o.updatedAt) AS art_mp, argMax(m.kdo, o.updatedAt) AS kdo, argMax(o.status, o.updatedAt) AS status, argMax(o.sku, o.updatedAt) AS sku, argMax(if(o.currency = 'kzt', o.partnerAgreedPrice * (c.Value / c.Nominal), o.partnerAgreedPrice), o.updatedAt) AS partnerAgreedPrice, argMax(if(o.currency = 'kzt', o.paidPrice * (c.Value / c.Nominal), o.paidPrice), o.updatedAt) AS paidPrice, argMax(o.currency, o.updatedAt) AS currency FROM `zendendb`.LAMODA_Sales_TM AS o FINAL LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = toString(o.sku)) AND (m.mp = 'Ламода') LEFT JOIN `zendendb`.currency_rate AS c ON (c.Date = o.createdAt) AND (c.CharCode = 'KZT') WHERE (source IS NULL) AND (toDate(o.createdAt) < today()) AND (((item_id NOT IN (SELECT item_id FROM lm_dubles)) AND (toYear(o.createdAt) = toYear(today()))) OR (toYear(o.createdAt) != toYear(today()))) GROUP BY orderNr, createdAt, item_id) SELECT toDate(o.date) AS dt, 'Вайлдберриз' AS mp, m.art AS art, m.kdo AS kdo, o.isCancel AS iscancel, toInt32(countDistinct(o.srid)) AS order_qty, sum(if((o.totalPrice = 0) AND (o.priceWithDisc != 0), toDecimal64(o.priceWithDisc, 2), toDecimal64(o.totalPrice * (1 - (o.discountPercent * 0.01)), 2))) AS order_rub, toDecimal64(sum(o.finishedPrice), 2) AS order_rub_spp FROM `zendendb`.WB_FBO_Orders_TM AS o FINAL ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = o.supplierArticle) AND (m.mp = 'Вайлдберриз') WHERE o.date < today() GROUP BY dt, mp, art, kdo, iscancel UNION ALL WITH yandex_orders_rows AS (SELECT x.*, rank() OVER (PARTITION BY ORDER_ID, SHOP_SKU, toDate(timestamp) ORDER BY OFFER_STATUS ASC) AS row_num FROM `zendendb`.YANDEX_Orders_TM AS x FINAL), agg_orders AS (SELECT ORDER_ID, SHOP_SKU, argMax(s.CREATION_DATE, timestamp) AS CREATION_DATE, argMax(s.DELIVERED_OR_RETURNED, timestamp) AS DELIVERED_OR_RETURNED, argMax(s.PARTNER_PRICE_FOR_DELIVERY, timestamp) AS PARTNER_PRICE_FOR_DELIVERY, argMax(s.BILLING_PRICE, timestamp) AS BILLING_PRICE, argMax(s.MARKETPLACE_SUBSIDY, timestamp) AS MARKETPLACE_SUBSIDY, argMax(s.OFFER_STATUS, timestamp) AS OFFER_STATUS, argMax(s.STATUS_CHANGED, timestamp) AS STATUS_CHANGED