num FROM `zendendb`.YANDEX_Orders_TM AS x FINAL), agg_orders AS (SELECT ORDER_ID, SHOP_SKU, argMax(s.CREATION_DATE, timestamp) AS CREATION_DATE, argMax(s.DELIVERED_OR_RETURNED, timestamp) AS DELIVERED_OR_RETURNED, argMax(s.PARTNER_PRICE_FOR_DELIVERY, timestamp) AS PARTNER_PRICE_FOR_DELIVERY, argMax(s.BILLING_PRICE, timestamp) AS BILLING_PRICE, argMax(s.MARKETPLACE_SUBSIDY, timestamp) AS MARKETPLACE_SUBSIDY, argMax(s.OFFER_STATUS, timestamp) AS OFFER_STATUS, argMax(s.STATUS_CHANGED, timestamp) AS STATUS_CHANGED FROM yandex_orders_rows AS s WHERE toDate(s.CREATION_DATE) < today() GROUP BY ORDER_ID, SHOP_SKU, row_num), lm_dubles AS (SELECT item_id, toYear(today()), s.createdAt FROM `zendendb`.LAMODA_Sales_TM AS s WHERE (toYear(s.createdAt) = toYear(today())) AND (item_id IN (SELECT item_id FROM `zendendb`.LAMODA_Sales_TM WHERE toYear(createdAt) < toYear(today())))), lm_sale AS (SELECT orderNr, createdAt, item_id, argMax(m.art, o.updatedAt) AS art, argMax(m.art_mp, o.updatedAt) AS art_mp, argMax(m.kdo, o.updatedAt) AS kdo, argMax(o.status, o.updatedAt) AS status, argMax(o.sku, o.updatedAt) AS sku, argMax(if(o.currency = 'kzt', o.partnerAgreedPrice * (c.Value / c.Nominal), o.partnerAgreedPrice), o.updatedAt) AS partnerAgreedPrice, argMax(if(o.currency = 'kzt', o.paidPrice * (c.Value / c.Nominal), o.paidPrice), o.updatedAt) AS paidPrice, argMax(o.currency, o.updatedAt) AS currency FROM `zendendb`.LAMODA_Sales_TM AS o FINAL LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = toString(o.sku)) AND (m.mp = 'Ламода') LEFT JOIN `zendendb`.currency_rate AS c ON (c.Date = o.createdAt) AND (c.CharCode = 'KZT') WHERE (source IS NULL) AND (toDate(o.createdAt) < today()) AND (((item_id NOT IN (SELECT item_id FROM lm_dubles)) AND (toYear(o.createdAt) = toYear(today()))) OR (toYear(o.createdAt) != toYear(today()))) GROUP BY orderNr, createdAt, item_id) SELECT toDate(o.createdAt) AS dt, 'Ламода' AS mp, m.art AS art, m.kdo AS kdo, o.status IN ('Returned', 'Canceled', 'Not bought')