, o.updatedAt) AS paidPrice, argMax(o.`fullSum.currency`, o.updatedAt) AS currency FROM `zendendb`.LAMODA_Sales_TM AS o LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = toString(o.items_externalSku)) AND (m.mp = 'Ламода') LEFT JOIN `zendendb`.currency_rate AS c ON (c.Date = o.createdAt) AND (c.CharCode = 'KZT') LEFT JOIN lm_dubles AS db ON db.items_id = o.items_id WHERE ((source IS NULL) OR (source = '')) AND ((toDate(o.createdAt) >= {start_date:date}) AND (toDate(o.createdAt) <= {end_date:date})) AND ((db.min_date = toDate(o.createdAt)) OR (db.min_date IS NULL)) GROUP BY orderId, createdAt, o.items_id), wb_orders AS (SELECT toDate(o.date) AS dt, o.nmId AS nmId, toInt32(countDistinct(o.srid)) AS order_qty, toInt32(countIfDistinct(o.srid, o.isCancel)) AS order_qty_cancelled, sum(if((o.totalPrice = 0) AND (o.priceWithDisc != 0), toDecimal64(o.priceWithDisc, 2), toDecimal64(o.totalPrice * (1 - (o.discountPercent * 0.01)), 2))) AS order_rub, toDecimal64(sum(o.finishedPrice), 2) AS order_rub_spp FROM `zendendb`.WB_FBO_Orders_TM AS o FINAL WHERE (toDate(o.date) >= {start_date:date}) AND (toDate(o.date) <= {end_date:date}) GROUP BY dt, nmId), wb_last_spp AS (SELECT toDate(o.date) AS dt, o.nmId AS nmId, toDecimal64(avg(o.finishedPrice), 2) AS order_rub_spp FROM `zendendb`.WB_FBO_Orders_TM AS o FINAL WHERE (o.date < today()) AND (o.date >= '2025-01-01') GROUP BY dt, nmId ORDER BY nmId ASC, dt ASC WITH FILL TO today() STEP toIntervalDay(1) INTERPOLATE (`order_rub_spp` AS order_rub_spp)) SELECT toDate(o.`Принят в обработку`) AS dt, 'Озон' AS mp, m.art AS art, m.kdo AS kdo, replaceAll(splitByChar('_', o.`Артикул`)[2], ',', '.') AS size, toInt32(sum(o.`Количество`)) AS order_qty, toInt32(sumIf(o.`Количество`, o.`Статус` = 'Отменён')) AS order_qty_cancelled, toDecimal64(sum(o.`Ваша цена`), 3) AS order_rub, toDecimal64(sumIf(o.`Ваша цена`, o.`Статус` = 'Отменён'), 3) AS order_rub_cancelled, toDecimal64(sum(o.`Оплачено покупателем`), 3) AS order_rub_spp, toDecimal64(sumIf(o.`Оплачено покупателем`, o.`Статус` = 'Отменён'), 3) AS order_rub_spp_cancelled FROM `zendendb`.OZON_Orders_TM AS o ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = o.`Артикул`) AND (m.mp = 'Озон') WHERE (toDate(o.`Принят в обработку`) >= {start_date:date}) AND (toDate(o.`Принят в обработку`) <= {end_date:date}) GROUP BY dt, mp, art, kdo, size UNION ALL WITH yandex_orders_rows AS (SELECT x.*, rank() OVER (PARTITION BY ORDER_ID, SHOP_SKU, toDate(timestamp) ORDER BY OFFER_STATUS ASC) AS row_num FROM `zendendb`.YANDEX_Orders_TM AS x FINAL), agg_orders AS (SELECT ORDER_ID, SHOP_SKU, argMax(s.CREATION_DATE, timestamp) AS CREATION_DATE, argMax(s.DELIVERED_OR_RETURNED, timestamp) AS DELIVERED_OR_RETURNED, argMax(s.PARTNER_PRICE_FOR_DELIVERY, timestamp) AS PARTNER_PRICE_FOR_DELIVERY, argMax(s.BILLING_PRICE, timestamp) AS BILLING_PRICE, argMax(s.MARKETPLACE_SUBSIDY, timestamp) AS MARKETPLACE_SUBSIDY, argMax(s.OFFER_STATUS, timestamp) AS OFFER_STATUS, argMax(s.STATUS_CHANGED, timestamp) AS STATUS_CHANGED FROM yandex_orders_rows AS s WHERE (toDate(s.CREATION_DATE) >= {start_date:date}) AND (toDate(s.CREATION_DATE) <= {end_date:date}) GROUP BY ORDER_ID, SHOP_SKU, row_num), lm_dubles AS (SELECT items_id, min(s.createdAt) AS min_date, max(s.createdAt) AS max_date FROM `zendendb`.LAMODA_Sales_TM AS s FINAL GROUP BY items_id HAVING min_date != max_date), lm_sale AS (SELECT orderId, createdAt, o.items_id AS item_id, argMax(m.art, o.updatedAt) AS art, argMax(m.art_mp, o.updatedAt) AS art_mp, argMax(m.kdo, o.updatedAt) AS kdo, argMax(o.status, o.updatedAt) AS status, argMax(o.items_externalSku, o.updatedAt) AS sku, argMax(o.items_size, o.updatedAt) AS size, argMax(if(o.items_sellerAgreedPrice_currency = 'kzt', o.items_sellerAgreedPrice_amount * (c.Value / c.Nominal), o.items_sellerAgreedPrice_amount), o.updatedAt) AS partnerAgreedPrice, argMax(if(o.items_paidPrice_currency = 'kzt', o.items_paidPrice_amount * (c.Value / c.Nominal), o.items_paidPrice_amount), o.updatedAt) AS paidPrice, argMax(o.`fullSum.currency`, o.updatedAt) AS currency FROM `zendendb`.LAMODA_Sales_TM AS o LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = toString(o.items_externalSku)) AND (m.mp = 'Ламода') LEFT JOIN `zendendb`.currency_rate AS c ON (c.Date = o.createdAt) AND (c.CharCode = 'KZT') LEFT JOIN lm_dubles AS db ON db.items_id = o.items_id WHERE ((source IS NULL) OR (source = '')) AND ((toDate(o.createdAt) >= {start_date:date}) AND (toDate(o.createdAt) <= {end_date:date})) AND ((db.min_date = toDate(o.createdAt)) OR (db.min_date IS NULL)) GROUP BY orderId, createdAt, o.items_id), wb_orders AS (SELECT toDate(o.date) AS dt, o.nmId AS nmId, toInt32(countDistinct(o.srid)) AS order_qty, toInt32(countIfDistinct(o.srid, o.isCancel)) AS order_qty_cancelled, sum(if((o.totalPrice = 0) AND (o.priceWithDisc != 0), toDecimal64(o.priceWithDisc, 2), toDecimal64(o.totalPrice * (1 - (o.discountPercent * 0.01)), 2))) AS order_rub, toDecimal64(sum(o.finishedPrice), 2) AS order_rub_spp FROM `zendendb`.WB_FBO_Orders_TM AS o FINAL WHERE (toDate(o.date) >= {start_date:date}) AND (toDate(o.date) <= {end_date:date}) GROUP BY dt, nmId), wb_last_spp AS (SELECT toDate(o.date) AS dt, o.nmId AS nmId, toDecimal64(avg(o.finishedPrice), 2) AS order_rub_spp FROM `zendendb`.WB_FBO_Orders_TM AS o FINAL WHERE (o.date < today()) AND (o.date >= '2025-01-01') GROUP BY dt, nmId ORDER BY nmId ASC, dt ASC WITH FILL TO today() STEP toIntervalDay(1) INTERPOLATE (`order_rub_spp` AS order_rub_spp)) SELECT toDate(o.createdAt) AS dt, 'Ламода' AS mp, m.art AS art, m.kdo AS kdo, o.size, toInt32(countDistinct(o.item_id)) AS order_qty, toInt32(countIfDistinct(o.item_id, (lower(o.status) IN ('returned', 'canceled', 'not bought')))) AS order_qty_cancelled, toDecimal64(sum(o.partnerAgreedPrice), 3) AS order_rub, toDecimal64(sumIf(o.partnerAgreedPrice, (lower(o.status) IN ('returned', 'canceled', 'not bought'))), 3) AS order_rub_cancelled, toDecimal64(sum(o.paidPrice), 3) AS order_rub_spp, toDecimal64(sumIf(o.paidPrice, (lower(o.status) IN ('returned', 'canceled', 'not bought'))), 3) AS order_rub_spp_cancelled FROM lm_sale AS o ANY LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = toString(o.sku)) AND (m.mp = 'Ламода') WHERE (toDate(o.createdAt) >= {start_date:date}) AND (toDate(o.createdAt) <= {end_date:date}) GROUP BY dt, mp, art, kdo, size ORDER BY dt DESC, kdo DESC SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`ozon_art_mapping2_v` (`mp` String, `art_mp` String, `art` Nullable(String), `kdo` Nullable(UInt32), `art_in_mp` UInt32, `art_link` String) AS WITH ozon_art AS (SELECT DISTINCT o.`Артикул` AS art_mp, toUInt32(max(o.`OZON id`)) AS art_in_mp, max(multiIf(((splitByChar('_', o.`Артикул`)[1]) IN ('Elegance', 'Nuance')), arrayStringConcat(arraySlice(splitByChar('_', o.`Артикул`), 1, -1), '_'), (splitByChar('_', o.`Артикул`)[1]) = '073-002E-2121', '81-01MV-023TT', ((splitByChar('_', o.`Артикул`)[1]) IN ('SC', 'KN')), arrayStringConcat(arraySlice(splitByChar('_', o.`Артикул`), 1, -1), '_'), o.`Артикул` = '126-599A-10', '126-599A-10610', splitByChar('_', o.`Артикул`)[1])) AS art FROM `zendendb`.OZON_Orders_TM AS o WHERE (o.`Артикул` != '') AND (o.`OZON id` NOT IN (SELECT DISTINCT SKU FROM `zendendb`.OZON_Products_TM AS o)) GROUP BY art_mp) SELECT 'Озон' AS mp, toString(a.art_mp) AS art_mp, a.art AS art, t.`КодДляОбмена` AS kdo, ifNull(p.SKU, a.art_in_mp) AS art_in_mp, concat('https://ozon.ru/product/', ifNull(p.SKU, a.art_in_mp)) AS art_link FROM ozon_art AS a ANY LEFT JOIN `zendendb`.`Товары` AS t ON t.`Артикул` = a.art ANY LEFT JOIN `zendendb`.OZON_Products_TM AS p ON a.art_in_mp = p.`Ozon Product ID` UNION DISTINCT WITH ozon_art AS (SELECT DISTINCT o.`Артикул` AS art_mp, toUInt32(max(o.`OZON id`)) AS art_in_mp, max(multiIf(((splitByChar('_', o.`Артикул`)[1]) IN ('Elegance', 'Nuance')), arrayStringConcat(arraySlice(splitByChar('_', o.`Артикул`), 1, -1), '_'), (splitByChar('_', o.`Артикул`)[1]) = '073-002E-2121', '81-01MV-023TT', ((splitByChar('_', o.`Артикул`)[1]) IN ('SC', 'KN')), arrayStringConcat(arraySlice(splitByChar('_', o.`Артикул`), 1, -1), '_'), o.`Артикул` = '126-599A-10', '126-599A-10610', splitByChar('_', o.`Артикул`)[1])) AS art FROM `zendendb`.OZON_Orders_TM AS o WHERE (o.`Артикул` != '') AND (o.`OZON id` NOT IN (SELECT DISTINCT SKU FROM `zendendb`.OZON_Products_TM AS o)) GROUP BY art_mp) SELECT 'Озон' AS mp, toString(p.`Ozon Product ID`) AS art_mp, t.`Артикул` AS art, t.`КодДляОбмена` AS kdo, p.SKU AS art_in_mp, concat('https://ozon.ru/product/', p.SKU) AS art_link FROM `zendendb`.OZON_Products_TM AS p ANY LEFT JOIN `zendendb`.`Товары` AS t ON t.`Артикул` = multiIf(((splitByChar('_', p.`Артикул`)[1]) IN ('Elegance', 'Nuance')), arrayStringConcat(arraySlice(splitByChar('_', p.`Артикул`), 1, -1), '_'), (splitByChar('_', p.`Артикул`)[1]) = '073-002E-2121', '81-01MV-023TT', ((splitByChar('_', p.`Артикул`)[1]) IN ('SC', 'KN')), arrayStringConcat(arraySlice(splitByChar('_', p.`Артикул`), 1, -1), '_'), p.`Артикул` = '126-599A-10', '126-599A-10610', splitByChar('_', p.`Артикул`)[1]) SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`ozon_art_mapping_v` (`mp` String, `art_mp` String, `art` Nullable(String), `kdo` Nullable(UInt32), `art_in_mp` UInt64, `art_link` String) AS WITH ozon_art AS (SELECT DISTINCT o.`Артикул` AS art_mp, toUInt32(max(o.`OZON id`)) AS art_in_mp, max(multiIf(((splitByChar('_', o.`Артикул`)[1]) IN ('Elegance', 'Nuance')), arrayStringConcat(arraySlice(splitByChar('_', o.`Артикул`), 1, -1), '_'), (splitByChar('_', o.`Артикул`)[1]) = '073-002E-2121', '81-01MV-023TT', ((splitByChar('_', o.`Артикул`)[1]) IN ('SC', 'KN')), arrayStringConcat(arraySlice(splitByChar('_', o.`Артикул`), 1, -1), '_'), o.`Артикул` = '126-599A-10', '126-599A-10610', splitByChar('_', o.`Артикул`)[1])) AS art FROM `zendendb`.OZON_Orders_TM AS o WHERE (o.`Артикул` != '') AND (o.`Артикул` NOT IN (SELECT DISTINCT `Артикул` FROM `zendendb`.OZON_Products_TM WHERE SKU != 0)) AND (o.`Принят в обработку` > (today() - toIntervalYear(1))) GROUP BY art_mp) SELECT 'Озон' AS mp, toString(a.art_mp) AS art_mp, a.art AS art, t.`КодДляОбмена` AS kdo, a.art_in_mp AS art_in_mp, concat('https://ozon.ru/product/', a.art_in_mp) AS art_link FROM ozon_art AS a ANY LEFT JOIN `zendendb`.`Товары` AS t ON t.`Артикул` = a.art UNION DISTINCT WITH ozon_art AS (SELECT DISTINCT o.`Артикул` AS art_mp, toUInt32(max(o.`OZON id`)) AS art_in_mp, max(multiIf(((splitByChar('_', o.`Артикул`)[1]) IN ('Elegance', 'Nuance')), arrayStringConcat(arraySlice(splitByChar('_', o.`Артикул`), 1, -1), '_'), (splitByChar('_', o.`Артикул`)[1]) = '073-002E-2121', '81-01MV-023TT', ((splitByChar('_', o.`Артикул`)[1]) IN ('SC', 'KN')), arrayStringConcat(arraySlice(splitByChar('_', o.`Артикул`), 1, -1), '_'), o.`Артикул` = '126-599A-10', '126-599A-10610', splitByChar('_', o.`Артикул`)[1])) AS art FROM `zendendb`.OZON_Orders_TM AS o WHERE (o.`Артикул` != '') AND (o.`Артикул` NOT IN (SELECT DISTINCT `Артикул` FROM `zendendb`.OZON_Products_TM WHERE SKU != 0)) AND (o.`Принят в обработку` > (today() - toIntervalYear(1))) GROUP BY art_mp) SELECT 'Озон' AS mp, toString(p.`Артикул`) AS art_mp, t.`Артикул` AS art, t.`КодДляОбмена` AS kdo, p.SKU AS art_in_mp, concat('https://ozon.ru/product/', p.SKU) AS art_link FROM `zendendb`.OZON_Products_TM AS p ANY LEFT JOIN `zendendb`.`Товары` AS t ON t.`Артикул` = multiIf(((splitByChar('_', p.`Артикул`)[1]) IN ('Elegance', 'Nuance')), arrayStringConcat(arraySlice(splitByChar('_', p.`Артикул`), 1, -1), '_'), (splitByChar('_', p.`Артикул`)[1]) = '073-002E-2121', '81-01MV-023TT', ((splitByChar('_', p.`Артикул`)[1]) IN ('SC', 'KN')), arrayStringConcat(arraySlice(splitByChar('_', p.`Артикул`), 1, -1), '_'), p.`Артикул` = '126-599A-10', '126-599A-10610', splitByChar('_', p.`Артикул`)[1]) SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`portal_sale_order_v` (`DATE_ORDER` Nullable(Date), `SHOP_NAME` Nullable(String), `ID_COUNT` Nullable(UInt64), `PRICE_SUM` Nullable(Decimal(38, 3)), `DISCOUNT_VALUE_SUM` Nullable(Decimal(38, 3)), `TAX_VALUE_SUM` Nullable(Decimal(38, 3)), `SUM_PAID_SUM` Nullable(Decimal(38, 3)), `ID_COUNT_DONE` Nullable(UInt64), `PRICE_SUM_DONE` Nullable(Decimal(38, 3)), `DISCOUNT_VALUE_SUM_DONE` Nullable(Decimal(38, 3)), `TAX_VALUE_SUM_DONE` Nullable(Decimal(38, 3)), `SUM_PAID_SUM_DONE` Nullable(Decimal(38, 3))) AS WITH new_orders AS (SELECT toDate(DATE_INSERT) AS DATE_ORDER, SHOP_NAME, COUNTDistinct(ID) AS ID_COUNT, sum(PRICE) AS PRICE_SUM, sum(DISCOUNT_VALUE) AS DISCOUNT_VALUE_SUM, sum(TAX_VALUE) AS TAX_VALUE_SUM, sum(SUM_PAID) AS SUM_PAID_SUM FROM `zendendb`.`ЗаказКлиента` FINAL GROUP BY toDate(DATE_INSERT), SHOP_NAME), done_orders AS (SELECT toDate(DATE_STATUS) AS DATE_ORDER_DONE, SHOP_NAME AS SHOP_NAME_DONE, COUNTDistinct(ID) AS ID_COUNT_DONE, sum(PRICE) AS PRICE_SUM_DONE, sum(DISCOUNT_VALUE) AS DISCOUNT_VALUE_SUM_DONE, sum(TAX_VALUE) AS TAX_VALUE_SUM_DONE, sum(SUM_PAID) AS SUM_PAID_SUM_DONE FROM `zendendb`.`ЗаказКлиента` FINAL WHERE STATUS = 'Выполнен' GROUP BY toDate(DATE_STATUS), SHOP_NAME) SELECT ifNull(DATE_ORDER, DATE_ORDER_DONE) AS DATE_ORDER, ifNull(SHOP_NAME, SHOP_NAME_DONE) AS SHOP_NAME, ID_COUNT, PRICE_SUM, DISCOUNT_VALUE_SUM, TAX_VALUE_SUM, SUM_PAID_SUM, ID_COUNT_DONE, PRICE_SUM_DONE, DISCOUNT_VALUE_SUM_DONE, TAX_VALUE_SUM_DONE, SUM_PAID_SUM_DONE FROM new_orders AS nor FULL OUTER JOIN done_orders AS dor ON (nor.DATE_ORDER = dor.DATE_ORDER_DONE) AND (nor.SHOP_NAME = dor.SHOP_NAME_DONE) SETTINGS join_use_nulls = 1;

CREATE VIEW `zendendb`.`positions_employees_by_date_v` AS WITH kadri AS (SELECT k.`ДатаНачала` AS start_date, k.`ДатаОкончания` AS and_date, k.`Сотрудник` AS staff, k.`Должность` AS position, k.`ВидСобытия` AS event FROM `zendendb`.`КадроваяИсторияСотрудников` AS k WHERE (`ДатаНачала` > '2000-01-01') AND (k.`ДатаОкончания` >= {end_date:date}) ORDER BY k.`Сотрудник` ASC, `ДатаНачала` ASC WITH FILL TO toDateTime64(today(), 0) STEP toIntervalDay(1) INTERPOLATE (`and_date` AS and_date, `position` AS position, `event` AS event)) SELECT toDate(k.start_date) AS `Дата`, toDate(k.and_date) AS `ДатаОкончания`, k.staff AS `Сотрудник`, k.position AS `Должность`, k.event AS `ВидСобытия` FROM kadri AS k WHERE event != 'Увольнение' UNION ALL WITH kadri AS (SELECT k.`ДатаНачала` AS start_date, k.`ДатаОкончания` AS and_date, k.`Сотрудник` AS staff, k.`Должность` AS position, k.`ВидСобытия` AS event FROM `zendendb`.`КадроваяИсторияСотрудников` AS k WHERE (`ДатаНачала` > '2000-01-01') AND (k.`ДатаОкончания` >= {end_date:date}) ORDER BY k.`Сотрудник` ASC, `ДатаНачала` ASC WITH FILL TO toDateTime64(today(), 0) STEP toIntervalDay(1) INTERPOLATE (`and_date` AS and_date, `position` AS position, `event` AS event)) SELECT toDate(k.`ДатаНачала`) AS `Дата`, toDate(k.`ДатаОкончания`) AS `ДатаОкончания`, k.`Сотрудник` AS `Сотрудник`, k.`Должность` AS `Должность`, k.`ВидСобытия` AS `ВидСобытия` FROM `zendendb`.`КадроваяИсторияСотрудников` AS k WHERE (k.`ВидСобытия` = 'Увольнение') AND (k.`ДатаОкончания` >= {end_date:date});

CREATE VIEW `zendendb`.`prices_TM_MP_fill_v` (`dt` Date, `mp` LowCardinality(String), `kdo` UInt32, `art` Nullable(String), `cur_pr` Nullable(Decimal(10, 3)), `init_pr` Nullable(Decimal(10, 3)), `customer_price` Nullable(Decimal(10, 3)), `is_real` UInt8) AS WITH price_fill AS (SELECT *, 1 AS is_real FROM (SELECT dt, mp, kdo, art, cur_pr, init_pr, customer_price FROM `zendendb`.prices_TM_MP WHERE is_real = 1) WHERE (dt >= (today() - 30)) AND (dt <= today()) ORDER BY mp ASC, kdo ASC, art ASC, dt ASC WITH FILL TO today() STEP toIntervalDay(1) INTERPOLATE (`cur_pr` AS cur_pr, `init_pr` AS init_pr, `customer_price` AS customer_price)) SELECT * FROM price_fill WHERE is_real = 0;

CREATE VIEW `zendendb`.`prices_TM_MP_v` AS WITH order_price_by_day AS (SELECT toDate(date) AS dt, nmId, avg(finishedPrice) AS finished_price FROM `zendendb`.WB_FBO_Orders_TM AS o WHERE (toDate(date) >= ({start_date:date} - 14)) AND (toDate(date) <= {end_date:date}) GROUP BY dt, nmId), order_price AS (SELECT * FROM order_price_by_day ORDER BY nmId ASC, dt ASC WITH FILL FROM {start_date:date} - 14 TO {end_date:date} + 1 STEP toIntervalDay(1) INTERPOLATE (`finished_price` AS finished_price)) SELECT p.date AS dt, 'Вайлдберриз' AS mp, m.kdo AS kdo, max(m.art) AS art, avg(p.price - ((p.price * p.discount) / 100)) AS cur_pr, avg(price) AS init_pr, if(avg(op.finished_price) > avg(p.price - ((p.price * p.discount) / 100)), NULL, avg(op.finished_price)) AS customer_price, 1 AS is_real FROM `zendendb`.WB_Prices_TM AS p LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = p.vendorcode) AND (m.mp = 'Вайлдберриз') LEFT JOIN order_price AS op ON (op.nmId = p.nmid) AND (op.dt = p.date) WHERE (dt >= {start_date:date}) AND (dt <= {end_date:date}) GROUP BY dt, kdo UNION ALL WITH order_price_by_day AS (SELECT toDate(date) AS dt, nmId, avg(finishedPrice) AS finished_price FROM `zendendb`.WB_FBO_Orders_TM AS o WHERE (toDate(date) >= ({start_date:date} - 14)) AND (toDate(date) <= {end_date:date}) GROUP BY dt, nmId), order_price AS (SELECT * FROM order_price_by_day ORDER BY nmId ASC, dt ASC WITH FILL FROM {start_date:date} - 14 TO {end_date:date} + 1 STEP toIntervalDay(1) INTERPOLATE (`finished_price` AS finished_price)) SELECT p.date AS dt, 'Озон' AS mp, m.kdo AS kdo, max(m.art) AS art, avg(p.price) AS cur_pr, avg(p.old_price) AS init_pr, avg(dp.customer_price) AS customer_price, 1 AS is_real FROM `zendendb`.OZON_Prices_TM AS p LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = p.offer_id) AND (m.mp = 'Озон') LEFT JOIN `zendendb`.OZON_Prices_details_TM AS dp ON (toString(dp.sku) = m.art_in_mp) AND (dp.date = p.date) WHERE (p.date >= {start_date:date}) AND (p.date <= {end_date:date}) GROUP BY dt, kdo UNION ALL WITH order_price_by_day AS (SELECT toDate(date) AS dt, nmId, avg(finishedPrice) AS finished_price FROM `zendendb`.WB_FBO_Orders_TM AS o WHERE (toDate(date) >= ({start_date:date} - 14)) AND (toDate(date) <= {end_date:date}) GROUP BY dt, nmId), order_price AS (SELECT * FROM order_price_by_day ORDER BY nmId ASC, dt ASC WITH FILL FROM {start_date:date} - 14 TO {end_date:date} + 1 STEP toIntervalDay(1) INTERPOLATE (`finished_price` AS finished_price)) SELECT toDate(p.timestamp) AS dt, 'Яндекс' AS mp, m.kdo AS kdo, max(m.art) AS art, avg(p.price_value) AS cur_pr, if(avg(p.price_discountbase) != 0, avg(p.price_discountbase), avg(p.price_value)) AS init_pr, NULL AS customer_price, 1 AS is_real FROM `zendendb`.YANDEX_Price_TM AS p LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = p.offerid) AND (m.mp = 'Яндекс') WHERE (toDate(p.timestamp) >= {start_date:date}) AND (toDate(p.timestamp) <= {end_date:date}) GROUP BY dt, kdo UNION ALL WITH order_price_by_day AS (SELECT toDate(date) AS dt, nmId, avg(finishedPrice) AS finished_price FROM `zendendb`.WB_FBO_Orders_TM AS o WHERE (toDate(date) >= ({start_date:date} - 14)) AND (toDate(date) <= {end_date:date}) GROUP BY dt, nmId), order_price AS (SELECT * FROM order_price_by_day ORDER BY nmId ASC, dt ASC WITH FILL FROM {start_date:date} - 14 TO {end_date:date} + 1 STEP toIntervalDay(1) INTERPOLATE (`finished_price` AS finished_price)) SELECT toDate(p.timestamp) AS dt, 'Ламода' AS mp, m.kdo AS kdo, max(m.art) AS art, avg(if(p.saleprice = 0, NULL, saleprice)) AS cur_pr, avg(if(p.price = 0, NULL, p.price)) AS init_pr, NULL AS customer_price, 1 AS is_real FROM `zendendb`.LAMODA_Prices_TM AS p LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.art_mp = p.sku) AND (m.mp = 'Ламода') WHERE (toDate(p.timestamp) >= {start_date:date}) AND (toDate(p.timestamp) <= {end_date:date}) AND (countriesenabled != 'KZ') GROUP BY dt, kdo SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`prices_TM_MP_with_filter_v` (`Дата` Date, `МП` LowCardinality(String), `КДО` UInt32, `Артикул` Nullable(String), `Цена со скидкой` Nullable(Decimal(10, 3)), `Цена начальная` Nullable(Decimal(10, 3)), `Цена для покупателя` Nullable(Decimal(10, 3)), `Скидка` Decimal(18, 3), `Скидка МП` Nullable(Decimal(18, 3)), `is_filter` Bool, `art_link` Nullable(String), `Артикул МП` Nullable(String), `СвойствоВидОбуви` Nullable(String), `СвойствоГод` Nullable(String), `СвойствоМатериалВерха` Nullable(String), `СвойствоРод` Nullable(String), `СвойствоСезон` Nullable(String), `СвойствоТорговаяМарка` Nullable(String), `ТипНоменклатуры` Nullable(String), `СтавкаНДС` Nullable(String), `OrderTM` Nullable(String), `СвойствоКоллекцияПроизводства` Nullable(String), `СвойствоКоллекцияПроизводстваКомментарий` Nullable(String), `ПовторАналогНовинка` Nullable(String), `Проект` String, `Когорта` Nullable(UInt8), `Когорта МП` Nullable(UInt8)) AS WITH prices AS (SELECT p.dt AS `Дата`, p.mp AS `МП`, p.kdo AS `КДО`, p.art AS `Артикул`, p.cur_pr AS `Цена со скидкой`, p.init_pr AS `Цена начальная`, p.customer_price AS `Цена для покупателя`, if(p.cur_pr = 0, 0, 100 - (coalesce(p.cur_pr / nullIf(p.init_pr, 0), 1) * 100)) AS `Скидка`, 100 - (coalesce(p.customer_price / nullIf(p.cur_pr, 0), NULL) * 100) AS `Скидка МП`, if(f.art IS NULL, false, true) AS is_filter, m.art_link AS art_link, m.art_in_mp AS `Артикул МП`, g.`СвойствоВидОбуви` AS `СвойствоВидОбуви`, g.`СвойствоГод` AS `СвойствоГод`, g.`СвойствоМатериалВерха` AS `СвойствоМатериалВерха`, g.`СвойствоРод` AS `СвойствоРод`, g.`СвойствоСезон` AS `СвойствоСезон`, g.`СвойствоТорговаяМарка` AS `СвойствоТорговаяМарка`, g.`ТипНоменклатуры` AS `ТипНоменклатуры`, g.`СтавкаНДС` AS `СтавкаНДС`, g.OrderTM AS OrderTM, g.`СвойствоКоллекцияПроизводства` AS `СвойствоКоллекцияПроизводства`, g.`СвойствоКоллекцияПроизводстваКомментарий` AS `СвойствоКоллекцияПроизводстваКомментарий`, g.`ПовторАналогНовинка` AS `ПовторАналогНовинка`, multiIf((g.`СвойствоТорговаяМарка` IN ('ARA', 'Bugatti', 'KINETIX', 'LUMBERJACK', 'POLARIS', 'Reebok', 'REMONTE', 'Rieker', 'U.S. POLO ASSN.')), 'ПТМ', (g.`СвойствоТорговаяМарка` IN ('Bridget', 'BRIGGS', 'LOLLI|POLLI', 'MUNZ Shoes', 'MUNZ YOUNG', 'O2')), 'СТМ', (g.`СвойствоТорговаяМарка` IN ('LURCHI', 'M-Shoes', 'SALAMANDER')), 'Salamander', (g.`СвойствоТорговаяМарка` IN ('Thomas Munz', 'Thomas Munz black')), 'Thomas Munz', '') AS `Проект` FROM `zendendb`.prices_TM_MP AS p LEFT JOIN `zendendb`.prices_TM_MP_filter AS f ON p.art = f.art LEFT JOIN `zendendb`.`ТоварыУПП` AS g ON g.`КодДляОбмена` = p.kdo LEFT JOIN `zendendb`.TM_MP_art_mapping AS m ON (m.kdo = p.kdo) AND (m.mp = p.mp) WHERE `КДО` != 0) SELECT p.*, multiIf(abs(`Скидка`) IS NULL, NULL, abs(`Скидка`) = 0, 0, (abs(`Скидка`) > 0) AND (abs(`Скидка`) <= 15), 10, (abs(`Скидка`) > 15) AND (abs(`Скидка`) <= 25), 20, (abs(`Скидка`) > 25) AND (abs(`Скидка`) <= 35), 30, (abs(`Скидка`) > 35) AND (abs(`Скидка`) <= 45), 40, (abs(`Скидка`) > 45) AND (abs(`Скидка`) <= 55), 50, (abs(`Скидка`) > 55) AND (abs(`Скидка`) <= 65), 60, (abs(`Скидка`) > 65) AND (abs(`Скидка`) <= 75), 70, (abs(`Скидка`) > 75) AND (abs(`Скидка`) <= 85), 80, abs(`Скидка`) > 85, 90, 100) AS `Когорта`, multiIf(abs(`Скидка МП`) IS NULL, NULL, abs(`Скидка МП`) = 0, 0, (abs(`Скидка МП`) > 0) AND (abs(`Скидка МП`) <= 15), 10, (abs(`Скидка МП`) > 15) AND (abs(`Скидка МП`) <= 25), 20, (abs(`Скидка МП`) > 25) AND (abs(`Скидка МП`) <= 35), 30, (abs(`Скидка МП`) > 35) AND (abs(`Скидка МП`) <= 45), 40, (abs(`Скидка МП`) > 45) AND (abs(`Скидка МП`) <= 55), 50, (abs(`Скидка МП`) > 55) AND (abs(`Скидка МП`) <= 65), 60, (abs(`Скидка МП`) > 65) AND (abs(`Скидка МП`) <= 75), 70, (abs(`Скидка МП`) > 75) AND (abs(`Скидка МП`) <= 85), 80, abs(`Скидка МП`) > 85, 90, 100) AS `Когорта МП` FROM prices AS p SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`query_log_search_v` AS SELECT toDateTime(ql.event_time, 'Europe/Moscow') AS event_time, type, ql.query, query_kind, ql.tables, user, http_user_agent, os_user, ql.event_time_microseconds, ql.databases, ql.current_database FROM system.query_log AS ql WHERE hasAny(ql.tables, [concat('zendendb.', {search_table:String}), concat('zendendb.`', {search_table:String}, '`')]);

CREATE VIEW `zendendb`.`sales_report_MAIN_MUNZ_GROUP_v` (`Период` Date, `Группа` LowCardinality(String), `Магазин Родитель` LowCardinality(String), `Регион` LowCardinality(String), `ТипМагазинаУПП` LowCardinality(String), `Магазин` String, `ТипНоменклатуры` LowCardinality(String), `Сезон` LowCardinality(String), `ЧекГуид` UUID, `Возврат` UInt8, `Реклама` UInt8, `Исключение` UInt8, `СтоимостьОборот` Int32, `СтоимостьБезСкидокОборот` Int32, `Скидка` Int16, `КоличествоОборот` Int16, `Вал` Decimal(10, 2), `Трафик` UInt32, `Трафик по группе` UInt32, `План Оборот` Int32, `План Трафик` UInt32, `План Вал` UInt32, `План Чеки` UInt32, `Выручка по группе` Int32, `Выручка вся` Int32) AS SELECT * FROM `zendendb`.sales_report_MAIN WHERE `Группа` = 'Munz Group';

CREATE VIEW `zendendb`.`sales_report_MAIN_all_by_day_v` (`Неделя` UInt8, `Период` Date, `Группа` Nullable(String), `Магазин Родитель` Nullable(String), `Регион` Nullable(String), `Город` Nullable(String), `ТипМагазинаУПП` Nullable(String), `МагазинГуид` LowCardinality(String), `Магазин` Nullable(String), `Выручка` Decimal(38, 4), `СтоимостьБезСкидок` Decimal(38, 4), `ВыручкаБезИсключений` Decimal(38, 4), `Себестоимость` Decimal(38, 4), `Вал` Decimal(38, 4), `Количество` Int64, `СкидкаСумма` Decimal(38, 4), `Трафик` Decimal(38, 4), `МимоХодящие` Decimal(38, 4), `Чеки покупок` UInt64, `Чеки возвратов` UInt64, `Продажи, шт` Int64, `Возвраты, шт` UInt64, `Возвраты в руб` Decimal(38, 4), `Пары` Int64, `Строк` UInt64, `План Оборот` Decimal(38, 4), `План Трафик` Decimal(38, 4), `План Вал` Decimal(38, 4), `План Чеки` Decimal(38, 4), `План Пары` Decimal(38, 4)) AS SELECT `Неделя`, `Период`, multiIf(`Группа` ILIKE '%Zenden%', 'Z', `Группа` ILIKE '%Mascotte%', 'R', `Группа`) AS `Группа`, multiIf(`Магазин Родитель` ILIKE '%Zenden%', 'Z', `Магазин Родитель` ILIKE '%Mascotte%', 'R', `Магазин Родитель`) AS `Магазин Родитель`, `Регион`, `Город`, `ТипМагазинаУПП`, `МагазинГуид`, `Магазин`, sum(`СтоимостьОборот`) AS `Выручка`, sum(`СтоимостьБезСкидокОборот`) AS `СтоимостьБезСкидок`, sumIf(`СтоимостьОборот`, `Исключение` = 0) AS `ВыручкаБезИсключений`, sum(`Себестоимость`) AS `Себестоимость`, sum(`Вал`) AS `Вал`, sum(`КоличествоОборот`) AS `Количество`, sum(`Скидка`) AS `СкидкаСумма`, sum(`Трафик`) AS `Трафик`, sum(`МимоХодящие`) AS `МимоХодящие`, countIfDistinct(`ЧекГуид`, `Возврат` = 0) AS `Чеки покупок`, countIfDistinct(`ЧекГуид`, `Возврат` = 1) AS `Чеки возвратов`, sumIf(`КоличествоОборот`, `Реклама` = 0) AS `Продажи, шт`, sumIf(abs(`КоличествоОборот`), `Возврат` = 1) AS `Возвраты, шт`, sumIf(abs(`СтоимостьОборот`), `Возврат` = 1) AS `Возвраты в руб`, sumIf(`КоличествоОборот`, `ТипНоменклатуры` = 'Обувь') AS `Пары`, count(*) AS `Строк`, sum(`План Оборот`) AS `План Оборот`, sum(`План Трафик`) AS `План Трафик`, sum(`План Вал`) AS `План Вал`, sum(`План Чеки`) AS `План Чеки`, sum(`План Пары`) AS `План Пары` FROM `zendendb`.sales_report_MAIN_full_all_v GROUP BY `Неделя`, `Период`, `Группа`, `Магазин Родитель`, `Регион`, `Город`, `ТипМагазинаУПП`, `МагазинГуид`, `Магазин` SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`sales_report_MAIN_all_by_day_with_plan_for_LFL_v` AS WITH fact AS (SELECT m.`Период`, toString(m.`МагазинГуид`) AS `МагазинГуид`, m.`Магазин` AS `Магазин`, m.`Группа` AS `Группа`, m.`Магазин Родитель` AS `Магазин Родитель`, m.`Регион` AS `Регион`, m.`Город` AS `Город`, m.`Выручка` AS `Выручка`, m.`Количество` AS `Количество`, m.`Трафик` AS `Трафик`, m.`Чеки покупок`, m.`Чеки возвратов`, m.`Вал`, m.`Пары` FROM `zendendb`.sales_report_MAIN_all_by_day AS m WHERE `Период` >= {start_date:date}), plan AS (SELECT s.`Дата` AS `Период`, s.`МагазинГуид` AS `МагазинГуид`, s.`Магазин` AS `Магазин`, mf.`Иерархия`[1] AS `Группа`, mf.`Магазин Родитель` AS `Магазин Родитель`, mf.`Регион` AS `Регион`, mf.`Город` AS `Город`, s.`Оборот`, s.`Трафик`, s.`Вал`, s.`Чеки`, s.`Пары` FROM `zendendb`.`ПланПродаж` AS s FINAL LEFT JOIN `zendendb`.`Магазины_fix` AS mf FINAL ON mf.`МагазинГуид` = s.`МагазинГуид`), shops_lfl AS (SELECT mf.`МагазинГуид` AS `МагазинГуид`, mf.`Магазин` AS `Магазин`, `Год`, half FROM `zendendb`.`МагазиныLFL` AS m LEFT JOIN `zendendb`.`Магазины_fix` AS mf FINAL ON mf.`МагазинГуид` = m.`МагазинГуид`), fact_plan AS (SELECT ifNull(f.`Период`, p.`Период`) AS `Период`, ifNull(f.`МагазинГуид`, p.`МагазинГуид`) AS `МагазинГуид`, ifNull(f.`Магазин`, p.`Магазин`) AS `Магазин`, ifNull(f.`Группа`, p.`Группа`) AS `Группа`, ifNull(f.`Магазин Родитель`, p.`Магазин Родитель`) AS `Магазин Родитель`, ifNull(f.`Регион`, p.`Регион`) AS `Регион`, ifNull(f.`Город`, p.`Город`) AS `Город`, f.`Выручка` AS `Оборот`, f.`Количество` AS `Количество`, p.`Оборот` AS `Оборот План`, f.`Трафик` AS `Трафик`, p.`Трафик` AS `Трафик План`, f.`Вал` AS `Вал`, p.`Вал` AS `Вал План`, f.`Чеки покупок` AS `Чеки покупок`, f.`Чеки возвратов` AS `Чеки возвратов`, p.`Чеки` AS `Чеки План`, f.`Пары` AS `Пары`, p.`Пары` AS `Пары План` FROM fact AS f FULL OUTER JOIN plan AS p ON (f.`Период` = p.`Период`) AND (f.`МагазинГуид` = p.`МагазинГуид`)), working_days AS (SELECT p.`МагазинГуид`, toYYYYMM(p.`Период`) AS month_year, if(max(toDate(p.`Период`)) != today(), (max(toYYYYMMDD(p.`Период`)) - min(toYYYYMMDD(p.`Период`))) + 1, max(toYYYYMMDD(p.`Период`)) - min(toYYYYMMDD(p.`Период`))) AS working_days FROM `zendendb`.`Продажи` AS p WHERE `Период` >= toStartOfMonth({start_date:date}) GROUP BY p.`МагазинГуид`, toYYYYMM(p.`Период`) ORDER BY p.`МагазинГуид` ASC, month_year ASC) SELECT fp.`Период` AS `Период`, fp.`Магазин` AS `Магазин`, fp.`Группа` AS `Группа`, fp.`Магазин Родитель` AS `Магазин Родитель`, fp.`Регион` AS `Регион`, fp.`Город` AS `Город`, fp.`Оборот` AS `Оборот`, fp2.`Оборот` AS `Оборот год назад`, fp.`Количество` AS `Количество`, fp2.`Количество` AS `Количество год назад`, fp.`Трафик` AS `Трафик`, fp2.`Трафик` AS `Трафик год назад`, fp.`Оборот План` AS `Оборот План`, fp.`Трафик План` AS `Трафик План`, fp.`Вал` AS `Вал`, fp.`Вал План` AS `Вал План`, fp.`Чеки покупок` AS `Чеки покупок`, fp.`Чеки возвратов` AS `Чеки возвратов`, fp.`Чеки План` AS `Чеки План`, fp.`Пары` AS `Пары`, fp.`Пары План` AS `Пары План`, m.`МагазинГуид` IS NOT NULL AS LFL, wd.working_days AS working_days_in_month FROM fact_plan AS fp LEFT JOIN fact_plan AS fp2 ON (fp2.`МагазинГуид` = fp.`МагазинГуид`) AND ((fp.`Период` - toIntervalYear(1)) = fp2.`Период`) LEFT JOIN shops_lfl AS m ON (m.`МагазинГуид` = fp.`МагазинГуид`) AND (m.half = if(toMonth(fp.`Период`) <= 6, toStartOfYear(fp.`Период`), toStartOfYear(fp.`Период`) + toIntervalMonth(6))) LEFT JOIN working_days AS wd ON (wd.`МагазинГуид` = fp.`МагазинГуид`) AND (toYYYYMM(fp.`Период`) = wd.month_year) WHERE `Период` >= {start_date:date} SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`sales_report_MAIN_all_no_traffic` (`Неделя` UInt8, `Период` Date, `Группа` LowCardinality(String), `Магазин Родитель` LowCardinality(String), `Регион` LowCardinality(String), `Город` String, `ТипМагазинаУПП` LowCardinality(String), `МагазинГуид` UUID, `Магазин` String, `ЧекГуид` UUID, `ТоварГуид` UUID, `Товар` String, `ТипНоменклатуры` LowCardinality(String), `Сезон` LowCardinality(String), `ТорговаяМарка` String, `Вид` String, `СезонГод` LowCardinality(String), `Род` LowCardinality(String), `Возврат` UInt8, `Реклама` UInt8, `Исключение` UInt8, `СтоимостьОборот` Decimal(10, 2), `СтоимостьБезСкидокОборот` Decimal(10, 2), `Себестоимость` Decimal(10, 2), `Вал` Decimal(10, 2), `КоличествоОборот` Int16, `Скидка` Decimal(10, 2), `Трафик` UInt32) AS SELECT * FROM `zendendb`.sales_report_MAIN_all AS s WHERE s.`ТипНоменклатуры` NOT IN ('', 'Трафик');

