CREATE VIEW `zendendb`.`sales_report_MAIN_short_all_v` AS WITH shop_traffic AS (SELECT toDate(`Период`) AS `Дата`, t.`МагагазинГуид` AS `МагазинГуид`, 'Для магазина' AS `ТипНоменклатуры`, round(((sum((`КоличествоВошло` + `РучКорВошло`) + `АвтКорВошло`) + sum((`КоличествоВышло` + `РучКорВышло`) + `АвтКорВышло`)) * 0.5) * any(if(m.`Коэффициент` = 0, 1, m.`Коэффициент`)), 3) AS `Трафик`, round(((sum(`МимоХодящиеВошло`) + sum(`МимоХодящиеВышло`)) * 0.5) * any(if(m.`Коэффициент` = 0, 1, m.`Коэффициент`)), 3) AS `МимоХодящие` FROM `zendendb`.`ПосещаемостьМагазинов` AS t LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = t.`МагагазинГуид` WHERE (toDate(t.`Период`) >= {start_date:date}) AND (toDate(t.`Период`) <= {end_date:date}) GROUP BY `Дата`, `МагазинГуид`), shop_traffic_plus AS (SELECT `Дата`, t.`МагазинГуид` AS `МагазинГуид`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, t.`Трафик` AS `Трафик`, t.`МимоХодящие` AS `МимоХодящие` FROM shop_traffic AS t), sales AS (SELECT toDate(z.Period) AS `Период`, z.MagazinGuid AS `МагазинГуид`, toUUIDOrDefault(z.UnikalnyyIdentifikatorCHeka, toUUID(hex(sipHash128(z.Period, z.MagazinGuid, z.NomerCHekaKKM)))) AS `ЧекГуид`, z.NomerStroki AS `НомерСтроки`, t.`ТоварГуид` AS `ТоварГуид`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, if(z.VidOperatsii = 'продажа', 0, 1) AS `Возврат`, if(t.`ТипНоменклатуры` = 'Реклама', 1, 0) AS `Реклама`, 0 AS `Исключение`, z.StoimostOborot AS `СтоимостьОборот`, z.StoimostBezSkidokOborot AS `СтоимостьБезСкидокОборот`, s.value_rub AS `Себестоимость`, if(t.`ТипНоменклатуры` = 'Подарочный сертификат', 0, z.StoimostOborot - (z.KolichestvoOborot * ifNull(s.value_rub, s2.value_rub))) AS `Вал`, z.KolichestvoOborot AS `КоличествоОборот`, if(toDecimal32(StoimostBezSkidokOborot, 0) != 0, (1 - divideDecimal(toDecimal32(StoimostOborot, 0), toDecimal32(StoimostBezSkidokOborot, 0), 5)) * 100, -1) AS `Скидка`, fl.`Наименование` AS `Продавец`, ifNull(ps.`Должность`, if((fl.`Должность` = '') AND (fl.`Наименование` = 'яСАМООБСЛУЖИВАНИЕ '), '', 'Продавец-кассир')) AS `Должность` FROM `zendendb`.`ПродажиПроведенные` AS z ANY LEFT JOIN `zendendb`.`ФизическиеЛица` AS fl ON fl.`ПродавецГуид` = z.ProdavetsGuid ANY LEFT JOIN `zendendb`.`ДолжностиСотрудников` AS ps ON (fl.`Наименование` = ps.`Сотрудник`) AND (toDate(z.Period) = ps.`Дата`) ANY LEFT JOIN `zendendb`.`Товары` AS t ON z.NomenklaturaGuid = t.`ТоварГуид` ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t2 ON t.`КодДляОбмена` = t2.`КодДляОбмена` ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS s ON (z.NomenklaturaGuid = s.guidSales) AND (s.half = if(toMonth(z.Period) <= 6, toStartOfYear(z.Period), toStartOfYear(z.Period) + toIntervalMonth(6))) AND (s.price_type = 'Себестоимость') ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS s2 ON (z.NomenklaturaGuid = s2.guidSales) AND (s2.half = if(toMonth(z.Period) <= 6, toStartOfYear(z.Period), toStartOfYear(z.Period) + toIntervalMonth(6))) AND (s2.price_type != 'Себестоимость') WHERE (toDate(z.Period) >= {start_date:date}) AND (toDate(z.Period) <= {end_date:date}) UNION ALL SELECT DISTINCT toDate(z.Period) AS `Период`, z.MagazinGuid AS `МагазинГуид`, toUUIDOrDefault(0) AS `ЧекГуид`, 0 AS `НомерСтроки`, toString(toUUIDOrDefault(0)) AS `ТоварГуид`, 'Для магазина' AS `ТипНоменклатуры`, 2 AS `Возврат`, 2 AS `Реклама`, 2 AS `Исключение`, 0 AS `СтоимостьОборот`, 0 AS `СтоимостьБезСкидокОборот`, 0 AS `Себестоимость`, 0 AS `Вал`, 0 AS `КоличествоОборот`, 0 AS `Скидка`, NULL AS `Продавец`, NULL AS `Должность` FROM `zendendb`.`ПродажиПроведенные` AS z ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m FINAL ON m.`МагазинГуид` = z.MagazinGuid WHERE (toDate(z.Period) >= {start_date:date}) AND (toDate(z.Period) <= {end_date:date})), plan AS (SELECT s.`МагазинГуид` AS `МагазинГуид`, `Дата`, `Оборот`, `Трафик`, `Вал`, `Чеки`, `Пары`, 'Для магазина' AS `ТипНоменклатуры` FROM `zendendb`.`ПланПродаж` AS s WHERE toDate(s.`Дата`) >= {start_date:date}), sales_traffic AS (SELECT ifNull(toWeek(toDate(s.`Период`), 3), toWeek(toDate(st.`Дата`), 3)) AS `Неделя`, ifNull(s.`Период`, st.`Дата`) AS `Период`, ifNull(s.`МагазинГуид`, st.`МагазинГуид`) AS `МагазинГуид`, s.`ЧекГуид` AS `ЧекГуид`, s.`НомерСтроки` AS `НомерСтроки`, s.`ТоварГуид` AS `ТоварГуид`, ifNull(s.`ТипНоменклатуры`, st.`ТипНоменклатуры`) AS `ТипНоменклатуры`, s.`Возврат` AS `Возврат`, s.`Реклама` AS `Реклама`, s.`Исключение` AS `Исключение`, s.`СтоимостьОборот` AS `СтоимостьОборот`, s.`СтоимостьБезСкидокОборот` AS `СтоимостьБезСкидокОборот`, s.`Себестоимость` AS `Себестоимость`, s.`Вал` AS `Вал`, s.`КоличествоОборот` AS `КоличествоОборот`, s.`Скидка` AS `Скидка`, s.`Продавец` AS `Продавец`, s.`Должность` AS `Должность`, st.`Трафик` AS `Трафик`, st.`МимоХодящие` AS `МимоХодящие` FROM sales AS s FULL OUTER JOIN shop_traffic_plus AS st ON (st.`МагазинГуид` = s.`МагазинГуид`) AND (st.`Дата` = s.`Период`) AND (st.`ТипНоменклатуры` = s.`ТипНоменклатуры`)) SELECT ifNull(toWeek(toDate(s.`Период`), 3), toWeek(toDate(pl.`Дата`), 3)) AS `Неделя`, ifNull(s.`Период`, pl.`Дата`) AS `Период`, ifNull(s.`МагазинГуид`, pl.`МагазинГуид`) AS `МагазинГуид`, s.`ЧекГуид` AS `ЧекГуид`, s.`НомерСтроки` AS `НомерСтроки`, s.`ТоварГуид` AS `ТоварГуид`, ifNull(s.`ТипНоменклатуры`, pl.`ТипНоменклатуры`) AS `ТипНоменклатуры`, s.`Возврат` AS `Возврат`, s.`Реклама` AS `Реклама`, s.`Исключение` AS `Исключение`, s.`СтоимостьОборот` AS `СтоимостьОборот`, s.`СтоимостьБезСкидокОборот` AS `СтоимостьБезСкидокОборот`, s.`Себестоимость` AS `Себестоимость`, s.`Вал` AS `Вал`, s.`КоличествоОборот` AS `КоличествоОборот`, s.`Скидка` AS `Скидка`, s.`Продавец` AS `Продавец`, s.`Должность` AS `Должность`, s.`Трафик` AS `Трафик`, s.`МимоХодящие` AS `МимоХодящие`, pl.`Оборот` AS `План Оборот`, pl.`Трафик` AS `План Трафик`, pl.`Вал` AS `План Вал`, pl.`Чеки` AS `План Чеки`, pl.`Пары` AS `План Пары` FROM sales_traffic AS s FULL OUTER JOIN plan AS pl ON (pl.`МагазинГуид` = s.`МагазинГуид`) AND (pl.`Дата` = s.`Период`) AND (pl.`ТипНоменклатуры` = s.`ТипНоменклатуры`) 