CREATE VIEW `zendendb`.`sales_report_MAIN_v` (`Период` Nullable(Date), `Группа` Nullable(String), `Магазин Родитель` Nullable(String), `Регион` Nullable(String), `ТипМагазинаУПП` Nullable(String), `Магазин` Nullable(String), `ТипНоменклатуры` Nullable(String), `Сезон` Nullable(String), `OrderTM` Nullable(String), `КоллекцияПроизводства` Nullable(String), `КоллекцияПроизводстваКомментарий` Nullable(String), `ЧекГуид` Nullable(UUID), `Возврат` Nullable(UInt8), `Реклама` Nullable(UInt8), `Исключение` Nullable(UInt8), `СтоимостьОборот` Nullable(Decimal(38, 2)), `СтоимостьБезСкидокОборот` Nullable(Decimal(38, 2)), `Скидка` Nullable(Decimal(76, 5)), `КоличествоОборот` Nullable(Decimal(38, 3)), `Вал` Nullable(Decimal(38, 8)), `Трафик` Nullable(Float64), `Трафик по группе` Nullable(Float64), `План Оборот` Nullable(Decimal(10, 3)), `План Трафик` Nullable(Decimal(10, 3)), `План Вал` Nullable(Decimal(10, 3)), `План Чеки` Nullable(Decimal(5, 3)), `План Пары` Nullable(Decimal(5, 3)), `Выручка по группе` Nullable(Decimal(38, 2)), `Выручка вся` Nullable(Decimal(38, 2)), `Выручка по группе(обувь)` Nullable(Decimal(38, 2)), `Выручка вся(обувь)` Nullable(Decimal(38, 2))) AS WITH group_in_sales AS (SELECT DISTINCT m.`МагазинГуид` FROM `zendendb`.`Магазины_fix` AS m WHERE m.`Магазин Родитель` IN (SELECT * FROM `zendendb`.`Магазины_Родители_v`)), goods_cost AS (SELECT * FROM `zendendb`.`Себестоимость_по_полугодиям` WHERE (half >= if(toMonth(today() - 7) <= 6, toStartOfYear(today() - 7), toStartOfYear(today() - 7) + toIntervalMonth(6))) AND (half <= if(toMonth(today()) <= 6, toStartOfYear(today()), toStartOfYear(today()) + toIntervalMonth(6)))), sales_all AS (SELECT Period AS `Период`, if(toMonth(Period) <= 6, toStartOfYear(Period), toStartOfYear(Period) + toIntervalMonth(6)) AS half, z.MagazinGuid AS `МагазинГуид`, z.NomenklaturaGuid AS `НоменклатураГуид`, z.StoimostOborot AS `СтоимостьОборот`, z.KolichestvoOborot AS `КоличествоОборот`, z.StoimostBezSkidokOborot AS `СтоимостьБезСкидокОб