 AS m FINAL ON m.`МагазинГуид` = z.`МагазинГуид` ANY LEFT JOIN goods_cost AS s ON (z.`НоменклатураГуид` = s.guidSales) AND (s.half = z.half) AND (s.price_type = 'Себестоимость') ANY LEFT JOIN goods_cost AS s2 ON (z.`НоменклатураГуид` = s.guidSales) AND (s2.half = z.half) AND (s.price_type != 'Себестоимость') WHERE (toTime(z.`Период` - toIntervalHour(m.`Относительно Москвы`)) <= (SELECT toTime(max(event_time)) FROM `zendendb`.sales_report_updated AS sru WHERE sru.table_names = 'Продажи' LIMIT 1)) AND (z.`МагазинГуид` IN (SELECT * FROM group_in_sales)) UNION ALL SELECT toDate(z.`Период`) - 1 AS `Дата`, z.`МагазинГуид` AS `МагазинГуид`, z.`НоменклатураГуид` AS `НоменклатураГуид`, t.`СвойствоСезон` AS `Сезон`, z.`ЧекГуид` AS `ЧекГуид`, if(z.`ВидОперации` = 'продажа', 0, 1) AS `Возврат`, if(t.`ТипНоменклатуры` = 'Реклама', 1, 0) AS `Реклама`, 0 AS `Исключение`, z.`СтоимостьОборот` AS `СтоимостьОборот`, z.`СтоимостьБезСкидокОборот` AS `СтоимостьБезСкидокОборот`, if(toDecimal32(`СтоимостьБезСкидокОборот`, 0) != 0, 1 - divideDecimal(toDecimal32(`СтоимостьОборот`, 0), toDecimal32(`СтоимостьБезСкидокОборот`, 0), 5), 0) * 100 AS `Скидка`, z.`КоличествоОборот` AS `КоличествоОборот`, if(t.`ТипНоменклатуры` = 'Подарочный сертификат', 0, z.`СтоимостьОборот` - (z.`КоличествоОборот` * ifNull(s.value_rub, s2.value_rub))) AS `Вал` FROM sales_all AS z ANY LEFT JOIN `zendendb`.`Товары` AS t ON z.`НоменклатураГуид` = t.`ТоварГуид` ANY LEFT JOIN goods_cost AS s ON (z.`НоменклатураГуид` = s.guidSales) AND (s.half = z.half) AND (s.price_type = 'Себестоимость') ANY LEFT JOIN goods_cost AS s2 ON (z.`НоменклатураГуид` = s.guidSales) AND (s2.half = z.half) AND (s.price_type != 'Себестоимость') WHERE (toDate(z.`Период`) IN (today() - 1, today() - 7)) AND (z.`МагазинГуид` IN (SELECT * FROM group_in_sales))), shop_traffic_by_group AS (SELECT m.`Группа` AS `Группа`, `Дата`, sum(t.`Трафик`) AS `Трафик по группе` FROM traffic AS t ANY LEFT JOIN `zendendb`.`Магазины_fix_with_group_v` AS m ON m.`МагазинГуид` = t.`МагазинГуид` GROUP BY `Группа`, `Дата`), sales_plan_traffic AS (SELECT ifNull(s.`Дата`, ifNull(tr.`Дата`, pl.`Дата`)) AS `Дата`, ifNull(s.`МагазинГуид`, ifNull(tr.`МагазинГуид`, pl.`МагазинГуид`)) AS `МагазинГуид`, ifNull(s.`НоменклатураГуид`, ifNull(tr.`НоменклатураГуид`, pl.`НоменклатураГуид`)) AS `НоменклатураГуид`, s.`ЧекГуид` AS `ЧекГуид`, s.`Возврат` AS `Возврат`, s.`Реклама` AS `Реклама`, s.`Исключение` AS `Исключение`, s.`СтоимостьОборот` AS `СтоимостьОборот`, s.`СтоимостьБезСкидокОборот` AS `СтоимостьБезСкидокОборот`, s.`Скидка` AS `Скидка`, s.`КоличествоОборот` AS `КоличествоОборот`, s.`Вал` AS `Вал`, tr.`Трафик` AS `Трафик`, pl.`ПланОборот` AS `ПланОборот`, pl.`ПланТрафик` AS `ПланТрафик`, pl.`ПланВал` AS `ПланВал`, pl.`ПланЧеки` AS `ПланЧеки`, pl.`ПланПары` AS `ПланПары` FROM sales AS s FULL OUTER JOIN traffic AS tr ON (tr.`МагазинГуид` = s.`МагазинГуид`) AND (tr.`Дата` = s.`Дата`) AND (tr.`НоменклатураГуид` = s.`НоменклатураГуид`) FULL OUTER JOIN plan AS pl ON (pl.`МагазинГуид` = s.`МагазинГуид`) AND (pl.`Дата` = s.`Дата`) AND (pl.`НоменклатураГуид` = s.`НоменклатураГуид`)) SELECT s.`Дата` AS `Период`, multiIf(m.`Группа` ILIKE '%Zenden%', 'Z', m.`Группа` ILIKE '%Mascotte%', 'R', m.`Группа`) AS `Группа`, multiIf(`Магазин Родитель` ILIKE '%Zenden%', 'Z', `Магазин Родитель` ILIKE '%Mascotte%', 'R', `Магазин Родитель`) AS `Магазин Родитель`, m.`Регион` AS `Регион`, m.`ТипМагазинаДляПланированияУПП` AS `ТипМагазинаУПП`, m.`Магазин` AS `Магазин`, t2.`ТипНоменклатуры` AS `ТипНоменклатуры`, t2.`СвойствоСезон` AS `Сезон`, t2.OrderTM AS OrderTM, t2.`СвойствоКоллекцияПроизводства` AS `КоллекцияПроизводства`, t2.`СвойствоКоллекцияПроизводстваКомментарий` AS `КоллекцияПроизводстваКомментарий`, s.`ЧекГуид` AS `ЧекГуид`, s.`Возврат` AS `Возврат`, s.`Реклама` AS `Реклама`, s.`Исключение` AS `Исключение`, s.`СтоимостьОборот` AS `СтоимостьОборот`, s.`СтоимостьБезСкидокОборот` AS `СтоимостьБезСкидокОборот`, s.`Скидка` AS `Скидка`, s.`КоличествоОборот` AS `КоличествоОборот`, s.`Вал` AS `Вал`, s.`Трафик` AS `Трафик`, stg.`Трафик по группе` AS `Трафик по группе`, s.`ПланОборот` AS `План Оборот`, s.`ПланТрафик` AS `План Трафик`, s.`ПланВал` AS `План Вал`, s.`ПланЧеки` AS `План Чеки`, s.`ПланПары` AS `План Пары`, sum(s.`СтоимостьОборот`) OVER (PARTITION BY `Группа`, `Период`) AS `Выручка по группе`, sum(s.`СтоимостьОборот`) OVER (PARTITION BY `Период`) AS `Выручка вся`, sumIf(s.`СтоимостьОборот`, (t.`ТипНоменклатуры` IN ('Обувь'))) OVER (PARTITION BY `Группа`, `Период`) AS `Выручка по группе(обувь)`, sumIf(s.`СтоимостьОборот`, (t.`ТипНоменклатуры` IN ('Обувь'))) OVER (PARTITION BY `Период`) AS `Выручка вся(обувь)` FROM sales_plan_traffic AS s ANY LEFT JOIN `zendendb`.`Товары` AS t ON s.`НоменклатураГуид` = t.`ТоварГуид` ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t2 ON t.`КодДляОбмена` = t2.`КодДляОбмена` ANY LEFT JOIN `zendendb`.`Магазины_fix_with_group_v` AS m ON m.`МагазинГуид` = s.`МагазинГуид` ANY LEFT JOIN shop_traffic_by_group AS stg ON (stg.`Группа` = m.`Группа`) AND (stg.`Дата` = s.`Дата`) SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`sales_report_by_day_v` (`Период` Date, `Магазин` Nullable(String), `Магазин Родитель` Nullable(String), `Чеки покупок` UInt64, `Чеки возвратов` UInt64, `КоличествоОборот` Decimal(38, 3), `СтоимостьОборот` Decimal(38, 4), `Валовая прибыль` Nullable(Decimal(38, 8)), `Трафик` Nullable(Decimal(18, 4)), `МимоХодящие` Nullable(Decimal(18, 4))) AS WITH today_sales AS (SELECT p.`МагазинГуид` AS `МагазинГуид`, p.`КоличествоОборот` AS `КоличествоОборот`, p.`СтоимостьОборот` AS `СтоимостьОборот`, p.`НоменклатураГуид` AS `НоменклатураГуид`, toDate(p.`Период`) AS `Период_пр`, if(p.`ВидОперации` = 'продажа', 1, 0) AS `ВидОперации`, toUUIDOrDefault(p.`ЧекГуид`, toUUID(hex(sipHash128(p.`Период`, p.`МагазинГуид`, p.`НомерЧекаККМ`)))) AS `ЧекГуид`, ifNull(s.value_rub, s2.value_rub) AS `Себестоимость` FROM `zendendb`.`Продажи` AS p ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m FINAL ON m.`МагазинГуид` = p.`МагазинГуид` ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS s ON (p.`НоменклатураГуид` = s.guidSales) AND (s.half = if(toMonth(p.`Период`) <= 6, toStartOfYear(p.`Период`), toStartOfYear(p.`Период`) + toIntervalMonth(6))) AND (s.price_type = 'Себестоимость') ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS s2 ON (p.`НоменклатураГуид` = s2.guidSales) AND (s2.half = if(toMonth(p.`Период`) <= 6, toStartOfYear(p.`Период`), toStartOfYear(p.`Период`) + toIntervalMonth(6))) AND (s2.price_type != 'Себестоимость') WHERE (toDate(`Период`) = today()) AND (m.`Магазин Родитель` NOT IN ('Неиспользуемые Zenden', 'Закрытые Mascotte', 'Комиссионеры ТМ', 'Неиспользуемые ТМ', 'Закрытые SALAMANDER'))), today_traffic AS (SELECT `МагагазинГуид` AS `МагазинГуид`, toDate(t.`Период`) AS `Период_тр`, sum((`КоличествоВошло` + `РучКорВошло`) + `АвтКорВошло`) AS `Вошло`, sum((`КоличествоВышло` + `РучКорВышло`) + `АвтКорВышло`) AS `Вышло`, sum(`МимоХодящиеВошло`) AS `МимоХодящиеВошло`, sum(`МимоХодящиеВышло`) AS `МимоХодящиеВышло` FROM `zendendb`.`ПосещаемостьМагазинов` AS t WHERE toDate(t.`Период`) = today() GROUP BY `МагазинГуид`, toDate(t.`Период`)), goods AS (SELECT DISTINCT *, t.`КодДляОбмена` IN (0) AS `Исключение` FROM `zendendb`.`Товары` AS t), past_sales AS (SELECT md.`Период`, md.`Магазин`, md.`Магазин Родитель`, md.`Чеки покупок`, md.`Чеки возвратов`, md.`Количество` AS `КоличествоОборот`, md.`Выручка` AS `СтоимостьОборот`, md.`Вал` AS `Валовая прибыль`, md.`Трафик` AS `Трафик`, md.`МимоХодящие` AS `МимоХодящие` FROM `zendendb`.sales_report_MAIN_all_by_day AS md WHERE (md.`Магазин Родитель` NOT IN ('Неиспользуемые Zenden', 'Закрытые Mascotte', 'Комиссионеры ТМ', 'Неиспользуемые ТМ', 'Закрытые SALAMANDER')) AND (md.`Период` < today())) SELECT s.`Период_пр` AS `Период`, m.`Магазин` AS `Магазин`, m.`Магазин Родитель` AS `Магазин Родитель`, countIfDistinct(s.`ЧекГуид`, s.`ВидОперации` = 1) AS `Чеки покупок`, countIfDistinct(s.`ЧекГуид`, s.`ВидОперации` = 0) AS `Чеки возвратов`, sum(`КоличествоОборот`) AS `КоличествоОборот`, sum(`СтоимостьОборот`) AS `СтоимостьОборот`, sum(if(g.`ТипНоменклатуры` = 'Подарочный сертификат', 0, s.`СтоимостьОборот` - (s.`КоличествоОборот` * `Себестоимость`))) AS `Валовая прибыль`, toDecimal32(avg(((t.`Вошло` + t.`Вышло`) * 0.5) * if(m.`Коэффициент` = 0, 1, m.`Коэффициент`)), 4) AS `Трафик`, toDecimal32(avg(((t.`МимоХодящиеВошло` + t.`МимоХодящиеВышло`) * 0.5) * if(m.`Коэффициент` = 0, 1, m.`Коэффициент`)), 4) AS `МимоХодящие` FROM today_sales AS s LEFT JOIN today_traffic AS t ON (s.`Период_пр` = t.`Период_тр`) AND (s.`МагазинГуид` = t.`МагазинГуид`) LEFT JOIN `zendendb`.`Магазины_fix` AS m FINAL ON s.`МагазинГуид` = m.`МагазинГуид` LEFT JOIN goods AS g ON s.`НоменклатураГуид` = g.`ТоварГуид` GROUP BY s.`Период_пр`, m.`Магазин`, m.`Магазин Родитель` UNION ALL WITH today_sales AS (SELECT p.`МагазинГуид` AS `МагазинГуид`, p.`КоличествоОборот` AS `КоличествоОборот`, p.`СтоимостьОборот` AS `СтоимостьОборот`, p.`НоменклатураГуид` AS `НоменклатураГуид`, toDate(p.`Период`) AS `Период_пр`, if(p.`ВидОперации` = 'продажа', 1, 0) AS `ВидОперации`, toUUIDOrDefault(p.`ЧекГуид`, toUUID(hex(sipHash128(p.`Период`, p.`МагазинГуид`, p.`НомерЧекаККМ`)))) AS `ЧекГуид`, ifNull(s.value_rub, s2.value_rub) AS `Себестоимость` FROM `zendendb`.`Продажи` AS p ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m FINAL ON m.`МагазинГуид` = p.`МагазинГуид` ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS s ON (p.`НоменклатураГуид` = s.guidSales) AND (s.half = if(toMonth(p.`Период`) <= 6, toStartOfYear(p.`Период`), toStartOfYear(p.`Период`) + toIntervalMonth(6))) AND (s.price_type = 'Себестоимость') ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS s2 ON (p.`НоменклатураГуид` = s2.guidSales) AND (s2.half = if(toMonth(p.`Период`) <= 6, toStartOfYear(p.`Период`), toStartOfYear(p.`Период`) + toIntervalMonth(6))) AND (s2.price_type != 'Себестоимость') WHERE (toDate(`Период`) = today()) AND (m.`Магазин Родитель` NOT IN ('Неиспользуемые Zenden', 'Закрытые Mascotte', 'Комиссионеры ТМ', 'Неиспользуемые ТМ', 'Закрытые SALAMANDER'))), today_traffic AS (SELECT `МагагазинГуид` AS `МагазинГуид`, toDate(t.`Период`) AS `Период_тр`, sum((`КоличествоВошло` + `РучКорВошло`) + `АвтКорВошло`) AS `Вошло`, sum((`КоличествоВышло` + `РучКорВышло`) + `АвтКорВышло`) AS `Вышло`, sum(`МимоХодящиеВошло`) AS `МимоХодящиеВошло`, sum(`МимоХодящиеВышло`) AS `МимоХодящиеВышло` FROM `zendendb`.`ПосещаемостьМагазинов` AS t WHERE toDate(t.`Период`) = today() GROUP BY `МагазинГуид`, toDate(t.`Период`)), goods AS (SELECT DISTINCT *, t.`КодДляОбмена` IN (0) AS `Исключение` FROM `zendendb`.`Товары` AS t), past_sales AS (SELECT md.`Период`, md.`Магазин`, md.`Магазин Родитель`, md.`Чеки покупок`, md.`Чеки возвратов`, md.`Количество` AS `КоличествоОборот`, md.`Выручка` AS `СтоимостьОборот`, md.`Вал` AS `Валовая прибыль`, md.`Трафик` AS `Трафик`, md.`МимоХодящие` AS `МимоХодящие` FROM `zendendb`.sales_report_MAIN_all_by_day AS md WHERE (md.`Магазин Родитель` NOT IN ('Неиспользуемые Zenden', 'Закрытые Mascotte', 'Комиссионеры ТМ', 'Неиспользуемые ТМ', 'Закрытые SALAMANDER')) AND (md.`Период` < today())) SELECT * FROM past_sales SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`sales_report_cohors_all_v` (`Дата` Date, `МагазинРодитель` String, `Магазин` String, `Когорта` UInt8, `СтоимостьОборот` Decimal(38, 2), `СтоимостьБезСкидокОборот` Decimal(38, 2), `КоличествоОборот` Decimal(38, 3)) AS WITH dicount AS (SELECT toDate(s.`Период`) AS `Дата`, m.`Магазин` AS `Магазин`, m.`Магазин Родитель` AS `МагазинРодитель`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, s.`СтоимостьОборот` AS `СтоимостьОборот`, s.`СтоимостьБезСкидокОборот` AS `СтоимостьБезСкидокОборот`, s.`КоличествоОборот` AS `КоличествоОборот`, if(s.`СтоимостьБезСкидокОборот` != 0, (1 - divideDecimal(toDecimal32(s.`СтоимостьОборот`, 0), toDecimal32(s.`СтоимостьБезСкидокОборот`, 0), 5)) * 100, -1) AS `Скидка` FROM `zendendb`.`Продажи` AS s ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m FINAL ON m.`МагазинГуид` = s.`МагазинГуид` ANY LEFT JOIN `zendendb`.`Товары` AS t ON s.`НоменклатураГуид` = t.`ТоварГуид` WHERE (m.`Магазин Родитель` IN (SELECT * FROM `zendendb`.`Магазины_Родители_v`)) AND (`ТипНоменклатуры` = 'Обувь') AND (toDate(s.`Период`) < today()) AND (toDate(s.`Период`) > (SELECT max(`Дата`) FROM `zendendb`.sales_report_cohors_all))), dicount_cohors AS (SELECT *, multiIf(abs(`Скидка`) = 0, 0, (abs(`Скидка`) > 0) AND (abs(`Скидка`) <= 15), 10, (abs(`Скидка`) > 15) AND (abs(`Скидка`) <= 25), 20, (abs(`Скидка`) > 25) AND (abs(`Скидка`) <= 35), 30, (abs(`Скидка`) > 35) AND (abs(`Скидка`) <= 45), 40, (abs(`Скидка`) > 45) AND (abs(`Скидка`) <= 55), 50, (abs(`Скидка`) > 55) AND (abs(`Скидка`) <= 65), 60, (abs(`Скидка`) > 65) AND (abs(`Скидка`) <= 75), 70, (abs(`Скидка`) > 75) AND (abs(`Скидка`) <= 85), 80, abs(`Скидка`) > 85, 90, 100) AS `Когорта` FROM dicount) SELECT `Дата`, `МагазинРодитель`, `Магазин`, `Когорта`, sum(`СтоимостьОборот`) AS `СтоимостьОборот`, sum(`СтоимостьБезСкидокОборот`) AS `СтоимостьБезСкидокОборот`, sum(`КоличествоОборот`) AS `КоличествоОборот` FROM dicount_cohors AS d GROUP BY `Дата`, `МагазинРодитель`, `Магазин`, `Когорта` ORDER BY `МагазинРодитель` ASC, `Дата` ASC, `Магазин` ASC, `Когорта` ASC SETTINGS final = 1;

CREATE VIEW `zendendb`.`sales_report_discount_cohors_v` (`Период` Date, `Магазин` String, `Магазин Родитель` LowCardinality(String), `Регион` LowCardinality(String), `Тип Магазина` LowCardinality(String), `Сезон` LowCardinality(String), `ТипНоменклатуры` LowCardinality(String), `СтоимостьОборот` Decimal(10, 3), `СтоимостьБезСкидокОборот` Decimal(10, 3), `Скидка` Decimal(76, 2), `КоличествоОборот` Int16, `Когорта` UInt8) AS WITH sales_disc AS (SELECT `Период`, `Магазин`, `Магазин Родитель`, `Регион`, `ТипМагазинаУПП` AS `Тип Магазина`, `Сезон`, `ТипНоменклатуры`, `СтоимостьОборот`, `СтоимостьБезСкидокОборот`, if(isZeroOrNull(toInt64(`СтоимостьБезСкидокОборот`)), 0, 1 - divideDecimal(toDecimal32(`СтоимостьОборот`, 2), toDecimal32(`СтоимостьБезСкидокОборот`, 2))) * 100 AS `Скидка`, `КоличествоОборот` FROM `zendendb`.sales_report_MAIN AS z WHERE `ТипНоменклатуры` = 'Обувь'), disc AS (SELECT *, multiIf(abs(`Скидка`) = 0, 0, (abs(`Скидка`) > 0) AND (abs(`Скидка`) <= 15), 10, (abs(`Скидка`) > 15) AND (abs(`Скидка`) <= 25), 20, (abs(`Скидка`) > 25) AND (abs(`Скидка`) <= 35), 30, (abs(`Скидка`) > 35) AND (abs(`Скидка`) <= 45), 40, (abs(`Скидка`) > 45) AND (abs(`Скидка`) <= 55), 50, (abs(`Скидка`) > 55) AND (abs(`Скидка`) <= 65), 60, (abs(`Скидка`) > 65) AND (abs(`Скидка`) <= 75), 70, (abs(`Скидка`) > 75) AND (abs(`Скидка`) <= 85), 80, abs(`Скидка`) > 85, 90, 100) AS `Когорта` FROM sales_disc) SELECT * FROM disc AS d SETTINGS final = 1;

CREATE VIEW `zendendb`.`sales_report_today_LFL_v` (`Неделя` Nullable(UInt8), `Период` Nullable(Date), `Группа` Nullable(String), `Магазин Родитель` Nullable(String), `Регион` Nullable(String), `Город` Nullable(String), `ТипМагазинаУПП` Nullable(String), `МагазинГуид` Nullable(UUID), `Магазин` Nullable(String), `ЧекГуид` Nullable(UUID), `ТоварГуид` Nullable(UUID), `Товар` Nullable(String), `ТипНоменклатуры` Nullable(String), `Сезон` Nullable(String), `ТорговаяМарка` Nullable(String), `Вид` Nullable(String), `СезонГод` Nullable(String), `Род` Nullable(String), `Возврат` Nullable(UInt8), `Реклама` Nullable(UInt8), `Исключение` Nullable(UInt8), `СтоимостьОборот` Nullable(Decimal(38, 2)), `СтоимостьБезСкидокОборот` Nullable(Decimal(38, 2)), `Себестоимость` Nullable(Decimal(18, 5)), `Вал` Nullable(Decimal(38, 8)), `КоличествоОборот` Nullable(Decimal(38, 3)), `Скидка` Nullable(Decimal(76, 5)), `Трафик Магазина` Nullable(Float64)) AS WITH shop_traffic AS (SELECT toDate(`Период`) AS `Дата`, t.`МагагазинГуид` AS `МагазинГуид`, 'Трафик' AS `ТипНоменклатуры`, round(((sum((`КоличествоВошло` + `РучКорВошло`) + `АвтКорВошло`) + sum((`КоличествоВышло` + `РучКорВышло`) + `АвтКорВышло`)) * 0.5) * any(if(m.`Коэффициент` = 0, 1, m.`Коэффициент`))) AS `Трафик` FROM `zendendb`.`ПосещаемостьМагазинов` AS t ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m FINAL ON m.`МагазинГуид` = t.`МагагазинГуид` WHERE (toDate(`Период`) IN (today(), today() - toIntervalDay(1), today() - toIntervalWeek(1), today() - toIntervalMonth(1), today() - toIntervalYear(1))) AND (toTime(`Период` - toIntervalHour(m.`Относительно Москвы`)) <= (SELECT toTime(max(event_time)) FROM `zendendb`.sales_report_updated AS sru WHERE sru.table_names = 'Продажи' LIMIT 1)) AND (m.`Магазин Родитель` IN (SELECT * FROM `zendendb`.`Магазины_Родители_v`)) GROUP BY `Дата`, `МагазинГуид`), shop_traffic_plus AS (SELECT `Дата`, multiIf((m.`Магазин Родитель` IN ('MUNZ STORE', 'Salamander', 'TM Concept', 'Thomas Munz')), 'Munz Group', m.`Магазин Родитель` = 'Розница Mascotte', 'Mascotte', m.`Магазин Родитель` = 'Zenden', 'Zenden', m.`Магазин Родитель`) AS `Группа`, m.`Магазин Родитель` AS `Магазин Родитель`, m.`Регион` AS `Регион`, m.`Город` AS `Город`, m.`ТипМагазинаУПП` AS `ТипМагазинаУПП`, toUUID(t.`МагазинГуид`) AS `МагазинГуид`, m.`Магазин` AS `Магазин`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, t.`Трафик` AS `Трафик` FROM shop_traffic AS t ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m FINAL ON m.`МагазинГуид` = t.`МагазинГуид`), sales AS (SELECT toDate(z.`Период`) AS `Дата`, multiIf((m.`Магазин Родитель` IN ('MUNZ STORE', 'Salamander', 'TM Concept', 'Thomas Munz')), 'Munz Group', m.`Магазин Родитель` = 'Розница Mascotte', 'Mascotte', m.`Магазин Родитель` = 'Zenden', 'Zenden', m.`Магазин Родитель`) AS `Группа`, m.`Магазин Родитель` AS `Магазин Родитель`, m.`Регион` AS `Регион`, m.`Город` AS `Город`, m.`ТипМагазинаУПП` AS `ТипМагазинаУПП`, toUUID(z.`МагазинГуид`) AS `МагазинГуид`, m.`Магазин` AS `Магазин`, toUUIDOrDefault(z.`ЧекГуид`, toUUID(hex(sipHash128(z.`Период`, z.`МагазинГуид`, z.`НомерЧекаККМ`)))) AS `ЧекГуид`, toUUID(t.`ТоварГуид`) AS `ТоварГуид`, t.`Товар` AS `Товар`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, t.`СвойствоСезон` AS `Сезон`, t.`СвойствоТорговаяМарка` AS `ТорговаяМарка`, t.`СвойствоВидОбуви` AS `Вид`, t.`СвойствоГод` AS `Год`, t.`СвойствоРод` AS `Род`, if(z.`ВидОперации` = 'продажа', 0, 1) AS `Возврат`, if(t.`ТипНоменклатуры` = 'Реклама', 1, 0) AS `Реклама`, if((t.`КодДляОбмена` IN (SELECT id FROM `zendendb`.`ПродажиИсключения`)), 1, 0) AS `Исключение`, z.`СтоимостьОборот` AS `СтоимостьОборот`, z.`СтоимостьБезСкидокОборот` AS `СтоимостьБезСкидокОборот`, ifNull(s.value_rub, s2.value_rub) AS `Себестоимость`, if(t.`ТипНоменклатуры` = 'Подарочный сертификат', 0, z.`СтоимостьОборот` - (z.`КоличествоОборот` * ifNull(s.value_rub, s2.value_rub))) AS `Вал`, z.`КоличествоОборот` AS `КоличествоОборот`, if(`СтоимостьБезСкидокОборот` != 0, (1 - divideDecimal(toDecimal32(`СтоимостьОборот`, 0), toDecimal32(`СтоимостьБезСкидокОборот`, 0), 5)) * 100, -1) AS `Скидка` FROM `zendendb`.`Продажи` AS z ANY LEFT JOIN `zendendb`.`Товары` AS t ON z.`НоменклатураГуид` = t.`ТоварГуид` ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m FINAL ON m.`МагазинГуид` = z.`МагазинГуид` ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS s ON (z.`НоменклатураГуид` = s.guidSales) AND (s.half = if(toMonth(`Период`) <= 6, toStartOfYear(`Период`), toStartOfYear(`Период`) + toIntervalMonth(6))) AND (s.price_type = 'Себестоимость') ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS s2 ON (z.`НоменклатураГуид` = s2.guidSales) AND (s2.half = if(toMonth(`Период`) <= 6, toStartOfYear(`Период`), toStartOfYear(`Период`) + toIntervalMonth(6))) AND (s2.price_type != 'Себестоимость') WHERE (toDate(`Период`) IN (today(), today() - toIntervalDay(1), today() - toIntervalWeek(1), today() - toIntervalMonth(1), today() - toIntervalYear(1))) AND (toTime(`Период` - toIntervalHour(m.`Относительно Москвы`)) <= (SELECT toTime(max(event_time)) FROM `zendendb`.sales_report_updated AS sru WHERE sru.table_names = 'Продажи' LIMIT 1)) AND (m.`Магазин Родитель` IN (SELECT * FROM `zendendb`.`Магазины_Родители_v`)) UNION ALL SELECT DISTINCT toDate(z.`Период`) AS `Дата`, multiIf((m.`Магазин Родитель` IN ('MUNZ STORE', 'Salamander', 'TM Concept', 'Thomas Munz')), 'Munz Group', m.`Магазин Родитель` = 'Розница Mascotte', 'Mascotte', m.`Магазин Родитель` = 'Zenden', 'Zenden', m.`Магазин Родитель`) AS `Группа`, m.`Магазин Родитель` AS `Магазин Родитель`, m.`Регион` AS `Регион`, m.`Город` AS `Город`, m.`ТипМагазинаУПП` AS `ТипМагазинаУПП`, toUUID(z.`МагазинГуид`) AS `МагазинГуид`, m.`Магазин` AS `Магазин`, toUUIDOrDefault(0) AS `ЧекГуид`, toUUIDOrDefault(0) AS `ТоварГуид`, 'Трафик' AS `Товар`, 'Трафик' AS `ТипНоменклатуры`, 'Трафик' AS `Сезон`, 'Трафик' AS `ТорговаяМарка`, 'Трафик' AS `Вид`, 'Трафик' AS `Год`, 'Трафик' AS `Род`, 2 AS `Возврат`, 2 AS `Реклама`, 2 AS `Исключение`, 0 AS `СтоимостьОборот`, 0 AS `СтоимостьБезСкидокОборот`, 0 AS `Себестоимость`, 0 AS `Вал`, 0 AS `КоличествоОборот`, 0 AS `Скидка` FROM `zendendb`.`Продажи` AS z ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m FINAL ON m.`МагазинГуид` = z.`МагазинГуид` WHERE (toDate(`Период`) IN (today(), today() - toIntervalDay(1), today() - toIntervalWeek(1), today() - toIntervalMonth(1), today() - toIntervalYear(1))) AND (toTime(`Период` - toIntervalHour(m.`Относительно Москвы`)) <= (SELECT toTime(max(event_time)) FROM `zendendb`.sales_report_updated AS sru WHERE sru.table_names = 'Продажи' LIMIT 1)) AND (m.`Магазин Родитель` IN (SELECT * FROM `zendendb`.`Магазины_Родители_v`))) SELECT ifNull(toWeek(toDate(s.`Дата`), 3), toWeek(toDate(st.`Дата`), 3)) AS `Неделя`, ifNull(s.`Дата`, st.`Дата`) AS `Период`, ifNull(s.`Группа`, st.`Группа`) AS `Группа`, ifNull(s.`Магазин Родитель`, st.`Магазин Родитель`) AS `Магазин Родитель`, ifNull(s.`Регион`, st.`Регион`) AS `Регион`, ifNull(s.`Город`, st.`Город`) AS `Город`, ifNull(s.`ТипМагазинаУПП`, st.`ТипМагазинаУПП`) AS `ТипМагазинаУПП`, ifNull(s.`МагазинГуид`, st.`МагазинГуид`) AS `МагазинГуид`, ifNull(s.`Магазин`, st.`Магазин`) AS `Магазин`, s.`ЧекГуид` AS `ЧекГуид`, s.`ТоварГуид` AS `ТоварГуид`, s.`Товар` AS `Товар`, ifNull(s.`ТипНоменклатуры`, st.`ТипНоменклатуры`) AS `ТипНоменклатуры`, s.`Сезон` AS `Сезон`, s.`ТорговаяМарка` AS `ТорговаяМарка`, s.`Вид` AS `Вид`, s.`Год` AS `СезонГод`, s.`Род` AS `Род`, s.`Возврат` AS `Возврат`, s.`Реклама` AS `Реклама`, s.`Исключение` AS `Исключение`, s.`СтоимостьОборот` AS `СтоимостьОборот`, s.`СтоимостьБезСкидокОборот` AS `СтоимостьБезСкидокОборот`, s.`Себестоимость` AS `Себестоимость`, s.`Вал` AS `Вал`, s.`КоличествоОборот` AS `КоличествоОборот`, s.`Скидка` AS `Скидка`, st.`Трафик` AS `Трафик Магазина` FROM sales AS s FULL OUTER JOIN shop_traffic_plus AS st ON (st.`МагазинГуид` = s.`МагазинГуид`) AND (st.`Дата` = s.`Дата`) AND (st.`ТипНоменклатуры` = s.`ТипНоменклатуры`) SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`sales_report_updated_v` (`event_time` DateTime('Europe/Moscow'), `table_names` String, `operation_time` DateTime) AS WITH max_time AS (SELECT 'Продажи' AS table_names, max(`Период` - toIntervalHour(m.`Относительно Москвы`)) AS operation_time FROM `zendendb`.`Продажи` AS s LEFT JOIN `zendendb`.`Магазины_fix` AS m ON s.`МагазинГуид` = m.`МагазинГуид` WHERE s.`Период` > (today() - 2) UNION ALL SELECT 'ПосещаемостьМагазинов' AS table_names, max(`Период` - toIntervalHour(m.`Относительно Москвы`)) AS operation_time FROM `zendendb`.`ПосещаемостьМагазинов` AS s LEFT JOIN `zendendb`.`Магазины_fix` AS m ON s.`МагагазинГуид` = m.`МагазинГуид` WHERE s.`Период` > (today() - 2) UNION ALL SELECT 'ПродажиУПП' AS table_names, max(`Период`) AS operation_time FROM `zendendb`.`ПродажиУПП` AS s WHERE s.`Период` > (today() - 2)) SELECT toDateTime(max(event_time), 'Europe/Moscow') AS event_time, p.`table` AS table_names, max(m.operation_time) AS operation_time FROM system.part_log AS p LEFT JOIN max_time AS m ON m.table_names = p.`table` WHERE (database = 'zendendb') AND (`table` IN ('ПродажиУПП', 'Продажи', 'ПосещаемостьМагазинов')) GROUP BY `table`;

CREATE VIEW `zendendb`.`sales_report_warehouses_shops_goods` (`ГодМесяц` UInt32, `Год` UInt16, `Период` Date, `НоменклатураГуид` UUID, `МагазинГуид` UUID, `Продажи, шт` Decimal(10, 2), `Продажи, руб` Decimal(10, 2), `Продажи в СС` Decimal(10, 2), `Вал` Decimal(10, 2), `Остатки` Int32, `Остатки в СС` Decimal(10, 2), `КодДляОбмена` UInt32, `Магазин` Nullable(String), `Магазин Родитель` LowCardinality(Nullable(String)), `Регион` LowCardinality(Nullable(String)), `Группа` LowCardinality(Nullable(String)), `Магазин Признак LFL` Array(String), `Товар` Nullable(String), `Артикул` Nullable(String), `СвойствоВидОбуви` Nullable(String), `СвойствоГод` Nullable(String), `СвойствоРод` Nullable(String), `СвойствоСезон` Nullable(String), `СвойствоТорговаяМарка` Nullable(String), `ТипНоменклатуры` Nullable(String), `OrderTM` Nullable(String), `СвойствоКоллекцияПроизводства` Nullable(String), `СвойствоКоллекцияПроизводстваКомментарий` Nullable(String), `ПовторАналогНовинка` Nullable(String), `СвойствоПодвидОбуви` Nullable(String), `СвойствоПризнак` Nullable(String), `СвойствоПроизводитель` Nullable(String), `СвойствоСтиль` Nullable(String)) AS SELECT toYYYYMM(s.`Период`) AS `ГодМесяц`, toYear(s.`Период`) AS `Год`, s.`Период` AS `Период`, s.`НоменклатураГуид` AS `НоменклатураГуид`, s.`МагазинГуид` AS `МагазинГуид`, s.`Продажи, шт` AS `Продажи, шт`, s.`Продажи, руб` AS `Продажи, руб`, s.`Продажи в СС` AS `Продажи в СС`, s.`Вал` AS `Вал`, s.`Остатки` AS `Остатки`, s.`Остатки в СС` AS `Остатки в СС`, s.`КодДляОбмена` AS `КодДляОбмена`, m.`Магазин` AS `Магазин`, m.`Магазин Родитель` AS `Магазин Родитель`, m.`Регион` AS `Регион`, m.`Группа` AS `Группа`, m.`Магазин Признак LFL` AS `Магазин Признак LFL`, t.`Товар` AS `Товар`, t.`Артикул` AS `Артикул`, t.`СвойствоВидОбуви` AS `СвойствоВидОбуви`, t.`СвойствоГод` AS `СвойствоГод`, t.`СвойствоРод` AS `СвойствоРод`, t.`СвойствоСезон` AS `СвойствоСезон`, t.`СвойствоТорговаяМарка` AS `СвойствоТорговаяМарка`, t.`ТипНоменклатуры` AS `ТипНоменклатуры`, t.OrderTM AS OrderTM, t.`СвойствоКоллекцияПроизводства` AS `СвойствоКоллекцияПроизводства`, t.`СвойствоКоллекцияПроизводстваКомментарий` AS `СвойствоКоллекцияПроизводстваКомментарий`, t.`ПовторАналогНовинка` AS `ПовторАналогНовинка`, t.`СвойствоПодвидОбуви` AS `СвойствоПодвидОбуви`, t.`СвойствоПризнак` AS `СвойствоПризнак`, t.`СвойствоПроизводитель` AS `СвойствоПроизводитель`, t.`СвойствоСтиль` AS `СвойствоСтиль` FROM `zendendb`.sales_report_warehouses AS s ANY LEFT JOIN `zendendb`.`Магазины_fix_with_group_short_v` AS m ON m.`МагазинГуид` = s.`МагазинГуид` ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`КодДляОбмена` = s.`КодДляОбмена` SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`sales_report_warehouses_v` AS WITH goods_not_for_sale AS (SELECT `ТоварГуид` FROM `zendendb`.`Товары` AS x WHERE `ТипНоменклатуры` IN ('*не исп. Канц./хоз. товары', '<>', '<Объект не найден> (61:81a2000423cce49211ddd026e53a35a5)', 'Бытовая техника', 'Возмещение убытков', 'Доля в УК', 'Здания', 'ИТ-оборудование', 'Канц./хоз. товары', 'Канцтовары', 'Комплектующие', 'Комплектующие к ПК', 'Компьютерная программа', 'Лагерь', 'Материалы', 'Материалы и оборудование', 'НЕ_ИСП_Комплектующие к ПК', 'НЕ_ИСП_Оргтехника', 'НЕ_ИСП_Электронно-вычислительная техника', 'НМА', 'Не использовать !!!! Для списания IT-оборудования', 'Основные средства', 'Офисная мебель', 'Паллеты', 'Периодические издания', 'Пожарная безопасность', 'Программное обеспечение', 'Реклама и оборудование КНР', 'Реклама и оборудование ТМ', 'Рекламное оборудование', 'Рекламное оборудование (аудио-видео)', 'Светильники', 'Складская техника', 'Сокращенный GTIN', 'Станки', 'СтарыеКанцтовары', 'Строительные материалы', 'Техника (аудио, видео, фото)', 'Торговое оборудование', 'Услуги', 'Услуги (оказанные)', 'Услуги (полученные)', 'Форма для сотрудников', 'Хоз. инвентарь', 'Хоз. товары', 'Электроматериалы', 'автомобили', 'билеты', 'производственный и хозяйственный инвентарь', 'услуги Аренды', '')), sales AS (SELECT toDate(s.Period) AS `Период`, toUUIDOrZero(s.NomenklaturaGuid) AS `НоменклатураГуид`, toUUIDOrZero(s.MagazinGuid) AS `МагазинГуид`, sum(KolichestvoOborot) AS `Продажи, шт`, sum(s.StoimostOborot) AS `Продажи, руб` FROM `zendendb`.`ПродажиПроведенные` AS s LEFT JOIN `zendendb`.`Товары` AS g ON g.`ТоварГуид` = s.NomenklaturaGuid LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = s.MagazinGuid WHERE (g.`КодДляОбмена` NOT IN (SELECT id FROM `zendendb`.`ПродажиИсключения`)) AND (`ТипНоменклатуры` NOT IN ('Пакеты', 'Реклама')) AND (toDate(s.Period) = {start_date:date}) AND (m.`Магазин Родитель` NOT IN ('Zenden', 'Неиспользуемые Zenden', 'Комиссионеры ТМ', '')) GROUP BY toDate(s.Period), toUUIDOrZero(s.NomenklaturaGuid), toUUIDOrZero(s.MagazinGuid)), warehouse AS (SELECT `Период`, `ПодразделениеГуид`, `НоменклатураГуид`, sum(`Количество`) AS `Остатки` FROM `zendendb`.`ТоварыНаСкладахПоДате` AS w LEFT JOIN `zendendb`.`Магазины_fix` AS m ON toUUIDOrZero(m.`МагазинГуид`) = w.`ПодразделениеГуид` WHERE (toDate(`Период`) = {start_date:date}) AND (w.`СкладТип` = 'Основной') AND (w.`НоменклатураГуид` NOT IN (SELECT * FROM goods_not_for_sale)) AND (m.`Магазин Родитель` NOT IN ('Zenden', 'Неиспользуемые Zenden', 'Комиссионеры ТМ', '')) GROUP BY `Период`, `ПодразделениеГуид`, `НоменклатураГуид`), cross_join AS (SELECT `Период`, `НоменклатураГуид`, `МагазинГуид` FROM sales UNION DISTINCT SELECT `Период`, `НоменклатураГуид`, `ПодразделениеГуид` FROM warehouse), sales_warehouse AS (SELECT c.`Период` AS `Период`, c.`НоменклатураГуид` AS `НоменклатураГуид`, c.`МагазинГуид` AS `МагазинГуид`, s.`Продажи, шт` AS `Продажи, шт`, s.`Продажи, руб` AS `Продажи, руб`, w.`Остатки` AS `Остатки` FROM cross_join AS c LEFT JOIN sales AS s ON (s.`МагазинГуид` = c.`МагазинГуид`) AND (c.`НоменклатураГуид` = s.`НоменклатураГуид`) LEFT JOIN warehouse AS w ON (w.`ПодразделениеГуид` = c.`МагазинГуид`) AND (c.`НоменклатураГуид` = w.`НоменклатураГуид`)), cost AS (SELECT half, guidSales, argMin(value_rub, price_type) AS value_rub FROM `zendendb`.`Себестоимость_по_полугодиям` WHERE toDate(half) = if(toMonth({start_date:date}) <= 6, toStartOfYear({start_date:date}), toStartOfYear({start_date:date}) + toIntervalMonth(6)) GROUP BY half, guidSales) SELECT s.`Период` AS `Период`, s.`НоменклатураГуид` AS `НоменклатураГуид`, s.`МагазинГуид` AS `МагазинГуид`, s.`Продажи, шт` AS `Продажи, шт`, s.`Продажи, руб` AS `Продажи, руб`, cc.value_rub * `Продажи, шт` AS `Продажи в СС`, s.`Продажи, руб` - (cc.value_rub * `Продажи, шт`) AS `Вал`, s.`Остатки` AS `Остатки`, cc.value_rub * `Остатки` AS `Остатки в СС`, g.`КодДляОбмена` AS `КодДляОбмена` FROM sales_warehouse AS s LEFT JOIN cost AS cc ON (cc.half = if(toMonth(s.`Период`) <= 6, toStartOfYear(s.`Период`), toStartOfYear(s.`Период`) + toIntervalMonth(6))) AND (toUUIDOrZero(cc.guidSales) = s.`НоменклатураГуид`) ANY LEFT JOIN `zendendb`.`Товары_v` AS g ON toUUIDOrZero(g.`ТоварГуидЦР`) = s.`НоменклатураГуид` WHERE ((((((ifNull(`Продажи, шт`, 0) + ifNull(`Продажи, руб`, 0)) + ifNull(`Продажи в СС`, 0)) + ifNull(`Вал`, 0)) + ifNull(`Остатки`, 0)) + ifNull(`Остатки в СС`, 0)) != 0) AND (`КодДляОбмена` != 0) SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`stock_art_mapping_v` (`mp` Nullable(String), `art_mp` String, `art` Nullable(String), `kdo` UInt32) AS WITH stock AS (SELECT kdo, mp_gr AS mp, 'stock' AS art_mp FROM `zendendb`.Stock_TM_MP_UPP AS t LEFT JOIN `zendendb`.TM_MP_mapping AS m ON m.mp = t.warehouse UNION DISTINCT SELECT kdo, mp_gr AS mp, 'stock' AS art_mp FROM `zendendb`.Stock_TM_MP_CR AS t LEFT JOIN `zendendb`.TM_MP_mapping AS m ON m.mp = t.mp UNION DISTINCT SELECT kdo, mp_gr AS mp, 'stock' AS art_mp FROM `zendendb`.Stock_TM_MP AS t LEFT JOIN `zendendb`.TM_MP_mapping AS m ON m.mp = t.mp UNION DISTINCT SELECT kdo, mp_gr AS mp, 'stock' AS art_mp FROM `zendendb`.Shipments_TM_MP_CR AS t LEFT JOIN `zendendb`.TM_MP_mapping AS m ON m.mp = t.mp) SELECT s.mp, s.art_mp, t.`Артикул` AS art, s.kdo AS kdo FROM stock AS s LEFT JOIN `zendendb`.`Товары` AS t ON s.kdo = t.`КодДляОбмена` WHERE mp IS NOT NULL SETTINGS final = 1, join_use_nulls = 1;

