ль5` AS `Родитель5` FROM `ВТКадроваяИсторияМаксимумДатДляДолжностей` AS m INNER JOIN `ВТКадроваяИсторияЗаписи` AS k ON (m.`ПериодДействия` = k.`ПериодДействия`) AND (m.`СотрудникГуид` = k.`СотрудникГуид`) AND (m.`ФизическоеЛицоГуид` = k.`ФизическоеЛицоГуид`) AND (m.`Организация` = k.`Организация`) AND (m.`Подразделение` = k.`Подразделение`) AND (m.`Период` = k.`Период`) LEFT JOIN `МестоПозицииШтатногоРасписанияВСтруктуреПредприятия` AS s ON toUUID(s.`ПозицияГуид`) = k.`ДолжностьПоШтатномуРасписаниюГуид`), `ВТДанныеСУпрПодразделениями` AS (SELECT gr.`Период`, gr.`Организация`, gr.`СотрудникГуид`, gr.`ФизическоеЛицоГуид`, gr.`ФизическоеЛицо`, gr.`Сотрудник`, gr.`СтатьяФинансирования`, gr.`Подразделение`, gr.`Начисление`, gr.`Группа`, gr.`ГруппаПорядок`, gr.`ОтработаноДней`, gr.`ОтработаноЧасов`, gr.`Сумма`, gr.`ДатаКадровойИстории`, s.`Должность`, multiIf(s.`ДолжностьПоШтатномуРасписанию` IS NULL, s.`Должность`, s.`ДолжностьПоШтатномуРасписанию`) AS `ДолжностьУправленческая`, s.`Позиция`, multiIf(s.`ПодразделениеУправленческое` IS NULL, st.`Наименование`, s.`ПодразделениеУправленческое`) AS `ПодразделениеУправленческое`, gr.`ПодразделениеКодМагазина`, multiIf(s.`Родитель1` IS NULL, st.`Родитель1`, s.`Родитель1`) AS `Родитель1`, multiIf(s.`Родитель2` IS NULL, st.`Родитель2`, s.`Родитель2`) AS `Родитель2`, multiIf(s.`Родитель3` IS NULL, st.`Родитель3`, s.`Родитель3`) AS `Родитель3`, multiIf(s.`Родитель4` IS NULL, st.`Родитель4`, s.`Родитель4`) AS `Родитель4`, multiIf(s.`Родитель5` IS NULL, st.`Родитель5`, s.`Родитель5`) AS `Родитель5` FROM `ВТВсеСуммыПоГруппам` AS gr LEFT JOIN `ВТКадроваяИсторияДляСпособаСрезНаДату` AS s ON (gr.`СотрудникГуид` = s.`СотрудникГуид`) AND (gr.`ДатаКадровойИстории` = s.`Период`) AND (gr.`Организация` = s.`Организация`) AND (gr.`ФизическоеЛицоГуид` = s.`ФизическоеЛицоГуид`) LEFT JOIN `Структура` AS st ON (st.`КодМагазина` = gr.`ПодразделениеКодМагазина`) AND (st.`КодМагазина` > 0) WHERE `СпособПолученияКадровойИстории` = 'СрезНаДату' UNION ALL SELECT gr.`Период`, gr.`Организация`, gr.`СотрудникГуид`, gr.`ФизическоеЛицоГуид`, gr.`ФизическоеЛицо`, gr.`Сотрудник`, gr.`СтатьяФинансирования`, gr.`Подразделение`, gr.`Начисление`, gr.`Группа`, gr.`ГруппаПорядок`, gr.`ОтработаноДней`, gr.`ОтработаноЧасов`, gr.`Сумма`, gr.`ДатаКадровойИстории`, s.`Должность`, multiIf(s.`ДолжностьПоШтатномуРасписанию` IS NULL, s.`Должность`, s.`ДолжностьПоШтатномуРасписанию`) AS `ДолжностьУправленческая`, s.`Позиция`, multiIf(s.`ПодразделениеУправленческое` IS NULL, st.`Наименование`, s.`ПодразделениеУправленческое`) AS `ПодразделениеУправленческое`, gr.`ПодразделениеКодМагазина`, multiIf(s.`Родитель1` IS NULL, st.`Родитель1`, s.`Родитель1`) AS `Родитель1`, multiIf(s.`Родитель2` IS NULL, st.`Родитель2`, s.`Родитель2`) AS `Родитель2`, multiIf(s.`Родитель3` IS NULL, st.`Родитель3`, s.`Родитель3`) AS `Родитель3`, multiIf(s.`Родитель4` IS NULL, st.`Родитель4`, s.`Родитель4`) AS `Родитель4`, multiIf(s.`Родитель5` IS NULL, st.`Родитель5`, s.`Родитель5`) AS `Родитель5` FROM `ВТВсеСуммыПоГруппам` AS gr LEFT JOIN `ВТКадроваяИсторияДляСпособаПоПериодуДействияИПодразделению` AS s ON (gr.`СотрудникГуид` = s.`СотрудникГуид`) AND (CAST(gr.`ДатаКадровойИстории`, 'DATE') = CAST(s.`ПериодДействия`, 'DATE')) AND (gr.`Организация` = s.`Организация`) AND (gr.`ФизическоеЛицоГуид` = s.`ФизическоеЛицоГуид`) AND (gr.`Подразделение` = s.`Подразделение`) LEFT JOIN `Структура` AS st ON (st.`КодМагазина` = gr.`ПодразделениеКодМагазина`) AND (st.`КодМагазина` > 0) WHERE `СпособПолученияКадровойИстории` = 'ПоПериодуДействияИПодразделению') SELECT * FROM `ВТДанныеСУпрПодразделениями`;

CREATE VIEW `zendendb`.`КадроваяИсторияСотрудников_v` (`ДатаОкончания` DateTime64(0), `ДатаНачала` DateTime64(0), `ПериодПредыдущейЗаписи` DateTime64(0), `ДействуетДо` DateTime64(0), `ПериодЗаписи` DateTime64(0), `СотрудникГуид` UUID, `Сотрудник` String, `ГоловнаяОрганизацияГуид` UUID, `ГоловнаяОрганизация` String, `ФизическоеЛицоГуид` UUID, `ФизическоеЛицо` String, `Организация` String, `ПодразделениеГуид` UUID, `Подразделение` String, `Должность` String, `ДолжностьПоШтатномуРасписаниюГуид` UUID, `ДолжностьПоШтатномуРасписанию` String, `ВидСобытия` String, `КоличествоСтавок` Decimal(38, 6), `КодМагазина` Decimal(38, 6), `Год` Date32, `ДатаВыгрузки` DateTime64(0), `Магазин` Nullable(String), `Магазин Родитель` Nullable(String), `Территориальный Менеджер` Nullable(String)) AS SELECT h.*, m.`Магазин` AS `Магазин`, m.`Магазин Родитель` AS `Магазин Родитель`, m.`Территорияальный Менеджер` AS `Территориальный Менеджер` FROM `zendendb`.`КадроваяИсторияСотрудников` AS h LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`КодМагазина` = h.`КодМагазина` WHERE (m.`Магазин Родитель` IN (SELECT * FROM `zendendb`.`Магазины_Родители_v`)) AND (h.`Должность` IN ('Продавец-кассир', 'Заместитель управляющего обособленным подразделением', 'Управляющий обособленным подразделением', 'Продавец-кассир выходного дня', 'Работник торгового зала', 'Кассир')) SETTINGS join_use_nulls = 1;

CREATE VIEW `zendendb`.`Магазины для LFL_v` (`МагазинГуид` String, `Магазин` String, `Магазин Признак LFL` Array(String)) AS WITH LFL_shops AS (SELECT t.`МагазинГуид` AS `МагазинГуид`, t.`Магазин` AS `Магазин`, t.half, concat(multiIf((m.`Магазин Родитель` IN ('Salamander', 'Закрытые SALAMANDER')), 'SR_', (m.`Магазин Родитель` IN ('MUNZ STORE', 'Неиспользуемые ТМ', 'TM Concept', 'Thomas Munz')), 'TM_', '_'), toString(t.`Год`), '/', toString(t.`Год` - 1), '_', multiIf(toMonth(t.half) = 1, '1ПГ', toMonth(t.half) = 7, '2ПГ', '_')) AS LFL FROM `zendendb`.`Магазины для LFL` AS t ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = t.`МагазинГуид`), LFL_count_shop AS (SELECT `МагазинГуид`, `Магазин`, LFL, half, count(*) OVER (PARTITION BY LFL) AS count_shops FROM LFL_shops) SELECT `МагазинГуид`, `Магазин`, groupArray(concat(LFL, ' - ', count_shops, multiIf((count_shops % exp10(length(toString(count_shops)) - 1)) = 1, ' магазин', ((count_shops % exp10(length(toString(count_shops)) - 1)) IN (2, 3, 4)), ' магазина', ' магазинов'))) AS `Магазин Признак LFL` FROM LFL_count_shop GROUP BY `МагазинГуид`, `Магазин`;

CREATE VIEW `zendendb`.`Магазины_fix_v` (`s.Иерархия` Array(String), `s.ВывескаФасадная` String, `s.Дивизиональный Директор` String, `s.Коэффициент` Decimal(10, 2), `Магазин` String, `s.Магазин Родитель` String, `s.МагазинГуид` String, `s.МагазинРодительГуид` String, `s.Региональный Директор` String, `s.Статус Работы` String, `s.Территорияальный Менеджер` String, `Город` String, `Относительно Москвы` Int8, `s.ТипМагазинаУПП` String, `Регион` String, `ТипМагазинаДляПланированияУПП` String, `КодМагазина` Int32, `ДатаЗакрытия` DateTime, `ДатаОткрытия` DateTime) AS WITH shop_change AS (SELECT s.`МагазинГуид`, if(s.`Магазин` LIKE 'МО-Одинцово-О%', 'МО-Одинцово-О Парк-ТМ', s.`Магазин`), s.`МагазинГуид` NOT IN (SELECT s.`МагазинГуид` FROM `zendendb`.`Магазины_fix` AS s), s1.`Магазин` != s.`Магазин`, (s1.`Коэффициент` - s.`Коэффициент`) > 0.1, s1.`Магазин Родитель` != s.`Магазин Родитель`, s1.`ТипМагазинаУПП` != s.`ТипМагазинаУПП`, s1.`Регион` != s.`Регион`, s1.`КодМагазина` != s.`КодМагазина`, s1.`Дивизиональный Директор` != s.`Дивизиональный Директор`, s1.`Региональный Директор` != s.`Региональный Директор`, s1.`Территорияальный Менеджер` != s.`Территорияальный Менеджер` FROM `zendendb`.`Магазины` AS s LEFT JOIN `zendendb`.`Магазины_fix` AS s1 ON s1.`МагазинГуид` = s.`МагазинГуид` WHERE ((s.`МагазинГуид` NOT IN (SELECT s.`МагазинГуид` FROM `zendendb`.`Магазины_fix` AS s)) OR (if(s1.`Магазин` LIKE 'МО-Одинцово-О%', 'МО-Одинцово-О Парк-ТМ', s1.`Магазин`) != if(s.`Магазин` LIKE 'МО-Одинцово-О%', 'МО-Одинцово-О Парк-ТМ', s.`Магазин`)) OR (abs(s1.`Коэффициент` - s.`Коэффициент`) > 0.1) OR (s1.`Магазин Родитель` != s.`Магазин Родитель`) OR (s1.`ТипМагазинаУПП` != s.`ТипМагазинаУПП`) OR (s1.`Регион` != s.`Регион`) OR (s1.`Дивизиональный Директор` != s.`Дивизиональный Директор`) OR (s1.`КодМагазина` != s.`КодМагазина`) OR (s1.`Региональный Директор` != s.`Региональный Директор`) OR (s1.`Территорияальный Менеджер` != s.`Территорияальный Менеджер`)) AND (s.`Магазин Родитель` NOT IN ('НЕИСПОЛЬЗУЕМЫЕ', 'Склады из UPP для RPAS', 'Новый Аналитика', 'РЕЗЕРВ все бренды', ''))), shop_city AS (SELECT *, trimRight(multiIf((m.`Город` IN ('удСанкт Петербург', 'Санкт Петербург')), 'Санкт-Петербург', (m.`Город` IN ('Челябинск и область')), 'Челябинск', ((m.`Город` IS NULL) OR (m.`Город` = '')) AND ((splitByChar('-', m.`Магазин`)[1]) IN ('Санкт', 'Каменск')), concat(splitByChar('-', m.`Магазин`)[1], '-', splitByChar('-', m.`Магазин`)[2]), (m.`Город` IS NULL) OR (m.`Город` = ''), splitByChar('-', m.`Магазин`)[1], m.`Город`)) AS new_city FROM (SELECT * FROM `zendendb`.`Магазины` AS s WHERE s.`МагазинГуид` IN (SELECT `МагазинГуид` FROM shop_change AS s)) AS m), shops AS (SELECT DISTINCT [multiIf((m.`Магазин Родитель` IN ('MUNZ STORE', 'Salamander', 'TM Concept')), 'Munz Group', m.`Магазин Родитель` = 'Розница Mascotte', 'Mascotte', m.`Магазин Родитель` = 'Zenden', 'Zenden', m.`Магазин Родитель`), m.`Магазин Родитель`, m.`Магазин`] AS `Иерархия`, m.`ВывескаФасадная`, m.`Дивизиональный Директор`, m.`Коэффициент`, m.`Магазин`, m.`Магазин Родитель`, m.`МагазинГуид`, m.`МагазинРодительГуид`, m.`Региональный Директор`, m.`Статус Работы`, m.`Территорияальный Менеджер`, m.`ТипМагазинаДляПланированияУПП`, m.`КодМагазина`, trimRight(multiIf((m.new_city NOT IN (SELECT `Город` FROM `zendendb`.`ЧасовыеПояса`)) AND (m.new_city IN ('Мрсква', 'Москва Московская область')), 'Москва', (m.new_city NOT IN (SELECT `Город` FROM `zendendb`.`ЧасовыеПояса`)) AND (m.new_city IN ('МO', 'МО')), 'Московская область', (m.new_city NOT IN (SELECT `Город` FROM `zendendb`.`ЧасовыеПояса`)) AND (m.new_city IN ('Ногинск (Ногинский р-н)')), 'Ногинск', (m.new_city NOT IN (SELECT `Город` FROM `zendendb`.`ЧасовыеПояса`)) AND (m.new_city IN ('п.Новая Адыгея')), 'Новая Адыгея', m.new_city)) AS `Город`, m.`ТипМагазинаУПП` AS `ТипМагазинаУПП`, m.`Регион` AS `Регион` FROM shop_city AS m) SELECT s.`Иерархия`, s.`ВывескаФасадная`, s.`Дивизиональный Директор`, s.`Коэффициент`, if(s.`МагазинГуид` = '607d3258-bb8a-11e5-a683-000c298b1ba7', 'МО-Одинцово-О\'Парк-ТМ', s.`Магазин`) AS `Магазин`, s.`Магазин Родитель`, s.`МагазинГуид`, s.`МагазинРодительГуид`, s.`Региональный Директор`, s.`Статус Работы`, s.`Территорияальный Менеджер`, if((s.`Город` NOT IN (SELECT `Город` FROM `zendendb`.`ЧасовыеПояса`)), concat('!!!', s.`Город`), s.`Город`) AS `Город`, ch.`Относительно Москвы` AS `Относительно Москвы`, s.`ТипМагазинаУПП`, s.`Регион` AS `Регион`, s.`ТипМагазинаДляПланированияУПП` AS `ТипМагазинаДляПланированияУПП`, s.`КодМагазина` AS `КодМагазина`, s1.`ДатаЗакрытия` AS `ДатаЗакрытия`, s1.`ДатаОткрытия` AS `ДатаОткрытия` FROM shops AS s LEFT JOIN `zendendb`.`ЧасовыеПояса` AS ch USING (`Город`) LEFT JOIN `zendendb`.`Магазины_fix` AS s1 ON s1.`МагазинГуид` = s.`МагазинГуид` SETTINGS final = 1;

CREATE VIEW `zendendb`.`Магазины_fix_with_group_short_v` (`Иерархия` Array(String), `Коэффициент` Decimal(10, 2), `Магазин` String, `Магазин Родитель` LowCardinality(String), `МагазинГуид` UUID, `МагазинРодительГуид` UUID, `ТипМагазинаУПП` LowCardinality(String), `Регион` LowCardinality(String), `ТипМагазинаДляПланированияУПП` LowCardinality(String), `КодМагазина` UInt32, `Группа` LowCardinality(String), `Магазин Признак LFL` Array(String)) AS WITH LFL_shops AS (SELECT t.`МагазинГуид` AS `МагазинГуид`, t.half, concat(multiIf((m.`Магазин Родитель` IN ('Salamander', 'Закрытые SALAMANDER')), 'SR_', (m.`Магазин Родитель` IN ('MUNZ STORE', 'Неиспользуемые ТМ', 'TM Concept', 'Thomas Munz')), 'TM_', '_'), toString(t.`Год`), '/', toString(t.`Год` - 1), '_', multiIf(toMonth(t.half) = 1, '1ПГ', toMonth(t.half) = 7, '2ПГ', '_')) AS LFL FROM `zendendb`.`Магазины для LFL` AS t ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = t.`МагазинГуид`), LFL_count_shop AS (SELECT `МагазинГуид`, LFL, half, count(*) OVER (PARTITION BY LFL) AS count_shops FROM LFL_shops), LFL_shops_final AS (SELECT `МагазинГуид`, groupArray(concat(LFL, ' - ', count_shops, multiIf((count_shops % exp10(length(toString(count_shops)) - 1)) = 1, ' магазин', ((count_shops % exp10(length(toString(count_shops)) - 1)) IN (2, 3, 4)), ' магазина', ' магазинов'))) AS `Магазин Признак LFL` FROM LFL_count_shop GROUP BY `МагазинГуид`) SELECT `Иерархия`, `Коэффициент`, `Магазин`, `Магазин Родитель`, toUUIDOrZero(`МагазинГуид`) AS `МагазинГуид`, toUUIDOrZero(`МагазинРодительГуид`) AS `МагазинРодительГуид`, `ТипМагазинаУПП`, `Регион`, `ТипМагазинаДляПланированияУПП`, `КодМагазина`, multiIf((m.`Магазин Родитель` IN ('MUNZ STORE', 'Salamander', 'TM Concept', 'Thomas Munz')), 'Munz Group', m.`Магазин Родитель` = 'Розница Mascotte', 'Mascotte', m.`Магазин Родитель` = 'Zenden', 'Zenden', m.`Магазин Родитель`) AS `Группа`, l.`Магазин Признак LFL` AS `Магазин Признак LFL` FROM `zendendb`.`Магазины_fix` AS m LEFT JOIN LFL_shops_final AS l ON l.`МагазинГуид` = m.`МагазинГуид` SETTINGS final = 1, join_use_nulls = 0;

CREATE VIEW `zendendb`.`Магазины_fix_with_group_v` (`Иерархия` Array(String), `ВывескаФасадная` String, `Дивизиональный Директор` String, `Коэффициент` Decimal(10, 2), `Магазин` String, `Магазин Родитель` String, `МагазинГуид` String, `МагазинРодительГуид` String, `Региональный Директор` String, `Статус Работы` String, `Территорияальный Менеджер` String, `Город` String, `Относительно Москвы` Int8, `ТипМагазинаУПП` String, `Регион` String, `ТипМагазинаДляПланированияУПП` String, `КодМагазина` UInt32, `ДатаЗакрытия` DateTime, `ДатаОткрытия` DateTime, `Группа` String, `Магазин Признак LFL` Array(String)) AS WITH LFL_shops AS (SELECT t.`МагазинГуид` AS `МагазинГуид`, t.half, concat(multiIf((m.`Магазин Родитель` IN ('Salamander', 'Закрытые SALAMANDER')), 'SR_', (m.`Магазин Родитель` IN ('MUNZ STORE', 'Неиспользуемые ТМ', 'TM Concept', 'Thomas Munz')), 'TM_', '_'), toString(t.`Год`), '/', toString(t.`Год` - 1), '_', multiIf(toMonth(t.half) = 1, '1ПГ', toMonth(t.half) = 7, '2ПГ', '_')) AS LFL FROM `zendendb`.`МагазиныLFL` AS t ANY LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = t.`МагазинГуид`), LFL_count_shop AS (SELECT `МагазинГуид`, LFL, half, count(*) OVER (PARTITION BY LFL) AS count_shops FROM LFL_shops), LFL_shops_final AS (SELECT `МагазинГуид`, groupArray(concat(LFL, ' - ', count_shops, multiIf((count_shops % exp10(length(toString(count_shops)) - 1)) = 1, ' магазин', ((count_shops % exp10(length(toString(count_shops)) - 1)) IN (2, 3, 4)), ' магазина', ' магазинов'))) AS `Магазин Признак LFL` FROM LFL_count_shop GROUP BY `МагазинГуид`) SELECT `Иерархия`, `ВывескаФасадная`, `Дивизиональный Директор`, `Коэффициент`, `Магазин`, `Магазин Родитель`, `МагазинГуид`, `МагазинРодительГуид`, `Региональный Директор`, `Статус Работы`, `Территорияальный Менеджер`, if(m.`Город` = 'Ростов', 'Ростов-на-Дону', m.`Город`) AS `Город`, `Относительно Москвы`, `ТипМагазинаУПП`, `Регион`, `ТипМагазинаДляПланированияУПП`, `КодМагазина`, `ДатаЗакрытия`, `ДатаОткрытия`, multiIf((m.`Магазин Родитель` IN ('MUNZ STORE', 'Salamander', 'TM Concept', 'Thomas Munz')), 'Munz Group', m.`Магазин Родитель` = 'Розница Mascotte', 'Mascotte', m.`Магазин Родитель` = 'Zenden', 'Zenden', m.`Магазин Родитель`) AS `Группа`, l.`Магазин Признак LFL` AS `Магазин Признак LFL` FROM `zendendb`.`Магазины_fix` AS m LEFT JOIN LFL_shops_final AS l ON l.`МагазинГуид` = m.`МагазинГуид` SETTINGS final = 1, join_use_nulls = 0;

CREATE VIEW `zendendb`.`Магазины_Родители_v` (`Магазин Родитель` String) AS SELECT DISTINCT s.`Магазин Родитель` FROM `zendendb`.`Магазины` AS s WHERE (`Магазин Родитель` NOT LIKE '%Закрыт%') AND (`Магазин Родитель` NOT LIKE '%Неиспользуемые%') AND (`Магазин Родитель` != '');

CREATE VIEW `zendendb`.`Остатки КМ Mascotte_v` (`Организация` LowCardinality(String), `КодДляОбмена` UInt32, `Номенклатура` String, `ХарактеристикаНоменклатуры` LowCardinality(String), `КМ` String, `timestamp` DateTime, `ОперацияЗаПоследнийГод` LowCardinality(Nullable(String)), `in_stock` Nullable(Bool)) AS WITH not_in AS (SELECT `КМ` FROM `zendendb`.`Остатки КМ Mascotte` AS o WHERE (o.`Организация` = 'Изначальные') AND (o.`КМ` NOT IN (SELECT `КМ` FROM `zendendb`.`Остатки КМ Mascotte` WHERE `Организация` != 'Изначальные'))) SELECT o.*, multiIf(o.`Организация` != 'Изначальные', NULL, NOT (n.`КМ` IS NULL), true, false) AS in_stock FROM `zendendb`.`Остатки КМ Mascotte` AS o LEFT JOIN not_in AS n ON (n.`КМ` = o.`КМ`) AND (o.`Организация` = 'Изначальные') SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`Остатки КМ Zenden_v` (`Организация` LowCardinality(String), `КодДляОбмена` UInt32, `Номенклатура` String, `ХарактеристикаНоменклатуры` LowCardinality(String), `КМ` String, `timestamp` DateTime, `ОперацияЗаПоследнийГод` LowCardinality(Nullable(String)), `in_stock` Nullable(Bool)) AS WITH not_in AS (SELECT `КМ` FROM `zendendb`.`Остатки КМ Zenden` AS o WHERE (o.`Организация` = 'Изначальные') AND (o.`КМ` NOT IN (SELECT `КМ` FROM `zendendb`.`Остатки КМ Zenden` WHERE `Организация` != 'Изначальные'))) SELECT o.*, multiIf(o.`Организация` != 'Изначальные', NULL, NOT (n.`КМ` IS NULL), true, false) AS in_stock FROM `zendendb`.`Остатки КМ Zenden` AS o LEFT JOIN not_in AS n ON (n.`КМ` = o.`КМ`) AND (o.`Организация` = 'Изначальные') SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`Остатки КМ_v` (`Организация` LowCardinality(String), `КодДляОбмена` UInt32, `Номенклатура` String, `ХарактеристикаНоменклатуры` LowCardinality(String), `КМ` String, `timestamp` DateTime, `ОперацияЗаПоследнийГод` LowCardinality(Nullable(String)), `in_stock` Nullable(Bool)) AS WITH not_in AS (SELECT `КМ` FROM `zendendb`.`Остатки КМ` AS o WHERE (o.`Организация` = 'Изначальные') AND (o.`КМ` NOT IN (SELECT `КМ` FROM `zendendb`.`Остатки КМ` WHERE `Организация` != 'Изначальные'))) SELECT o.*, multiIf(o.`Организация` != 'Изначальные', NULL, NOT (n.`КМ` IS NULL), true, false) AS in_stock FROM `zendendb`.`Остатки КМ` AS o LEFT JOIN not_in AS n ON (n.`КМ` = o.`КМ`) AND (o.`Организация` = 'Изначальные') SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`ПосещаемостьМагазинов_v` (`Период` DateTime, `Вошло` Int64, `Вышло` Int64, `Трафик` Nullable(Float64), `Магазин Родитель` Nullable(String), `Регион` Nullable(String), `Магазин` Nullable(String), `Признаки LFL` Array(String)) AS SELECT t.`Период` AS `Период`, (t.`КоличествоВошло` + t.`РучКорВошло`) + t.`АвтКорВошло` AS `Вошло`, (t.`КоличествоВышло` + t.`РучКорВышло`) + t.`АвтКорВышло` AS `Вышло`, ((((((t.`КоличествоВошло` + t.`РучКорВошло`) + t.`АвтКорВошло`) + t.`КоличествоВышло`) + t.`РучКорВышло`) + t.`АвтКорВышло`) * 0.5) * if(m.`Коэффициент` = 0, 1, m.`Коэффициент`) AS `Трафик`, m.`Магазин Родитель` AS `Магазин Родитель`, m.`Регион` AS `Регион`, m.`Магазин` AS `Магазин`, m.`Магазин Признак LFL` AS `Признаки LFL` FROM `zendendb`.`ПосещаемостьМагазинов` AS t ANY LEFT JOIN `zendendb`.`Магазины_fix_with_group_v` AS m ON t.`МагагазинГуид` = m.`МагазинГуид` WHERE t.`Период` >= '2023-01-01' SETTINGS join_use_nulls = 1;

CREATE VIEW `zendendb`.`ПродажиПродавцыМесяц_v` (`Дата` Nullable(Date), `Регион` Nullable(String), `Магазин Родитель` Nullable(String), `МагазинГуид` Nullable(String), `Магазин` Nullable(String), `Должность` Nullable(String), `Сотрудник` Nullable(String), `Часы` Nullable(Decimal(9, 2)), `Оборот` Nullable(Decimal(38, 2)), `Оборот магазин` Nullable(Decimal(38, 2)), `Оборот План` Nullable(Decimal(38, 3)), `Пары` Nullable(Decimal(38, 3)), `Пары магазин` Nullable(Decimal(38, 3)), `Пары План` Nullable(Decimal(38, 3)), `Чеки` Nullable(Int64), `Чеки магазин` Int64, `Чеки План` Nullable(Decimal(38, 3))) AS WITH sales AS (SELECT toDate(s.Period) AS Period, s.MagazinGuid, s.ProdavetsGuid, s.NomenklaturaGuid, s.StoimostOborot, s.KolichestvoOborot, toUUIDOrDefault(s.UnikalnyyIdentifikatorCHeka, toUUID(hex(sipHash128(s.Period, s.MagazinGuid, s.NomerCHekaKKM)))) AS UnikalnyyIdentifikatorCHeka, s.VidOperatsii FROM `zendendb`.`ПродажиПроведенные` AS s WHERE (toDate(s.Period) < today()) AND (toDate(s.Period) >= (SELECT min(`Дата`) FROM `zendendb`.`РабочееВремя` FINAL))), sales_by_saler AS (SELECT toDate(s.Period) AS `Дата`, s.MagazinGuid AS MagazinGuid, s.ProdavetsGuid AS ProdavetsGuid, fl.`Наименование` AS Prodavets, if(fl.`Должность` = '', h.`Должность`, fl.`Должность`) AS `Должность`, sum(s.StoimostOborot) AS `Оборот`, sumIf(s.KolichestvoOborot, (t.`ТипНоменклатуры` IN ('Обувь'))) AS `Пары`, countIfDistinct(s.UnikalnyyIdentifikatorCHeka, (s.VidOperatsii IN ('продажа'))) - countIfDistinct(s.UnikalnyyIdentifikatorCHeka, (s.VidOperatsii NOT IN ('продажа'))) AS `Чеки` FROM sales AS s ANY LEFT JOIN `zendendb`.`Товары` AS t ON t.`ТоварГуид` = s.NomenklaturaGuid ANY LEFT JOIN `zendendb`.`ФизическиеЛица` AS fl ON fl.`ПродавецГуид` = s.ProdavetsGuid LEFT JOIN (SELECT `СотрудникГуид`, toYYYYMM(`Дата`) AS `МесяцДата`, argMax(`Должность`, `Дата`) AS `Должность` FROM `zendendb`.`РабочееВремя` GROUP BY `СотрудникГуид`, toYYYYMM(`Дата`)) AS h ON (h.`СотрудникГуид` = s.ProdavetsGuid) AND (h.`МесяцДата` = toYYYYMM(Period)) GROUP BY s.MagazinGuid, s.ProdavetsGuid, fl.`Наименование`, `Должность`, toDate(s.Period)), shop_plan AS (SELECT `Дата`, `МагазинГуид`, `Магазин`, sum(`Оборот`) AS `Оборот План`, sum(`Чеки`) AS `Чеки План`, sum(`Пары`) AS `Пары План` FROM `zendendb`.`ПланПродаж` AS pp FINAL WHERE `Дата` < today() GROUP BY `МагазинГуид`, `Магазин`, `Дата`), shop_data AS (SELECT ifNull(h.`МагазинГуид`, s.MagazinGuid) AS `МагазинГуид`, ifNull(h.`Дата`, toDate(s.Period)) AS `Дата`, sum(s.StoimostOborot) AS `Оборот магазин`, sumIf(s.KolichestvoOborot, (t.`ТипНоменклатуры` IN ('Обувь'))) AS `Пары магазин`, countIfDistinct(s.UnikalnyyIdentifikatorCHeka, (s.VidOperatsii IN ('продажа'))) - countIfDistinct(s.UnikalnyyIdentifikatorCHeka, (s.VidOperatsii NOT IN ('продажа'))) AS `Чеки магазин`, max(p.`Оборот План`) AS `Оборот План`, max(p.`Пары План`) AS `Пары План`, max(p.`Чеки План`) AS `Чеки План` FROM sales AS s FULL OUTER JOIN `zendendb`.`РабочееВремя` AS h FINAL ON (h.`СотрудникГуид` = s.ProdavetsGuid) AND (h.`МагазинГуид` = s.MagazinGuid) AND (h.`Дата` = toDate(s.Period)) LEFT JOIN shop_plan AS p ON (p.`МагазинГуид` = h.`МагазинГуид`) AND (p.`Дата` = h.`Дата`) ANY LEFT JOIN `zendendb`.`Товары` AS t ON t.`ТоварГуид` = s.NomenklaturaGuid GROUP BY `МагазинГуид`, `Дата`), union_report AS (SELECT ifNull(s.`Дата`, h.`Дата`) AS `Дата`, ifNull(s.MagazinGuid, h.`МагазинГуид`) AS `МагазинГуид`, ifNull(s.`Должность`, h.`Должность`) AS `Должность`, ifNull(s.ProdavetsGuid, h.`СотрудникГуид`) AS `СотрудникГуид`, ifNull(s.Prodavets, h.`Сотрудник`) AS `Сотрудник`, h.`Часы` AS `Часы`, s.`Оборот` AS `Оборот`, s.`Пары` AS `Пары`, s.`Чеки` AS `Чеки`, 0 AS `Оборот магазин`, 0 AS `Пары магазин`, 0 AS `Чеки магазин`, 0 AS `Оборот План`, 0 AS `Пары План`, 0 AS `Чеки План` FROM `zendendb`.`РабочееВремя` AS h FINAL FULL OUTER JOIN sales_by_saler AS s ON (h.`Сотрудник` = s.Prodavets) AND (h.`МагазинГуид` = s.MagazinGuid) AND (h.`Дата` = s.`Дата`) UNION ALL SELECT sd.`Дата` AS `Дата`, m.`МагазинГуид` AS `МагазинГуид`, '' AS `Должность`, '' AS `СотрудникГуид`, '' AS `Сотрудник`, 0 AS `Часы`, 0 AS `Оборот`, 0 AS `Пары`, 0 AS `Чеки`, sd.`Оборот магазин` AS `Оборот магазин`, sd.`Пары магазин` AS `Пары магазин`, sd.`Чеки магазин` AS `Чеки магазин`, sd.`Оборот План` AS `Оборот План`, sd.`Пары План` AS `Пары План`, sd.`Чеки План` AS `Чеки План` FROM shop_data AS sd LEFT JOIN `zendendb`.`Магазины_fix` AS m FINAL ON m.`МагазинГуид` = sd.`МагазинГуид`), employees AS (SELECT `Сотрудник`, arrayStringConcat(arraySlice(splitByWhitespace(`Сотрудник`), 1, 3), ' ') AS `Сотрудник_join`, argMax(`Должность`, `ДатаНачала`) AS `Должность`, `КодМагазина`, m.`МагазинГуид` AS `МагазинГуид`, argMax(`ВидСобытия`, `ВидСобытия`) AS `ВидСобытия`, toDate(`ДатаНачала`) AS `ДатаНачала`, toDate(`ДатаОкончания`) AS `ДатаОкончания` FROM `zendendb`.`КадроваяИсторияСотрудников` AS k LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`КодМагазина` = k.`КодМагазина` GROUP BY `Сотрудник`, `ДатаНачала`, `ДатаОкончания`, `КодМагазина`, m.`МагазинГуид`, `Сотрудник_join`), employees_dates AS (SELECT DISTINCT s.`Дата` AS `Дата`, s.`МагазинГуид` AS `МагазинГуид`, max(ifNull(k.`Должность`, s.`Должность`)) AS `Должность`, s.`СотрудникГуид` AS `СотрудникГуид`, s.`Сотрудник` AS `Сотрудник`, k.`Сотрудник_join` FROM union_report AS s LEFT JOIN employees AS k ON (k.`Сотрудник_join` = s.`Сотрудник`) AND (k.`МагазинГуид` = s.`МагазинГуид`) WHERE ((k.`ДатаНачала` <= s.`Дата`) OR (k.`ДатаНачала` IS NULL)) AND ((k.`ДатаОкончания` > s.`Дата`) OR (k.`ДатаОкончания` IS NULL)) AND ((k.`ВидСобытия` NOT IN ('Неподтвержденные данные', 'Увольнение')) OR (k.`ВидСобытия` IS NULL)) GROUP BY `Дата`, `МагазинГуид`, `СотрудникГуид`, `Сотрудник`, k.`Сотрудник_join`) SELECT s.`Дата` AS `Дата`, m.`Регион` AS `Регион`, m.`Магазин Родитель` AS `Магазин Родитель`, s.`МагазинГуид` AS `МагазинГуид`, m.`Магазин` AS `Магазин`, ifNull(k.`Должность`, s.`Должность`) AS `Должность`, s.`Сотрудник` AS `Сотрудник`, `Часы` AS `Часы`, `Оборот` AS `Оборот`, `Оборот магазин` AS `Оборот магазин`, `Оборот План` AS `Оборот План`, `Пары` AS `Пары`, `Пары магазин` AS `Пары магазин`, `Пары План` AS `Пары План`, `Чеки` AS `Чеки`, `Чеки магазин` AS `Чеки магазин`, `Чеки План` AS `Чеки План` FROM union_report AS s LEFT JOIN `zendendb`.`Магазины_fix` AS m ON m.`МагазинГуид` = s.`МагазинГуид` LEFT JOIN employees_dates AS k ON (k.`Сотрудник` = s.`Сотрудник`) AND (k.`МагазинГуид` = s.`МагазинГуид`) AND (k.`Дата` = s.`Дата`) SETTINGS join_use_nulls = 1, final = 1;

CREATE VIEW `zendendb`.`ПродажиУПП_MP_TM_v` (`dt` Date, `mp` LowCardinality(Nullable(String)), `kdo` Nullable(UInt32), `qty` Decimal(38, 3), `turnover` Decimal(38, 2), `gross` Nullable(Decimal(38, 8))) AS SELECT toDate(s.`Период`) AS dt, group_str AS mp, t.`КодДляОбмена` AS kdo, sumIf(s.`Количество`, s.`СтоимостьРегл` != 0) AS qty, sum(s.`СтоимостьРегл`) AS turnover, sum(s.`СтоимостьРегл` - (s.`Количество` * c.value_rub)) AS gross FROM `zendendb`.`ПродажиУПП` AS s ANY LEFT JOIN `zendendb`.TM_MP_mapping AS mpm ON (mpm.value_str = s.`Контрагент`) AND (mpm.mapping_type = 'Склад') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`ТоварГуид` = s.`ТоварГуид` ANY LEFT JOIN `zendendb`.`Себестоимость_по_полугодиям` AS c ON (c.half = if(toMonth(s.`Период`) <= 6, toStartOfYear(s.`Период`), toStartOfYear(s.`Период`) + toIntervalMonth(6))) AND (c.kdo = t.`КодДляОбмена`) WHERE (s.`Организация` = 'Мюнц Групп ООО') AND (s.`Контрагент` IN ('Вайлдберриз-Thomas Muenz', 'Вайлдберриз ООО', 'Интернет Решения ООО Thomas Munz (Озон)', 'Купишуз ООО', 'МАРКЕТПЛЕЙС ООО', 'РВБ ООО', 'Яндекс Маркет ООО', 'Яндекс ООО')) AND (t.`ТипНоменклатуры` NOT IN ('Услуги', 'Услуги (оказанные)', 'Услуги (полученные)')) GROUP BY dt, mp, kdo SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`ПродажиУПП_by_size_MP_TM_v` (`dt` Date, `mp` LowCardinality(Nullable(String)), `kdo` Nullable(UInt32), `size` Nullable(String), `qty` Decimal(38, 3), `turnover` Decimal(38, 2)) AS SELECT toDate(s.`Период`) AS dt, group_str AS mp, t.`КодДляОбмена` AS kdo, s.`ХарактеристикаНоменклатуры` AS size, sum(s.`Количество`) AS qty, sum(s.`СтоимостьРегл`) AS turnover FROM `zendendb`.`ПродажиУПП` AS s ANY LEFT JOIN `zendendb`.TM_MP_mapping AS mpm ON (mpm.value_str = s.`Контрагент`) AND (mpm.mapping_type = 'Контрагент') ANY LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`ТоварГуид` = s.`ТоварГуид` WHERE (s.`Организация` = 'Мюнц Групп ООО') AND (s.`Контрагент` IN ('Вайлдберриз-Thomas Muenz', 'Вайлдберриз ООО', 'Интернет Решения ООО Thomas Munz (Озон)', 'Купишуз ООО', 'МАРКЕТПЛЕЙС ООО', 'РВБ ООО', 'Яндекс Маркет ООО', 'Яндекс ООО')) AND (t.`ТипНоменклатуры` NOT IN ('Услуги', 'Услуги (оказанные)', 'Услуги (полученные)')) GROUP BY dt, mp, kdo, size ORDER BY dt DESC SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`ПродажиУПП_duplicate_v` (`id` String, `ЗаказПокупателя` Nullable(String), `Количество` Decimal(15, 3), `Контрагент` String, `Номенклатура` String, `НоменклатураАртикул` Nullable(String), `НомерСтроки` UInt32, `Организация` String, `Период` DateTime, `Подразделение` Nullable(String), `Проект` Nullable(String), `Стоимость` Decimal(15, 2), `СтоимостьБезСкидок` Decimal(15, 2), `СтоимостьРегл` Decimal(15, 2), `ТоварГуид` String, `ХарактеристикаНоменклатуры` Nullable(String), `ХарактеристикаНоменклатурыГуид` Nullable(String), `Регистратор` String, `КорректировкаЗаписейРегистров` Nullable(String)) AS SELECT s.* FROM `zendendb`.`ПродажиУПП` AS s WHERE if(((toDate(s.`Период`) >= '2026-03-30') AND (toDate(s.`Период`) <= '2026-04-06')) AND (s.`Контрагент` = 'РВБ ООО') AND (s.`Организация` = 'Мюнц Групп ООО'), 0, 1) = 1 UNION ALL SELECT s.* FROM `zendendb`.`ПродажиУПП` AS s WHERE (if(((toDate(s.`Период`) >= '2026-03-30') AND (toDate(s.`Период`) <= '2026-04-06')) AND (s.`Контрагент` = 'РВБ ООО') AND (s.`Организация` = 'Мюнц Групп ООО'), 1, 0) = 1) AND (s.`Проект` = '\\N');

CREATE VIEW `zendendb`.`Себестоимость_по_дням_v` (`date` Date, `guid` String, `kdo` UInt32, `value_rub` Nullable(Decimal(15, 2))) AS SELECT s.* FROM `zendendb`.`Себестоимость_по_дням` AS s FINAL INNER JOIN `zendendb`.`Товары` AS t ON t.`ТоварГуид` = s.guid WHERE t.`ТипНоменклатуры` NOT IN ('Рекламное оборудование', 'ИТ-оборудование', 'Реклама', 'Электроматериалы', 'Строительные материалы', 'Оборудование', 'Хоз. товары', 'Торговое оборудование', 'Реклама и оборудование КНР', 'Канцтовары', '*не исп. Канц./хоз. товары', 'автомобили', 'АХО', 'Возмещение убытков', 'Доля в УК', 'Комплектующие', 'Компьютерная программа', 'Лагерь', 'Маркетинговые материалы', 'НЕ товары', 'Офисная мебель', 'производственный и хозяйственный инвентарь', 'Реклама и оборудование ТМ', 'Рекламное оборудование (аудио-видео)', 'Складская техника');

CREATE VIEW `zendendb`.`ТоварнаяМатрица_На_Сегодня_v` (`m.ТоварГуид` String, `m.Номенклатура` String, `m.ВидОбуви` String, `m.Артикул` String, `m.КодДляОбмена` Int32, `m.Род` String, `m.ТорговаяМарка` String, `m.ВидНоменклатуры` String, `m.Сезон` String, `m.Год` String, `m.CтартПродаж` Date, `m.Рейтинг общий` Decimal(38, 2), `m.Рейтинг ИМ` Nullable(Decimal(38, 2)), `m.Продажи сеть Всего` Nullable(Int64), `m.Продажи ИМ Всего` Nullable(Int64), `m.Продажи Всего` Nullable(Int64), `m.Заказы ИМ Всего` Nullable(Int64), `m.Продажи сеть 360` Nullable(Int64), `m.Продажи ИМ 360` Nullable(Int64), `m.Продажи 360` Int64, `m.Заказы ИМ 360` Nullable(Int64), `m.Продажи сеть 180` Nullable(Int64), `m.Продажи ИМ 180` Nullable(Int64), `m.Продажи 180` Int64, `m.Заказы ИМ 180` Nullable(Int64), `m.Продажи сеть 90` Nullable(Int64), `m.Продажи ИМ 90` Nullable(Int64), `m.Продажи 90` Int64, `m.Заказы ИМ 90` Nullable(Int64), `m.Продажи сеть 30` Nullable(Int64), `m.Продажи ИМ 30` Nullable(Int64), `m.Продажи 30` Int64, `m.Заказы ИМ 30` Nullable(Int64), `m.Заказы ИМ W1` Nullable(Int64), `m.Заказы ИМ W2` Nullable(Int64), `m.Заказы ИМ W3` Nullable(Int64), `m.Заказы ИМ W4` Nullable(Int64), `w.КоличествоРозница` Nullable(Int32), `w.КоличествоИМ` Nullable(Int32), `p.ЦенаРозница` Nullable(Int32), `p.ЦенаСкидка` Nullable(Float64), `p.ЦенаИМ` Nullable(Int32)) AS WITH matrix AS (SELECT `ТоварГуид`, `Номенклатура`, `ВидОбуви`, `Артикул`, `КодДляОбмена`, `Род`, `ТорговаяМарка`, `ВидНоменклатуры`, `Сезон`, `Год`, min(`CтартПродаж`) AS `CтартПродаж`, ifNull(sumIf(m.`ВыручкаРозница`, m.`Дата` >= (today() - 30)), 0) + ifNull(sumIf(m.`ВыручкаИМ`, m.`Дата` >= (today() - 30)), 0) AS `Рейтинг общий`, sumIf(m.`ВыручкаИМ`, m.`Дата` >= (today() - 30)) AS `Рейтинг ИМ`, sum(m.`КоличествоРозница`) AS `Продажи сеть Всего`, sum(m.`КоличествоИМ`) AS `Продажи ИМ Всего`, sum(m.`КоличествоРозница`) + sum(m.`КоличествоИМ`) AS `Продажи Всего`, sum(m.`ЗаказыИМ`) AS `Заказы ИМ Всего`, sumIf(m.`КоличествоРозница`, m.`Дата` >= (today() - 360)) AS `Продажи сеть 360`, sumIf(m.`КоличествоИМ`, m.`Дата` >= (today() - 360)) AS `Продажи ИМ 360`, ifNull(sumIf(m.`КоличествоРозница`, m.`Дата` >= (today() - 360)), 0) + ifNull(sumIf(m.`КоличествоИМ`, m.`Дата` >= (today() - 90)), 0) AS `Продажи 360`, sumIf(m.`ЗаказыИМ`, m.`Дата` >= (today() - 360)) AS `Заказы ИМ 360`, sumIf(m.`КоличествоРозница`, m.`Дата` >= (today() - 180)) AS `Продажи сеть 180`, sumIf(m.`КоличествоИМ`, m.`Дата` >= (today() - 180)) AS `Продажи ИМ 180`, ifNull(sumIf(m.`КоличествоРозница`, m.`Дата` >= (today() - 180)), 0) + ifNull(sumIf(m.`КоличествоИМ`, m.`Дата` >= (today() - 180)), 0) AS `Продажи 180`, sumIf(m.`ЗаказыИМ`, m.`Дата` >= (today() - 180)) AS `Заказы ИМ 180`, sumIf(m.`КоличествоРозница`, m.`Дата` >= (today() - 90)) AS `Продажи сеть 90`, sumIf(m.`КоличествоИМ`, m.`Дата` >= (today() - 90)) AS `Продажи ИМ 90`, ifNull(sumIf(m.`КоличествоРозница`, m.`Дата` >= (today() - 90)), 0) + ifNull(sumIf(m.`КоличествоИМ`, m.`Дата` >= (today() - 90)), 0) AS `Продажи 90`, sumIf(m.`ЗаказыИМ`, m.`Дата` >= (today() - 90)) AS `Заказы ИМ 90`, sumIf(m.`КоличествоРозница`, m.`Дата` >= (today() - 30)) AS `Продажи сеть 30`, sumIf(m.`КоличествоИМ`, m.`Дата` >= (today() - 30)) AS `Продажи ИМ 30`, ifNull(sumIf(m.`КоличествоРозница`, m.`Дата` >= (today() - 30)), 0) + ifNull(sumIf(m.`КоличествоИМ`, m.`Дата` >= (today() - 30)), 0) AS `Продажи 30`, sumIf(m.`ЗаказыИМ`, m.`Дата` >= (today() - 30)) AS `Заказы ИМ 30`, sumIf(m.`ЗаказыИМ`, m.`Дата` >= (today() - 8)) AS `Заказы ИМ W1`, sumIf(m.`ЗаказыИМ`, (m.`Дата` >= (today() - 14)) AND (m.`Дата` < (today() - 7))) AS `Заказы ИМ W2`, sumIf(m.`ЗаказыИМ`, (m.`Дата` >= (today() - 21)) AND (m.`Дата` < (today() - 14))) AS `Заказы ИМ W3`, sumIf(m.`ЗаказыИМ`, (m.`Дата` >= (today() - 28)) AND (m.`Дата` < (today() - 21))) AS `Заказы ИМ W4` FROM `zendendb`.`ТоварнаяМатрицаПродаж` AS m GROUP BY `ТоварГуид`, `Номенклатура`, `ВидОбуви`, `Артикул`, `КодДляОбмена`, `Род`, `ТорговаяМарка`, `ВидНоменклатуры`, `Сезон`, `Год`), werehouse AS (SELECT ifNull(w.`НоменклатураГуид`, w2.`НоменклатураГуид`) AS `НоменклатураГуид`, w.`Количество` AS `КоличествоРозница`, w2.`Количество` AS `КоличествоИМ` FROM (SELECT * FROM `zendendb`.`ТоварыНаСкладахНаСегодня` WHERE `Розница` = 1) AS w FULL OUTER JOIN (SELECT * FROM `zendendb`.`ТоварыНаСкладахНаСегодня` WHERE `Розница` = 0) AS w2 ON w.`НоменклатураГуид` = w2.`НоменклатураГуид`), prices AS (SELECT ifNull(p.`НоменклатураГуид`, p2.`НоменклатураГуид`) AS `НоменклатураГуид`, p.`Цена` AS `ЦенаРозница`, round((p.`Цена` * (100 - p.`ПроцентСкидки`)) * 0.01, 0) AS `ЦенаСкидка`, p2.`Цена` AS `ЦенаИМ` FROM (SELECT * FROM `zendendb`.`ЦеныЦРСоСкидками_На_Сегодня` WHERE (`Розница` = 1) AND (`Подразделение` = 'Москва-Авиапарк')) AS p FULL OUTER JOIN (SELECT * FROM `zendendb`.`ЦеныЦРСоСкидками_На_Сегодня` WHERE `Розница` = 0) AS p2 ON p.`НоменклатураГуид` = p2.`НоменклатураГуид`) SELECT m.*, w.`КоличествоРозница`, w.`КоличествоИМ`, p.`ЦенаРозница`, p.`ЦенаСкидка`, p.`ЦенаИМ` FROM matrix AS m LEFT JOIN werehouse AS w ON w.`НоменклатураГуид` = m.`ТоварГуид` LEFT JOIN prices AS p ON p.`НоменклатураГуид` = m.`ТоварГуид` SETTINGS join_use_nulls = 1;

CREATE VIEW `zendendb`.`ТоварнаяМатрицаПродаж_v` AS WITH sales_filter AS (SELECT toDate(s.`Период`) AS `Дата`, s.`ТоварГуид` AS `ТоварГуид`, s.`Организация` AS `Организация`, s.`СтоимостьРегл` AS `СтоимостьРегл`, s.`Количество` AS `Количество`, `КорректировкаЗаписейРегистров`, dr.`ИнтернетЗаказ` FROM `zendendb`.`ПродажиУПП` AS s ANY LEFT JOIN `zendendb`.`ТоварыОбщие_v` AS t ON t.`ТоварГуид` = s.`ТоварГуид` ANY LEFT JOIN `zendendb`.`ДокументыНаОснованииИнтернет` AS dr ON (s.`Регистратор` = dr.`Документ`) AND (s.`Номенклатура` = dr.`Номенклатура`) AND (s.`ХарактеристикаНоменклатуры` = dr.`Характеристика`) WHERE ((s.`Организация` IN ('САКУРА ООО', 'Сезонная коллекция ООО')) OR ((s.`Организация` = 'Дом Одежды ООО') AND (s.`Контрагент` = 'Дом Одежды  (Интернет-магазин)') AND (dr.`Документ` IS NOT NULL) AND (`КорректировкаЗаписейРегистров` = '\\N'))) AND (t.`ТипНоменклатуры` = 'Обувь') AND (toDate(s.`Период`) >= {start_date:date}) AND (toDate(s.`Период`) < today())), sales AS (SELECT s.`Дата`, s.`ТоварГуид`, s.`Организация` IN ('САКУРА ООО', 'Сезонная коллекция ООО') AS `Розница`, avg(s.`СтоимостьРегл`) AS `ЦенаРеализации`, sum(s.`Количество`) AS `Количество`, sum(s.`СтоимостьРегл` * abs(s.`Количество`)) AS `Выручка`, min(`CтартПродаж`) AS `CтартПродаж` FROM sales_filter AS s LEFT JOIN `zendendb`.`СтартПродаж` AS st ON st.`ТоварГуид` = s.`ТоварГуид` GROUP BY s.`Дата`, s.`ТоварГуид`, `Розница`), goods AS (SELECT t.`ТоварГуид`, t.`КодДляОбмена`, t.`СвойствоВидОбуви`, t.`Товар`, t.`Артикул`, t.`СвойствоРод`, t.`СвойствоТорговаяМарка`, t.`ТипНоменклатуры`, t.`СвойствоСезон`, t.`СвойствоГод`, length(concat(t.`СвойствоВидОбуви`, t.`СвойствоГод`, t.`СвойствоРод`, t.`СвойствоСезон`, t.`СвойствоТорговаяМарка`)) AS info FROM `zendendb`.`ТоварыОбщие_v` AS t WHERE t.`ТипНоменклатуры` = 'Обувь'), i_sales AS (SELECT toDate(z.DATE_INSERT) AS `Дата`, tv.`ТоварГуид` AS `ТоварГуид`, COUNTDistinct(z.ID) AS `ЗаказыИМ`, min(st.`CтартПродаж`) AS `CтартПродаж` FROM `zendendb`.`ЗаказКлиента` AS z FINAL LEFT JOIN (SELECT * FROM `zendendb`.`ЗаказКлиента.Товары` FINAL) AS t ON t.ORDER_ID = z.ID LEFT JOIN `zendendb`.`ТоварыОбщие_v` AS tv ON tv.`КодДляОбмена` = toInt64OrNull(splitByChar('#', assumeNotNull(t.PRODUCT_XML_ID))[1]) LEFT JOIN `zendendb`.`СтартПродаж` AS st ON tv.`ТоварГуид` = st.`ТоварГуид` WHERE (toDate(z.DATE_INSERT) >= {start_date:date}) AND (toDate(z.DATE_INSERT) < today()) AND (z.SHOP_NAME IN ('imshop (Zenden)', 'zenden.ru', 'zenden.ru - ПВЗ', 'zenden.ru - самовывоз', 'zenden.ru - APP')) AND (tv.`ТипНоменклатуры` = 'Обувь') GROUP BY `Дата`, tv.`ТоварГуид`), all_sales AS (SELECT ifNull(rs.`Дата`, ins.`Дата`) AS `Дата`, ifNull(rs.`ТоварГуид`, ins.`ТоварГуид`) AS `ТоварГуид`, rs.`Количество` AS `КоличествоРозница`, ins.`Количество` AS `КоличествоИМ`, rs.`Выручка` AS `ВыручкаРозница`, ins.`Выручка` AS `ВыручкаИМ`, ifNull(rs.`CтартПродаж`, ins.`CтартПродаж`) AS `CтартПродаж` FROM (SELECT * FROM sales AS s WHERE s.`Розница` = 1) AS rs FULL OUTER JOIN (SELECT * FROM sales AS s WHERE s.`Розница` = 0) AS ins ON (ins.`Дата` = rs.`Дата`) AND (rs.`ТоварГуид` = ins.`ТоварГуид`)), all_sales_with_IP AS (SELECT ifNull(s.`Дата`, ins.`Дата`) AS `Дата`, ifNull(s.`ТоварГуид`, ins.`ТоварГуид`) AS `ТоварГуид`, s.`КоличествоРозница`, s.`КоличествоИМ`, s.`ВыручкаРозница`, s.`ВыручкаИМ`, ins.`ЗаказыИМ` AS `ЗаказыИМ`, ifNull(s.`CтартПродаж`, ins.`CтартПродаж`) AS `CтартПродаж` FROM all_sales AS s FULL OUTER JOIN i_sales AS ins ON (ins.`Дата` = s.`Дата`) AND (s.`ТоварГуид` = ins.`ТоварГуид`)), goods_by_art AS (SELECT g.`ТоварГуид` AS `ТоварГуид`, g.`Артикул` AS `Артикул`, g.`КодДляОбмена` AS `КодДляОбмена`, argMax(g.`Товар`, g.info) AS `Номенклатура`, argMax(g.`СвойствоВидОбуви`, g.info) AS `ВидОбуви`, argMax(g.`СвойствоРод`, g.info) AS `Род`, argMax(g.`СвойствоТорговаяМарка`, g.info) AS `ТорговаяМарка`, argMax(g.`ТипНоменклатуры`, g.info) AS `ТипНоменклатуры`, argMax(g.`СвойствоСезон`, g.info) AS `Сезон`, argMax(g.`СвойствоГод`, g.info) AS `Год` FROM goods AS g GROUP BY `Артикул`, `КодДляОбмена`, `ТоварГуид`) SELECT s.`Дата` AS `Дата`, s.`ТоварГуид` AS `ТоварГуид`, g.`Номенклатура` AS `Номенклатура`, g.`ВидОбуви` AS `ВидОбуви`, g.`Артикул` AS `Артикул`, g.`КодДляОбмена` AS `КодДляОбмена`, g.`Род` AS `Род`, g.`ТорговаяМарка` AS `ТорговаяМарка`, g.`ТипНоменклатуры` AS `ВидНоменклатуры`, g.`Сезон` AS `Сезон`, g.`Год` AS `Год`, s.`ВыручкаРозница`, s.`ВыручкаИМ`, s.`КоличествоРозница`, s.`КоличествоИМ`, s.`ЗаказыИМ`, s.`CтартПродаж` FROM all_sales_with_IP AS s LEFT JOIN goods_by_art AS g ON s.`ТоварГуид` = g.`ТоварГуид` SETTINGS join_use_nulls = 1;

CREATE VIEW `zendendb`.`Товары_v` (`ТоварГуид` String, `ТоварГуидЦР` String, `Товар` Nullable(String), `Артикул` Nullable(String), `КодДляОбмена` Nullable(UInt32), `СвойствоВидОбуви` Nullable(String), `СвойствоГод` Nullable(String), `СвойствоМатериалВерха` Nullable(String), `СвойствоРод` Nullable(String), `СвойствоСезон` Nullable(String), `СвойствоТорговаяМарка` Nullable(String), `ТипНоменклатуры` Nullable(String), `СтавкаНДС` Nullable(String), `OrderTM` Nullable(String), `СвойствоКоллекцияПроизводства` Nullable(String), `СвойствоКоллекцияПроизводстваКомментарий` Nullable(String), `ПовторАналогНовинка` Nullable(String), `Полнота` Nullable(Int32), `СвойствоБренд` Nullable(String), `СвойствоВидДетскойОбуви` Nullable(String), `СвойствоВидТкани` Nullable(String), `СвойствоВкладнаяСтелька` Nullable(String), `СвойствоВозрастнаяГруппаОбуви` Nullable(String), `СвойствоВысотаКаблука` Nullable(String), `СвойствоКреплениеКаблука` Nullable(String), `СвойствоМатериалПодкладки` Nullable(String), `СвойствоПодвидОбуви` Nullable(String), `СвойствоПодсезон` Nullable(String), `СвойствоПодстиль` Nullable(String), `СвойствоПризнак` Nullable(String), `СвойствоПроизводитель` Nullable(String), `СвойствоРазмерОдежды` Nullable(String), `СвойствоРазмерТовара` Nullable(String), `СвойствоСтиль` Nullable(String), `СвойствоЦвет` Nullable(String), `СтранаПроисхождения` Nullable(String)) AS WITH goods_join AS (SELECT ifNull(t2.`ТоварГуид`, '') AS `ТоварГуидЦР`, ifNull(t.`ТоварГуид`, '') AS `ТоварГуид` FROM `zendendb`.`ТоварыУПП` AS t FULL OUTER JOIN `zendendb`.`Товары` AS t2 ON t.`КодДляОбмена` = t2.`КодДляОбмена`) SELECT g.`ТоварГуид` AS `ТоварГуид`, g.`ТоварГуидЦР` AS `ТоварГуидЦР`, ifNull(t.`Товар`, t2.`Товар`) AS `Товар`, ifNull(t.`Артикул`, t2.`Артикул`) AS `Артикул`, ifNull(t.`КодДляОбмена`, t2.`КодДляОбмена`) AS `КодДляОбмена`, ifNull(t.`СвойствоВидОбуви`, t2.`СвойствоВидОбуви`) AS `СвойствоВидОбуви`, ifNull(t.`СвойствоГод`, t2.`СвойствоГод`) AS `СвойствоГод`, ifNull(t.`СвойствоМатериалВерха`, t2.`СвойствоМатериалВерха`) AS `СвойствоМатериалВерха`, ifNull(t.`СвойствоРод`, t2.`СвойствоРод`) AS `СвойствоРод`, ifNull(t.`СвойствоСезон`, t2.`СвойствоСезон`) AS `СвойствоСезон`, ifNull(t.`СвойствоТорговаяМарка`, t2.`СвойствоТорговаяМарка`) AS `СвойствоТорговаяМарка`, ifNull(t.`ТипНоменклатуры`, t2.`ТипНоменклатуры`) AS `ТипНоменклатуры`, t.`СтавкаНДС` AS `СтавкаНДС`, t.OrderTM AS OrderTM, t.`СвойствоКоллекцияПроизводства` AS `СвойствоКоллекцияПроизводства`, t.`СвойствоКоллекцияПроизводстваКомментарий` AS `СвойствоКоллекцияПроизводстваКомментарий`, t.`ПовторАналогНовинка` AS `ПовторАналогНовинка`, t.`Полнота` AS `Полнота`, t.`СвойствоБренд` AS `СвойствоБренд`, t.`СвойствоВидДетскойОбуви` AS `СвойствоВидДетскойОбуви`, t.`СвойствоВидТкани` AS `СвойствоВидТкани`, t.`СвойствоВкладнаяСтелька` AS `СвойствоВкладнаяСтелька`, t.`СвойствоВозрастнаяГруппаОбуви` AS `СвойствоВозрастнаяГруппаОбуви`, t.`СвойствоВысотаКаблука` AS `СвойствоВысотаКаблука`, t.`СвойствоКреплениеКаблука` AS `СвойствоКреплениеКаблука`, t.`СвойствоМатериалПодкладки` AS `СвойствоМатериалПодкладки`, t.`СвойствоПодвидОбуви` AS `СвойствоПодвидОбуви`, t.`СвойствоПодсезон` AS `СвойствоПодсезон`, t.`СвойствоПодстиль` AS `СвойствоПодстиль`, t.`СвойствоПризнак` AS `СвойствоПризнак`, t.`СвойствоПроизводитель` AS `СвойствоПроизводитель`, t.`СвойствоРазмерОдежды` AS `СвойствоРазмерОдежды`, t.`СвойствоРазмерТовара` AS `СвойствоРазмерТовара`, t.`СвойствоСтиль` AS `СвойствоСтиль`, t.`СвойствоЦвет` AS `СвойствоЦвет`, t.`СтранаПроисхождения` AS `СтранаПроисхождения` FROM goods_join AS g LEFT JOIN `zendendb`.`ТоварыУПП` AS t ON t.`ТоварГуид` = g.`ТоварГуид` LEFT JOIN `zendendb`.`Товары` AS t2 ON t2.`ТоварГуид` = g.`ТоварГуидЦР` SETTINGS final = 1, join_use_nulls = 1;

CREATE VIEW `zendendb`.`ТоварыНаСкладахНаСегодняИМ_v` (`НоменклатураГуид` String, `Количество` Decimal(38, 3), `Розница` UInt8, `t.КодДляОбмена` Nullable(UInt32), `t.Артикул` Nullable(String)) AS WITH warehouse_internet AS (SELECT w.`НоменклатураГуид`, sum(if(w.`ВидДвижения` = 'Приход', w.`Количество`, -w.`Количество`)) AS `Количество`, 0 AS `Розница` FROM (SELECT * FROM `zendendb`.`ТоварыНаСкладахУПП` WHERE (`НоменклатураГуид` IN (SELECT `ТоварГуид` FROM `zendendb`.`ТоварнаяМатрицаПродаж`)) AND (`Период` < today())) AS w ANY LEFT JOIN `zendendb`.`ТоварыОбщие_v` AS t ON t.`ТоварГуид` = w.`НоменклатураГуид` WHERE (w.`Склад` IN ('РЦ ДОМОДЕДОВО FBS Zenden ПАРЫ', 'РЦ ДОМОДЕДОВО FBS Zenden ПАРЫ Подсортировка')) AND (t.`ТипНоменклатуры` = 'Обувь') GROUP BY w.`НоменклатураГуид`) SELECT w.*, t.`КодДляОбмена`, t.`Артикул` FROM warehouse_internet AS w ANY LEFT JOIN `zendendb`.`ТоварыОбщие_v` AS t ON t.`ТоварГуид` = w.`НоменклатураГуид` SETTINGS join_use_nulls = 1;

CREATE VIEW `zendendb`.`ТоварыНаСкладахНаСегодняЦР_v` (`НоменклатураГуид` UUID, `Количество` Int32, `Розница` UInt8, `КодДляОбмена` Nullable(UInt32), `Артикул` Nullable(String)) AS WITH werehouse_retail AS (SELECT w.`НоменклатураГуид`, w.`Количество` AS `Количество`, 1 AS `Розница` FROM (SELECT * FROM `zendendb`.`ТоварыНаСкладахПоДате` WHERE (`НоменклатураГуид` IN (SELECT `ТоварГуид` FROM `zendendb`.`ТоварнаяМатрицаПродаж`)) AND (`Период` = (today() - 1))) AS w ANY LEFT JOIN `zendendb`.`ТоварыОбщие_v` AS t ON toUUIDOrZero(t.`ТоварГуид`) = w.`НоменклатураГуид` WHERE (t.`ТипНоменклатуры` = 'Обувь') AND (w.`НоменклатураГуид` IN (SELECT DISTINCT toUUIDOrZero(`ТоварГуид`) FROM `zendendb`.`ТоварнаяМатрицаПродаж`))) SELECT w.`НоменклатураГуид` AS `НоменклатураГуид`, w.`Количество` AS `Количество`, w.`Розница` AS `Розница`, t.`КодДляОбмена` AS `КодДляОбмена`, t.`Артикул` AS `Артикул` FROM werehouse_retail AS w ANY LEFT JOIN `zendendb`.`ТоварыОбщие_v` AS t ON toUUIDOrZero(t.`ТоварГуид`) = w.`НоменклатураГуид` SETTINGS join_use_nulls = 1;

CREATE VIEW `zendendb`.`ТоварыОбщие_v` (`ТоварГуид` String, `Товар` String, `Артикул` String, `КодДляОбмена` UInt32, `СвойствоВидОбуви` String, `СвойствоГод` String, `СвойствоМатериалВерха` String, `СвойствоРод` String, `СвойствоСезон` String, `СвойствоТорговаяМарка` String, `ТипНоменклатуры` String) AS WITH all_goods AS (SELECT `ТоварГуид`, `Товар`, `Артикул`, `КодДляОбмена`, `СвойствоВидОбуви`, `СвойствоГод`, `СвойствоМатериалВерха`, `СвойствоРод`, `СвойствоСезон`, `СвойствоТорговаяМарка`, trimBoth(`ТипНоменклатуры`) AS `ТипНоменклатуры` FROM `zendendb`.`Товары` WHERE `Артикул` != '' UNION DISTINCT SELECT `ТоварГуид`, `Товар`, `Артикул`, `КодДляОбмена`, `СвойствоВидОбуви`, `СвойствоГод`, `СвойствоМатериалВерха`, `СвойствоРод`, `СвойствоСезон`, `СвойствоТорговаяМарка`, trimBoth(`ТипНоменклатуры`) AS `ТипНоменклатуры` FROM `zendendb`.`ТоварыУПП` WHERE (`ТоварГуид` NOT IN (SELECT `ТоварГуид` FROM `zendendb`.`Товары`)) AND (`Артикул` != '')) SELECT * FROM all_goods AS g WHERE `ТипНоменклатуры` IN ('Перчатки', 'Обувная косметика', 'Галантерея', 'Изделия купальные', 'Подарочная упаковка', 'Подарочный сертификат', 'Изделия бельевые', 'Одежда', 'Изделия верхние', 'Аксессуары для обуви', 'Головные уборы', 'Кошельки', 'Очки', 'Бижутерия', 'Обувь', 'Сумки', 'Обувь детская', 'Чулочно-носочные изделия', 'Маски не медицинские', 'Аксессуары', 'Текстиль для дома', 'КожГалантерея', 'Ремни', 'Ессо ОБУВЬ', 'BeFree', 'Платки и Шарфы', 'Боттичелли аксессуары', 'Средства по уходу за одеждой', 'Сувенирная продукция', 'Косметика', 'Боттичелли одежда', 'Галоши', 'Пляжная обувь', 'Зонты', 'Пакеты', 'Носки', 'Косметические средства', 'Реклама', 'Ювелирные изделия', 'Ecco сопутка', 'Домашняя обувь');

CREATE VIEW `zendendb`.`ТоварыУчаствующиеВАкции_На_Сегодня_v` (`Подразделение` String, `НоменклатураГуид` String, `ПроцентСкидки` Decimal(7, 4)) AS SELECT a.`Организация` AS `Подразделение`, `НоменклатураГуид`, argMax(`ПроцентСкидки`, `Период`) AS `ПроцентСкидки` FROM `zendendb`.`ТоварыУчаствующиеВАкции` AS a WHERE (a.`ДатаОкончания` >= (today() - 1)) AND (a.`ПроцентСкидки` != 0) AND (a.`Период` > (today() - toIntervalMonth(6))) AND (a.`Организация` IN (SELECT DISTINCT `Подразделение` FROM `zendendb`.`ЦеныНоменклатурыЦР_На_Сегодня`)) GROUP BY a.`НоменклатураГуид`, a.`Организация`;

CREATE VIEW `zendendb`.`ФОТ/ТО_v` (`Месяц` Date, `СотрудникГуид` String, `Сотрудник` String, `Должность` String, `ДолжностьУправленческая` String, `Организация` LowCardinality(String), `СтатьяФинансирования` String, `Подразделение` LowCardinality(String), `ПодразделениеУправленческое` LowCardinality(String), `КодМагазина` Int32, `ТМ` LowCardinality(String), `РМ` LowCardinality(String), `Магазин Родитель` LowCardinality(String), `Город` LowCardinality(String), `Регион` LowCardinality(String), `ОтработаноДней` Int32, `ОтработаноЧасов` Int32, `ПФР по суммарному тарифу` Nullable(Decimal(15, 3)), `ФСС НС` Nullable(Decimal(15, 3)), `НДФЛ` Nullable(Decimal(15, 3)), `Районный коэффициент` Nullable(Decimal(15, 3)), `Праздничные и вых. дни` Nullable(Decimal(15, 3)), `Оклад` Nullable(Decimal(15, 3)), `Премия` Nullable(Decimal(15, 3)), `Отпуск` Nullable(Decimal(15, 3)), `Командировка` Nullable(Decimal(15, 3)), `Больничный` Nullable(Decimal(15, 3)), `Комп отпуска при увольнении` Nullable(Decimal(15, 3)), `Северная надбавка` Nullable(Decimal(15, 3)), `Удержание по исполнительному документу` Nullable(Decimal(15, 3)), `Мат помощь` Nullable(Decimal(15, 3)), `Компенсация по соглашению сторон` Nullable(Decimal(15, 3)), `ШтатФакт` Nullable(Decimal(15, 3)), `ШтатПлан` Nullable(Decimal(15, 3)), `Укомплектованность` Nullable(Decimal(15, 3)), `Количество` Int64, `ТО` Nullable(Decimal(15, 3)), `Вал` Nullable(Decimal(15, 3)), `Трафик` Nullable(Decimal(15, 3)), `Пары` Int64, `Чеки покупок` Int32, `Чеки возвратов` Int32, `План Оборот` Nullable(Decimal(15, 3)), `План Трафик` Nullable(Decimal(15, 3)), `План Вал` Nullable(Decimal(15, 3)), `План Чеки` Nullable(Decimal(15, 3)), `План Пары` Nullable(Decimal(15, 3)), `Вентра Часов день` Nullable(Decimal(15, 3)), `Вентра Всего без НДС` Nullable(Decimal(15, 3))) AS SELECT * FROM `zendendb`.`ФОТ/ТО` FINAL;

CREATE VIEW `zendendb`.`ЦеныНоменклатурыЦР_На_Сегодня_v` (`Подразделение` String, `НоменклатураГуид` String, `Цена` Decimal(15, 2), `Розница` UInt8) AS WITH prices AS (SELECT pr.`Период`, if(pr.`ТипЦен` = 'Продажная (ИНТЕРНЕТ-магазин Zenden)', 'ИНТЕРНЕТ-магазин Zenden', pr.`ПодразделениеТипЦен`) AS `ПодразделениеТипЦен`, pr.`ТипЦен`, if(pr.`ТипЦен` = 'Продажная (ИНТЕРНЕТ-магазин Zenden)', 0, 1) AS `Розница`, pr.`НоменклатураГуид`, pr.`Цена`, t.`Артикул` AS `Артикул` FROM `zendendb`.`ЦеныНоменклатурыЦР` AS pr ANY LEFT JOIN `zendendb`.`ТоварыОбщие_v` AS t ON t.`ТоварГуид` = pr.`НоменклатураГуид` WHERE (pr.`Период` >= (SELECT toStartOfISOYear(min(`Период`)) FROM `zendendb`.`ПродажиУПП`)) AND (t.`ТипНоменклатуры` = 'Обувь') AND (pr.`ТипЦен` LIKE 'Продажная%')) SELECT pr.`ПодразделениеТипЦен` AS `Подразделение`, pr.`НоменклатураГуид`, argMax(pr.`Цена`, `Период`) AS `Цена`, max(`Розница`) AS `Розница` FROM prices AS pr WHERE (pr.`ПодразделениеТипЦен` NOT LIKE '<%') AND (pr.`ПодразделениеТипЦен` != '') AND (pr.`ПодразделениеТипЦен` != '1') GROUP BY pr.`ПодразделениеТипЦен`, pr.`НоменклатураГуид`;

CREATE VIEW `zendendb`.`ЦеныЦРСоСкидками_На_Сегодня_v` (`НоменклатураГуид` String, `Подразделение` String, `Цена` Int32, `ПроцентСкидки` Nullable(Decimal(9, 2)), `Розница` Int8, `Артикул` Nullable(String), `КодДляОбмена` Nullable(UInt32)) AS WITH all_prices AS (SELECT r.`НоменклатураГуид` AS `НоменклатураГуид`, r.`Подразделение` AS `Подразделение`, r.`Цена` AS `Цена`, t.`ПроцентСкидки` AS `ПроцентСкидки`, r.`Розница` AS `Розница` FROM (SELECT * FROM `zendendb`.`ЦеныНоменклатурыЦР_На_Сегодня` WHERE `Розница` = 1) AS r LEFT JOIN `zendendb`.`ТоварыУчаствующиеВАкции_На_Сегодня` AS t ON (t.`Подразделение` = r.`Подразделение`) AND (t.`НоменклатураГуид` = r.`НоменклатураГуид`) UNION ALL SELECT i.`НоменклатураГуид` AS `НоменклатураГуид`, i.`Подразделение` AS `Подразделение`, i.`Цена` AS `Цена`, 0 AS `ПроцентСкидки`, i.`Розница` AS `Розница` FROM (SELECT * FROM `zendendb`.`ЦеныНоменклатурыЦР_На_Сегодня` WHERE `Розница` = 0) AS i) SELECT p.*, t.`Артикул` AS `Артикул`, t.`КодДляОбмена` AS `КодДляОбмена` FROM all_prices AS p ANY LEFT JOIN `zendendb`.`ТоварыОбщие_v` AS t ON t.`ТоварГуид` = p.`НоменклатураГуид` WHERE (t.`Артикул` != '') AND (p.`НоменклатураГуид` IN (SELECT `ТоварГуид` FROM `zendendb`.`ТоварнаяМатрицаПродаж`)) SETTINGS join_use_nulls = 1;

CREATE VIEW `zendendb`.`ЦеныЦРСоСкидками_На_Сегодня_ИМ_v` (`НоменклатураГуид` String, `Подразделение` String, `Цена` Int32, `ПроцентСкидки` Decimal(7, 2), `Артикул` String, `КодДляОбмена` Int32) AS SELECT * FROM `zendendb`.`ЦеныЦРСоСкидками_На_Сегодня` WHERE `Подразделение` = 'ИНТЕРНЕТ-магазин Zenden';

CREATE VIEW `zendendb`.`ЦеныЦРСоСкидками_На_Сегодня_Розница_v` (`НоменклатураГуид` String, `Подразделение` String, `Цена` Int32, `ПроцентСкидки` Decimal(7, 2), `Артикул` String, `КодДляОбмена` Int32) AS SELECT * FROM `zendendb`.`ЦеныЦРСоСкидками_На_Сегодня` WHERE (`Подразделение` NOT LIKE 'ИНТЕРНЕТ%') AND (`Подразделение` NOT IN ('ОЗОН-FBS-ZENDEN', 'неисп.Уфа-Планета'));

